import { toSafeText } from "./safe-text";
import { useCallback, useEffect, useRef, useState, type KeyboardEvent } from "react";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import type { CellEditorProps, CellRenderProps, CellType, GridCellTypes } from "../types";
import { CellSpan } from "./cell-span";
import { TEXT_FILTER_OPERATORS } from "./capabilities";
import { useCommitGuard } from "../interaction/use-commit-guard";
import { useCellTextInsets } from "../interaction/use-cell-editor";
import { isComposingKey } from "../interaction/is-composing-key";
import { columnLabelText } from "../columns/column-format-helpers";
import { displayText } from "./display-text";
import { sortCollator } from "../sort-filter/sort-collator";

/** Rendered text is capped so one huge stored value cannot stall layout. */
const LONG_TEXT_DISPLAY_LIMIT = 500;

/** The type's default `validate` bound, and the editor textarea's `maxLength` when a column sets no `maxLength` of its own. */
export const LONG_TEXT_DEFAULT_MAX_LENGTH = 100_000;

function LongTextCell({ value, options }: CellRenderProps<unknown, string, GridCellTypes["longText"]["options"]>) {
  return <CellSpan text={displayText(longTextCellType, value, options)} />;
}

/** Popover + textarea (the date editor's pattern): the cell stays one line, the editor takes a real multi-line surface. Outside press commits the draft; Escape cancels. */
function LongTextEditor({
  value,
  options,
  onChange,
  commit,
  cancel,
  column,
  pending,
  rejectionCount,
}: CellEditorProps<unknown, string, GridCellTypes["longText"]["options"]>) {
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const { triggerRef, measure } = useCellTextInsets();
  const [text, setText] = useState(longTextCellType.toText(value));
  const [open, setOpen] = useState(true);
  const committed = useCommitGuard();

  // Re-arm on each rejection, not on pending->false (that also fires on the cancel right before unmount); see CellEditorProps.rejectionCount.
  const lastRejectionCount = useRef(rejectionCount ?? 0);
  useEffect(() => {
    if ((rejectionCount ?? 0) !== lastRejectionCount.current) committed.reset();
    lastRejectionCount.current = rejectionCount ?? 0;
  }, [rejectionCount, committed]);

  // The portal commits its content one render after mount; a mount effect would read a null ref.
  const setTextareaRef = useCallback((el: HTMLTextAreaElement | null) => {
    textareaRef.current = el;
    if (!el) return;
    // first line sits on the display text, so opening the editor moves nothing
    const { start, top } = measure();
    el.style.padding = `${top}px ${start}px`;
    el.focus({ preventScroll: true });
    const end = el.value.length;
    el.setSelectionRange(end, end);
  }, [measure]);

  const commitValue = (nextValue: string, movement?: { dx: number; dy: number }) => {
    if (!committed.tryCommit()) return;
    onChange(nextValue);
    commit(movement);
  };

  const insertLineBreak = () => {
    const el = textareaRef.current;
    const start = el?.selectionStart ?? text.length;
    const end = el?.selectionEnd ?? text.length;
    setText(text.slice(0, start) + "\n" + text.slice(end));
    // restore the caret after React re-renders the controlled value
    requestAnimationFrame(() => el?.setSelectionRange(start + 1, start + 1));
  };

  return (
    <Popover
      open={open}
      onOpenChange={(next, details) => {
        if (!next && details.reason === "escape-key" && isComposingKey(details.event)) {
          details.cancel();
          return;
        }
        setOpen(next);
        if (!next) {
          // Escape cancels the edit; any other close (outside press) commits the draft.
          // commitValue owns the one-shot guard; cancel is idempotent.
          if (details.reason === "escape-key") cancel();
          else commitValue(longTextCellType.fromText(text), { dx: 0, dy: 0 });
        }
      }}
    >
      <PopoverTrigger nativeButton={false} render={<span ref={triggerRef} className="block w-full min-w-0 truncate" />}>
        {displayText(longTextCellType, value, options)}
      </PopoverTrigger>
      <PopoverContent
        data-grid-cell-editor=""
        // Base UI's open-focus wins the rAF race and resets the caret; the mount effect owns focus.
        initialFocus={false}
        align="start"
        alignOffset={() => -measure().start}
        sideOffset={() => -measure().textBottomToCellTop}
        className="w-100 max-w-[calc(100vw-1rem)] p-0 data-open:animate-none data-closed:animate-none"
        onKeyDown={(e: KeyboardEvent<HTMLDivElement>) => {
          if (e.key === "Escape" && !isComposingKey(e) && committed.tryCommit()) cancel();
        }}
      >
        <textarea
          ref={setTextareaRef}
          value={text}
          // readOnly, not disabled: a disabled textarea swallows Escape while an async validation is pending.
          readOnly={pending}
          dir="auto"
          aria-multiline
          aria-label={columnLabelText(column)}
          maxLength={options?.maxLength ?? LONG_TEXT_DEFAULT_MAX_LENGTH}
          placeholder={options?.placeholder}
          onChange={(e) => setText(e.target.value)}
          onKeyDown={(e: KeyboardEvent<HTMLTextAreaElement>) => {
            if (isComposingKey(e)) return;
            if (e.key !== "Enter") return;
            e.preventDefault();
            if (e.shiftKey || e.altKey) insertLineBreak();
            else commitValue(longTextCellType.fromText(text), { dx: 0, dy: 1 });
          }}
          className="block max-h-75 min-h-37.5 w-full resize-none overflow-y-auto border-none bg-transparent text-[length:inherit] shadow-none outline-none"
        />
      </PopoverContent>
    </Popover>
  );
}

/** `longText`: multi-line value stored verbatim; the cell renders the first 500 characters with line breaks as spaces, the editor is a popover textarea. The type's `validate` bounds every write at the column `maxLength`, or {@link LONG_TEXT_DEFAULT_MAX_LENGTH}, before the column's own `validate` runs. */
export const longTextCellType: CellType<unknown, string, GridCellTypes["longText"]["options"]> = {
  Cell: LongTextCell,
  Editor: LongTextEditor,
  filter: { operators: TEXT_FILTER_OPERATORS, valueInput: "text" },
  toText: (value) => toSafeText(value),
  toDisplayText: (value) => toSafeText(value).slice(0, LONG_TEXT_DISPLAY_LIMIT).replace(/\r\n|\r|\n/g, " "),
  fromText: (text) => text,
  clearValue: () => "",
  isEmpty: (value) => value == null || value === "",
  compare: (a, b) => sortCollator().compare(toSafeText(a), toSafeText(b)),
  validate: (value, _row, options) => {
    const max = options?.maxLength ?? LONG_TEXT_DEFAULT_MAX_LENGTH;
    return toSafeText(value).length > max ? `Too long: max ${max} characters` : null;
  },
};

import type { CellType } from "../types";
import { toSafeText } from "./safe-text";

/** Generic display-text resolution: any {@link CellType} may define `toDisplayText` for a formatted read view; falls back to `toText`. Clipboard and CSV/XLSX export call `toText`; print and `buildExportRows({ text: "display" })` read this. */
export function displayText<TValue, TOptions>(
  cellType: Pick<CellType<unknown, TValue, TOptions>, "toText" | "toDisplayText">,
  value: TValue,
  options?: TOptions,
): string {
  return (cellType.toDisplayText ?? cellType.toText)(value, options);
}

/** The cell type's `toText` for clipboard and export; a throwing `toText` falls back to the value's safe text. */
export function exportText<TValue, TOptions>(
  cellType: Pick<CellType<unknown, TValue, TOptions>, "toText">,
  value: TValue,
  options?: TOptions,
): string {
  try {
    return toSafeText(cellType.toText(value, options));
  } catch {
    return toSafeText(value);
  }
}

/** `String(value ?? "")` that falls back to `""` when the conversion throws (null-prototype objects, deeply nested arrays). */
export function toSafeText(value: unknown): string {
  if (value == null) return "";
  try {
    return String(value);
  } catch {
    return "";
  }
}

import { isDev } from "../is-dev";
import { createWarnOnce } from "../is-dev";
import { isThenable } from "../store/async-gate";
import { toSafeText } from "./safe-text";
import type { CellValidate } from "../validation/validate-cell";
import type { CellType } from "../types";

const warnedTypes = new WeakSet<object>();

const UNPARSEABLE_MESSAGE = "The text could not be parsed";

/** A parsed cell: the value, plus the validator that decides it (a rejecting one when `fromText` threw). */
export type ParsedCellText = { value: unknown; validate: CellValidate };

/** Thrown by a built-in `fromText` for text it deliberately rejects; the cell reports a rejection without the development warning for a faulty type. */
export class UnparseableTextError extends Error {
  /** Set by {@link rejectText}; a built-in type's message embeds the text, so it is never shown. */
  explicitMessage?: string;
}

/**
 * Refuses the text inside a cell type's `fromText`: the cell keeps its value, and the grid reports the
 * text to `onValidationError` with `message`, as the built-in types do. Typed `never`, so it fits any `fromText` return:
 * `fromText: (text) => parseRating(text) ?? rejectText("Enter 0 to 5")`.
 */
export function rejectText(message?: string): never {
  const error = new UnparseableTextError(message ?? UNPARSEABLE_MESSAGE);
  if (message !== undefined) error.explicitMessage = message;
  throw error;
}

// A rejecting validator throws, so `thrown: true` blocks the cell under validationMode "warn" too.
const rejectionValidators = new WeakSet<object>();
const deliberateRejections = new WeakSet<object>();

function rejecting(message: string, deliberate: boolean): CellValidate {
  const validate: CellValidate = () => {
    throw new Error(message);
  };
  rejectionValidators.add(validate);
  if (deliberate) deliberateRejections.add(validate);
  return validate;
}

const rejectUnparseable = rejecting(UNPARSEABLE_MESSAGE, true);
const rejectFaulty = rejecting(UNPARSEABLE_MESSAGE, false);

function rejectionOf(error: UnparseableTextError): CellValidate {
  return error.explicitMessage === undefined ? rejectUnparseable : rejecting(error.explicitMessage, true);
}

/**
 * Runs `cellType.fromText` so a throw becomes a rejected cell instead of an aborted write.
 * Warns once per cell type in development.
 */
export function safeFromText(
  cellType: CellType<any, any, any>, // eslint-disable-line @typescript-eslint/no-explicit-any
  text: string,
  options: unknown,
  validate: CellValidate,
): ParsedCellText {
  try {
    return { value: cellType.fromText(text, options), validate };
  } catch (error) {
    if (!(error instanceof UnparseableTextError) && isDev() && !warnedTypes.has(cellType)) {
      warnedTypes.add(cellType);
      console.warn("[data-grid] a cell type's fromText threw; the cell is rejected. Call rejectText() in fromText to refuse text without this warning.");
    }
    return { value: undefined, validate: error instanceof UnparseableTextError ? rejectionOf(error) : rejectFaulty };
  }
}

/** True when {@link safeFromText} caught a throw for this cell. */
export function isUnparseable(parsed: ParsedCellText): boolean {
  return rejectionValidators.has(parsed.validate as object);
}

/** True when the cell type rejected the text on purpose with {@link UnparseableTextError}. */
export function isRejectedText(parsed: ParsedCellText): boolean {
  return deliberateRejections.has(parsed.validate as object);
}

const HOOK_FAILED = Symbol("hookFailed");

/**
 * Runs a consumer parse hook (`processCellFromClipboard`, `processCellFromText`) for one cell. A sync throw or a
 * rejected promise rejects that cell like unparseable text and the batch goes on. Settle async values with {@link settleHookFailure}.
 */
export function parseWithHook(hookName: string, run: () => unknown, validate: CellValidate, warnOnce: ReturnType<typeof createWarnOnce>): ParsedCellText {
  const fail = (error: unknown) => warnOnce(hookName, () => `${hookName} threw for a cell, so that cell is rejected: ${toSafeText(error)}`);
  try {
    const value = run();
    if (!isThenable(value)) return { value, validate };
    return { value: Promise.resolve(value).then(undefined, (error: unknown) => (fail(error), HOOK_FAILED)), validate };
  } catch (error) {
    if (error instanceof UnparseableTextError) return { value: undefined, validate: rejectionOf(error) };
    fail(error);
    return { value: undefined, validate: rejectFaulty };
  }
}

/** Turns the settled value of a failed async hook into a rejected cell. */
export function settleHookFailure<T extends { value: unknown; validate: unknown }>(item: T): T {
  return item.value === HOOK_FAILED ? { ...item, value: undefined, validate: rejectFaulty } : item;
}

/** Domain barrel — built-in cell type registry and shared editor pieces. */
export {
  cellTypes,
  textCellType,
  numberCellType,
  checkboxCellType,
  selectCellType,
  dateCellType,
  urlCellType,
  longTextCellType,
  safeHref,
} from "./cell-types";
export { displayText } from "./display-text";
export { CellSpan } from "./cell-span";

import { toSafeText } from "./safe-text";
import { UnparseableTextError } from "./safe-from-text";
import type { KeyboardEvent } from "react";
import { Input } from "@/components/ui/input";
import type { CellEditorProps, CellRenderProps, CellType, GridCellTypes } from "../types";
import { CellSpan } from "./cell-span";
import { COMPARISON_FILTER_OPERATORS, SET_FILTER_OPERATORS, TEXT_FILTER_OPERATORS } from "./capabilities";
import { CELL_INPUT_CLASS, useCellEditorDraft } from "../interaction/use-cell-editor";
import { cn } from "@/lib/utils";
import { isComposingKey } from "../interaction/is-composing-key";
import { displayText } from "./display-text";
import { createFormatterCache, formatKey } from "./formatter-cache";
import { compareNumbers } from "../sort-filter/builtin-compare";

const IMPLIED_NUMBER_FORMAT: Intl.NumberFormatOptions = {};

const DECIMAL_NUMBER = /^[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:e[+-]?\d+)?$/i;

const COMMA_GROUPS = /^[+-]?\d{1,3}(?:,\d{3})+(?:\.\d+)?$/;
const DOT_GROUPS_COMMA_DECIMAL = /^[+-]?\d{1,3}(?:\.\d{3})+,\d+$/;
const SINGLE_GROUP_AMBIGUOUS = /^[+-]?\d{1,3},\d{3}$/;

/** Reads a pasted number to the text `Number()` parses; throws for text that could mean two numbers or none. */
function normalizeNumberText(text: string): string {
  const trimmed = text.trim();
  if (SINGLE_GROUP_AMBIGUOUS.test(trimmed)) throw new UnparseableTextError(`"${trimmed}" is ambiguous`);
  if (COMMA_GROUPS.test(trimmed)) return trimmed.replaceAll(",", "");
  if (DOT_GROUPS_COMMA_DECIMAL.test(trimmed)) return trimmed.replaceAll(".", "").replace(",", ".");
  return trimmed.replace(",", ".");
}

/** Clamps a parsed number into the column's configured min/max, if any. */
function clampNumber(value: number, options?: GridCellTypes["number"]["options"]): number {
  let clamped = value;
  if (options?.min !== undefined) clamped = Math.max(clamped, options.min);
  if (options?.max !== undefined) clamped = Math.min(clamped, options.max);
  return clamped;
}

/** Moves the decimal point by `places` through the exponent, so `1.005` shifts to exactly `100.5`. */
function shiftDecimal(value: number, places: number): number {
  const [mantissa = "0", exponent = "0"] = String(value).split("e");
  return Number(`${mantissa}e${Number(exponent) + places}`);
}

/** Rounds to the column's configured decimal precision, if any; never returns `-0`. */
function roundToDecimals(value: number, options?: GridCellTypes["number"]["options"]): number {
  if (options?.decimals === undefined || !Number.isFinite(value)) return value;
  const rounded = shiftDecimal(Math.round(shiftDecimal(value, options.decimals)), -options.decimals);
  return rounded === 0 ? 0 : rounded;
}

/** Count of fractional digits in a finite number's shortest decimal form. */
function decimalPlaces(value: number): number {
  const [mantissa = "", exponent = "0"] = String(value).split("e");
  const fraction = mantissa.split(".")[1]?.length ?? 0;
  return Math.min(100, Math.max(0, fraction - Number(exponent)));
}

/** Pulls a bound into the column's decimals, keeping a bound that already sits on that grid. */
function boundToDecimals(bound: number, decimals: number, inward: (n: number) => number): number {
  const rounded = Math.round(bound * 10 ** decimals) / 10 ** decimals;
  if (rounded === bound) return rounded;
  return inward(bound * 10 ** decimals) / 10 ** decimals;
}

/** Clamps into min/max, pulling each bound inward to the column's decimals so the result never exceeds it. */
function clampToDecimals(value: number, options: GridCellTypes["number"]["options"], decimals: number): number {
  let clamped = value;
  if (options?.min !== undefined) clamped = Math.max(clamped, boundToDecimals(options.min, decimals, Math.ceil));
  if (options?.max !== undefined) clamped = Math.min(clamped, boundToDecimals(options.max, decimals, Math.floor));
  return clamped;
}

const cachedNumberFormatter = createFormatterCache<Intl.NumberFormat>("invalid number format options, showing the raw value");

// Skips the key build per cell: a scan of 200,000 cells spends more time on the key than on `format`.
const lastFormatterOf = new WeakMap<Intl.NumberFormatOptions, { locale: string; decimals: number | undefined; formatter: Intl.NumberFormat | null }>();

/** The formatter for the options, or `null` when they are invalid. A re-created literal with equal content reuses one formatter. */
function getNumberFormatter(format: Intl.NumberFormatOptions, locale: string, decimals: number | undefined): Intl.NumberFormat | null {
  const last = lastFormatterOf.get(format);
  if (last !== undefined && last.locale === locale && last.decimals === decimals) return last.formatter;
  const formatter = buildNumberFormatter(format, locale, decimals);
  lastFormatterOf.set(format, { locale, decimals, formatter });
  return formatter;
}

function buildNumberFormatter(format: Intl.NumberFormatOptions, locale: string, decimals: number | undefined): Intl.NumberFormat | null {
  return cachedNumberFormatter(`${locale}|${decimals ?? ""}|${formatKey(format)}`, () => {
    // decimals fills in fraction digits the format left open (0.25 under style:"percent" + decimals:2 renders 25.00%)
    const effective =
      decimals !== undefined && format.minimumFractionDigits === undefined && format.maximumFractionDigits === undefined
        ? { ...format, minimumFractionDigits: decimals, maximumFractionDigits: decimals }
        : format;
    return new Intl.NumberFormat(locale, effective);
  });
}

const DECIMAL_TEXT = /^-?\d+(?:\.\d+)?$/;

// Intl formats a decimal string exactly since ES2023; an older engine keeps the raw text.
const formatsDecimalText = (() => {
  try {
    return new Intl.NumberFormat("en-US").format("9007199254740993") === "9,007,199,254,740,993";
  } catch {
    return false;
  }
})();

const MAX_DECIMAL_TEXT = 1024;

const isDecimalText = (value: unknown): value is Intl.StringNumericLiteral => formatsDecimalText && typeof value === "string" && value.length <= MAX_DECIMAL_TEXT && DECIMAL_TEXT.test(value);

/** Rounds a decimal string like {@link roundToDecimals}: half up, no `-0`. A string within `decimals` stays as it is. */
function roundDecimalText(text: Intl.StringNumericLiteral, decimals: number): string {
  const dot = text.indexOf(".");
  if (dot === -1 || text.length - dot - 1 <= decimals) return NEGATIVE_ZERO.test(text) ? "0" : text;
  const formatter = exactFormatter(decimals);
  return formatter ? formatter.format(text) : text;
}

const NEGATIVE_ZERO = /^-0(?:\.0+)?$/;

const exactFormatters = new Map<number, Intl.NumberFormat | null>();

function exactFormatter(decimals: number): Intl.NumberFormat | null {
  let formatter = exactFormatters.get(decimals);
  if (formatter === undefined) {
    formatter = cachedNumberFormatter(`exact|${decimals}`, () => new Intl.NumberFormat("en-US", { useGrouping: false, maximumFractionDigits: decimals, roundingMode: "halfCeil", signDisplay: "negative" }));
    exactFormatters.set(decimals, formatter);
  }
  return formatter;
}

function NumberCell({ value, options }: CellRenderProps<unknown, number | null, GridCellTypes["number"]["options"]>) {
  return <CellSpan text={displayText(numberCellType, value, options)} />;
}

function parseDraft(draft: string, options?: GridCellTypes["number"]["options"]): number | null {
  try {
    return numberCellType.fromText(draft, options);
  } catch {
    return null;
  }
}

function NumberEditor(props: CellEditorProps<unknown, number | null, GridCellTypes["number"]["options"]>) {
  const { value, options, pending } = props;
  // seed with `toText` so `decimals` rounding matches; `format` stays display-only
  const { bindings, setDraft } = useCellEditorDraft(props, {
    toDraft: (draftValue) => numberCellType.toText(draftValue, options),
    toValue: (draft) => numberCellType.fromText(draft, options),
  });
  const { ref, onKeyDown, ...rest } = bindings;

  return (
    <Input
      ref={ref}
      {...rest}
      onKeyDown={(e: KeyboardEvent<HTMLInputElement>) => {
        if (e.key !== "ArrowUp" && e.key !== "ArrowDown") {
          onKeyDown(e);
          return;
        }
        if (pending || isComposingKey(e)) return;
        // step the draft; a cleared draft falls back to the committed value, so an empty
        // cell with a null value has no step base and stays untouched
        const base = parseDraft(rest.value, options) ?? value;
        if (base === null) return;
        e.preventDefault();
        const configuredStep = options?.step ?? 1;
        const step = options?.decimals !== undefined ? Math.max(configuredStep, 10 ** -options.decimals) : configuredStep;
        const raw = base + (e.key === "ArrowUp" ? step : -step);
        const clamped = clampNumber(raw, options);
        // float drift (0.1 + 0.2) rounds away at the finer of the draft's and the step's precision
        const next =
          options?.decimals !== undefined
            ? clampToDecimals(roundToDecimals(raw, options), options, options.decimals)
            : clamped === raw
              ? Number(raw.toFixed(Math.max(decimalPlaces(base), decimalPlaces(step))))
              : clamped;
        setDraft(String(next));
      }}
      className={cn(CELL_INPUT_CLASS, "[text-align:inherit] [appearance:textfield] [&::-webkit-inner-spin-button]:appearance-none [&::-webkit-outer-spin-button]:appearance-none")}
    />
  );
}

/** `number`: comma-decimal and grouped-thousands parse that rejects ambiguous or non-numeric text, min/max clamp, decimals rounding, plain `String()` serialization; `options.format` (implied as `{}` by `options.locale` alone) renders display-only locale formatting — copy, export, and the editor keep the raw value. */
export const numberCellType: CellType<unknown, number | null, GridCellTypes["number"]["options"]> = {
  Cell: NumberCell,
  Editor: NumberEditor,
  numeric: true,
  filter: { operators: [...TEXT_FILTER_OPERATORS, ...COMPARISON_FILTER_OPERATORS, ...SET_FILTER_OPERATORS], valueInput: "number" },
  toText: (value, options) => {
    if (value == null) return "";
    if (options?.decimals !== undefined && isDecimalText(value)) return roundDecimalText(value, options.decimals);
    return toSafeText(options?.decimals !== undefined ? roundToDecimals(value, options) : value);
  },
  toDisplayText: (value, options) => {
    if (value == null) return "";
    // a locale alone implies the default grouped format
    const format = options?.format ?? (options?.locale ? IMPLIED_NUMBER_FORMAT : undefined);
    if (format && isDecimalText(value)) {
      const formatter = getNumberFormatter(format, options?.locale ?? "en-US", options?.decimals);
      const rounded = options?.decimals === undefined ? value : (roundDecimalText(value, options.decimals) as Intl.StringNumericLiteral);
      return formatter ? formatter.format(rounded) : numberCellType.toText(value, options);
    }
    if (!format || typeof value !== "number") return numberCellType.toText(value, options);
    const formatter = getNumberFormatter(format, options?.locale ?? "en-US", options?.decimals);
    return formatter ? formatter.format(roundToDecimals(value, options)) : numberCellType.toText(value, options);
  },
  fromText: (text, options) => {
    const normalized = normalizeNumberText(text);
    if (normalized === "") return null;
    const parsed = DECIMAL_NUMBER.test(normalized) ? Number(normalized) : Number.NaN;
    if (!Number.isFinite(parsed)) throw new UnparseableTextError(`"${text}" is not a number`);
    if (options?.decimals !== undefined) return clampToDecimals(roundToDecimals(parsed, options), options, options.decimals);
    return clampNumber(parsed, options);
  },
  clearValue: () => null,
  isEmpty: (value) => value == null,
  compare: compareNumbers,
  align: "end",
};

import { useEffect, useRef, useState } from "react";
import { toSafeText } from "./safe-text";
import { UnparseableTextError } from "./safe-from-text";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import type { CellEditorProps, CellRenderProps, CellType, GridCellTypes } from "../types";
import { CellSpan } from "./cell-span";
import { SET_FILTER_OPERATORS, TEXT_FILTER_OPERATORS } from "./capabilities";
import { useCommitGuard } from "../interaction/use-commit-guard";
import { columnLabelText } from "../columns/column-format-helpers";
import { defaultCompareText } from "../sort-filter/default-compare-text";
import { sortCollator } from "../sort-filter/sort-collator";

type Choice = { value: string; label: string };
type ChoiceInput = GridCellTypes["select"]["options"]["choices"];
type ChoiceIndex = { byValue: Map<string, Choice>; byLowerLabel: Map<string, Choice> };

const resolvedChoices = new WeakMap<ChoiceInput, readonly Choice[]>();

/** The `{ value, label }` list of a `choices` array: a string becomes a choice with equal value and label. Cached per array. */
export function resolveSelectChoices(input: ChoiceInput | undefined): readonly Choice[] {
  if (!input) return [];
  let resolved = resolvedChoices.get(input);
  if (resolved) return resolved;
  resolved = input.some((choice) => typeof choice === "string")
    ? input.map((choice) => (typeof choice === "string" ? { value: choice, label: choice } : choice))
    : (input as readonly Choice[]);
  resolvedChoices.set(input, resolved);
  return resolved;
}

// Per-cell lookups (search, display, copy) stay O(1); keyed by array identity, so an in-place mutation of `choices` is not seen.
const choiceIndexes = new WeakMap<readonly Choice[], ChoiceIndex>();

function choiceIndex(choices: readonly Choice[]): ChoiceIndex {
  let index = choiceIndexes.get(choices);
  if (index) return index;
  index = { byValue: new Map(), byLowerLabel: new Map() };
  for (const choice of choices) {
    if (!index.byValue.has(choice.value)) index.byValue.set(choice.value, choice);
    const lower = choice.label.toLowerCase();
    if (!index.byLowerLabel.has(lower)) index.byLowerLabel.set(lower, choice);
  }
  choiceIndexes.set(choices, index);
  return index;
}

// Sort ranks by label per `choices` array; equal labels share a rank, so a sort compares integers.
const choiceRanks = new WeakMap<readonly Choice[], WeakMap<Intl.Collator, Map<string, number>>>();

function choiceRank(choices: readonly Choice[]): Map<string, number> {
  const collator = sortCollator();
  let byCollator = choiceRanks.get(choices);
  if (!byCollator) choiceRanks.set(choices, (byCollator = new WeakMap()));
  let ranks = byCollator.get(collator);
  if (ranks) return ranks;
  ranks = new Map();
  const byLabel = [...choices].sort((a, b) => defaultCompareText(a.label, b.label));
  let rank = -1;
  let previous: string | undefined;
  for (const choice of byLabel) {
    if (previous === undefined || defaultCompareText(previous, choice.label) !== 0) rank++;
    previous = choice.label;
    if (!ranks.has(choice.value)) ranks.set(choice.value, rank);
  }
  byCollator.set(collator, ranks);
  return ranks;
}

/** The choice whose value is `raw`, else the first whose label matches `raw` case-insensitively. */
function findChoice(choices: ChoiceInput | undefined, raw: string): Choice | undefined {
  if (!choices) return undefined;
  const index = choiceIndex(resolveSelectChoices(choices));
  return index.byValue.get(raw) ?? index.byLowerLabel.get(toSafeText(raw).toLowerCase());
}

/** The built-in `select` cell type's `compare`; the keyed sort recognizes a column that uses it by identity. */
export function compareSelect(a: string | null, b: string | null, options?: GridCellTypes["select"]["options"]): number {
  if (a == null && b == null) return 0;
  if (a == null) return -1;
  if (b == null) return 1;
  const choices = options?.choices;
  if (choices) {
    const ranks = choiceRank(resolveSelectChoices(choices));
    const rankA = ranks.get(a);
    const rankB = ranks.get(b);
    if (rankA !== undefined && rankB !== undefined) return rankA - rankB;
  }
  return defaultCompareText(findChoice(choices, a)?.label ?? a, findChoice(choices, b)?.label ?? b);
}

function SelectCell({ value, options }: CellRenderProps<unknown, string | null, GridCellTypes["select"]["options"]>) {
  const key = toSafeText(value);
  return <CellSpan text={findChoice(options?.choices, key)?.label ?? key} />;
}

/** Opens on mount; picking an option commits immediately (no separate confirm step). */
function SelectEditor({ value, options, onChange, commit, cancel, column, rejectionCount }: CellEditorProps<unknown, string | null, GridCellTypes["select"]["options"]>) {
  const [open, setOpen] = useState(true);
  const committed = useCommitGuard();

