import { escapeHtmlText, sanitizeFormulaCell } from "./serialize-cells";

const BLOCK_TAGS = new Set(["P", "DIV", "LI"]);

/** Maps the character references the serializer and `innerHTML` disagree on (`&nbsp;`, `&#13;`) to their characters. */
function normalizeHtmlText(html: string): string {
  return html.replace(/&nbsp;/g, "\u00a0").replace(/&#13;/g, "\r");
}

/**
 * The grid's own `data-gridcn-raw` trust check: the attribute holds a value the DOM never sees
 * (raw "\t"/spaces/newlines the display renders as spans/`<br>`), so it is trusted only when it is
 * the serializer's own rendering of this exact cell — a hand-crafted payload cannot set it to a
 * different value without the cell's visible text contradicting it. The formula-sanitized
 * rendering (`'` prefix) of the same value also matches.
 */
function rawMatchesCell(raw: string, cell: Element): boolean {
  const rendered = normalizeHtmlText(cell.innerHTML);
  return rendered === normalizeHtmlText(escapeHtmlText(raw)) || rendered === normalizeHtmlText(escapeHtmlText(sanitizeFormulaCell(raw)));
}

/** Converts a table cell's DOM content to text, treating `<br>` as a newline and separating block-level children (e.g. Apple Numbers' `<p>` per line) with one. */
function cellNodeToText(cell: Element): string {
  const raw = cell.getAttribute("data-gridcn-raw");
  if (raw !== null && rawMatchesCell(raw, cell)) return raw;

  let out = "";
  for (const node of Array.from(cell.childNodes)) {
    if (node.nodeType === Node.TEXT_NODE) {
      out += node.textContent ?? "";
    } else if (node.nodeType === Node.ELEMENT_NODE) {
      const el = node as Element;
      if (el.tagName === "BR") {
        out += "\n";
      } else if (BLOCK_TAGS.has(el.tagName) && out !== "") {
        out += "\n" + cellNodeToText(el);
      } else {
        out += cellNodeToText(el);
      }
    }
  }
  return out;
}

const MAX_COL_SPAN = 1000;
const MAX_ROW_SPAN = 65534;

/** A cell's `colspan` or `rowspan` as an integer in 1..max; a missing or malformed value is 1. */
function readSpan(cell: Element, attribute: string, max: number): number {
  const parsed = Math.trunc(Number(cell.getAttribute(attribute)));
  return Number.isFinite(parsed) && parsed > 1 ? Math.min(parsed, max) : 1;
}

/**
 * Parses a clipboard `text/html` payload into a 2D string grid using the first `<table>` found.
 * Prefers each cell's `data-gridcn-raw` attribute — trusted only when it is the grid's own
 * serialization of the cell (it renders back to the cell's exact innerHTML) — falling back to
 * text content with `<br>` treated as a newline. A cell with `colspan` or `rowspan` gives its text to its first position and leaves the positions it covers empty. With `maxCells`, parsing stops once the cell total passes it. Returns null when no table is present.
 */
export function parseClipboardHtml(html: string, maxCells?: number): string[][] | null {
  const doc = new DOMParser().parseFromString(html, "text/html");
  const table = doc.querySelector("table");
  if (!table) return null;

  const rows: string[][] = [];
  const rowsStillCovered: number[] = [];
  let cellCount = 0;
  for (const tableRow of Array.from(table.rows)) {
    const cells: string[] = [];
    const overCap = () => maxCells !== undefined && cellCount + cells.length > maxCells;
    const skipCovered = () => {
      while (rowsStillCovered[cells.length]! > 0 && !overCap()) {
        rowsStillCovered[cells.length]!--;
        cells.push("");
      }
    };
    for (const cell of Array.from(tableRow.cells)) {
      skipCovered();
      const colSpan = readSpan(cell, "colspan", MAX_COL_SPAN);
      const rowSpan = readSpan(cell, "rowspan", MAX_ROW_SPAN);
      for (let offset = 0; offset < colSpan && !overCap(); offset++) {
        if (rowSpan > 1) rowsStillCovered[cells.length] = rowSpan - 1;
        cells.push(offset === 0 ? cellNodeToText(cell) : "");
      }
      if (overCap()) break;
    }
    skipCovered();
    rows.push(cells);
    cellCount += cells.length;
    if (maxCells !== undefined && cellCount > maxCells) break;
  }
  return rows;
}

/**
 * Parses a clipboard `text/plain` TSV payload with Excel-style quoting: a field starting with
 * `"` is quoted, `""` is an escaped quote, and tabs/newlines inside quotes are literal.
 * Handles both `\r\n` and `\n` row separators; a trailing empty row from a final newline is dropped.
 * With `maxCells`, parsing stops after the row that pushes the cell total past it; the caller trims that row.
 */
export function parseClipboardText(text: string, maxCells?: number): string[][] {
  const rows: string[][] = [];
  let row: string[] = [];
  let field = "";
  let inQuotes = false;
  // tracks whether the current field has any content (incl. a closed "") so it isn't mistaken for "nothing pending"
  let fieldPending = false;
  let i = 0;
  const len = text.length;
  let cellCount = 0;
  let full = false;
  // start of the current unflushed run; -1 means nothing pending (avoids per-char += allocation)
  let start = -1;

  const flush = () => {
    if (start !== -1) {
      field += text.slice(start, i);
      start = -1;
    }
  };
  const endField = () => {
    flush();
    row.push(field);
    field = "";
    fieldPending = false;
    if (maxCells !== undefined && cellCount + row.length > maxCells) full = true;
  };
  const endRow = () => {
    endField();
    rows.push(row);
    cellCount += row.length;
    row = [];
    if (maxCells !== undefined && cellCount > maxCells) full = true;
  };

  while (i < len && !full) {
    const ch = text[i];

    if (inQuotes) {
      if (ch === '"') {
        flush();
        if (text[i + 1] === '"') {
          field += '"';
          i += 2;
          continue;
        }
        inQuotes = false;
        i += 1;
        continue;
      }
      if (start === -1) start = i;
      i += 1;
      continue;
    }

    if (ch === '"' && !fieldPending) {
      inQuotes = true;
      fieldPending = true;
      i += 1;
      continue;
    }
    if (ch === "\t") {
      endField();
      i += 1;
      continue;
    }
    if (ch === "\r") {
      // lookahead for \r\n; a lone \r is treated as a row separator too
      endRow();
      i += text[i + 1] === "\n" ? 2 : 1;
      continue;
    }
    if (ch === "\n") {
      endRow();
      i += 1;
      continue;
    }
    if (start === -1) start = i;
    fieldPending = true;
    i += 1;
  }

  if (full) {
    if (row.length > 0) rows.push(row);
    return rows;
  }

  // final field/row, unless the input ended exactly on a row separator (trailing newline)
  if (fieldPending || row.length > 0) {
    endRow();
  }

  return rows;
}

/** Upper bound for the markup one cell takes in a clipboard table; a larger payload skips the HTML parse. */
const HTML_CHARS_PER_CELL = 80;

/** Upper bound for the text one cell takes; a plain-text payload above the total is not parsed. */
const TEXT_CHARS_PER_CELL = 256;
const MIN_TEXT_CHARS = 1024 * 1024;

/**
 * Produces a 2D string grid from clipboard data, preferring the HTML table representation
 * and falling back to TSV plain text. With `maxCells`, an HTML payload too large for that many cells
 * is skipped, a text payload too large for them yields no cells, and the text parse stops early. Returns an empty array when neither is usable.
 */
export function parseClipboard(data: { html?: string; text?: string }, maxCells?: number): string[][] {
  if (data.html && (maxCells === undefined || data.html.length <= maxCells * HTML_CHARS_PER_CELL)) {
    const fromHtml = parseClipboardHtml(data.html, maxCells);
    if (fromHtml && fromHtml.length > 0) return fromHtml;
  }
  if (data.text !== undefined) {
    if (maxCells !== undefined && data.text.length > Math.max(maxCells * TEXT_CHARS_PER_CELL, MIN_TEXT_CHARS)) return [];
    return parseClipboardText(data.text, maxCells);
  }
  return [];
}

import type { DataGridStoreState } from "../store/types";
import type { ViewCoord } from "../types";
import { isThenable } from "../store/async-gate";

/**
 * Calls each touched column's `resolveTexts` once with the column's distinct texts. Returns `undefined`
 * when no hook answered with a promise, so a sync paste keeps its straight-line cost.
 */
export function resolveColumnTexts(s: DataGridStoreState, cells: readonly (readonly string[])[], target: ViewCoord, signal: () => AbortSignal): Promise<void> | undefined {
  const pending: Promise<void>[] = [];
  const width = cells.reduce((max, row) => Math.max(max, row.length), 0);
  for (let c = 0; c < width && target.col + c < s.visibleColumns.length; c++) {
    const column = s.visibleColumns[target.col + c]!; // bounded by the loop condition
    const resolveTexts = s.cellTypes[column.type ?? "text"]?.resolveTexts;
    if (!resolveTexts) continue;
    const texts = new Set<string>();
    for (const row of cells) texts.add(row[c] ?? "");
    texts.delete("");
    const answer = resolveTexts.call(s.cellTypes[column.type ?? "text"], [...texts], column.options, { signal: signal() });
    if (isThenable(answer)) pending.push(Promise.resolve(answer));
  }
  return pending.length > 0 ? Promise.all(pending).then(() => undefined) : undefined;
}

const NEEDS_QUOTING = /[\t\n\r"]/;

/** Escapes a single TSV field per Excel quoting rules (quote wrap + doubled internal quotes). */
function quoteTsvField(cell: string): string {
  if (!NEEDS_QUOTING.test(cell)) return cell;
  return `"${cell.replace(/"/g, '""')}"`;
}

/** A leading one of these makes a CSV/TSV cell a formula in Excel, LibreOffice, and Sheets. */
const FORMULA_LEAD_CHARS = new Set(["=", "+", "-", "@", "\t", "\r"]);

/** Values where a leading `+` or `-` is still a plain number, including the exponent and bare-decimal forms `String(number)` can produce. */
const PLAIN_NUMBER_RE = /^[+-]?(\d+(\.\d*)?|\.\d+)(e[+-]?\d+)?$/i;

/**
 * Prefixes a formula-like cell (leading `=`, `+`, `-`, `@`, TAB, or CR; plain numbers exempt) with a
 * single quote. External spreadsheets treat that quote as a hidden text marker, so a CSV export or
 * clipboard paste cannot run `=HYPERLINK(...)`-style formulas in another sheet.
 */
export function sanitizeFormulaCell(value: string): string {
  const lead = value[0];
  if (lead === undefined || !FORMULA_LEAD_CHARS.has(lead) || PLAIN_NUMBER_RE.test(value)) return value;
  return `'${value}`;
}

/** Options for {@link serializeCells}. */
export type SerializeCellsOptions = {
  /** Prefix formula-like cells with `'` in the text/plain payload and the HTML cell text so external spreadsheets read them as text; `data-gridcn-raw` keeps the raw value for a paste back into gridcn. Default `false`. */
  sanitizeFormulas?: boolean;
};

/** Escapes text and preserves whitespace fidelity for Excel/Sheets: tabs -> 4 spaces, runs of >=2 spaces wrapped in a span. Also the round-trip check `parse-clipboard.ts` applies to `data-gridcn-raw`. */
export function escapeHtmlText(value: string): string {
  return value
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/\r/g, "&#13;")
    .replace(/\t/g, "    ")
    .replace(/  +/g, (run) => `<span>${" ".repeat(run.length)}</span>`)
    .replace(/\n/g, "<br>");
}

function escapeHtmlAttr(value: string): string {
  return value
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/\r/g, "&#13;");
}

/**
 * Serializes a rectangular block of display strings into clipboard `text/plain` (quoted TSV)
 * and `text/html` (a `<table>` carrying the raw value in `data-gridcn-raw` per cell).
 */
export function serializeCells(cells: string[][], options: SerializeCellsOptions = {}): { text: string; html: string } {
  const { sanitizeFormulas = false } = options;
  const shown = (cell: string): string => (sanitizeFormulas ? sanitizeFormulaCell(cell) : cell);
  const text = cells.map((row) => row.map((cell) => quoteTsvField(shown(cell))).join("\t")).join("\n");

  const rowsHtml = cells
    .map((row) => {
      const cellsHtml = row
        .map((cell) => `<td data-gridcn-raw="${escapeHtmlAttr(cell)}">${escapeHtmlText(shown(cell))}</td>`)
        .join("");
      return `<tr>${cellsHtml}</tr>`;
    })
    .join("");

  return { text, html: `<table><tbody>${rowsHtml}</tbody></table>` };
}

"use client";

