/** Props for {@link DataGrid}: the sync props (the store's home) plus the root's render/layout props — a prop lives on exactly one surface, so nothing is hand-forwarded. */
export type DataGridProps<TData> = (ExternalStoreProps | OwnedStoreProps<TData>) &
  DataGridRootProps<TData> & {
    /**
     * Imperative handle (React 19 ref-as-prop): assigned with this grid's {@link DataGridApi} once
     * mounted; stable for the grid's lifetime. Manual composition gets the same handle from
     * `DataGridProvider`'s `ref` or from {@link useDataGridApi}.
     */
    ref?: Ref<DataGridApi<TData>>;
    /** Per-column header cell slot of the default header — see {@link HeaderCellRenderer}. With `children`, pass it to `DataGridHeader` instead. */
    renderHeaderCell?: HeaderCellRenderer;
    /** Rendered inside the provider, above the grid: a toolbar, a search field, or a status bar that reads the grid's store. */
    toolbar?: ReactNode;
  };

/**
 * The imperative API of one grid — see {@link DataGridApi}. Call it anywhere under the grid's
 * `DataGridProvider`, a toolbar sibling of `DataGridRoot` included. `scrollTo` and `focus` no-op
 * until a `DataGridRoot` mounts. Pass a `ref` to hand the handle out; the returned object is
 * stable for the grid's lifetime, safe to close over.
 */
export function useDataGridApi<TData = unknown>(ref?: Ref<DataGridApi<TData>>): DataGridApi<TData> {
  const api = apiHandleOf<TData>(useDataGridStoreApi());
  useImperativeHandle(ref, () => api, [api]);
  return api;
}

/**
 * Types every row-reading hook once for a row type: `export const { useDataGridRow, useDataGridApi } = createDataGridHooks<Order>();`.
 * The returned hooks are the plain hooks with `TData` fixed, so a component reads `Order` rows without a type argument at each call.
 */
export function createDataGridHooks<TData>() {
  return {
    useDataGridApi: useDataGridApi as (ref?: Ref<DataGridApi<TData>>) => DataGridApi<TData>,
    useDataGridRow: useDataGridRow as (viewRowIndex: number) => TData | undefined,
    useDataGridVisibleColumns: useDataGridVisibleColumns as () => readonly ColumnDefOf<TData>[],
    useDataGridAllColumns: useDataGridAllColumns as () => readonly ColumnDefOf<TData>[],
    useDataGridSelector: createDataGridSelector<TData>(),
  };
}

/**
 * Convenience wrapper: provider + scroll root + header + body. Compose the
 * parts directly (`DataGridProvider`/`DataGridRoot`/`DataGridHeader`/`DataGridBody`)
 * for custom layouts (toolbar, overlays, context menu).
 */
export function DataGrid<TData>(props: DataGridProps<TData>): ReactNode {
  // The root keeps exactly DATA_GRID_ROOT_PROP_KEYS; the rest (the sync props plus `store`) goes to the provider.
  const {
    className,
    "aria-label": ariaLabel,
    "aria-labelledby": ariaLabelledBy,
    rowHeight,
    markerWidth,
    density,
    headerHeight,
    columnOverscan,
    direction,
    emptyState,
    loading,
    loadingState,
    error,
    onRetry,
    errorState,
    renderHeaderCell,
    renderHeaderMenu,
    renderHeaderFilter,
    renderMarker,
    renderMarkerHeader,
    getRowClassName,
    getCellClassName,
    children,
    toolbar,
    ...rest
  } = props;
  return (
    <DataGridProvider {...rest}>
      {toolbar}
      <DataGridRoot
        className={className}
        aria-label={ariaLabel}
        aria-labelledby={ariaLabelledBy}
        rowHeight={rowHeight}
        markerWidth={markerWidth}
        density={density}
        headerHeight={headerHeight}
        columnOverscan={columnOverscan}
        direction={direction}
        emptyState={emptyState}
        error={error}
        onRetry={onRetry}
        errorState={errorState}
        loading={loading}
        loadingState={loadingState}
        renderHeaderMenu={renderHeaderMenu}
        renderHeaderFilter={renderHeaderFilter}
        renderMarker={renderMarker}
        renderMarkerHeader={renderMarkerHeader}
        getRowClassName={getRowClassName}
        getCellClassName={getCellClassName}
      >
        {children ?? (
          <>
            <DataGridHeader renderHeaderCell={renderHeaderCell} />
            <DataGridBody />
          </>
        )}
      </DataGridRoot>
    </DataGridProvider>
  );
}

