      const rect = el.getBoundingClientRect();
      // guaranteed present: the closest() selector above only matches elements with [data-column-id]
      const columnId = el.dataset["columnId"]!;
      // "before"/"after" stay logical (reading order): the inline-START half is "before" in both
      // directions, which under RTL is the header's physical RIGHT half.
      const position: "before" | "after" = isInlineStartHalf(clientX, rect, direction) ? "before" : "after";
      return { columnId, position };
    },
    [direction, headerHeight, headerRowHeight],
  );

  const isColumnReorderable = useCallback(
    (columnId: string) => {
      if (columnGroupModel?.groups.has(columnId)) return columns.every((column) => !groupPathOf(columnGroupModel, column.id).includes(columnId) || column.reorderable !== false);
      return renderedColumns.some(({ column }) => column.id === columnId && column.reorderable !== false);
    },
    [renderedColumns, columns, columnGroupModel],
  );

  const { onHeaderDragPointerDown, dragState } = useColumnReorder({
    enabled: enableColumnReorder,
    isColumnReorderable,
    hitTestHeader,
    onReorder: actions.setColumnOrder,
    onArm: interaction.cancelColumnSelectDrag,
  });

  /**
   * Single drop-indicator line at the reorder drag's current boundary. Grid-placed on the boundary
   * column's own track: an unpinned column gets raw track coords (the header layer already
   * translates by -scrollLeft), a pinned boundary column reuses the exact pinned-cell offset,
   * so the line lands at the cell's rendered edge either way.
   */
  const dropIndicator = useMemo<{ index: number; style: CSSProperties } | null>(() => {
    if (!dragState?.overId) return null;
    let boundaryId = dragState.overId;
    if (columnGroupModel) {
      const unit = dropUnit(columns.map((c) => c.id), columnGroupModel, dragState.draggingId, dragState.overId);
      if (!unit) return null;
      boundaryId = dragState.position === "before" ? unit[0]! : unit[unit.length - 1]!;
    }
    const over = renderedColumns.find(({ column }) => column.id === boundaryId);
    if (!over) return null;
    const { column, index } = over;
    const width = layout.widths[index];
    const pinStyle = pinnedInsetStyle(column.pin, index);
    // unpinned: the div is grid-placed on the boundary column's own track (raw track coords, like
    // any other header cell), so its local left edge is 0 — "after" just adds the column's width.
    // pinned: pinnedInsetStyle's insetInlineStart already lands this div at the pinned cell's own
    // rendered left edge (same track, same formula) — "after" shifts that by the column's width too.
    const insetInlineStart =
      dragState.position === "before"
        ? (pinStyle.insetInlineStart ?? 0)
        : pinStyle.insetInlineStart
          ? `calc(${pinStyle.insetInlineStart} + ${width}px)`
          : width;
    const rowStart = groupPathOf(columnGroupModel, column.id).length + 1;
    const style: CSSProperties = {
      gridRowStart: rowStart,
      gridRowEnd: headerRowCount + 1,
      gridColumnStart: index + markerColOffset,
      position: "relative",
      insetBlockStart: 0,
      insetInlineStart,
      height: "100%",
      width: 2,
      zIndex: GRID_LAYER.header,
      pointerEvents: "none",
      backgroundColor: "var(--color-primary)",
    };
    return { index, style };
  }, [dragState, columns, renderedColumns, layout.widths, markerColOffset, columnGroupModel, headerRowCount]);

  const layerStyle: CSSProperties = {
    position: "absolute",
    insetBlockStart: 0,
    insetInlineStart: 0,
    display: "grid",
    gridTemplateColumns: template,
    gridAutoRows: headerRowHeight,
    // stacking context (transform) painted after the rows canvas in DOM order; without an explicit
    // z-index the canvas's own stacking context wins paint order and buries the header on scroll.
    zIndex: GRID_LAYER.pinnedHeader,
    // header never moves vertically — only the canvas does — so only the horizontal term applies here.
    // --grid-dir signs it for RTL (see body.tsx's canvas transform for the full reasoning).
    transform: "translate3d(calc(var(--grid-dir, -1) * var(--grid-scroll-left, 0px)), 0, 0)",
  };
  // Stable props let the memoized header cells skip a header render that changes nothing of theirs.
  const resize = useMemo(
    () => ({ enabled: enableColumnResize, previewColumnWidth: actions.previewColumnWidth, cancelColumnResize: actions.cancelColumnResize, setColumnWidth: actions.setColumnWidth, autosizeColumns: actions.autosizeColumns, direction }),
    [enableColumnResize, actions, direction],
  );
  const reorder = useMemo(() => ({ enabled: enableColumnReorder, state: dragState, onPointerDown: onHeaderDragPointerDown }), [enableColumnReorder, dragState, onHeaderDragPointerDown]);
  const renderLeaf = ({ column, index }: { column: AnyColumnDef; index: number }, rowStart: number) => (
    <DataGridHeaderCell
      key={column.id}
      column={column}
      index={index}
      width={layout.widths[index]!} // index is a real index into columns; layout.widths is columns.map(...), same length
      gridColOffset={markerColOffset}
      rowStart={rowStart}
      rowSpan={headerRowCount - rowStart + 1}
      headerClickBehavior={headerClickBehavior}
      sortState={sortState}
      resize={resize}
      reorder={reorder}
      onSelect={interaction.onHeaderPointerDown}
      onSort={actions.toggleSort}
      renderHeaderMenu={renderHeaderMenu}
      renderHeaderFilter={renderHeaderFilter}
      renderHeaderCell={renderHeaderCell}
    />
  );
  const marker = layout.markerWidth > 0 && <DataGridMarkerHeader mode={rowMarkers} headerHeight={headerHeight} rowSpan={headerRowCount} />;
  const indicator = dragState && dropIndicator && <div data-grid-drop-indicator="" aria-hidden="true" style={dropIndicator.style} />;

  if (headerRows.length === 0) {
    return (
      <div role="row" style={layerStyle} className={className} data-grid-header-layer="">
        {marker}
        {renderedColumns.map((rendered) => renderLeaf(rendered, 1))}
        {indicator}
      </div>
    );
  }

  const pinnedStartEdge = layout.pins.reduce((edge, pin, i) => (pin === "start" ? edge + layout.widths[i]! : edge), layout.markerWidth);
  return (
    <div role="rowgroup" style={layerStyle} className={className} data-grid-header-layer="">
      {Array.from({ length: headerRowCount }, (_, level) => (
        <div key={level} role="row" aria-rowindex={level + 1} style={{ display: "contents" }}>
          {level === 0 && marker}
          {level < headerRows.length &&
            renderedSegments(headerRows[level]!, renderedColumns).map((segment) => {
              const group = columnGroupModel?.groups.get(segment.groupId);
              if (!group) return null;
              return (
                <DataGridGroupHeaderCell
                  key={`${segment.groupId}:${segment.start}`}
                  segment={segment}
                  group={group.def}
                  gridColOffset={markerColOffset}
                  width={layout.trackRights[segment.end - 1]! - layout.trackLefts[segment.start]!} // segment ranges are real column indices
                  trackLeft={layout.trackLefts[segment.start]!}
                  pinnedStartEdge={pinnedStartEdge}
                  headerClickBehavior={headerClickBehavior}
                  onSelect={interaction.onGroupHeaderPointerDown}
                  reorder={{ enabled: enableColumnReorder, draggingId: dragState?.draggingId ?? null, onPointerDown: onHeaderDragPointerDown }}
                />
              );
            })}
          {renderedColumns.filter(({ column }) => groupPathOf(columnGroupModel, column.id).length === level).map((rendered) => renderLeaf(rendered, level + 1))}
          {level === headerRowCount - 1 && indicator}
        </div>
      ))}
    </div>
  );
}

/** The segments that touch at least one rendered column. Rendered indices ascend, so each segment needs one binary search. */
function renderedSegments(segments: readonly HeaderSegment[], rendered: readonly { index: number }[]): HeaderSegment[] {
  return segments.filter(({ start, end }) => {
    let lo = 0;
    let hi = rendered.length;
    while (lo < hi) {
      const mid = (lo + hi) >>> 1;
      if (rendered[mid]!.index < start) lo = mid + 1; // mid is in [lo, hi), inside rendered
      else hi = mid;
    }
    return lo < rendered.length && rendered[lo]!.index < end;
  });
}

import type { DataChange, DataOp } from "../types";
import { defaultGetRowId } from "../store/types";

/** Inverts a single operation: update swaps row/prev, insert becomes delete, delete becomes insert. */
function invertOp<TData>(op: DataOp<TData>): DataOp<TData> {
  switch (op.type) {
    case "update":
      return {
        type: "update",
        rowId: op.rowId,
        row: op.prev,
        prev: op.row,
        cells: op.cells?.map((cell) => ({
          columnId: cell.columnId,
          value: cell.prev,
          prev: cell.value,
        })),
      };
    case "insert":
      return { type: "delete", rowId: op.rowId, row: op.row, index: op.index };
    case "delete":
      return { type: "insert", rowId: op.rowId, row: op.row, index: op.index };
    // the row sits at `op.to` after the move, so undoing swaps the two snapshot positions
    case "move":
      return { type: "move", rowId: op.rowId, row: op.row, from: op.to, to: op.from };
  }
}

/**
 * Produces the change that undoes `change`: each operation is inverted and the operation
 * order is reversed (so a batch unwinds in the correct dependency order). `source` tags the result;
 * pass `"rollback"` to revert a failed optimistic save so an `onDataChange` handler can tell it from an undo.
 */
export function invertChange<TData>(change: DataChange<TData>, source: "history" | "rollback" = "history"): DataChange<TData> {
  return {
    ops: [...change.ops].reverse().map(invertOp),
    source,
    label: change.label,
  };
}

/**
 * Applies a change to `data` immutably in O(n + k log(n + k)), returning a new array.
 * Rows are located by id (never by the operation's stored index, which is only a
 * hint for where an insert should land). If an id referenced by an
 * update/delete operation is no longer present (row was deleted by a later change),
 * that operation is skipped silently rather than throwing.
 *
 * `index` convention: update/delete operation indices are informational only (those operations are
 * row-id-based). An insert's `index` is the row's slot in the resulting array, after all of the
 * batch's inserts are in place (the natural output of an insert-rows or duplicate-rows emitter).
 * `getRowId` defaults to the row's `id` field, as in the grid.
 * Inserts are applied in ascending-index order regardless of their order in `ops`, so a multi-row
 * batch (including one produced by inverting a delete batch) round-trips through invertChange.
 */
export function applyChange<TData>(data: readonly TData[], change: DataChange<TData>, getRowId: (row: TData, index: number) => string = defaultGetRowId): TData[] {
  return applyChangeWith(data, change, getRowId);
}

export type ApplyChangeOptions<TData> = {
  /** Picks the row an `update` operation writes, given the row currently in `data`. Default: the operation's own `row`. */
  rowOfUpdate?: (op: Extract<DataOp<TData>, { type: "update" }>, current: TData) => TData;
};

/** {@link applyChange} with options; internal to the add-ons, not on the consumer barrel. */
export function applyChangeWith<TData>(
  data: readonly TData[],
  change: DataChange<TData>,
  getRowId: (row: TData, index: number) => string,
  { rowOfUpdate }: ApplyChangeOptions<TData> = {},
): TData[] {
  const indexById = new Map<string, number>();
  const idByIndex = new Array<string>(data.length);
  let hasDuplicateId = false;
  for (let i = 0; i < data.length; i++) {
    const id = getRowId(data[i]!, i);
    idByIndex[i] = id;
    if (indexById.has(id)) hasDuplicateId = true;
    else indexById.set(id, i);
  }

  const deleteIndices = new Set<number>();
  const inserts: Extract<DataOp<TData>, { type: "insert" }>[] = [];
  let postDelete: TData[];

  if (!hasDuplicateId) {
    const updateById = new Map<string, TData>();
    for (const op of change.ops) {
      if (op.type === "insert") {
        inserts.push(op);
        continue;
      }
      const idx = indexById.get(op.rowId);
      if (idx === undefined) continue;
      if (op.type === "update") updateById.set(op.rowId, rowOfUpdate ? rowOfUpdate(op, data[idx]!) : op.row);
      else if (op.type === "delete") deleteIndices.add(idx);
      // a move is a delete + insert of the same row: the insert lands at the row's post-move slot
      else {
        deleteIndices.add(idx);
        inserts.push({ type: "insert", rowId: op.rowId, row: op.row, index: op.to });
      }
    }

    postDelete = [];
    for (let i = 0; i < data.length; i++) {
      if (deleteIndices.has(i)) continue;
      const id = idByIndex[i]!;
      const updated = updateById.get(id);
      postDelete.push(updated !== undefined ? updated : data[i]!);
    }
  } else {
    // Duplicate row ids are invalid, but this path preserves the legacy first-occurrence scan.
    const indicesById = new Map<string, number[]>();
    for (let i = 0; i < data.length; i++) {
      const id = idByIndex[i]!;
      const indices = indicesById.get(id);
      if (indices) indices.push(i);
      else indicesById.set(id, [i]);
    }

    const opsById = new Map<string, DataOp<TData>[]>();
    for (const op of change.ops) {
      if (op.type === "insert") {
        inserts.push(op);
        continue;
      }
      const ops = opsById.get(op.rowId);
      if (ops) ops.push(op);
      else opsById.set(op.rowId, [op]);
    }

    const updateByIndex = new Map<number, TData>();
    for (const idOps of opsById.values()) {
      const indices = indicesById.get(idOps[0]!.rowId);
      if (!indices) continue;
      let next = 0;
      for (const op of idOps) {
        if (next >= indices.length) break;
        const target = indices[next]!;
        if (op.type === "update") {
          updateByIndex.set(target, rowOfUpdate ? rowOfUpdate(op, data[target]!) : op.row);
        } else {
          deleteIndices.add(target);
          if (op.type === "move") inserts.push({ type: "insert", rowId: op.rowId, row: op.row, index: op.to });
          next++;
        }
      }
    }

    postDelete = [];
    for (let i = 0; i < data.length; i++) {
      if (deleteIndices.has(i)) continue;
      postDelete.push(updateByIndex.get(i) ?? data[i]!);
    }
  }

  const sorted = [...inserts].sort((a, b) => a.index - b.index);
  const total = postDelete.length + sorted.length;
  if (total === 0) return [];

  // Fenwick slot placement reproduces the legacy clamped insert order.
  const bit = new Int32Array(total + 1);
  for (let i = 1; i <= total; i++) bit[i] = i & -i;
  const insertAt = new Int32Array(total).fill(-1);
  const addFree = (pos: number) => {
    for (let i = pos + 1; i <= total; i += i & -i) bit[i]!--;
  };
  const findFreeSlot = (rank: number): number => {
    let idx = 0;
    let target = rank;
    let mask = 1 << Math.floor(Math.log2(total));
    while (mask !== 0) {
      const next = idx + mask;
      if (next <= total && bit[next]! < target) {
        idx = next;
        target -= bit[next]!;
      }
      mask >>= 1;
    }
    return idx;
  };

  for (let q = sorted.length - 1; q >= 0; q--) {
    const at = Math.min(sorted[q]!.index, postDelete.length + q);
    const pos = findFreeSlot(at + 1);
    insertAt[pos] = q;
    addFree(pos);
  }

  const out = new Array<TData>(total);
  let original = 0;
  for (let pos = 0; pos < total; pos++) {
    const q = insertAt[pos]!;
    out[pos] = q === -1 ? postDelete[original++]! : sorted[q]!.row;
  }
  return out;
}

/** Options for {@link createHistory}. */
export type HistoryOptions = {
  /** Maximum number of entries kept on the undo stack; oldest entries are dropped past this. */
  capacity?: number;
};

/**
 * Operation-based undo/redo stack, UI-free. Consumers call `push` after each
 * applied gesture, and `undo`/`redo` to get the change to apply back to data.
 */
export type History<TData> = {
  /** Records a change; discards any redo branch. Changes with source "history", "rollback", "merge" or "id-swap" are ignored. */
  push(change: DataChange<TData>): void;
  /** Removes a recorded change (matched by identity) from both stacks; true when it was found. Pass the change `undo()` or `redo()` returned to remove its entry. */
  discard(change: DataChange<TData>): boolean;
  /** Returns the inverted top-of-undo-stack change to apply, or null if nothing to undo. `rebase` maps the change before it is returned and tracked. */
  undo(rebase?: (change: DataChange<TData>) => DataChange<TData>): DataChange<TData> | null;
  /** Returns the original change, re-tagged source "history", to re-apply; or null if nothing to redo. `rebase` maps the change before it is returned and tracked. */
  redo(rebase?: (change: DataChange<TData>) => DataChange<TData>): DataChange<TData> | null;
  /**
   * Puts the entry behind a change that `undo()` or `redo()` returned back where it was, because the
   * change was not applied or was refused. False when the entry cannot return (a newer change moved on).
   */
  restore(change: DataChange<TData>): boolean;
  /**
   * Gives a row a new id in every entry: `ops` on `oldId` get `newId`, and each snapshot of the row takes
   * the fields that differ between `oldRow` and `newRow`. An entry with a snapshot that is not a plain
   * object goes. True when any entry changed.
   */
  replaceRowId(oldId: string, newId: string, oldRow: TData, newRow: TData): boolean;
  /** {@link History.replaceRowId} for many rows in one pass over the entries. */
  replaceRowIds(swaps: readonly { oldId: string; newId: string; oldRow: TData; newRow: TData }[]): boolean;
  /** Removes the `ops` on `rowIds` from every entry; an entry left without `ops` goes. True when any entry changed. */
  dropRows(rowIds: Iterable<string>): boolean;
  /** Whether `undo()` would return a change. */
  readonly canUndo: boolean;
  /** Whether `redo()` would return a change. */
  readonly canRedo: boolean;
  /** Clears both stacks. */
  clear(): void;
  /** Changes the capacity; a smaller one drops the oldest undo entries now. */
  setCapacity(capacity: number): void;
  /** Number of entries on the undo stack. */
  readonly size: number;
};

type Applied<TData> = { entry: DataChange<TData>; direction: "undo" | "redo" };

function isPlainObject(value: unknown): value is Record<string, unknown> {
  if (typeof value !== "object" || value === null) return false;
  const proto: unknown = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}

/** The fields to copy from `oldRow` to `newRow`: changed or added keys, and removed keys. */
function rowPatch(oldRow: unknown, newRow: unknown): { set: [string, unknown][]; unset: string[] } | null {
  if (!isPlainObject(oldRow) || !isPlainObject(newRow)) return null;
  const set: [string, unknown][] = [];
  const unset: string[] = [];
  for (const key of Object.keys(newRow)) {
    if (!(key in oldRow) || !Object.is(oldRow[key], newRow[key])) set.push([key, newRow[key]]);
  }
  for (const key of Object.keys(oldRow)) if (!(key in newRow)) unset.push(key);
  return { set, unset };
}

/** Creates a row-id-based undo/redo history. */
export function createHistory<TData>(opts: HistoryOptions = {}): History<TData> {
  let capacity = opts.capacity ?? 100;
  let undoStack: DataChange<TData>[] = [];
  let redoStack: DataChange<TData>[] = [];
  const applied = new WeakMap<DataChange<TData>, Applied<TData>>();
  // a rewritten entry stays findable by the change object the consumer holds
  const origin = new WeakMap<DataChange<TData>, DataChange<TData>>();
  const rootOf = (entry: DataChange<TData>) => origin.get(entry) ?? entry;

  const rewrite = (map: (entry: DataChange<TData>) => DataChange<TData> | null): boolean => {
    let changed = false;
    const mapStack = (stack: DataChange<TData>[]) => {
      const next: DataChange<TData>[] = [];
      for (const entry of stack) {
        const mapped = map(entry);
        if (mapped !== entry) {
          changed = true;
          if (mapped) origin.set(mapped, rootOf(entry));
        }
        if (mapped) next.push(mapped);
      }
      return next;
    };
    undoStack = mapStack(undoStack);
    redoStack = mapStack(redoStack);
    return changed;
  };

  return {
    push(change) {
      if (change.source === "history" || change.source === "rollback" || change.source === "merge" || change.source === "id-swap") return;
      undoStack.push(change);
      if (undoStack.length > capacity) undoStack.shift();
      redoStack = [];
    },
    discard(change) {
      const target = rootOf(applied.get(change)?.entry ?? change);
      const before = undoStack.length + redoStack.length;
      undoStack = undoStack.filter((entry) => rootOf(entry) !== target);
      redoStack = redoStack.filter((entry) => rootOf(entry) !== target);
      return undoStack.length + redoStack.length !== before;
    },
    undo(rebase) {
      const entry = undoStack.pop();
      if (!entry) return null;
      redoStack.push(entry);
      const inverted = rebase ? rebase(invertChange(entry)) : invertChange(entry);
      applied.set(inverted, { entry, direction: "undo" });
      return inverted;
    },
    redo(rebase) {
      const entry = redoStack.pop();
      if (!entry) return null;
      undoStack.push(entry);
      const replayed: DataChange<TData> = { ...entry, source: "history" };
      const replay = rebase ? rebase(replayed) : replayed;
      applied.set(replay, { entry, direction: "redo" });
      return replay;
    },
    restore(change) {
      const record = applied.get(change);
      if (!record) return false;
      applied.delete(change);
      const from = record.direction === "undo" ? redoStack : undoStack;
      const at = from.findIndex((entry) => rootOf(entry) === rootOf(record.entry));
      if (at < 0) return false;
      const [entry] = from.splice(at, 1);
      // a redo branch cannot sit under a newer undo entry
      if (record.direction === "redo" && at < from.length) return false;
      if (record.direction === "undo") {
        undoStack.push(entry!);
        if (undoStack.length > capacity) undoStack.shift();
      } else redoStack.push(entry!);
      return true;
    },
    replaceRowId(oldId, newId, oldRow, newRow) {
      return this.replaceRowIds([{ oldId, newId, oldRow, newRow }]);
    },
    replaceRowIds(swaps) {
      const bySource = new Map(swaps.map((swap) => [swap.oldId, { newId: swap.newId, patch: rowPatch(swap.oldRow, swap.newRow) }] as const));
      const patchRow = (row: TData, patch: ReturnType<typeof rowPatch>): TData | null => {
        if (!patch || !isPlainObject(row)) return null;
        const next: Record<string, unknown> = { ...row };
        for (const key of patch.unset) delete next[key];
        for (const [key, value] of patch.set) next[key] = value;
        return next as TData;
      };
      const rewriteOp = (op: DataOp<TData>): DataOp<TData> | null => {
        const swap = bySource.get(op.rowId);
        if (!swap) return op;
        const row = patchRow(op.row, swap.patch);
        if (!row) return null;
        if (op.type !== "update") return { ...op, rowId: swap.newId, row };
        const prev = patchRow(op.prev, swap.patch);
        return prev ? { ...op, rowId: swap.newId, row, prev } : null;
      };
      return rewrite((entry) => {
        if (!entry.ops.some((op) => bySource.has(op.rowId))) return entry;
        const ops: DataOp<TData>[] = [];
        for (const op of entry.ops) {
          const mapped = rewriteOp(op);
          if (!mapped) return null;
          ops.push(mapped);
        }
        return { ...entry, ops };
      });
    },
    dropRows(rowIds) {
      const ids = new Set(rowIds);
      return rewrite((entry) => {
        const ops = entry.ops.filter((op) => !ids.has(op.rowId));
        if (ops.length === entry.ops.length) return entry;
        return ops.length === 0 ? null : { ...entry, ops };
      });
    },
    get canUndo() {
      return undoStack.length > 0;
    },
    get canRedo() {
      return redoStack.length > 0;
    },
    clear() {
      undoStack = [];
      redoStack = [];
    },
    setCapacity(next) {
      capacity = next;
      if (undoStack.length > capacity) undoStack = undoStack.slice(undoStack.length - capacity);
    },
    get size() {
      return undoStack.length;
    },
  };
}

import type { DataChange } from "../types";
import { getCellValue, setCellValue } from "../columns/column-helpers";
import { invertChange } from "./history";

/** What {@link buildRollback} reads from the store. */
export type RollbackSource<TData> = { data: readonly unknown[]; getRowId: (row: TData, index: number) => string; columns: readonly { id: string }[] };

function shallowEqualRows(a: unknown, b: unknown): boolean {
  if (Object.is(a, b)) return true;
  if (typeof a !== "object" || typeof b !== "object" || a === null || b === null) return false;
  const keys = Object.keys(a);
  return keys.length === Object.keys(b).length && keys.every((k) => Object.is((a as never)[k], (b as never)[k]));
}

/**
 * Builds the inverse of `change` against the current data: a cell reverts only while it still holds
 * the change's value, so later edits to the same row (or the same cell) survive the rollback.
 * The result names `change` in `reverts`.
 */
export function buildRollback<TData>(change: DataChange<TData>, s: RollbackSource<TData>): DataChange<TData> {
  const rowById = new Map<string, TData>();
  (s.data as readonly TData[]).forEach((row, i) => {
    if (row === undefined) return;
    const id = s.getRowId(row, i);
    if (!rowById.has(id)) rowById.set(id, row);
  });
  const columnsById = new Map(s.columns.map((c) => [c.id, c] as const));
  const working = new Map<string, TData>();
  const ops: DataChange<TData>["ops"] = [];
  const reinsertedAt = new Map<string, number>();
  const pushUpdate = (update: Extract<DataChange<TData>["ops"][number], { type: "update" }>) => {
    const at = reinsertedAt.get(update.rowId);
    const insert = at === undefined ? undefined : ops[at];
    // a batch applies an update before the insert that creates its row, so the update folds into the insert
    if (at !== undefined && insert?.type === "insert") ops[at] = { ...insert, row: update.row };
    else ops.push(update);
  };
  for (const op of [...change.ops].reverse()) {
    if (op.type !== "update") {
      const inverse = invertChange({ ops: [op], source: "rollback" }, "rollback").ops;
      for (const inverted of inverse) {
        if (inverted.type !== "insert") continue;
        working.set(inverted.rowId, inverted.row);
        reinsertedAt.set(inverted.rowId, ops.length + inverse.indexOf(inverted));
      }
      ops.push(...inverse);
      continue;
    }
    const current = working.get(op.rowId) ?? rowById.get(op.rowId);
    if (current === undefined) continue;
    if (!op.cells) {
      if (!shallowEqualRows(current, op.row)) continue;
      pushUpdate({ type: "update", rowId: op.rowId, row: op.prev, prev: current });
      working.set(op.rowId, op.prev);
      continue;
    }
    let row: TData = current;
    const cells: NonNullable<typeof op.cells> = [];
    for (const cell of [...op.cells].reverse()) {
      const column = columnsById.get(cell.columnId);
      if (!column || !Object.is(getCellValue(row, column as never), cell.value)) continue;
      row = setCellValue<TData, never>(row, column as never, cell.prev as never);
      cells.push({ columnId: cell.columnId, value: cell.prev, prev: cell.value });
    }
    if (cells.length > 0) {
      pushUpdate({ type: "update", rowId: op.rowId, row, prev: current, cells });
      working.set(op.rowId, row);
    }
  }
  return { ops, source: "rollback", label: change.label, reverts: change };
}

/**
 * Re-targets an undo or redo `change` at the current rows: an update with cells writes only those
 * cells onto the row as it is now, so values that changed since the edit (a stream push, a refetch) stay.
 * An update without cells, an update for a row that `s.data` lacks, and every insert, delete, and move pass through.
 */
export function rebaseOntoCurrent<TData>(change: DataChange<TData>, s: RollbackSource<TData>): DataChange<TData> {
  if (!change.ops.some((op) => op.type === "update" && op.cells)) return change;
  const rowById = new Map<string, TData>();
  (s.data as readonly TData[]).forEach((row, i) => {
    if (row === undefined) return;
    const id = s.getRowId(row, i);
    if (!rowById.has(id)) rowById.set(id, row);
  });
  const columnsById = new Map(s.columns.map((c) => [c.id, c] as const));
  const working = new Map<string, TData>();
  const ops: DataChange<TData>["ops"] = [];
  for (const op of change.ops) {
    if (op.type === "insert") working.set(op.rowId, op.row);
    if (op.type !== "update" || !op.cells) {
      ops.push(op);
      continue;
    }
    const current = working.get(op.rowId) ?? rowById.get(op.rowId);
    if (current === undefined) {
      ops.push(op);
      continue;
    }
    let row: TData = current;
    const cells: NonNullable<typeof op.cells> = [];
    for (const cell of op.cells) {
      const column = columnsById.get(cell.columnId);
      if (!column) continue;
      cells.push({ columnId: cell.columnId, value: cell.value, prev: getCellValue(row, column as never) });
      row = setCellValue<TData, never>(row, column as never, cell.value as never);
    }
    if (cells.length === 0) continue;
    working.set(op.rowId, row);
    ops.push({ type: "update", rowId: op.rowId, row, prev: current, cells });
  }
  return { ...change, ops };
}

