import { useEffect, useRef, useState } from "react";
import { toSafeText } from "../cell-types/safe-text";
import type { AnyColumnDef, DataGridInternalActions } from "../store";

type AsyncValidateActions = Pick<DataGridInternalActions, "_commitCellEdit" | "_setEditingError">;
import type { StandardSchemaV1Result } from "../types";
import { formatIssues, isStandardSchema, type CellValidate } from "../validation/validate-cell";

/**
 * Intercepts a cell-type editor's `commit(movement)` to support an async Standard Schema
 * `validate` — the ONLY place this repo awaits validation: the async branch lives at the
 * editor-commit layer, never inside a store action. `commitCellEdit`/`computeCommit` stay fully
 * synchronous; a schema whose `~standard.validate` resolves synchronously (the function form, or a
 * sync schema) is forwarded to `commitCellEdit` immediately with ZERO behavior change.
 *
 * When the schema returns a Promise, editing STAYS OPEN: `pending` flips true (the editor sets its
 * input `readOnly` — minimal, reduced-motion-safe treatment that still allows Escape to cancel),
 * and only on resolution does this either call
 * `_commitCellEdit(result.value, movement)` (success — the schema's own transformed value, per spec)
 * or, on issues, `actions._setEditingError(message)` (blocking default — editing continues, same as
 * the sync rejection UX, and the store bumps `editingRejectionCount` — the editors' commit-guard
 * re-arm nonce, single source of truth for sync AND async rejections; the editors re-arm off it,
 * never off "pending cleared", which also happens on Escape/cancel right before unmount) or
 * `_commitCellEdit(value, movement, message)` (`validationMode: "warn"` — the raw value commits and the
 * cell is flagged in `cellErrors`).
 *
 * Race guard: a generation counter bumped on every `commit()` call, on unmount/cancel, and when
 * `session` changes. A resolution whose captured generation no longer matches current is dropped
 * silently — covers Escape/cancel, a newer commit superseding an in-flight one, unmount, and a
 * restarted edit session on the same cell.
 */
export function useAsyncValidate(actions: AsyncValidateActions, column: AnyColumnDef, validate?: CellValidate, session?: number) {
  const [pending, setPending] = useState(false);
  const generationRef = useRef(0);

  useEffect(() => {
    return () => {
      generationRef.current += 1;
      setPending(false);
    };
  }, [session]);

  function commit(value: unknown, movement?: { dx: number; dy: number }): void {
    const validator = validate ?? column.validate;
    if (!isStandardSchema(validator)) {
      actions._commitCellEdit(value, movement);
      return;
    }

    // Peek: a sync-resolving schema (even one that never returns a Promise) takes the sync path — computeCommit re-runs it
    let probe: StandardSchemaV1Result<unknown> | Promise<StandardSchemaV1Result<unknown>>;
    try {
      probe = validator["~standard"].validate(value) as StandardSchemaV1Result<unknown> | Promise<StandardSchemaV1Result<unknown>>;
    } catch (error) {
      // a validator that throws is a rejection for this edit
      actions._setEditingError(errorMessage(error));
      return;
    }
    if (!(probe instanceof Promise)) {
      actions._commitCellEdit(value, movement);
      return;
    }

    const generation = ++generationRef.current;
    setPending(true);
    probe.then(
      (result) => {
        if (generationRef.current !== generation) return; // stale: cancelled/superseded/unmounted
        setPending(false);
        if (result.issues) {
          const message = formatIssues(result.issues);
          // validationMode "warn": commit the raw value and flag the cell — computeCommit's sync re-run cannot see a Promise's issues
          if (column.validationMode === "warn") {
            actions._commitCellEdit(value, movement, message);
            return;
          }
          actions._setEditingError(message);
          return;
        }
        actions._commitCellEdit(result.value, movement);
      },
      (error: unknown) => {
        if (generationRef.current !== generation) return; // stale: cancelled/superseded/unmounted
        // a rejecting promise is a rejection for this edit — unblock the editor the same way a thrown validator does
        setPending(false);
        actions._setEditingError(errorMessage(error));
      },
    );
  }

  /** Escape/cancel while a validation is pending: invalidates it (its resolution is dropped) and clears `pending`. */
  function cancelPending(): void {
    generationRef.current += 1;
    setPending(false);
  }

  return { commit, cancelPending, pending };
}

function errorMessage(error: unknown): string {
  return error instanceof Error ? error.message : toSafeText(error);
}

export const TAP_SLOP_PX = 10;
export const DOUBLE_TAP_MS = 300;
export const LONG_PRESS_MS = 500;

export type TouchPoint = { x: number; y: number };
export type TouchSample = TouchPoint & { time: number };
export type TapSample = TouchSample & { key: string };

export function movedBeyondSlop(start: TouchPoint, point: TouchPoint): boolean {
  const dx = point.x - start.x;
  const dy = point.y - start.y;
  return dx * dx + dy * dy > TAP_SLOP_PX * TAP_SLOP_PX;
}

export function isTap(start: TouchSample, end: TouchSample): boolean {
  return !movedBeyondSlop(start, end) && end.time - start.time < LONG_PRESS_MS;
}

export function isDoubleTap(previous: TapSample | null, next: TapSample): boolean {
  return previous !== null && previous.key === next.key && next.time - previous.time <= DOUBLE_TAP_MS && !movedBeyondSlop(previous, next);
}

export type LongPressTimer = { arm: () => void; cancel: () => void };

export function createLongPressTimer(onFire: () => void): LongPressTimer {
  let handle: ReturnType<typeof setTimeout> | null = null;
  const cancel = () => {
    if (handle !== null) clearTimeout(handle);
    handle = null;
  };
  const arm = () => {
    cancel();
    handle = setTimeout(() => {
      handle = null;
      onFire();
    }, LONG_PRESS_MS);
  };
  return { arm, cancel };
}

/** Captures the pointer on `element`; returns false when the browser refuses (unknown pointer id, detached element) or lacks the API. */
export function safeSetPointerCapture(element: Element | null | undefined, pointerId: number): boolean {
  if (!element?.setPointerCapture) return false;
  try {
    element.setPointerCapture(pointerId);
    return true;
  } catch (error) {
    if (error instanceof DOMException && (error.name === "NotFoundError" || error.name === "InvalidStateError")) return false;
    throw error;
  }
}

