   * that hook's JSDoc for the full disambiguation rule.
   */
   cancelColumnSelectDrag: () => void;
  /**
   * Imperatively scrolls the container so `coord` (view-index) is visible, honoring the
   * pinned-left/right bands. Public extension point for add-ons that move the active cell
   * programmatically, e.g. `data-grid-toolbar`'s search next/prev — never `scrollIntoView`
   * (see {@link scrollCellIntoView}'s own doc for why).
   */
  scrollCellIntoView: (coord: ViewCoord) => void;
};

/**
 * Builds every pointer/keyboard handler the grid root and cells wire up, plus the imperative
 * scroll-into-view/drag-autoscroll machinery. One instance per `<DataGridRoot>` mount.
 */
export function useGridInteraction(options: UseGridInteractionOptions): GridInteractionHandlers {
  const { scrollRef, layout, keymap } = options;
  const actions = useDataGridActions();
  const storeApi = useDataGridStoreApi();
  // Event-time values only: both refs are written in a layout effect (render-time ref writes
  // bail the React Compiler) and read exclusively inside the handlers below.
  const isMacRef = useRef(false);
  const layoutRef = useRef(layout);
  useLayoutEffect(() => {
    isMacRef.current = isMacPlatform();
    layoutRef.current = layout;
  }, [layout]);

  // drag state lives in a ref, never React state — a drag never re-renders anything but the
  // overlay/active-cell subscribers that selection changes already touch. `anchor` is the press row
  // of a plain marker or checkbox drag: with `pendingOffAnchor` it holds the drag back until the
  // pointer leaves that row, and it decides whether the click after the drag is swallowed.
  const dragRef = useRef<{ pointerId: number; mode: "range" | "row" | "column"; anchor?: number; pendingOffAnchor?: boolean; leftAnchor?: boolean; swallowClick?: boolean; armed?: { before: RowRangeGesture | null; armed: RowRangeGesture | null } } | null>(null);
  const rafRef = useRef<number | null>(null);
  const pendingActionFrameRef = useRef<number | null>(null);
  const lastPointerRef = useRef<{ clientX: number; clientY: number } | null>(null);

  // Active-cell click deferred to native `click` — pointerdown alone can't distinguish it from a drag.
  const pendingActiveClickRef = useRef<ViewCoord | null>(null);
  // Pointer capture retargets the click onto the cell, so the anchor is only known at pointerdown.
  const linkPressRef = useRef<ViewCoord | null>(null);
  // Coord a single click just resolved, so the following dblclick (same gesture) doesn't re-resolve it.
  const resolvedByClickRef = useRef<ViewCoord | null>(null);

  // The element that took setPointerCapture for the active drag; released explicitly on end
  // rather than relying on the browser's implicit release, which some environments (real
  // Chromium via Playwright) don't reliably fire before a later, unrelated click gesture —
  // a stale capture otherwise swallows that next gesture's pointerup/click on its real target
  // (e.g. an option in a portaled Select popup opened right after this cell's click).
  const captureElementRef = useRef<Element | null>(null);

  const stopAutoScrollLoop = useCallback(() => {
    if (rafRef.current !== null) {
      cancelAnimationFrame(rafRef.current);
      rafRef.current = null;
    }
  }, []);

  // Self-scheduling rAF re-enters through a ref: a direct self-reference and a hoisted
  // declaration both bail the React Compiler (use-before-declare / PruneHoistedContexts).
  const dragFrameRef = useRef<(() => void) | null>(null);
  const runDragFrame = useCallback(() => {
    const scrollElement = scrollRef.current;
    const pointer = lastPointerRef.current;
    const drag = dragRef.current;
    if (!scrollElement || !pointer || !drag) {
      rafRef.current = null;
      return;
    }
    const rect = scrollElement.getBoundingClientRect();

    // auto-scroll the container by a fixed step per frame while the pointer sits beyond an edge
    let scrolled = false;
    if (pointer.clientY < rect.top + AUTO_SCROLL_ZONE) {
      scrollElement.scrollTop -= AUTO_SCROLL_STEP;
      scrolled = true;
    } else if (pointer.clientY > rect.bottom - AUTO_SCROLL_ZONE) {
      scrollElement.scrollTop += AUTO_SCROLL_STEP;
      scrolled = true;
    }
    // Which physical edge means "scroll toward the inline start" depends on direction; the step is
    // then applied in the container's own scrollLeft convention.
    const direction = layoutRef.current.direction ?? "ltr";
    const inlineStep = inlineAutoScrollStep(pointer.clientX, rect, AUTO_SCROLL_ZONE, direction);
    if (inlineStep !== 0) {
      applyInlineScrollDelta(scrollElement, inlineStep * AUTO_SCROLL_STEP, direction);
      scrolled = true;
    }

    // Once edge auto-scroll engages, the pressed element will unmount out of the rendered window;
    // the browser releases the capture on unmount and cancels a touch pointer with it. Hand the
    // capture to the scroll element, which outlives the drag.
    if (scrolled && captureElementRef.current && captureElementRef.current !== scrollElement) {
      safeSetPointerCapture(scrollElement, drag.pointerId);
      captureElementRef.current = scrollElement;
    }

    const state = storeApi.getState();
    const rowCount = state.viewIndex.length;
    const coord = pointerToCoord(pointer.clientX, pointer.clientY, scrollElement, layoutRef.current, rowCount);
    const clamped = {
      col: Math.max(0, Math.min(coord.col, Math.max(0, state.visibleColumns.length - 1))),
      row: Math.max(0, Math.min(coord.row, Math.max(0, rowCount - 1))),
    };

    if (drag.pendingOffAnchor) {
      if (clamped.row === drag.anchor) {
        rafRef.current = requestAnimationFrame(() => dragFrameRef.current?.());
        return;
      }
      drag.pendingOffAnchor = false;
      drag.leftAnchor = true;
    }

    if (drag.mode === "range") actions.extendToAt(clamped);
    else if (drag.mode === "row") {
      if (state.enableRangeSelection) actions.checkRowRange(clamped.row);
    }
    else actions.selectColumn(clamped.col, { extendFromLast: true });

    rafRef.current = requestAnimationFrame(() => dragFrameRef.current?.());
  }, [actions, scrollRef, storeApi]);
  useEffect(() => {
    dragFrameRef.current = runDragFrame;
  }, [runDragFrame]);

  // pointermove/pointerup are attached to `document` only for the lifetime of an active drag —
  // beginDrag attaches them, endDrag tears them down immediately, instead of a permanent
  // always-on subscription.
  const documentListenersRef = useRef<(() => void) | null>(null);

  // Pointer capture retargets the click that follows a drag onto the pressed control; a range drag
  // must not also toggle it.
  const swallowNextClick = useCallback(() => {
    const swallow = (event: MouseEvent) => {
      event.stopPropagation();
      event.preventDefault();
    };
    document.addEventListener("click", swallow, { capture: true, once: true });
    setTimeout(() => document.removeEventListener("click", swallow, true), 0);
  }, []);

  const endDrag = useCallback(() => {
    const pointerId = dragRef.current?.pointerId;
    const captureEl = captureElementRef.current as (Element & { hasPointerCapture?: (id: number) => boolean; releasePointerCapture?: (id: number) => void }) | null;
    if (captureEl && pointerId !== undefined && captureEl.hasPointerCapture?.(pointerId)) {
      captureEl.releasePointerCapture?.(pointerId);
    }
    captureElementRef.current = null;
    dragRef.current = null;
    lastPointerRef.current = null;
    getInternalActions(storeApi)._setSelectionPress(false);
    stopAutoScrollLoop();
    documentListenersRef.current?.();
    documentListenersRef.current = null;
  }, [stopAutoScrollLoop, storeApi]);

  const beginDrag = useCallback(
    (mode: "range" | "row" | "column", pointerId: number, captureElement?: Element, anchor?: number, pendingOffAnchor?: boolean) => {
      dragRef.current = { pointerId, mode, anchor, pendingOffAnchor };
      captureElementRef.current = captureElement ?? null;
      if (rafRef.current === null) rafRef.current = requestAnimationFrame(runDragFrame);

      if (!documentListenersRef.current) {
        // an armed checkbox press that never wrote a row leaves the earlier anchor in place
        const abandonDrag = () => {
          const armed = dragRef.current?.armed;
          if (armed && storeApi.getState().rowRangeGesture === armed.armed) storeApi.setState({ rowRangeGesture: armed.before });
          endDrag();
        };
        const onLostCapture = (event: PointerEvent) => {
          if (dragRef.current?.pointerId === event.pointerId && event.target === captureElementRef.current) abandonDrag();
        };
        const onMove = (event: PointerEvent) => {
          if (!dragRef.current || dragRef.current.pointerId !== event.pointerId) return;
          lastPointerRef.current = { clientX: event.clientX, clientY: event.clientY };
          // Pointer capture still fires `click` on the pressed cell after a drag, even one that ends back there.
          const pending = pendingActiveClickRef.current;
          const linkPress = linkPressRef.current;
          const scrollElement = scrollRef.current;
          if ((pending || linkPress) && scrollElement) {
            const coord = pointerToCoord(event.clientX, event.clientY, scrollElement, layoutRef.current, storeApi.getState().viewIndex.length);
            if (pending && (coord.col !== pending.col || coord.row !== pending.row)) pendingActiveClickRef.current = null;
            if (linkPress && (coord.col !== linkPress.col || coord.row !== linkPress.row)) linkPressRef.current = null;
          }
          // the frame loop kills itself when no move has arrived yet (slow press-then-drag) —
          // restart it here or a drag whose first move lands after frame 1 never paints (user QA).
          if (rafRef.current === null) rafRef.current = requestAnimationFrame(runDragFrame);
        };
        const onUp = (event: PointerEvent) => {
          if (!dragRef.current || dragRef.current.pointerId !== event.pointerId) return;
          // If the capture was handed to the scroll element, the post-drag `click` targets the
          // scroll element and can never reach the pressed cell — the cell's click can't resolve
          // the pending active-cell press anymore, so resolve (or discard) it here, on the true
          // pointerup coordinate. Without the handoff the cell's own `click` resolves it as usual.
          const scrollElement = scrollRef.current;
          if (event.type === "pointercancel" || (scrollElement && captureElementRef.current === scrollElement)) linkPressRef.current = null;
          if (scrollElement && captureElementRef.current === scrollElement) {
            const pending = pendingActiveClickRef.current;
            pendingActiveClickRef.current = null;
            if (event.type !== "pointercancel" && pending && event.detail < 2) {
              const coord = pointerToCoord(event.clientX, event.clientY, scrollElement, layoutRef.current, storeApi.getState().viewIndex.length);
              if (coord.col === pending.col && coord.row === pending.row) {
                const state = storeApi.getState();
                if (!state.readOnly && hasActivateCell(state, pending)) {
                  getInternalActions(storeApi)._activateCellAt(pending);
                  resolvedByClickRef.current = pending;
                }
              }
            }
          }
          const drag = dragRef.current;
          if (event.type === "pointerup" && drag.mode === "row" && drag.swallowClick) swallowNextClick();
          else if (event.type === "pointerup" && drag.mode === "row" && drag.anchor !== undefined && scrollElement) {
            const endRow = pointerToCoord(event.clientX, event.clientY, scrollElement, layoutRef.current, storeApi.getState().viewIndex.length).row;
            if (endRow !== drag.anchor || drag.leftAnchor) swallowNextClick();
          }
          if (event.type === "pointercancel") abandonDrag();
          else endDrag();
        };
        document.addEventListener("pointermove", onMove);
        document.addEventListener("pointerup", onUp);
        document.addEventListener("pointercancel", onUp);
        document.addEventListener("lostpointercapture", onLostCapture);
        window.addEventListener("blur", abandonDrag);
        documentListenersRef.current = () => {
          document.removeEventListener("pointermove", onMove);
          document.removeEventListener("pointerup", onUp);
          document.removeEventListener("pointercancel", onUp);
          document.removeEventListener("lostpointercapture", onLostCapture);
          window.removeEventListener("blur", abandonDrag);
        };
      }
    },
    [actions, runDragFrame, endDrag, scrollRef, storeApi, swallowNextClick],
  );

  // safety net: tear down a still-active drag's listeners/rAF if the component unmounts mid-drag
  useEffect(() => () => documentListenersRef.current?.(), []);
  useEffect(
    () => () => {
      if (pendingActionFrameRef.current !== null) cancelAnimationFrame(pendingActionFrameRef.current);
    },
    [],
  );

  const scrollActiveCellIntoView = useCallback(
    (coord: ViewCoord) => {
      const scrollElement = scrollRef.current;
      if (!scrollElement) return;
      scrollCellIntoView(scrollElement, coord, layoutRef.current);
    },
    [scrollRef],
  );

  const markSelectionPointer = useCallback(
    (pointer: SelectionPointer) => {
      if (storeApi.getState().selectionPointer !== pointer) storeApi.setState({ selectionPointer: pointer });
    },
    [storeApi],
  );

  const lastKeyEvent = useRef<Event | null>(null);
  const onKeyDown = useCallback(
    (event: ReactKeyboardEvent<HTMLElement>) => {
      if (isComposingKey(event)) return;
      if (!MODIFIER_KEYS.has(event.key)) markSelectionPointer("keyboard");
      // Base UI mounts its popup container through a React portal, so React dispatches a popup keydown twice.
      if (lastKeyEvent.current === event.nativeEvent) return;
      lastKeyEvent.current = event.nativeEvent;

      // A key from an editor (inline, or a portaled popup) belongs to that edit even after its own handler ended it; a focused header trigger keeps only Enter and Space for its click.
      const target = event.target as HTMLElement | null;
      const fromEditorInput =
        target !== null &&
        target !== event.currentTarget &&
        (/^(INPUT|SELECT|TEXTAREA)$/.test(target.tagName) ||
          target.isContentEditable ||
          target.closest(gridAttrSelector("cellEditor")) !== null ||
          (isActivationKey(event) && target.closest(`${gridAttrSelector("headerMenuTrigger")}, ${gridAttrSelector("headerFilterTrigger")}, [data-grid-group-toggle]`) !== null) ||
          !event.currentTarget.contains(target));

      const state = storeApi.getState();
      const editing = state.editing;

      // Arrow keys move VISUALLY: under RTL, ArrowRight goes to the next column on the screen,
      // which is the PREVIOUS column index. Swapping the KEY here — the one place a key becomes
      // an action — is what lets every navigation helper, and any consumer's custom keymap, stay
      // written in logical terms (moveLeft/moveRight/extendLeft/jumpLeft). Tab/Shift+Tab are not
      // swapped: they are already reading-order logical. Home/End need no swap either, since
      // moveRowStart/moveRowEnd are logically named and "row start" is column 0 in both directions.
      const keymapEvent: KeymapEvent = {
        key: visualArrowKey(event.key, layoutRef.current.direction ?? "ltr"),
        ctrlKey: event.ctrlKey,
        metaKey: event.metaKey,
        shiftKey: event.shiftKey,
        altKey: event.altKey,
        altGraph: event.getModifierState?.("AltGraph"),
      };

      const dispatch = (action: GridAction) =>
        leavesGridOnTab(action, event.key, storeApi.getState()) ||
        dispatchGridAction({
          action,
          actions,
          storeApi,
          scrollRef,
          scrollCellIntoView: scrollActiveCellIntoView,
          rowHeight: layoutRef.current.rowHeight,
          triggerKey: isPrintableKey(keymapEvent, isMacRef.current) ? keymapEvent.key : undefined,
          preventDefault: () => event.preventDefault(),
          headerColumnId: target?.closest<HTMLElement>("[role='columnheader'][data-column-id]")?.dataset["columnId"],
          pendingFrameRef: pendingActionFrameRef,
        });

      // While a session is open the editor owns the built-in keys; only editor-scoped commands dispatch.
      if (editing || fromEditorInput) {
        const commands = state.commands;
        if (editing && commands) {
          const action = matchKeymap(keymapEvent, keymap, isMacRef.current, (a) => {
            const scope = commands[a]?.scope;
            return scope === "editing" || scope === "always";
          });
          if (action !== null) dispatch(action);
        }
        return;
      }

      const commands = state.commands;
      // An innermost pivot row never opens, so Enter falls to `edit`, which it refuses, and the arrows move.
      const groupIndex = state.activeCell === null ? undefined : groupIndexAt(state.viewIndex, state.activeCell.row);
      const groupNode = groupIndex === undefined ? undefined : state.groupLayout?.rows[groupIndex];
      const onGroupRow = groupNode !== undefined && groupRowExpandable(state, groupNode);
      const offered = (a: GridAction) => (onGroupRow || !GROUP_ROW_ACTIONS.has(a)) && commands?.[a]?.scope !== "editing";
      // unbound printable key = implicit typeToReplace trigger (Excel behavior); a consumer keymap that DEFINES typeToReplace (even []) takes it over and disables the fallback
      const action =
        matchKeymap(keymapEvent, keymap, isMacRef.current, offered) ??
        (isPrintableKey(keymapEvent, isMacRef.current) && keymap.typeToReplace === undefined ? "typeToReplace" : null);

      if (action) dispatch(action);
    },
    [actions, keymap, markSelectionPointer, scrollActiveCellIntoView, scrollRef, storeApi],
  );

  const touchTeardownRef = useRef<(() => void) | null>(null);
  const lastTapRef = useRef<TapSample | null>(null);
  const pressedCoordRef = useRef<ViewCoord | null>(null);

  const endTouchPress = useCallback(() => {
    touchTeardownRef.current?.();
    touchTeardownRef.current = null;
  }, []);
  useEffect(() => endTouchPress, [endTouchPress]);

  // A touch press resolves on release: the document listeners live only for the press, no pointer
  // capture is taken (native pan stays in charge), and a pan, cancel, second finger, or unmount ends it.
  const beginTouchPress = useCallback(
    (event: ReactPointerEvent<HTMLElement>, spec: { tapKey: string; onTap: (doubleTap: boolean) => void; onLongPress?: () => void }) => {
      if (touchTeardownRef.current) {
        endTouchPress();
        lastTapRef.current = null;
        return;
      }
      const { pointerId } = event;
      const start = { x: event.clientX, y: event.clientY, time: event.timeStamp };
      const press = { fired: false };
      const longPress = spec.onLongPress
        ? createLongPressTimer(() => {
            press.fired = true;
            spec.onLongPress?.();
          })
        : null;
      const onMove = (e: PointerEvent) => {
        if (e.pointerId === pointerId && movedBeyondSlop(start, { x: e.clientX, y: e.clientY })) endTouchPress();
      };
      const onLost = (e: PointerEvent) => {
        if (e.pointerId === pointerId) endTouchPress();
      };
      const onEnd = (e: PointerEvent) => {
        if (e.pointerId !== pointerId) return;
        endTouchPress();
        // A long press is not a click: the click after its release must not sort, toggle, or select.
        if (press.fired && e.type === "pointerup") swallowNextClick();
        if (press.fired || e.type !== "pointerup") return;
        const end = { x: e.clientX, y: e.clientY, time: e.timeStamp };
        if (isTap(start, end)) {
          const tap: TapSample = { ...end, key: spec.tapKey };
          const doubleTap = isDoubleTap(lastTapRef.current, tap);
          lastTapRef.current = doubleTap ? null : tap;
          spec.onTap(doubleTap);
        }
      };
      const onBlur = () => endTouchPress();
      document.addEventListener("pointermove", onMove);
      document.addEventListener("pointerup", onEnd);
      document.addEventListener("pointercancel", onEnd);
      document.addEventListener("lostpointercapture", onLost);
      window.addEventListener("blur", onBlur);
      touchTeardownRef.current = () => {
        longPress?.cancel();
        document.removeEventListener("pointermove", onMove);
        document.removeEventListener("pointerup", onEnd);
        document.removeEventListener("pointercancel", onEnd);
        document.removeEventListener("lostpointercapture", onLost);
        window.removeEventListener("blur", onBlur);
      };
      longPress?.arm();
    },
    [endTouchPress, swallowNextClick],
  );

  const openContextMenuFromPress = useCallback(
    (event: ReactPointerEvent<HTMLElement>) => {
      const target = event.target as Element;
      const { clientX, clientY } = event;
      return () => {
        markSelectionPointer("touch");
        if (target.isConnected) target.dispatchEvent(new MouseEvent("contextmenu", { bubbles: true, cancelable: true, button: 2, clientX, clientY }));
      };
    },
    [markSelectionPointer],
  );

  const editCellAt = useCallback(
    (coord: ViewCoord) => {
      const state = storeApi.getState();
      if (state.readOnly) return;
      pendingActiveClickRef.current = null;
      actions.selectCellAt(coord);
      // this gesture's first click may have already resolved the action via onCellClick.
      const alreadyResolved = resolvedByClickRef.current?.col === coord.col && resolvedByClickRef.current?.row === coord.row;
      resolvedByClickRef.current = null;
      if (alreadyResolved) return;
      // checkbox has no edit mode; direct-toggle instead of entering edit mode.
      if (hasActivateCell(state, coord)) getInternalActions(storeApi)._activateCellAt(coord);
      else actions.startEditingAt(coord);
    },
    [actions, storeApi],
  );

  const onCellTouchPress = useCallback(
    (coord: ViewCoord, event: ReactPointerEvent<HTMLElement>) => {
      const hitsCheckbox = pointerHitsCheckboxBox(event);
      beginTouchPress(event, {
        tapKey: `${coord.row}:${coord.col}`,
        onTap: (doubleTap) => {
          markSelectionPointer("touch");
          if (doubleTap && !hitsCheckbox) {
            editCellAt(coord);
            resolvedByClickRef.current = coord;
            return;
          }
          actions.selectCellAt(coord);
          const state = storeApi.getState();
          if (hitsCheckbox && !state.readOnly && hasActivateCell(state, coord)) getInternalActions(storeApi)._activateCellAt(coord);
        },
        onLongPress: openContextMenuFromPress(event),
      });
    },
    [actions, beginTouchPress, editCellAt, markSelectionPointer, openContextMenuFromPress, storeApi],
  );

  const onCellPointerDown = useCallback(
    (coord: ViewCoord, event: ReactPointerEvent<HTMLElement>) => {
      if (event.button !== 0) return;
      // React re-dispatches portaled content's events through the React tree of its logical
      // parent, not the DOM tree — so a press inside a cell's own popup editor (Select/Date,
      // rendered via a portal to document.body) still reaches this handler even though the
      // DOM target is nowhere under this cell. Ignore it; the editor's own handlers own it.
      if (isCellEditorEvent(event)) return;
      pressedCoordRef.current = coord;
      if (event.pointerType === "touch") {
        onCellTouchPress(coord, event);
        return;
      }
      markSelectionPointer(event.pointerType === "pen" ? "pen" : "mouse");
      getInternalActions(storeApi)._setSelectionPress(true);
      const state = storeApi.getState();
      const isMultiKey = isMacRef.current ? event.metaKey : event.ctrlKey;
      linkPressRef.current = isMultiKey && (event.target as HTMLElement | null)?.closest("a") ? coord : null;

      // Excel activation model: a click NEVER starts editing — it only
      // selects; dblclick/Enter/F2/typing edit. Only checkbox cells resolve a stationary
      // click into a direct toggle (a control, not an editor).
      const wasActive =
        !event.shiftKey &&
        !isMultiKey &&
        state.activeCell !== null &&
        state.activeCell.col === coord.col &&
        state.activeCell.row === coord.row &&
        !state.editing;

      if (event.shiftKey) {
        actions.extendToAt(coord);
      } else if (isMultiKey) {
        actions.pushRangeAt(coord);
      } else {
        actions.selectCellAt(coord);
      }

      const plainPress = !event.shiftKey && !isMultiKey && !state.editing;
      if ((wasActive || (plainPress && pointerHitsCheckboxBox(event))) && !state.readOnly && hasActivateCell(state, coord)) {
        // Resolved on the cell's native `click` — pointerdown can't yet tell a click from a drag.
        pendingActiveClickRef.current = coord;
      }

      safeSetPointerCapture(event.currentTarget, event.pointerId);
      beginDrag("range", event.pointerId, event.currentTarget);
    },
    [actions, beginDrag, markSelectionPointer, onCellTouchPress, storeApi],
  );

  const onCellClick = useCallback(
    (coord: ViewCoord, event: ReactMouseEvent<HTMLElement>) => {
      const pressed = pressedCoordRef.current;
      pressedCoordRef.current = null;
      if (
        (!pressed || pressed.col !== coord.col || pressed.row !== coord.row) &&
        !storeApi.getState().editing &&
        event.currentTarget.contains(event.target as Node) &&
        !(event.target as HTMLElement).closest(gridAttrSelector("cellEditor"))
      ) {
        actions.selectCellAt(coord);
      }
      const linkPress = linkPressRef.current;
      linkPressRef.current = null;
      const pending = pendingActiveClickRef.current;
      pendingActiveClickRef.current = null;
      const isMultiKey = isMacRef.current ? event.metaKey : event.ctrlKey;
      if (linkPress && isMultiKey && event.detail < 2 && !storeApi.getState().editing) {
        dispatchGridAction({
          action: "openLink",
          actions,
          storeApi,
          scrollRef,
          scrollCellIntoView: scrollActiveCellIntoView,
          rowHeight: layoutRef.current.rowHeight,
          preventDefault: () => event.preventDefault(),
        });
        return;
      }
      if (!pending || pending.col !== coord.col || pending.row !== coord.row) return;
      // detail >= 2 is a dblclick's second click — onCellDoubleClick resolves that case instead.
      if (event.detail >= 2) return;
      const state = storeApi.getState();
      // Excel model: only checkbox cells act on a stationary click; text/number/etc. never edit here.
      if (hasActivateCell(state, coord)) {
        getInternalActions(storeApi)._activateCellAt(coord);
        resolvedByClickRef.current = coord;
      }
    },
    [actions, scrollActiveCellIntoView, scrollRef, storeApi],
  );

  const onCellDoubleClick = useCallback(
    (coord: ViewCoord, event: ReactMouseEvent<HTMLElement>) => {
      if (isCellEditorEvent(event)) return;
      editCellAt(coord);
    },
    [editCellAt],
  );

  const onHeaderPointerDown = useCallback(
    (columnIndex: number, event: ReactPointerEvent<HTMLElement>) => {
      if (event.button !== 0) return;
      const state = storeApi.getState();
      const selects = state.enableColumnSelection && state.headerClickBehavior === "select";
      if (event.pointerType === "touch") {
        // iOS fires no native contextmenu, so the long press opens the header menu in every click behavior.
        beginTouchPress(event, {
          tapKey: `h:${columnIndex}`,
          onTap: () => {
            if (!selects) return;
            markSelectionPointer("touch");
            actions.selectColumn(columnIndex);
          },
          onLongPress: openContextMenuFromPress(event),
        });
        return;
      }
      if (!selects) return;
      getInternalActions(storeApi)._setSelectionPress(true);
      const isMultiKey = isMacRef.current ? event.metaKey : event.ctrlKey;
      if (event.shiftKey) {
        actions.selectColumn(columnIndex, { extendFromLast: true });
      } else if (isMultiKey) {
        actions.selectColumn(columnIndex, { additive: true });
      } else {
        actions.selectColumn(columnIndex);
      }
      safeSetPointerCapture(event.currentTarget, event.pointerId);
      beginDrag("column", event.pointerId, event.currentTarget);
    },
    [actions, beginDrag, beginTouchPress, markSelectionPointer, openContextMenuFromPress, storeApi],
  );

  const onGroupHeaderPointerDown = useCallback(
    (start: number, end: number, event: ReactPointerEvent<HTMLElement>) => {
      if (event.button !== 0) return;
      const state = storeApi.getState();
      if (!state.enableColumnSelection) return;
      const last = end - 1;
      if (event.pointerType === "touch") {
        beginTouchPress(event, {
          tapKey: `g:${start}:${end}`,
          onTap: () => {
            markSelectionPointer("touch");
            actions.selectColumn(start);
            if (last > start) actions.selectColumn(last, { extendFromLast: true });
          },
        });
        return;
      }
      const isMultiKey = isMacRef.current ? event.metaKey : event.ctrlKey;
      const anchor = state.lastHighlightedCol;
      if (event.shiftKey && anchor !== null) {
        actions.selectColumn(anchor < start ? last : start, { extendFromLast: true });
        return;
      }
      if (isMultiKey) actions.selectColumn(start, { additive: true });
      else actions.selectColumn(start);
      if (last > start) actions.selectColumn(last, { extendFromLast: true });
    },
    [actions, beginTouchPress, markSelectionPointer, storeApi],
  );

  const onMarkerPointerDown = useCallback(
    (viewRowIndex: number, event: ReactPointerEvent<HTMLElement>) => {
      if (event.button !== 0) return;
      if (!storeApi.getState().enableRowSelection) return;
      if (event.pointerType === "touch") {
        beginTouchPress(event, {
          tapKey: `m:${viewRowIndex}`,
          onTap: () => {
            markSelectionPointer("touch");
            actions.selectRow(viewRowIndex);
          },
        });
        return;
      }
      getInternalActions(storeApi)._setSelectionPress(true);
      const isMultiKey = isMacRef.current ? event.metaKey : event.ctrlKey;
      // only a plain press swallows the click that follows a drag; a modified press keeps its own click handling
      const anchor = isMultiKey || event.shiftKey ? undefined : viewRowIndex;
      if (event.shiftKey) {
        actions.checkRowRange(viewRowIndex, { commit: isMultiKey });
      } else if (isMultiKey) {
        actions.selectRow(viewRowIndex, { additive: true });
      } else {
        actions.selectRow(viewRowIndex);
      }
      safeSetPointerCapture(event.currentTarget, event.pointerId);
      beginDrag("row", event.pointerId, event.currentTarget, anchor, anchor !== undefined);
    },
    [actions, beginDrag, beginTouchPress, markSelectionPointer, storeApi],
  );

  const onMarkerCheckboxPointerDown = useCallback(
    (viewRowIndex: number, event: ReactPointerEvent<HTMLElement>) => {
      if (event.button !== 0) return;
      if (!storeApi.getState().enableRowSelection || event.pointerType === "touch") return;
      if (event.shiftKey) {
        onMarkerPointerDown(viewRowIndex, event);
        // the checkbox would toggle on the click after the press and undo the range step
        if (dragRef.current) dragRef.current.swallowClick = true;
        return;
      }
      // arms the range gesture without writing `selection.rows` — a stationary press+release
      // still resolves purely via the checkbox's own click->toggle. lastPointerRef stays unseeded,
      // so runDragFrame's first tick is a no-op; only a real pointermove extends from this anchor.
      getInternalActions(storeApi)._setSelectionPress(true);
      const before = storeApi.getState().rowRangeGesture;
      getInternalActions(storeApi)._armRowDragAnchor(viewRowIndex);
      const armed = storeApi.getState().rowRangeGesture;
      safeSetPointerCapture(event.currentTarget, event.pointerId);
      beginDrag("row", event.pointerId, event.currentTarget, viewRowIndex, true);
      if (dragRef.current) dragRef.current.armed = { before, armed };
    },
    [actions, beginDrag, onMarkerPointerDown, storeApi],
  );

  const beginSelectionHandleDrag = useCallback(
    (corner: "start" | "end", event: ReactPointerEvent<HTMLElement>) => {
      const range = storeApi.getState().selection.current?.range;
      const scrollElement = scrollRef.current;
      if (event.button !== 0 || !range || !scrollElement) return;
      const opposite =
        corner === "end"
          ? { col: range.x, row: range.y }
          : { col: range.x + range.width - 1, row: range.y + range.height - 1 };
      markSelectionPointer(event.pointerType === "touch" ? "touch" : event.pointerType === "pen" ? "pen" : "mouse");
      getInternalActions(storeApi)._setSelectionPress(true);
      actions.selectCellAt(opposite);
      safeSetPointerCapture(scrollElement, event.pointerId);
      beginDrag("range", event.pointerId, scrollElement);
    },
    [actions, beginDrag, markSelectionPointer, scrollRef, storeApi],
  );

  const onRootPointerDown = useCallback(
    (event: ReactPointerEvent<HTMLElement>) => {
      const handle = (event.target as HTMLElement).closest<HTMLElement>(gridAttrSelector("selectionHandle"));
      if (handle) {
        beginSelectionHandleDrag(handle.getAttribute(GRID_ATTR.selectionHandle) === "start" ? "start" : "end", event);
        return;
      }
      // only fires when the pointerdown wasn't already handled (and stopped) by a cell/header
      if (event.target !== event.currentTarget) return;
      // a press inside a portaled popover editor (select/date) is not a click-away, even if it
      // somehow bubbles here — data-grid-cell-editor is the marker both editors' content carries.
      const target = event.target as HTMLElement;
      if (target.closest(gridAttrSelector("cellEditor"))) return;
      actions.clearCellSelection();
    },
    [actions, beginSelectionHandleDrag],
  );

  const onRootPointerDownCapture = markPortaledPointerDown;

  const cancelColumnSelectDrag = useCallback(() => {
    if (dragRef.current?.mode === "column") endDrag();
  }, [endDrag]);

  useEffect(() => stopAutoScrollLoop, [stopAutoScrollLoop]);

  // Click-outside clears the cell range and columns, never the checked rows; attached only while one exists.
  useEffect(() => {
    let attached = false;
    let deferredClear: ReturnType<typeof setTimeout> | undefined;
    const onPointerDown = (event: PointerEvent) => {
      if (event.button !== 0) return;
      const target = event.target as Element | null;
      if (!target || !(target instanceof Element)) return;
      if (scrollRef.current?.contains(target)) return;
      if (target.closest(KEEP_RANGE_SURFACES)) return;
      if (!storeApi.getState().editing) {
        actions.clearCellSelection();
        return;
      }
      // a portaled editor without the marker attribute reaches React after this capture listener
      clearTimeout(deferredClear);
      deferredClear = setTimeout(() => {
        if (!wasPortaledPointerDown(event)) actions.clearCellSelection();
      }, 0);
    };
    const setAttached = (attach: boolean) => {
      if (attach === attached) return;
      if (attach) document.addEventListener("pointerdown", onPointerDown, true);
      else document.removeEventListener("pointerdown", onPointerDown, true);
      attached = attach;
    };
    setAttached(hasCellSelection(storeApi.getState().selection));
    const unsubscribe = storeApi.subscribe((state, prevState) => {
      if (state.selection === prevState.selection) return;
      setAttached(hasCellSelection(state.selection));
    });
    return () => {
      unsubscribe();
      clearTimeout(deferredClear);
      setAttached(false);
    };
  }, [actions, scrollRef, storeApi]);

  return useMemo(
    () => ({
      onKeyDown,
      onCellPointerDown,
      onCellClick,
      onCellDoubleClick,
      onHeaderPointerDown,
      onGroupHeaderPointerDown,
      onMarkerPointerDown,
      onMarkerCheckboxPointerDown,
      onRootPointerDown,
      onRootPointerDownCapture,
      cancelColumnSelectDrag,
      scrollCellIntoView: scrollActiveCellIntoView,
    }),
    [
      onKeyDown,
      onCellPointerDown,
      onCellClick,
      onCellDoubleClick,
      onHeaderPointerDown,
      onGroupHeaderPointerDown,
      onMarkerPointerDown,
      onMarkerCheckboxPointerDown,
      onRootPointerDown,
      onRootPointerDownCapture,
      cancelColumnSelectDrag,
      scrollActiveCellIntoView,
    ],
  );
}

import { type RefObject } from "react";
import type { StoreApi } from "zustand/vanilla";
import { viewIndex, viewIndexes, type ViewCoord, type GridSelection, type CellType, type GridAction, type GridCommandCtx } from "../types";
import type { RowActionName } from "../store/types";
import { getCellValue } from "../columns/column-helpers";
import { safeHref } from "../cell-types/safe-href";
import { getFocusCell, type DataGridActions, type DataGridStoreState } from "../store";
import { GRID_ATTR, gridAttrSelector } from "../data-attributes";
import { isRowRangeLive, selectionIsCursorOnly } from "../selection/row-range-gesture";
import { offersSetFilter } from "../cell-types/capabilities";
import { warnDev } from "../is-dev";
import { allRowsSelectedState } from "../store/hooks";
import { apiHandleOf } from "../store/api";
import { getInternalActions } from "../store/internal-actions";
import { holeRowId } from "../store/compute";
import { reportRowActionSkipped } from "../store/row-action-skip";
import { COLUMN_WIDTH_STEP, shownColumnWidth } from "../columns/column-step";
import { rowOperationTargets } from "../store/row-operation-targets";
import { isReorderMarkerMode } from "../rows/marker-width";
import { dataIndexAt } from "../store/view-rows";
import { isPivotColumn, pivotCellAt } from "../store/pivot-view";
import { groupRowMetaAt } from "../store/group-positions";

const warnedMissingTriggers = new WeakMap<object, Set<string>>();

function warnMissingTriggerOnce(storeApi: object, slotProp: string, message: string): void {
  const warned = warnedMissingTriggers.get(storeApi) ?? new Set<string>();
  warnedMissingTriggers.set(storeApi, warned);
  if (warned.has(slotProp)) return;
  warned.add(slotProp);
  warnDev(message);
}

/**
 * Executes one already-resolved keymap action against the store — the dispatch shared by the
 * in-grid keydown handler and the global-shortcut window layer, so a globally registered action
 * behaves EXACTLY like its in-grid binding (same scrolling, same store-side guards: `insertRowBelow`
 * without `createRow` no-ops, ...). `preventDefault` is the caller's event handler, invoked only for the
 * actions that would preventDefault in-grid.
 * Not part of the public hook surface.
 */
export function dispatchGridAction(args: {
  action: GridAction;
  actions: DataGridActions;
  storeApi: StoreApi<DataGridStoreState>;
  scrollRef: RefObject<HTMLElement | null>;
  scrollCellIntoView: (coord: ViewCoord) => void;
  /** The grid's resolved data-row height (px) — `pageUp`/`pageDown`'s visible-row math. */
  rowHeight: number;
  /** The printable seed char for `typeToReplace`, when the trigger was a printable key; undefined otherwise. */
  triggerKey?: string;
  preventDefault: () => void;
  /** The column of the focused header button; the column menu and filter actions use it instead of the active cell. */
  headerColumnId?: string;
  /** Holds the pending animation frame of a deferred action so the caller can cancel it on unmount. */
  pendingFrameRef?: RefObject<number | null>;
}): void {
  const { action, actions, storeApi, scrollRef, scrollCellIntoView, rowHeight, triggerKey, preventDefault, headerColumnId, pendingFrameRef } = args;
  const state = storeApi.getState();
  const rowCount = state.viewIndex.length;
  const colCount = state.visibleColumns.length;

  const targetColumnIndex = (): number =>
    headerColumnId === undefined ? (state.activeCell?.col ?? -1) : state.visibleColumns.findIndex((column) => column.id === headerColumnId);

  // A command name shadowing a built-in action wins; callers check the command's scope.
  const command = state.commands?.[action];
  if (command) {
    const api = apiHandleOf<unknown>(storeApi);
    const coord = state.activeCell;
    const dataRowIndex = coord === null ? undefined : dataIndexAt(state, coord.row);
    const row = dataRowIndex === undefined ? undefined : state.data[dataRowIndex];
    const cell =
      coord === null
        ? null
        : {
            // Every view rebuild clamps the cursor, so an unresolved row id stays a defensive fallback.
            rowId:
              dataRowIndex === undefined
                ? ""
                : row === undefined
                  ? holeRowId(dataRowIndex)
                  : state.getRowId(row, dataRowIndex),
            columnId: state.visibleColumns[coord.col]?.id ?? "",
          };
    const ctx: GridCommandCtx = {
      api,
      cell,
      viewRowIndex: coord === null ? null : coord.row,
      viewColumnIndex: coord === null ? null : coord.col,
      row,
      readOnly: state.readOnly,
    };
    if (command.when?.(ctx) === false) return;
    preventDefault();
    command.run(ctx);
    return;
  }

  const runRowOperation = (name: RowActionName, run: (rows: number[]) => void, { checkedWins = false } = {}) => {
    // a move keeps acting on the checked rows alone, also while a cell click would clear them (until-click)
    const targets = rowOperationTargets(checkedWins ? { ...state, checkedRowsLifetime: "until-cleared" } : state, state.activeCell?.row);
    if (targets.reason) getInternalActions(storeApi)._skipRowAction(name, targets.reason);
    else if (targets.rows.length > 0) run(targets.rows);
  };

  const moveAndScroll = (d: { dx: number; dy: number }, opts?: { extend?: boolean; retain?: boolean }) => {
    getInternalActions(storeApi)._moveActiveCell(d, opts);
    // extend keeps activeCell pinned at the anchor — scroll the growing selection's edge instead.
    const next = getFocusCell(storeApi.getState());
    if (next) scrollCellIntoView(next);
  };

  /** Moves the checked row range edge (and the active cell) to the row `targetOf` names for the current edge; false when no row range gesture is waiting for a key step. */
  const stepCheckedRows = (targetOf: (edge: number) => number): boolean => {
    const s = storeApi.getState();
    const gesture = s.rowRangeGesture;
    if (!s.enableRowSelection || !s.enableRangeSelection || !isRowRangeLive(gesture, s.selection, s.viewIndex)) return false;
    if (gesture.current !== s.selection.current || !selectionIsCursorOnly(s.selection)) return false;
    const target = Math.max(0, Math.min(targetOf(gesture.edge), s.viewIndex.length - 1));
    actions.checkRowRange(target);
    moveAndScroll({ dx: 0, dy: target - (s.activeCell?.row ?? 0) }, { retain: true });
    return true;
  };

  const jumpAndScroll = (direction: JumpDirection, opts?: { extend?: boolean }) => {
    const active = (opts?.extend ? getFocusCell(state) : state.activeCell) ?? { col: 0, row: 0 };
    const target = jumpToDataBoundary(state, active, direction);
    if (opts?.extend) actions.extendToAt(target);
    else actions.selectCellAt(target);
    scrollCellIntoView(target);
  };

  const startEditingAndReveal = (coord: ViewCoord, initialText?: string) => {
    actions.startEditingAt(coord, initialText);
    if (storeApi.getState().editing) scrollCellIntoView(coord);
  };

  const openActiveColumnTrigger = (triggerAttr: "headerMenuTrigger" | "headerFilterTrigger", triggerLabel: string, slotProp: string, offered: (column: (typeof state.visibleColumns)[number]) => boolean = () => true) => {
    preventDefault();
    const active = state.activeCell;
    const column = headerColumnId !== undefined ? state.visibleColumns.find((candidate) => candidate.id === headerColumnId) : active && state.visibleColumns[active.col];
    if (!column || !offered(column)) return;
    const findTrigger = () => scrollRef.current?.querySelector<HTMLElement>(`[data-column-id="${CSS.escape(column.id)}"] ${gridAttrSelector(triggerAttr)}`);
    const open = (trigger: HTMLElement) => {
      trigger.setAttribute(GRID_ATTR.keyboardOpen, "");
      trigger.click();
      trigger.removeAttribute(GRID_ATTR.keyboardOpen);
    };
    if (headerColumnId === undefined && active) scrollCellIntoView(active);
    const mounted = findTrigger();
    if (mounted) {
      open(mounted);
      return;
    }
    // the header is virtualized out until the scroll lands and a frame renders it
    const retry = () => {
      if (!scrollRef.current) return;
      const trigger = findTrigger();
      if (trigger) open(trigger);
      else warnMissingTriggerOnce(storeApi, slotProp, `${action} found no ${triggerLabel} for "${column.id}"; wire ${slotProp} to enable it`);
    };
    const frame = requestAnimationFrame(() => {
      const second = requestAnimationFrame(retry);
      if (pendingFrameRef) pendingFrameRef.current = second;
    });
    if (pendingFrameRef) pendingFrameRef.current = frame;
  };

  switch (action) {
    case "moveUp":
    case "moveDown":
    case "moveLeft":
    case "moveRight": {
      preventDefault();
      moveAndScroll(MOVE_DELTA[action]);
      break;
    }
    case "moveUpKeepSelection":
    case "moveDownKeepSelection":
    case "moveLeftKeepSelection":
    case "moveRightKeepSelection": {
      preventDefault();
      moveAndScroll(MOVE_DELTA[action], { retain: true });
      break;
    }
    case "scrollActiveIntoView": {
      preventDefault();
      const active = storeApi.getState().activeCell;
      if (active) scrollCellIntoView(active);
      break;
    }
    case "extendUp":
    case "extendDown":
    case "extendLeft":
    case "extendRight": {
      preventDefault();
      if (action !== "extendLeft" && action !== "extendRight" && stepCheckedRows((edge) => edge + MOVE_DELTA[action].dy)) break;
      moveAndScroll(MOVE_DELTA[action], { extend: true });
      break;
    }
    case "jumpUp":
    case "jumpDown":
    case "jumpLeft":
    case "jumpRight": {
      preventDefault();
      jumpAndScroll(JUMP_DIRECTION[action]);
      break;
    }
    case "extendJumpUp":
    case "extendJumpDown":
    case "extendJumpLeft":
    case "extendJumpRight": {
      preventDefault();
      jumpAndScroll(JUMP_DIRECTION[action], { extend: true });
      break;
    }
    case "moveRowStart": {
      preventDefault();
      const active = state.activeCell ?? { col: 0, row: 0 };
      const target = { col: 0, row: active.row };
      actions.selectCellAt(target);
      scrollCellIntoView(target);
      break;
    }
    case "moveRowEnd": {
      preventDefault();
      const active = state.activeCell ?? { col: 0, row: 0 };
      const target = { col: Math.max(0, colCount - 1), row: active.row };
      actions.selectCellAt(target);
      scrollCellIntoView(target);
      break;
    }
    case "moveFirstCell": {
      preventDefault();
      const target = { col: 0, row: 0 };
      actions.selectCellAt(target);
      scrollCellIntoView(target);
      break;
    }
    case "moveLastCell": {
      preventDefault();
      const target = { col: Math.max(0, colCount - 1), row: Math.max(0, rowCount - 1) };
      actions.selectCellAt(target);
      scrollCellIntoView(target);
      break;
    }
    case "extendFirstCell": {
      preventDefault();
      actions.extendToAt({ col: 0, row: 0 });
      const focus = getFocusCell(storeApi.getState());
      if (focus) scrollCellIntoView(focus);
      break;
    }
    case "extendLastCell": {
      preventDefault();
      actions.extendToAt({ col: Math.max(0, colCount - 1), row: Math.max(0, rowCount - 1) });
      const focus = getFocusCell(storeApi.getState());
      if (focus) scrollCellIntoView(focus);
      break;
    }
    case "extendRowsToStart":
    case "extendRowsToEnd":
    case "extendRowsPageUp":
    case "extendRowsPageDown": {
      const page = visiblePageRows(scrollRef.current, rowHeight);
      const targetOf: Record<typeof action, (edge: number) => number> = {
        extendRowsToStart: () => 0,
        extendRowsToEnd: () => rowCount - 1,
        extendRowsPageUp: (edge) => edge - page,
        extendRowsPageDown: (edge) => edge + page,
      };
      if (stepCheckedRows(targetOf[action])) preventDefault();
      break;
    }
    case "pageUp":
    case "pageDown": {
      preventDefault();
      const visibleRows = visiblePageRows(scrollRef.current, rowHeight);
      moveAndScroll({ dx: 0, dy: action === "pageUp" ? -visibleRows : visibleRows });
      break;
    }
    case "selectRow": {
      preventDefault();
      const active = state.activeCell;
      if (active) actions.selectRow(active.row, { additive: false });
      break;
    }
    case "selectColumn": {
      preventDefault();
      const active = state.activeCell;
      if (active) actions.selectColumn(active.col, { additive: false });
      break;
    }
    case "selectAll": {
      preventDefault();
      actions.selectAll();
      break;
    }
    case "toggleRow": {
      preventDefault();
      const active = state.activeCell;
      if (active) actions.setRowCheckedAt(viewIndex(active.row), !state.selection.rows.hasIndex(active.row));
      break;
    }
    case "toggleAllRows": {
      preventDefault();
      actions.setAllRowsChecked(allRowsSelectedState(state) !== "checked");
      break;
    }
    case "openColumnMenu":
      openActiveColumnTrigger("headerMenuTrigger", "column menu trigger", "renderHeaderMenu");
      break;
    case "openColumnFilter":
      openActiveColumnTrigger("headerFilterTrigger", "column filter trigger", "renderHeaderFilter", (column) => offersSetFilter(column, state.cellTypes[column.type ?? "text"]));
      break;
    case "edit": {
      preventDefault();
      if (state.readOnly || !state.activeCell) break;
      if (hasActivateCell(state, state.activeCell)) getInternalActions(storeApi)._activateCellAt(state.activeCell);
      else startEditingAndReveal(state.activeCell);
      break;
    }
    case "typeToReplace": {
      if (state.readOnly || !state.activeCell) break;
      preventDefault();
      if (hasActivateCell(state, state.activeCell)) break; // checkbox cells have no edit mode; the edit action toggles them, type-to-replace ignores them
      // printable trigger seeds the typed char (Excel replace mode); a non-printable binding (e.g. F3) starts a plain edit
      startEditingAndReveal(state.activeCell, triggerKey);
      break;
    }
    case "focusSearch": {
      if (!state.focusSearchImpl) break;
      preventDefault();
      state.focusSearchImpl();
      break;
    }
    case "cancel": {
      preventDefault();
      getInternalActions(storeApi)._cancelSelection();
      break;
    }
    case "clearContents": {
      preventDefault();
      if (!state.readOnly) actions.deleteSelection();
      break;
    }
    case "insertRowBelow":
    case "insertRowAbove": {
      preventDefault();
      if (!state.activeCell) break;
      // Without createRow, insertRow warns on every press; report the skip here instead.
      if (state.readOnly) reportRowActionSkipped(state, "insertRows", "readOnly");
      else if (!state.createRow) reportRowActionSkipped(state, "insertRows", "no-factory");
      else actions.insertRow(state.activeCell.row, action === "insertRowBelow" ? "below" : "above");
      break;
    }
    case "duplicateRow": {
      preventDefault();
      runRowOperation("duplicateRows", (rows) => actions.duplicateRowsAt(viewIndexes(rows)));
      break;
    }
    case "moveRowsUp":
    case "moveRowsDown": {
      preventDefault();
      if (!isReorderMarkerMode(state.rowMarkers)) {
        reportRowActionSkipped(state, "moveRows", "disabled");
        break;
      }
      let moved = false;
      runRowOperation("moveRows", (rows) => {
        moved = actions.moveRowsBy(rows, action === "moveRowsUp" ? -1 : 1);
      }, { checkedWins: true });
      const active = storeApi.getState().activeCell;
      if (moved && active) scrollCellIntoView(active);
      break;
    }
    case "deleteRows": {
      preventDefault();
      if (!state.enableRowDelete) {
        reportRowActionSkipped(state, "deleteRows", "disabled");
        break;
      }
      runRowOperation("deleteRows", (rows) => actions.deleteRowsAt(viewIndexes(rows)));
      break;
    }
    case "moveColumnTowardStart":
    case "moveColumnTowardEnd": {
      preventDefault();
      const index = targetColumnIndex();
      const step = action === "moveColumnTowardStart" ? -1 : 1;
      const column = state.visibleColumns[index];
      const neighbor = state.visibleColumns[index + step];
      if (!column || !neighbor || !actions.setColumnOrder(column.id, neighbor.id, step === -1 ? "before" : "after").ok) break;
      const active = storeApi.getState().activeCell;
      if (active) scrollCellIntoView(active);
      break;
    }
    case "widenColumn":
    case "narrowColumn": {
      preventDefault();
      const column = state.visibleColumns[targetColumnIndex()];
      if (!column || column.resizable === false) break;
      const width = shownColumnWidth(scrollRef.current, column, state.columnWidths);
      actions.setColumnWidth(column.id, width + (action === "widenColumn" ? COLUMN_WIDTH_STEP : -COLUMN_WIDTH_STEP));
      break;
    }
    case "toggleGroupRow":
    case "expandGroupRow":
    case "collapseGroupRow": {
      const group = state.activeCell ? groupRowMetaAt(state, state.activeCell.row) : null;
      if (!group) break;
      preventDefault();
      const changesState = action === "toggleGroupRow" || (action === "expandGroupRow") !== group.expanded;
      if (changesState) actions.toggleGroup(group.node.id);
      else dispatchGridAction({ ...args, action: action === "expandGroupRow" ? "moveRight" : "moveLeft" });
      break;
    }
    case "openCellMenu": {
      preventDefault();
      if (!state.activeCell) break;
      scrollCellIntoView(state.activeCell);
      const cell = scrollRef.current?.querySelector(gridAttrSelector("active"));
      if (!cell) break;
      const rect = cell.getBoundingClientRect();
      cell.dispatchEvent(new MouseEvent("contextmenu", { bubbles: true, cancelable: true, button: 2, clientX: rect.left + rect.width / 2, clientY: rect.top + rect.height / 2 }));
      break;
    }
    case "openLink": {
      // reads data only: runs in a read-only grid; during an edit session the grid's keydown never fires.
      preventDefault();
      const active = state.activeCell;
      if (!active) break;
      const column = state.visibleColumns[active.col];
      const href = cellTypeAt(state, active)?.href;
      if (!column || !href) break;
      const dataRowIndex = dataIndexAt(state, active.row);
      const row = dataRowIndex === undefined ? undefined : state.data[dataRowIndex];
      if (row === undefined) break; // lazy hole: nothing to link
      const link = href(getCellValue<unknown, typeof column>(row, column), column.options);
      const safe = link ? safeHref(link) : null;
      if (safe) window.open(safe, "_blank", "noopener,noreferrer");
      break;
    }
  }
}

function cellTypeAt(state: DataGridStoreState, coord: ViewCoord): CellType | undefined {
  return state.cellTypes[state.visibleColumns[coord.col]?.type ?? "text"];
}

/** Whether the cell's type declares `activate` — the gesture semantics come from the type, not the name. */
export function hasActivateCell(state: DataGridStoreState, coord: ViewCoord): boolean {
  return cellTypeAt(state, coord)?.activate != null;
}

/** Direction for a data-boundary (Ctrl/Cmd+Arrow) jump. */
export type JumpDirection = "up" | "down" | "left" | "right";

/**
 * Excel-style Ctrl/Cmd+Arrow "jump to data boundary": from `active`, scans view rows/columns in
 * `direction` using the cell type's `isEmpty`. If `active` and the next cell are both non-empty, jumps
 * to the last non-empty cell of the contiguous run; if `active` is empty and the next cell is not,
 * jumps to the next cell; otherwise jumps to the first non-empty cell found (or the grid edge if none).
 * Clamped at the grid edges either way.
 * Exported for direct unit testing of the boundary-scan math; not part of the public hook surface.
 */
export function jumpToDataBoundary(state: DataGridStoreState, active: ViewCoord, direction: JumpDirection): ViewCoord {
  const rowCount = state.viewIndex.length;
  const colCount = state.visibleColumns.length;
  const dx = direction === "left" ? -1 : direction === "right" ? 1 : 0;
  const dy = direction === "up" ? -1 : direction === "down" ? 1 : 0;

  const isEmptyAt = (coord: ViewCoord): boolean => {
    const column = state.visibleColumns[coord.col];
    if (!column) return true;
    if (isPivotColumn(column)) return pivotCellAt(state, coord.row, column) === null;
    const dataRowIndex = dataIndexAt(state, coord.row);
    const row = dataRowIndex === undefined ? undefined : state.data[dataRowIndex];
    if (row === undefined) return true;
    const cellType = state.cellTypes[column.type ?? "text"];
    if (!cellType) return true;
    // explicit TData=unknown: row's `undefined`-narrowed type ({} | null) would otherwise drive inference instead of column's own already-unknown TData.
    const value = getCellValue<unknown, typeof column>(row, column);
    return cellType.isEmpty(value);
  };

  const inBounds = (coord: ViewCoord): boolean =>
    coord.col >= 0 && coord.col < colCount && coord.row >= 0 && coord.row < rowCount;

  const clampToEdge = (): ViewCoord => {
    // no data at all beyond `active` in this direction: land on the grid edge
    let coord = active;
    while (inBounds({ col: coord.col + dx, row: coord.row + dy })) {
      coord = { col: coord.col + dx, row: coord.row + dy };
    }
    return coord;
  };

  const next = { col: active.col + dx, row: active.row + dy };
  if (!inBounds(next)) return active;

  if (!isEmptyAt(next)) {
    // from an empty cell the first non-empty cell is the target; from a filled one, land on the last cell of the run
    if (isEmptyAt(active)) return next;
    let coord = next;
    while (true) {
      const after = { col: coord.col + dx, row: coord.row + dy };
      if (!inBounds(after) || isEmptyAt(after)) return coord;
      coord = after;
    }
  }

  // next is empty: scan forward for the first non-empty cell; else land on the grid edge
  let coord = next;
  while (inBounds(coord)) {
    if (!isEmptyAt(coord)) return coord;
    const after = { col: coord.col + dx, row: coord.row + dy };
    if (!inBounds(after)) return clampToEdge();
    coord = after;
  }
  return clampToEdge();
}

/** Rows a PageUp or PageDown step moves: the visible rows minus four, 10 before the scroll element mounts. */
function visiblePageRows(scrollElement: HTMLElement | null, rowHeight: number): number {
  return scrollElement ? Math.max(1, Math.floor(scrollElement.clientHeight / rowHeight) - 4) : 10;
}

/** Move/extend actions that resolve through {@link MOVE_DELTA} — kept as its own union so the map is total (no `!` needed at the call site). */
type MoveAction = "moveUp" | "moveDown" | "moveLeft" | "moveRight" | "moveUpKeepSelection" | "moveDownKeepSelection" | "moveLeftKeepSelection" | "moveRightKeepSelection" | "extendUp" | "extendDown" | "extendLeft" | "extendRight";

/** Jump/extend-jump actions that resolve through {@link JUMP_DIRECTION} — kept as its own union so the map is total (no `!` needed at the call site). */
type JumpAction = "jumpUp" | "jumpDown" | "jumpLeft" | "jumpRight" | "extendJumpUp" | "extendJumpDown" | "extendJumpLeft" | "extendJumpRight";

/** Movement deltas for the plain move* / extend* actions. */
const MOVE_DELTA: Record<MoveAction, { dx: number; dy: number }> = {
  moveUp: { dx: 0, dy: -1 },
  moveDown: { dx: 0, dy: 1 },
  moveLeft: { dx: -1, dy: 0 },
  moveRight: { dx: 1, dy: 0 },
  moveUpKeepSelection: { dx: 0, dy: -1 },
  moveDownKeepSelection: { dx: 0, dy: 1 },
  moveLeftKeepSelection: { dx: -1, dy: 0 },
  moveRightKeepSelection: { dx: 1, dy: 0 },
  extendUp: { dx: 0, dy: -1 },
  extendDown: { dx: 0, dy: 1 },
  extendLeft: { dx: -1, dy: 0 },
  extendRight: { dx: 1, dy: 0 },
};

const JUMP_DIRECTION: Record<JumpAction, JumpDirection> = {
  jumpUp: "up",
  jumpDown: "down",
  jumpLeft: "left",
  jumpRight: "right",
  extendJumpUp: "up",
  extendJumpDown: "down",
  extendJumpLeft: "left",
  extendJumpRight: "right",
};

export function hasCellSelection(selection: GridSelection): boolean {
  return selection.current !== null || selection.columns.length > 0;
}

import { type ColumnPin, type ViewCoord } from "../types";
import { applyInlineScrollDelta, inlineStartX, normalizeScrollLeft, type GridDirection } from "../virtualization/direction";

/** Column/row layout the interaction hook needs to translate pointer px <-> view coords and to scroll a cell into view. */
export type InteractionLayout = {
  /** Cumulative left edge (px) of each visible column's track, data-space index. */
  trackLefts: readonly number[];
  /** Cumulative right edge (px) of each visible column's track, data-space index. */
  trackRights: readonly number[];
  rowHeight: number;
  /** Offset (px) from the scroll element's top to where data row 0 starts: the sticky header track PLUS any pinned-top row band. NOT the header track alone (that's the root context's `headerHeight`). */
  dataRowTop: number;
  /** Pinned-bottom row band height (px) — the effective viewport bottom is `clientHeight - pinnedBottomHeight`. 0 when there's no pinned-bottom band. */
  pinnedBottomHeight: number;
  /** Total pinned-left band width in px (cells must stay clear of this on the left). */
  pinnedLeftWidth: number;
  /** Total pinned-right band width in px (cells must stay clear of this on the right). */
  pinnedRightWidth: number;
  /** Per-column pin state, same order/index as trackLefts/trackRights — lets pointer math hit-test the static pinned bands instead of the scrolled content space. */
  pins: readonly (ColumnPin | undefined)[];
  /**
   * Layout direction of the grid. Every physical pointer coordinate is converted to the
   * inline-start-relative axis this layout's offsets are expressed in before any hit-test runs, so
   * the math below is direction-agnostic. Defaults to `"ltr"` when a caller omits it.
   */
  direction?: GridDirection;
};

/**
 * Resolves the view-index column index under `inlineX` — the pointer's distance from the viewport's
 * INLINE-START edge (the left edge in LTR, the right edge in RTL), not a physical screen x. Pinned
 * columns render at a fixed inline offset independent of scrollLeft (see pinnedInsetStyle), so
 * they're hit-tested directly in that space; only the unpinned middle band needs the content-space
 * (scrollLeft-adjusted) `contentX`.
 *
 * Because both inputs are already inline-start-relative and every offset this compares against
 * (trackLefts/trackRights/pin widths) is too, this function has no direction awareness of its own —
 * pointerToCoord normalizes at the seam and everything here is shared by both directions.
 *
 * All interval tests are half-open (`>= start && < end`) so a pointer exactly on the boundary two
 * cells share always resolves to the later one, in both directions. RTL's fractional layout can
 * land a point precisely on such an edge where LTR would not, so this is what keeps the resolution
 * deterministic rather than a coin flip on sub-pixel rounding.
 */
function columnAtX(
  inlineX: number,
  contentX: number,
  trackLefts: readonly number[],
  trackRights: readonly number[],
  pins: readonly (ColumnPin | undefined)[],
  pinnedLeftWidth: number,
  viewportWidth: number,
  pinnedRightWidth: number,
): number {
  if (inlineX < pinnedLeftWidth) {
    // pinned-left band: inline-start offset equals the cumulative pinned-left width prefix,
    // which is numerically the same as trackLefts/trackRights restricted to that prefix.
    // trackLefts/trackRights/pins are same-length parallel arrays (built together by the caller)
    for (let i = 0; i < trackLefts.length; i++) {
      if (pins[i] === "start" && inlineX >= trackLefts[i]! && inlineX < trackRights[i]!) return i;
    }
  } else if (inlineX >= viewportWidth - pinnedRightWidth) {
    // pinned-right band: mirror the same static-position reasoning from the inline-END edge.
    const fromRight = viewportWidth - inlineX;
    let acc = 0;
    for (let i = trackLefts.length - 1; i >= 0; i--) {
      if (pins[i] !== "end") continue;
      const width = trackRights[i]! - trackLefts[i]!;
      if (fromRight >= acc && fromRight < acc + width) return i;
      acc += width;
    }
  }
  for (let i = 0; i < trackLefts.length; i++) {
    if (pins[i]) continue;
    if (contentX >= trackLefts[i]! && contentX < trackRights[i]!) return i;
  }
  if (trackLefts.length === 0) return 0;
  return contentX < trackLefts[0]! ? 0 : trackLefts.length - 1;
}

/** Resolves the view-index row index at content-space `y` (already offset by scrollTop, header-relative). */
function rowAtY(y: number, rowHeight: number, rowCount: number): number {
  const row = Math.floor(y / rowHeight);
  return Math.max(0, Math.min(row, Math.max(0, rowCount - 1)));
}

/**
 * Maps a pointer event's viewport-relative position to a view-index cell coord using the current
 * scroll offsets. The SDK exports it for add-on authors.
 */
export function pointerToCoord(
  clientX: number,
  clientY: number,
  scrollElement: HTMLElement,
  layout: InteractionLayout,
  rowCount: number,
): ViewCoord {
  const rect = scrollElement.getBoundingClientRect();
  // The direction seam for all pointer input: past these two lines every x is inline-start-relative
  // and matches the space trackLefts/trackRights/pin widths are already expressed in, so no
  // hit-testing below this point knows or asks about direction.
  const inlineX = inlineStartX(clientX, rect, layout.direction ?? "ltr");
  const contentX = inlineX + normalizeScrollLeft(scrollElement.scrollLeft);
  const y = clientY - rect.top - layout.dataRowTop + scrollElement.scrollTop;
  const col = columnAtX(
    inlineX,
    contentX,
    layout.trackLefts,
    layout.trackRights,
    layout.pins,
    layout.pinnedLeftWidth,
    scrollElement.clientWidth,
    layout.pinnedRightWidth,
  );
  const row = rowAtY(y, layout.rowHeight, rowCount);
  return { col, row };
}

/**
 * Imperatively scrolls the container so `coord` is visible (nearest behavior), honoring the
 * pinned-left/right bands. Never uses `scrollIntoView` — cells live in the transformed
 * sticky-viewport layer, so only direct `scrollTop`/`scrollLeft` writes are architecturally safe.
 */
export function scrollCellIntoView(scrollElement: HTMLElement, coord: ViewCoord, layout: InteractionLayout): void {
  const { trackLefts, trackRights, rowHeight, dataRowTop, pinnedBottomHeight, pinnedLeftWidth, pinnedRightWidth } = layout;
  const cellTop = coord.row * rowHeight;
  const cellBottom = cellTop + rowHeight;
  const viewTop = scrollElement.scrollTop;
  const viewBottom = viewTop + scrollElement.clientHeight - dataRowTop - pinnedBottomHeight;

  let nextScrollTop: number | null = null;
  if (cellTop < viewTop) nextScrollTop = cellTop;
  else if (cellBottom > viewBottom) nextScrollTop = cellBottom - (scrollElement.clientHeight - dataRowTop - pinnedBottomHeight);

  // Inline axis in normalized (positive, inline-start-relative) space, the same space trackLefts
  // and the pin widths live in — so the visibility test itself is shared by both directions.
  const scrollLeft = normalizeScrollLeft(scrollElement.scrollLeft);
  const cellLeft = trackLefts[coord.col] ?? 0;
  const cellRight = trackRights[coord.col] ?? cellLeft;
  const viewLeft = scrollLeft + pinnedLeftWidth;
  const viewRight = scrollLeft + scrollElement.clientWidth - pinnedRightWidth;

  let nextScrollLeft: number | null = null;
  if (cellLeft < viewLeft) nextScrollLeft = cellLeft - pinnedLeftWidth;
  else if (cellRight > viewRight) nextScrollLeft = cellRight - (scrollElement.clientWidth - pinnedRightWidth);

  if (nextScrollTop !== null) scrollElement.scrollTop = Math.max(0, nextScrollTop);
  if (nextScrollLeft !== null) {
    // Applied as a RELATIVE inline delta rather than an absolute write: `scrollLeft` means
    // different things in each direction (RTL runs negative), and a relative move is correct in
    // both without this function ever reconstructing the container's own convention. The
    // Math.max(0, …) floor the absolute write needed would have pinned RTL scrolling to zero.
    applyInlineScrollDelta(scrollElement, Math.max(0, nextScrollLeft) - scrollLeft, layout.direction ?? "ltr");
  }
}

import { GRID_ROLE_SELECTOR, gridAttrSelector } from "../data-attributes";

const GRID_ROOT_SELECTOR = `:is(${GRID_ROLE_SELECTOR})${gridAttrSelector("instance")}`;

/** The innermost grid root around `node`, crossing shadow roots, so a nested grid's elements never count as its host's. */
export function closestGridRoot(node: Node | null): Element | null {
  let element = node instanceof Element ? node : (node?.parentElement ?? null);
  while (element) {
    const found = element.closest(GRID_ROOT_SELECTOR);
    if (found) return found;
    const root = element.getRootNode();
    element = root instanceof ShadowRoot ? root.host : null;
  }
  return null;
}

import type { KeyboardEvent as ReactKeyboardEvent } from "react";

/** Whether a key belongs to an IME composition; Safari sends the confirming Enter with `isComposing` false and keyCode 229. */
export function isComposingKey(event: ReactKeyboardEvent | Pick<KeyboardEvent, "isComposing" | "keyCode">): boolean {
  const native = "nativeEvent" in event ? event.nativeEvent : event;
  return native.isComposing || native.keyCode === 229;
}

import { useEffect, type RefObject } from "react";

/** Focuses an input on mount with the caret at the end of its content — never select-all. */
export function useSeedFocus(ref: RefObject<HTMLInputElement | null>, _initialText: string | undefined) {
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    el.focus({ preventScroll: true });
    const end = el.value.length;
    el.setSelectionRange(end, end);
    // seed-once on mount; re-running on every value change would fight the user's cursor
    // oxlint-disable-next-line react-hooks/exhaustive-deps
  }, []);
}

// file-local declaration, so the literal below typechecks in consumers without @types/node
declare const process: { env: { NODE_ENV?: string } };

/** True outside production builds. */
export function isDev(): boolean {
  // Bundlers replace only the bare literal; the catch covers a build that skips it and has no `process`.
  try {
    return process.env.NODE_ENV !== "production";
  } catch {
    return true;
  }
}

export function warnDev(message: string): void {
  if (isDev()) console.warn(`[data-grid] ${message}`);
}

/** A dev warning that fires once per key for the lifetime of the returned function. */
export function createWarnOnce(): (key: string, message: string | (() => string)) => void {
  const warned = new Set<string>();
  return (key, message) => {
    if (warned.has(key)) return;
    warned.add(key);
    warnDev(typeof message === "function" ? message() : message);
  };
}

