const STABLE_NAMED_KEYS: readonly string[] = [
  "ArrowUp", "ArrowDown", "ArrowLeft", "ArrowRight", "Home", "End", "PageUp", "PageDown",
  "Enter", "Escape", "Tab", "Backspace", "Delete", "Insert", "Clear", "Help",
  "CapsLock", "NumLock", "ScrollLock", "Pause", "PrintScreen", "ContextMenu",
  "Execute", "Menu", "Suspend", "EraseEOL", "Again", "Accept", "Redo", "Undo", "Props", "Select",
  "BrowserBack", "BrowserForward", "BrowserHome", "BrowserFavorites", "BrowserSearch",
  "BrowserRefresh", "BrowserStop",
  "MediaPlayPause", "MediaStop", "MediaTrackNext", "MediaTrackPrevious",
  "AudioVolumeUp", "AudioVolumeDown", "AudioVolumeMute",
  "LaunchMail", "LaunchApplication1", "LaunchApplication2", "LaunchApplication3",
  "LaunchCalendar", "LaunchCommunications", "LaunchControlPanel", "LaunchFileManager",
  "LaunchMediaPlayer", "LaunchMusicPlayer", "LaunchPhone", "LaunchScreenSaver",
  "LaunchWebBrowser", "LaunchWebCam", "LaunchTerminal",
  "Power", "Sleep", "Eject", "WakeUp",
  "Convert", "NonConvert", "Hiragana", "Katakana", "HangulMode", "Hangul", "HanjaMode", "Hanja",
  "KanaMode", "Zenkaku", "Hankaku", "ZenkakuHankaku",
];

const NAMED_KEYS: ReadonlySet<string> = new Set([
  ...STABLE_NAMED_KEYS,
  ...Array.from({ length: 24 }, (_, i) => `F${i + 1}`),
]);

// Same class as is-printable-key.ts: single code points the matcher can hit via `KeyboardEvent.key`.
const SINGLE_CODE_POINT = /[\p{L}\p{N}\p{S}\p{P}]/u;

const REPEATED_MODIFIER_ISSUE = "repeats modifier";

/** Whether the matcher can hit `binding`: no issue except a repeated modifier, which still matches. */
export function bindingCanMatch(binding: string): boolean {
  return validateKeyBinding(binding).every((issue) => issue.startsWith(REPEATED_MODIFIER_ISSUE));
}

/**
 * Issues for one binding string; empty means valid. Accepts single code points (printable or
 * space, any case) and exact-case stable named keys — exactly what the matcher can hit; the
 * named-key set is a superset of `KeyPart`'s autocomplete vocabulary.
 */
export function validateKeyBinding(binding: string): string[] {
  const issues: string[] = [];
  const parts = binding.split("+");
  const key = parts.at(-1) ?? "";
  const modifiers = parts.slice(0, -1);

  for (const token of modifiers) {
    if (!token) issues.push("has an empty modifier part");
    else if (!MODIFIER_TOKENS.includes(token)) issues.push(`has unknown modifier "${token}"`);
  }
  const seen = new Set<string>();
  for (const token of modifiers) {
    if (!MODIFIER_TOKENS.includes(token)) continue;
    if (seen.has(token)) issues.push(`${REPEATED_MODIFIER_ISSUE} "${token}"`);
    seen.add(token);
  }

  if (!key) {
    issues.push("has no key after the last \"+\"");
  } else if (Array.from(key).length === 1) {
    if (key !== " " && !SINGLE_CODE_POINT.test(key)) issues.push(`key "${key}" is not a printable character`);
  } else if (!NAMED_KEYS.has(key)) {
    issues.push(`key "${key}" is not a known key name (named keys match exact case, e.g. "ArrowUp")`);
  }
  return issues;
}

const warnedBindings = new Set<string>();

/**
 * Warns in development for every invalid binding, once per unique `action:binding` — a typo
 * never matches at runtime, so it must not pass silently (the type's `(string & {})` escape
 * hatch cannot reject it).
 */
export function validateKeymap(keymap: Keymap): void {
  if (!isDev()) return;
  for (const [action, bindings] of Object.entries(keymap)) {
    for (const binding of bindings ?? []) {
      const issues = validateKeyBinding(binding);
      if (!issues.length) continue;
      const dedupe = `${action}:${binding}`;
      if (warnedBindings.has(dedupe)) continue;
      warnedBindings.add(dedupe);
      warnDev(`keymap binding "${binding}" for action "${action}": ${issues.join("; ")}`);
    }
  }
}

/** One combo (modifier set + key) that two or more distinct actions bind. */
export type SharedKeymapBinding = {
  /** The first-seen binding string of the combo (modifier order as written). */
  binding: string;
  /** The distinct actions bound to the combo, in keymap entry order. */
  actions: readonly GridAction[];
  /** True when at least one binding of the combo is not a default binding of its action. */
  consumerInvolved: boolean;
};

/**
 * The combos of `keymap` bound to two or more distinct actions. The matcher resolves a shared
 * combo to ONE action, so the other bindings are dead; this list is what the dev warning reports.
 * Off macOS `ctrl` and `mod` both mean the Ctrl key, so they form one combo.
 */
export function sharedKeymapBindings(keymap: Keymap, isMac: boolean = isMacPlatform()): SharedKeymapBinding[] {
  const bySignature = new Map<string, { binding: string; actions: GridAction[]; consumerInvolved: boolean }>();
  for (const [action, bindings] of Object.entries(keymap) as [GridAction, string[] | undefined][]) {
    if (!bindings) continue;
    for (const binding of bindings) {
      const signature = bindingSignature(binding, !isMac);
      const entry = bySignature.get(signature) ?? { binding, actions: [], consumerInvolved: false };
      if (!entry.actions.includes(action)) entry.actions.push(action);
      if (!isDefaultBinding(action, binding)) entry.consumerInvolved = true;
      bySignature.set(signature, entry);
    }
  }
  return [...bySignature.values()]
    .filter((e) => e.actions.length >= 2)
    .map((e) => ({ binding: e.binding, actions: e.actions, consumerInvolved: e.consumerInvolved }));
}

const warnedSharedBindings = new Set<string>();

/**
 * Warns in development for every combo shared across two or more distinct actions that involves
 * at least one non-default binding, once per unique combo and action set. Shares between default
 * bindings stay silent.
 */
export function validateSharedBindings(keymap: Keymap, isMac: boolean = isMacPlatform()): void {
  if (!isDev()) return;
  for (const shared of sharedKeymapBindings(keymap, isMac)) {
    if (!shared.consumerInvolved) continue;
    const dedupe = `${shared.binding}:${[...shared.actions].sort().join(",")}`;
    if (warnedSharedBindings.has(dedupe)) continue;
    warnedSharedBindings.add(dedupe);
    warnDev(
      `keymap binding "${shared.binding}" is bound to multiple actions (${shared.actions.join(", ")}); the most specific binding wins; on a tie a keymap binding beats a default. Assign distinct combos to keep every action reachable.`,
    );
  }
}

import type { GridAction, Keymap } from "../types";
import { DEFAULT_KEYMAP } from "./default-keymap";

/** Parsed form of a binding string (see `Keymap` in ../types for the string format). */
export type ParsedBinding = {
  mod: boolean;
  /** Literal physical Ctrl key, distinct from `mod` (which is Cmd on mac); keymap-local extension for bindings like Ctrl+Space that must not resolve to Cmd on macOS. */
  ctrl: boolean;
  shift: boolean;
  alt: boolean;
  key: string;
};

const KNOWN_MODIFIERS: ReadonlySet<string> = new Set(["mod", "ctrl", "shift", "alt"]);

/** Splits a binding string like "mod+shift+ArrowUp" into its modifier flags and key. */
export function parseBinding(binding: string): ParsedBinding {
  const parts = binding.split("+");
  // last part is always the key; a literal "+" key never occurs in this keymap
  const modifiers = parts.slice(0, -1);
  // an unknown modifier (a typo or a wrong case) leaves no key, so the binding never matches
  const key = modifiers.every((token) => KNOWN_MODIFIERS.has(token)) ? (parts[parts.length - 1] ?? "") : "";
  return {
    mod: modifiers.includes("mod"),
    ctrl: modifiers.includes("ctrl"),
    shift: modifiers.includes("shift"),
    alt: modifiers.includes("alt"),
    key,
  };
}

/** Minimal event shape the matcher needs; matches both DOM and synthetic KeyboardEvents. */
export type KeymapEvent = {
  key: string;
  ctrlKey: boolean;
  metaKey: boolean;
  shiftKey: boolean;
  altKey: boolean;
  /** Windows reports AltGr as Ctrl+Alt; `getModifierState("AltGraph")` tells it apart from a real Ctrl+Alt chord. */
  altGraph?: boolean;
};

function keysEqual(eventKey: string, bindingKey: string): boolean {
  if (eventKey.length === 1 && bindingKey.length === 1) {
    return eventKey.toLowerCase() === bindingKey.toLowerCase();
  }
  return eventKey === bindingKey;
}

/** A punctuation key such as `?` needs Shift on some layouts and not on others; `event.key` already carries the result. */
function isShiftAgnosticKey(binding: ParsedBinding): boolean {
  return !binding.shift && /^[^\p{L}\p{N}\s]$/u.test(binding.key);
}

function matchesBinding(event: KeymapEvent, binding: ParsedBinding, isMac: boolean): boolean {
  if (!keysEqual(event.key, binding.key)) return false;
  if (event.shiftKey !== binding.shift && !isShiftAgnosticKey(binding)) return false;
  if (event.altKey !== binding.alt) return false;

  // literal ctrl: bypasses mod/Cmd resolution entirely, e.g. Ctrl+Space must stay Ctrl on mac
  if (binding.ctrl) {
    return event.ctrlKey && !event.metaKey;
  }

  const modPressed = isMac ? event.metaKey : event.ctrlKey;
  const otherPressed = isMac ? event.ctrlKey : event.metaKey;
  if (otherPressed) return false;
  if (modPressed !== binding.mod) return false;
  return true;
}

/**
 * Resolves a keyboard event to a `GridAction` using `keymap`, or null if unbound. `include`
 * limits the candidates to the actions it accepts. When several actions share a combo, the most
 * modifier-specific binding wins; on a tie a keymap binding that is not one of the action's
 * defaults beats a default, and a tie between two defaults keeps the earlier entry.
 */
export function matchKeymap(
  event: KeymapEvent,
  keymap: Keymap,
  isMac: boolean,
  include?: (action: GridAction) => boolean,
): GridAction | null {
  let best: { action: GridAction; specificity: number; consumer: boolean } | null = null;

  for (const [action, bindings] of Object.entries(keymap) as [GridAction, string[] | undefined][]) {
    if (!bindings) continue;
    if (include && !include(action)) continue;
    for (const raw of bindings) {
      const parsed = parseBinding(raw);
      if (!matchesBinding(event, parsed, isMac)) continue;
      const consumer = !isDefaultBinding(action, raw);
      const specificity =
        (parsed.mod ? 1 : 0) + (parsed.ctrl ? 1 : 0) + (parsed.shift ? 1 : 0) + (parsed.alt ? 1 : 0);
      if (!best || specificity > best.specificity) {
        best = { action, specificity, consumer };
      } else if (specificity === best.specificity && consumer && !best.consumer) {
        best = { action, specificity, consumer };
      }
    }
  }

  return best?.action ?? null;
}

/**
 * Canonical form of a binding: modifiers in fixed order and a lowercase single-character key.
 * With `ctrlIsMod`, `ctrl` and `mod` share one token (both mean the Ctrl key off macOS).
 */
export function bindingSignature(binding: string, ctrlIsMod = false): string {
  const parsed = parseBinding(binding);
  const key = parsed.key.length === 1 ? parsed.key.toLowerCase() : parsed.key;
  const mod = parsed.mod || (ctrlIsMod && parsed.ctrl);
  const ctrl = parsed.ctrl && !ctrlIsMod;
  return [mod ? "mod" : "", ctrl ? "ctrl" : "", parsed.shift ? "shift" : "", parsed.alt ? "alt" : "", key]
    .filter(Boolean)
    .join("+");
}

/** True when `binding` restates one of `action`'s `DEFAULT_KEYMAP` bindings (modifier order and key case aside). */
export function isDefaultBinding(action: GridAction, binding: string): boolean {
  const defaults: readonly string[] | undefined = DEFAULT_KEYMAP[action];
  if (!defaults) return false;
  const signature = bindingSignature(binding);
  return defaults.some((d) => bindingSignature(d) === signature);
}

import type { GridAction, Keymap } from "../types";
import { isComposingKey } from "../interaction/is-composing-key";
import { matchKeymap, parseBinding } from "./match-keymap";
import { isMacPlatform } from "./platform";

/**
 * An action the global-shortcut layer may resolve and dispatch while DOM focus is OUTSIDE the
 * grid. The layer is action-generic (the gate + `matchKeymap` + the grid's own dispatch path);
 * the default is `undo`/`redo` only. Extension rule for anything added to
 * {@link DataGridGlobalShortcutActions}: every binding of the added action must be mod-prefixed
 * (no ctrl-only/alt-only combos — Ctrl+Space is the Windows IME toggle, Ctrl+Q the browser quit,
 * etc.), and the action must make sense without grid focus (a navigation move scrolls the grid's
 * own container, never the page).
 */
export type GlobalShortcutAction = GridAction;

/**
 * Actions the global-shortcut window layer may enable, each a boolean flag. Core lists the
 * actions it ships; an add-on that owns a `GridAction` (undo/redo, fill) augments this
 * interface via `declare module` to offer its own flag — see `data-grid-history`'s and
 * `data-grid-fill`'s barrels for the augmentation.
 */
export interface DataGridGlobalShortcutActions {
  selectAll: boolean;
  insertRowAbove: boolean;
  insertRowBelow: boolean;
  duplicateRow: boolean;
  deleteRows: boolean;
}

/**
 * Global-shortcut config: one boolean flag per action. `undo` and `redo` default to `true`, every
 * other flag to `false`; `undo={false}` removes one. Keys are constrained to `GridAction` so an
 * add-on's augmentation of {@link DataGridGlobalShortcutActions} can never compile in a key
 * `dispatchGridAction` cannot resolve.
 */
export type GlobalShortcutsConfig = {
  [K in keyof DataGridGlobalShortcutActions & GridAction]?: boolean;
};

/** The actions enabled by default: undo/redo only (the safe set — see {@link GlobalShortcutAction}). */
// undo and redo are the history add-on's action names; without that add-on they stay inert strings.
const DEFAULT_GLOBAL_ACTIONS: readonly string[] = ["undo", "redo"];

/** A stable content key of a config: every defined flag with its value, so `undo={false}` and `undo={true}` differ. */
export function globalShortcutsConfigKey(config?: GlobalShortcutsConfig): string {
  if (!config) return "";
  const flags = config as Record<string, boolean | undefined>;
  return Object.keys(flags).filter((name) => flags[name] !== undefined).sort().map((name) => `${name}=${flags[name]}`).join("|");
}

/** The enabled actions of a config: the default set minus every `false` flag, plus every `true` flag. */
export function enabledGlobalActions(config?: GlobalShortcutsConfig): readonly GlobalShortcutAction[] {
  const flags = (config ?? {}) as Partial<Record<GlobalShortcutAction, boolean>>;
  const kept = DEFAULT_GLOBAL_ACTIONS.filter((action) => flags[action as GlobalShortcutAction] !== false) as GlobalShortcutAction[];
  const added = (Object.keys(flags) as GlobalShortcutAction[]).filter((action) => flags[action] === true && !kept.includes(action));
  return [...kept, ...added];
}

/** Minimal event shape for {@link resolveGlobalShortcut} — the matcher's `KeymapEvent` plus `isComposing`, `keyCode`, and `defaultPrevented`. */
export type GlobalShortcutEvent = {
  key: string;
  ctrlKey: boolean;
  metaKey: boolean;
  shiftKey: boolean;
  altKey: boolean;
  isComposing: boolean;
  keyCode: number;
  defaultPrevented: boolean;
};

/** DOM-derived facts the hook computes per event; keeps the gate pure. */
export type GlobalShortcutContext = {
  keymap: Keymap;
  isMac: boolean;
  actions: readonly GridAction[];
  /** The event target is `INPUT`/`TEXTAREA`/`SELECT` or `[contenteditable="true"]`. */
  targetIsEditable: boolean;
  /** The event target is inside ANY `role="grid"` element (including another grid). */
  targetInAnyGrid: boolean;
  /** The event target is inside a dialog, menu, or listbox; the popup owns its keys. */
  targetInPopup?: boolean;
  /** This grid is the last focused opted-in grid (the multi-grid tie-break). */
  ownsFocus: boolean;
  /** An edit session is open; its editor, including a portaled popup, owns the keys. */
  editing?: boolean;
  /** Limits the keymap match to the actions it accepts. */
  include?: (action: GridAction) => boolean;
};

/**
 * The gate for global shortcuts, pure and unit-tested (same posture as {@link matchKeymap}).
 * Rules run in order, any hit returns `null`:
 * 1. `isComposing` — IME composition owns the keys.
 * 2. `defaultPrevented` — the in-grid handler (earlier in the bubble) or the page already handled it.
 * 3. `targetIsEditable` — the field's native undo/redo wins; never hijack it.
 * 4. `targetInAnyGrid` — a grid's in-grid handler owns the key (this also excludes other grids).
 * 5. `targetInPopup` — a dialog, menu, or listbox owns its keys, including a portaled popup of this grid.
 * 6. `ownsFocus` — multi-grid: only the last focused opted-in grid proceeds.
 * 7. `editing` — an open edit session owns the keys, even from a popup outside the grid.
 * 8. The keymap resolves to one of the enabled actions.
 * 9. The event carries `ctrlKey` or `metaKey`; a bare key never fires page-wide.
 */
export function resolveGlobalShortcut(
  event: GlobalShortcutEvent,
  ctx: GlobalShortcutContext,
): GlobalShortcutAction | null {
  if (isComposingKey(event)) return null;
  if (event.defaultPrevented) return null;
  if (ctx.targetIsEditable) return null;
  if (ctx.targetInAnyGrid) return null;
  if (ctx.targetInPopup) return null;
  if (!ctx.ownsFocus) return null;
  if (ctx.editing) return null;
  const action = matchKeymap(event, ctx.keymap, ctx.isMac, ctx.include);
  if (action === null) return null;
  if (!ctx.actions.includes(action)) return null;
  return event.ctrlKey || event.metaKey ? action : null;
