/** Whether two rects span the same cells. */
export function rectsEqual(a: GridRect, b: GridRect): boolean {
  return a.x === b.x && a.y === b.y && a.width === b.width && a.height === b.height;
}

/** Normalizes two corner cells into a half-open GridRect. */
export function rectFromCorners(a: ViewCoord, b: ViewCoord): GridRect {
  const x = Math.min(a.col, b.col);
  const y = Math.min(a.row, b.row);
  const width = Math.abs(a.col - b.col) + 1;
  const height = Math.abs(a.row - b.row) + 1;
  return { x, y, width, height };
}

/** Bounding-box union of two rects. */
export function combineRects(a: GridRect, b: GridRect): GridRect {
  const x = Math.min(a.x, b.x);
  const y = Math.min(a.y, b.y);
  const right = Math.max(a.x + a.width, b.x + b.width);
  const bottom = Math.max(a.y + a.height, b.y + b.height);
  return { x, y, width: right - x, height: bottom - y };
}

import { compactSelectionFromRuns, forEachMember } from "./compact-selection";
import { rectFromCorners } from "./rects";
import type { GridRect, GridSelection } from "../types";

/**
 * Re-anchors a selection after the view rows permute (`newIndexOf[before] === after`). The row
 * channel and the cursor follow their rows. A range stays only when its rows land contiguous.
 * A split primary range collapses onto the cursor and drops the stack; a split stacked range is
 * dropped. O(r + k log k + h) for r checked rows that land in k runs and
 * ranges of h rows.
 */
export function remapSelectionRows(selection: GridSelection, newIndexOf: ArrayLike<number>): GridSelection {
  const after = (row: number) => newIndexOf[row] ?? row;
  const moved: [number, number][] = [];
  forEachMember(selection.rows.runs(), (row) => {
    const target = after(row);
    const last = moved[moved.length - 1];
    if (last && last[1] === target) last[1] = target + 1;
    else moved.push([target, target + 1]);
  });
  const rows = compactSelectionFromRuns(moved);
  const current = selection.current;
  if (!current) return { current: null, rows, columns: selection.columns };

  const cell = { ...current.cell, row: after(current.cell.row) };
  const mapRect = (rect: GridRect): GridRect | null => {
    let top = Infinity;
    let bottom = -Infinity;
    for (let row = rect.y; row < rect.y + rect.height; row++) {
      const moved = after(row);
      if (moved < top) top = moved;
      if (moved > bottom) bottom = moved;
    }
    return bottom - top + 1 === rect.height ? { ...rect, y: top } : null;
  };
  const range = mapRect(current.range);
  return {
    current: {
      cell,
      range: range ?? rectFromCorners(cell, cell),
      rangeStack: range ? current.rangeStack.flatMap((rect) => mapRect(rect) ?? []) : [],
    },
    rows,
    columns: selection.columns,
  };
}

import type { CompactSelectionLike, GridSelection } from "../types";
import type { CompactSelection } from "./compact-selection";

/**
 * A row range gesture: every Shift step applies the anchor..target span to `base`, so the
 * previous step is replaced (the range grows and shrinks) and rows outside it keep their state.
 */
export type RowRangeGesture = {
  anchor: number;
  /** The row the last step targeted: the moving end of the range. */
  edge: number;
  anchorRowId: string | undefined;
  /** The row channel as it was when the anchor was set. */
  base: CompactSelection;
  /** `true` checks the span, `false` unchecks it. */
  checked: boolean;
  /** The channel the gesture last wrote; the gesture is live only while the store still holds it. */
  rows: CompactSelectionLike;
  /** The cell selection the gesture last saw; a keyboard step continues the gesture only while it is unchanged. */
  current: GridSelection["current"];
  viewIndex: readonly number[];
};

export function isRowRangeLive(
  gesture: RowRangeGesture | null,
  selection: GridSelection,
  viewIndex: readonly number[],
): gesture is RowRangeGesture {
  return gesture !== null && gesture.rows === selection.rows && gesture.viewIndex === viewIndex;
}

/** The row channel after the anchor..target span is applied to the gesture's base. */
export function applyRowRange(gesture: Pick<RowRangeGesture, "anchor" | "base" | "checked">, target: number): CompactSelection {
  const span: [number, number] = [Math.min(gesture.anchor, target), Math.max(gesture.anchor, target) + 1];
  return gesture.checked ? gesture.base.add(span) : gesture.base.remove(span);
}

/** True when a keyboard row step may extend the checked range: the cell selection is empty or only the active cell. */
export function selectionIsCursorOnly(selection: GridSelection): boolean {
  const current = selection.current;
  if (current === null) return true;
  const { range } = current;
  return range.width === 1 && range.height === 1 && current.rangeStack.length === 0;
}

import { CompactSelection } from "./compact-selection";
import type { ViewCoord, GridRect, GridSelection } from "../types";

/** Two-stage progression the store tracks in `selectAllStage`: which stage the last `selectAllProgression` call produced. */
export type SelectAllStage = "region" | "all" | null;

/** Probes whether the cell at `coord` is empty, via the cell type's `isEmpty` — same contract as `jumpToDataBoundary`'s local helper. */
export type IsEmptyAt = (coord: ViewCoord) => boolean;

function wholeGridRect(rowCount: number, colCount: number): GridRect {
  return { x: 0, y: 0, width: colCount, height: rowCount };
}

/**
 * Excel's "current region": the maximal rectangle of contiguous non-empty rows/columns containing
 * `active`, grown one edge at a time (flood-fill by row/column, not per-cell) until every row/column
 * just outside the rect is entirely empty. An empty `active` cell's region is itself (Excel parity).
 * O(perimeter × rows/cols touched) — only called on an explicit Ctrl+A, never a hot path.
 */
export function computeDataRegion(active: ViewCoord, rowCount: number, colCount: number, isEmptyAt: IsEmptyAt): GridRect {
  if (isEmptyAt(active)) return { x: active.col, y: active.row, width: 1, height: 1 };

  let left = active.col;
  let right = active.col;
  let top = active.row;
  let bottom = active.row;

  const rowHasData = (row: number, fromCol: number, toCol: number): boolean => {
    for (let col = fromCol; col <= toCol; col++) if (!isEmptyAt({ col, row })) return true;
    return false;
  };
  const colHasData = (col: number, fromRow: number, toRow: number): boolean => {
    for (let row = fromRow; row <= toRow; row++) if (!isEmptyAt({ col, row })) return true;
    return false;
  };

  const growRows = (): boolean => {
    const before = bottom - top;
    while (top > 0 && rowHasData(top - 1, left, right)) top--;
    while (bottom < rowCount - 1 && rowHasData(bottom + 1, left, right)) bottom++;
    return bottom - top > before;
  };
  const growColumns = (): boolean => {
    const before = right - left;
    while (left > 0 && colHasData(left - 1, top, bottom)) left--;
    while (right < colCount - 1 && colHasData(right + 1, top, bottom)) right++;
    return right - left > before;
  };

  // Each axis grows to its limit; the other axis is re-checked only after this one grew.
  let rowsDirty = true;
  let columnsDirty = true;
  while (rowsDirty || columnsDirty) {
    if (rowsDirty) {
      rowsDirty = false;
      if (growRows()) columnsDirty = true;
    }
    if (columnsDirty) {
      columnsDirty = false;
      if (growColumns()) rowsDirty = true;
    }
  }

  return { x: left, y: top, width: right - left + 1, height: bottom - top + 1 };
}

function isRect(rect: GridRect, other: GridRect): boolean {
  return rect.x === other.x && rect.y === other.y && rect.width === other.width && rect.height === other.height;
}

function selectionForRect(rect: GridRect, anchor: ViewCoord): GridSelection {
  return {
    current: { cell: anchor, range: rect, rangeStack: [] },
    rows: CompactSelection.empty(),
    columns: CompactSelection.empty(),
  };
}

/**
 * Two-stage Ctrl+A (Excel/Sheets parity):
 * stage 1 selects the active cell's data region, stage 2 (an immediate repeat, tracked by the
 * caller via `stage`) selects the whole grid. When the region already equals the whole grid
 * (dense data), stage 1 already lands on `"all"`: a repeated press re-selects the whole grid and
 * drops any row or column check, and it changes nothing while the selection is already exactly the
 * whole-grid range.
 * Pure: takes the progression stage in, returns the next selection + stage out.
 */
export function selectAllProgression(
  selection: GridSelection,
  rowCount: number,
  colCount: number,
  active: ViewCoord,
  isEmptyAt: IsEmptyAt,
  stage: SelectAllStage,
): { selection: GridSelection; stage: "region" | "all" } {
  const wholeGrid = wholeGridRect(rowCount, colCount);

  if (stage === "region") {
    return { selection: selectionForRect(wholeGrid, active), stage: "all" };
  }

  const region = computeDataRegion(active, rowCount, colCount, isEmptyAt);
  if (isRect(region, wholeGrid)) {
    // Dense data: a repeat press is a no-op only while the selection is exactly the whole-grid range; a row or column check drops.
    const alreadyWholeGrid =
      selection.current !== null &&
      selection.current.rangeStack.length === 0 &&
      selection.rows.length === 0 &&
      selection.columns.length === 0 &&
      isRect(selection.current.range, wholeGrid);
    return { selection: alreadyWholeGrid ? selection : selectionForRect(wholeGrid, active), stage: "all" };
  }
  return { selection: selectionForRect(region, active), stage: "region" };
}

import { CompactSelection, compactSelectionFromRuns } from "./compact-selection";
import type { CompactSelectionLike } from "../types";

/**
 * Options for selectRow/selectColumn. Plain click (no options set) toggles membership of
 * just this index, clearing the rest of the channel.
 */
export type SelectLineOptions = {
  /** Ctrl-click: additive toggle of this index, keeping the rest of the channel. */
  additive?: boolean;
  /** Shift-click: range from the last-selected index (falls back to `index` when there is none). */
  extendFromLast?: boolean;
  /**
   * Explicit last-highlighted index for `extendFromLast` (insertion order, not
   * the channel's max member — an RLE set can't represent insertion order, so the caller/reducer
   * must track it). Falls back to the channel's max index, then `index`, when absent.
   */
  from?: number;
};

/** Shared by selectRow/selectColumn: applies a plain/additive/extendFromLast toggle to one selection channel. */
export function selectLine(
  channelLike: CompactSelectionLike,
  index: number,
  opts: SelectLineOptions = {},
): CompactSelection {
  const channel = channelLike instanceof CompactSelection ? channelLike : compactSelectionFromRuns(channelLike.runs());
  if (opts.extendFromLast) {
    const last = opts.from ?? channel.last() ?? index;
    const start = Math.min(last, index);
    const end = Math.max(last, index) + 1;
    return channel.add([start, end]);
  }
  if (opts.additive) {
    return channel.hasIndex(index) ? channel.remove(index) : channel.add(index);
  }
  // plain click: toggle-select just this index
  if (channel.length === 1 && channel.hasIndex(index)) {
    return CompactSelection.empty();
  }
  return CompactSelection.fromSingleSelection(index);
}

import type { GridRect, GridSelection } from "../types";

/** Half-open column range `[start, end)`, merged/sorted, describing which columns of one row are selected. */
export type ColRange = readonly [start: number, end: number];

/** True when `viewRow` falls inside `rect`'s row span. */
function rectCoversRow(rect: GridRect, viewRow: number): boolean {
  return viewRow >= rect.y && viewRow < rect.y + rect.height;
}

/** Inserts `[start, end)` into `ranges` (sorted, non-overlapping), merging any overlap/adjacency. */
function mergeRange(ranges: ColRange[], start: number, end: number): void {
  if (start >= end) return;
  let i = 0;
  // hot path (per-row selector): ranges[i]! guarded by i < ranges.length in the loop condition
  while (i < ranges.length && ranges[i]![1] < start) i++;
  let mergedStart = start;
  let mergedEnd = end;
  while (i < ranges.length && ranges[i]![0] <= mergedEnd) {
    mergedStart = Math.min(mergedStart, ranges[i]![0]);
    mergedEnd = Math.max(mergedEnd, ranges[i]![1]);
    ranges.splice(i, 1);
  }
  ranges.splice(i, 0, [mergedStart, mergedEnd]);
}

/**
 * The selected column ranges for one view row — a row is a rectangle's-worth of columns, not
 * individual cells, so this collapses to a handful of `[start, end)` tuples (usually 0 or 1) instead
 * of a per-column boolean/Set. Used by {@link useDataGridRowCellState} so a row's selector output
 * stays cheap to compute and cheap to compare (small array, content-equal across unrelated updates).
 */
export function selectedColRangesForRow(selection: GridSelection, viewRow: number, colCount: number): ColRange[] {
  const ranges: ColRange[] = [];
  if (selection.rows.hasIndex(viewRow)) mergeRange(ranges, 0, colCount);
  for (const [start, end] of selection.columns.runs()) mergeRange(ranges, start, end);
  if (selection.current) {
    if (rectCoversRow(selection.current.range, viewRow)) {
      mergeRange(ranges, selection.current.range.x, selection.current.range.x + selection.current.range.width);
    }
    for (const rect of selection.current.rangeStack) {
      if (rectCoversRow(rect, viewRow)) mergeRange(ranges, rect.x, rect.x + rect.width);
    }
  }
  return ranges;
}

/** Whether `col` falls inside any of `ranges` — the per-cell membership check row.tsx derives `isSelected` from. */
export function colRangesContain(ranges: readonly ColRange[], col: number): boolean {
  for (const [start, end] of ranges) {
    if (col >= start && col < end) return true;
  }
  return false;
}

/** Content equality for two `ColRange[]` — same length, same tuples in the same order (both are built sorted/merged, so order is deterministic). */
export function colRangesEqual(a: readonly ColRange[], b: readonly ColRange[]): boolean {
  if (a === b) return true;
  if (a.length !== b.length) return false;
  for (let i = 0; i < a.length; i++) {
    const ra = a[i]!; // i < a.length by loop condition, same length as b (checked above)
    const rb = b[i]!;
    if (ra[0] !== rb[0] || ra[1] !== rb[1]) return false;
  }
  return true;
}

import { compactSelectionFromRuns } from "./compact-selection";
import type { GridSelection } from "../types";

/**
 * Every view row index covered by `selection`: the union of the primary range, the ctrl-click
 * `rangeStack`, and the whole-row channel (`rows`), deduped and sorted ascending. The core's
 * single derivation of the selected row set — add-ons acting on selected rows (cell-menu row
 * operations, selection-scope export) consume this instead of re-reading `GridSelection`'s channels.
 * The result is view indices, not row ids. With `checkedRowsOnly`, any checked row makes the
 * checked rows the whole result and the cell ranges are ignored.
 */
export function getSelectedViewRows(selection: GridSelection, options: { checkedRowsOnly?: boolean } = {}): number[] {
  if (options.checkedRowsOnly && selection.rows.length > 0) return selection.rows.toArray();
  const current = selection.current;
  const rectSpans: (readonly [number, number])[] = current ? [current.range, ...current.rangeStack].map((rect) => [rect.y, rect.y + rect.height] as const) : [];
  return compactSelectionFromRuns(rectSpans.concat(selection.rows.runs())).toArray();
}

import type { ViewCoord, GridSelection, GridRect } from "../types";
import { CompactSelection } from "./compact-selection";
import { rectFromCorners, rectsEqual } from "./rects";

/** The selection with nothing selected. */
export function emptySelection(): GridSelection {
  return { current: null, rows: CompactSelection.empty(), columns: CompactSelection.empty() };
}

/** True when all three selection channels (current range, rows, columns) are empty. */
export function isSelectionEmpty(selection: GridSelection): boolean {
  return selection.rows.length === 0 && selection.columns.length === 0 && !selection.current;
}

/** A fresh 1x1 selection anchored at `coord`, clearing row/column channels. */
export function selectCell(coord: ViewCoord): GridSelection {
  return {
    current: { cell: coord, range: { x: coord.col, y: coord.row, width: 1, height: 1 }, rangeStack: [] },
    rows: CompactSelection.empty(),
    columns: CompactSelection.empty(),
  };
}

/** Shift-click/shift-arrow: extends the primary range from the existing anchor to `coord`; anchor is unchanged. Returns the input itself when the result equals the current range (a stationary drag re-fires the same coord; stable identity keeps selection observers quiet). */
export function extendTo(selection: GridSelection, coord: ViewCoord): GridSelection {
  if (!selection.current) return selectCell(coord);
  const { cell, rangeStack } = selection.current;
  const range = rectFromCorners(cell, coord);
  if (rectsEqual(range, selection.current.range)) return selection;
  return {
    current: { cell, range, rangeStack },
    rows: selection.rows,
    columns: selection.columns,
  };
}

/** Removes `row` from the rows channel and from every cell range, splitting a range that spans it; the piece holding the anchor stays primary. `selection` itself comes back when the row is in neither channel. */
export function removeRowFromSelection(selection: GridSelection, row: number, options: { multiRange?: boolean } = {}): GridSelection {
  const { multiRange = true } = options;
  const rows = selection.rows.hasIndex(row) ? CompactSelection.adopt(selection.rows).remove(row) : selection.rows;
  const current = selection.current;
  const covers = (r: GridRect) => row >= r.y && row < r.y + r.height;
  if (!current || (!covers(current.range) && !current.rangeStack.some(covers))) {
    return rows === selection.rows ? selection : { ...selection, rows };
  }
  const without = (r: GridRect): GridRect[] => {
    if (!covers(r)) return [r];
    const above = row - r.y;
    const below = r.y + r.height - row - 1;
    return [
      ...(above > 0 ? [{ ...r, height: above }] : []),
      ...(below > 0 ? [{ ...r, y: row + 1, height: below }] : []),
    ];
  };
  const { cell } = current;
  const holdsCell = (r: GridRect) => cell.col >= r.x && cell.col < r.x + r.width && cell.row >= r.y && cell.row < r.y + r.height;
  const primaryPieces = without(current.range);
  const stackPieces = multiRange ? current.rangeStack.flatMap(without) : [];
  const range = primaryPieces.find(holdsCell) ?? primaryPieces.at(-1) ?? stackPieces.at(-1);
  if (!range) return { ...selection, current: null, rows };
  const anchor =
    primaryPieces.length === 0
      ? { col: range.x, row: range.y }
      : { col: cell.col, row: Math.min(Math.max(cell.row, range.y), range.y + range.height - 1) };
  const rangeStack = multiRange ? [...stackPieces, ...primaryPieces].filter((piece) => piece !== range) : [];
  return { ...selection, rows, current: { cell: anchor, range, rangeStack } };
}

/** Ctrl-click: pushes the current primary range onto the stack and starts a new 1x1 range at `coord`. */
export function pushRange(selection: GridSelection, coord: ViewCoord): GridSelection {
  if (!selection.current) return selectCell(coord);
  const { range, rangeStack } = selection.current;
  return {
    current: {
      cell: coord,
      range: { x: coord.col, y: coord.row, width: 1, height: 1 },
      rangeStack: [...rangeStack, range],
    },
    rows: selection.rows,
    columns: selection.columns,
  };
}

import type { FilterJoinOperator, FilterNode, FilterSpec, SortSpec } from "../types";
import { groupChildren, isFilterGroup, withRootJoin } from "./filter-tree";
import { isDev } from "../is-dev";
import { sortCollator } from "./sort-collator";
import { createFilterMatcher, createNumberMatcher, isBuiltInOperator } from "./matches-filter";
import { KEYED_SORT_MIN_ROWS, sortByKeys, type SortKeyReader } from "./keyed-sort";

/**
 * Read-only accessor the view-index builder uses to reach cell data without
 * knowing the row type. `compare` supplies a custom row-index comparator for a
 * column (a column `sortCompare` or its cell type's `compare`). Without one, the
 * full build compares `getText` keys with a shared collator (empty last in both
 * directions); the incremental update uses `defaultCompareText`.
 *
 * A `compare` a caller returns MUST be deterministic and depend only on the two
 * rows' current values — {@link updateViewIndex} reuses the untouched rows'
 * order under it instead of re-deriving it.
 */
export type CellAccessor = {
  /** The raw text the filter matcher, the empty check, and the default sort read. */
  getText(rowIndex: number, columnId: string): string;
  /** The quick-search text; defaults to `getText`. */
  getSearchText?: (rowIndex: number, columnId: string) => string;
  compare?(columnId: string): ((a: number, b: number) => number) | undefined;
  /** Whether a row's cell in `columnId` is empty for sort placement; defaults to `getText() === ""`. */
  isEmpty?(rowIndex: number, columnId: string): boolean;
  /** The column's raw (un-stringified) cell value; only needed by a column's `filter.match`. */
  getValue?(rowIndex: number, columnId: string): unknown;
  /**
   * Opts a column into the keyed sort when its comparator is exactly a built-in one (see
   * {@link SortKeyReader}); the result must order rows exactly as `compare` and `isEmpty` do. A column
   * without it sorts through `compare`.
   */
  sortKeys?(columnId: string): SortKeyReader | undefined;
  /** The column's `filter.match` predicate for `operator`, if one evaluates it. */
  filterMatch?(columnId: string, operator: FilterSpec["operator"]): ((value: unknown, filter: FilterSpec) => boolean) | undefined;
  /** The column's `filter.compare`, ordering text against a filter bound. */
  filterCompare?(columnId: string): ((text: string, bound: string) => number) | undefined;
  /** Whether the column's built-in text and set operators respect letter case. */
  filterMatchCase?(columnId: string): boolean;
  /** The `match` of the custom operator `operator` registered on the column, if any. */
  customFilterMatch?(columnId: string, operator: string): ((text: string, filter: FilterSpec) => boolean) | undefined;
};

const MAX_WARNED_OPERATORS = 100;
const warnedUnwiredOperators = new Set<string>();

/**
 * One filter's per-row test: the column's `filter.match` (raw value) when the accessor provides
 * both the predicate and raw values and the operator is built in, else the text matcher with the
 * column's `filter.compare` and the custom operator's `match`. Both the rebuild and the
 * incremental path build through this so a custom predicate can never desync between them.
 */
export function makeFilterTest(accessor: CellAccessor, filter: FilterSpec): (row: number) => boolean {
  const custom = accessor.filterMatch?.(filter.columnId, filter.operator);
  const getValue = accessor.getValue;
  if (custom && getValue && isBuiltInOperator(filter.operator)) {
    // a thrown predicate fails the row rather than the view build
    return (row: number) => {
      try {
        return custom(getValue(row, filter.columnId), filter);
      } catch {
        return false;
      }
    };
  }
  const compare = accessor.filterCompare?.(filter.columnId);
  const customMatch = accessor.customFilterMatch?.(filter.columnId, filter.operator);
  if (!customMatch && !isBuiltInOperator(filter.operator) && isDev()) {
    const key = `${filter.columnId}:${filter.operator}`;
    if (!warnedUnwiredOperators.has(key) && warnedUnwiredOperators.size < MAX_WARNED_OPERATORS) {
      warnedUnwiredOperators.add(key);
      console.warn(
        `[data-grid] the filter operator "${filter.operator}" on column "${filter.columnId}" has no \`match\`, so the grid does not narrow rows with it. Give it a \`match\` in the column's \`filter.operators\`, or use filterMode="server".`,
      );
    }
  }
  const test = createFilterMatcher(filter, { compare, custom: customMatch, matchCase: accessor.filterMatchCase?.(filter.columnId) });
  const numberTest = !compare && getValue ? createNumberMatcher(filter) : null;
  if (numberTest) {
    return (row: number) => {
      const value = getValue!(row, filter.columnId);
      return typeof value === "number" && value === value ? numberTest(value) : test(accessor.getText(row, filter.columnId));
    };
  }
  return (row: number) => test(accessor.getText(row, filter.columnId));
}

/**
 * One node's per-row test. A group compiles to one closure over its children's tests: `every` for
 * `"and"`, `some` for `"or"`; any join other than `"or"` evaluates as `"and"`, and an empty group
 * matches every row. `not: true` negates a non-empty group.
 */
export function makeFilterNodeTest(accessor: CellAccessor, node: FilterNode): (row: number) => boolean {
  if (!isFilterGroup(node)) return makeFilterTest(accessor, node);
  const tests = groupChildren(node).map((child) => makeFilterNodeTest(accessor, child));
  if (tests.length === 0) return () => true;
  const match = tests.length === 1 ? tests[0]! : node.join === "or" ? (row: number) => tests.some((test) => test(row)) : (row: number) => tests.every((test) => test(row));
  return node.not === true ? (row) => !match(row) : match;
}

/** The accessor's quick-search reader: `getSearchText` when present, else `getText`. */
export function searchTextReader(accessor: CellAccessor): (rowIndex: number, columnId: string) => string {
  return accessor.getSearchText ?? ((rowIndex, columnId) => accessor.getText(rowIndex, columnId));
}

/** Whether `row`'s cell in `columnId` counts as empty for sort placement — empty sorts last in BOTH directions. */
export function isEmptyCell(accessor: CellAccessor, rowIndex: number, columnId: string): boolean {
  return accessor.isEmpty ? accessor.isEmpty(rowIndex, columnId) : accessor.getText(rowIndex, columnId) === "";
}

/**
 * Options for {@link buildViewIndex}. `searchColumnIds` is only consulted
 * when `search` is set; if omitted in that case, the search filter is
 * skipped (no rows are excluded) rather than matching against zero columns.
 */
export type ViewIndexOptions = {
  sorts: SortSpec[];
  filters: readonly FilterNode[];
  /** How the top-level `filters` combine. Default: `"and"`. */
  filterJoin?: FilterJoinOperator;
  search?: string;
  searchColumnIds?: string[];
};

/**
 * Computes the row-index view: filter, then search, then a stable
 * multi-column sort. `sorts[0]` is primary; each subsequent sort only
 * breaks ties left by the ones before it. No sorts leaves filtered/searched
 * rows in their original order.
 */
export function buildViewIndex(
  rowCount: number,
  accessor: CellAccessor,
  opts: ViewIndexOptions,
): number[] {
  let indices: number[] = [];
  for (let i = 0; i < rowCount; i++) indices.push(i);

  const filters = withRootJoin(opts.filters, opts.filterJoin);
  if (filters.length > 0) {
    // One test per top-level node, built once outside the per-row loop: a numeric bound is parsed here, not per row.
    // Narrowing node by node keeps a flat list on the short-circuiting path it always had.
    for (const node of filters) {
      const test = makeFilterNodeTest(accessor, node);
      indices = indices.filter((row) => test(row));
    }
  }

  const search = opts.search?.trim();
  if (search && opts.searchColumnIds) {
    const needle = search.toLowerCase();
    const columnIds = opts.searchColumnIds;
    const readSearchText = searchTextReader(accessor);
    indices = indices.filter((row) =>
      columnIds.some((columnId) => readSearchText(row, columnId).toLowerCase().includes(needle)),
    );
  }

  if (opts.sorts.length === 0) return indices;

  if (indices.length >= KEYED_SORT_MIN_ROWS) {
    const keyed = sortByKeys(indices, accessor, opts.sorts);
    if (keyed) return keyed;
  }

  // One collator amortized across every default-compare column and every pairwise
  // comparison in this call, instead of a lookup per comparison.
  const collator = sortCollator();

  const comparators = opts.sorts.map((sort) => {
    const custom = accessor.compare?.(sort.columnId);
    const dir = sort.direction === "asc" ? 1 : -1;

    if (custom) {
      const empties = new Uint8Array(rowCount);
      for (const row of indices) empties[row] = isEmptyCell(accessor, row, sort.columnId) ? 1 : 0;
      // Same empty-last-in-both-directions rule as the default path, so a typed column's blanks
      // don't flip sides on a direction change while a text column's stay put.
      return (a: number, b: number) => {
        const emptyA = empties[a] === 1;
        const emptyB = empties[b] === 1;
        if (emptyA && emptyB) return 0;
        if (emptyA) return 1;
        if (emptyB) return -1;
        return dir * custom(a, b);
      };
    }

    // Each row's text key is read once (O(n)) into a dense array, not on every comparison.
    const keys = new Array<string>(rowCount);
    for (const row of indices) keys[row] = accessor.getText(row, sort.columnId);

    // Empty sorts last in both directions; only the non-empty order flips.
    return (a: number, b: number) => {
      const textA = keys[a]!;
      const textB = keys[b]!;
      if (textA === "") return textB === "" ? 0 : 1;
      if (textB === "") return -1;
      return dir * collator.compare(textA, textB);
    };
  });

  // Decorate-sort-undecorate keeps the sort stable across the composed comparators.
  const decorated = indices.map((row, position) => ({ row, position }));
  decorated.sort((a, b) => {
    for (const cmp of comparators) {
      const result = cmp(a.row, b.row);
      if (result !== 0) return result;
    }
    return a.position - b.position;
  });

  return decorated.map((d) => d.row);
}

import type { FilterNode, SortSpec } from "../types";
import { withRootJoin } from "./filter-tree";
import { isEmptyCell, makeFilterNodeTest, type CellAccessor, type ViewIndexOptions } from "./build-view-index";
import { defaultCompareText } from "./default-compare-text";

/**
 * Above this many touched rows, {@link updateViewIndex} refuses the incremental path and the caller
 * rebuilds. Each touched row costs one splice-out plus one splice-in against the index array, so the
 * cost is linear in k while the rebuild is a flat O(n log n) — the two cross where k × per-row cost
 * meets the rebuild.
 *
 * Measured (prod build, 100k rows, one sort column, paired in one launch): the rebuild is ~415 ms
 * flat; the incremental path is 0.3 / 0.9 / 7.6 / 28.5 / 137 ms at k = 1 / 20 / 256 / 1000 / 5000,
 * a slope near 0.027 ms per touched row. The curves therefore meet around k ≈ 15,000. 256 sits ~58x
 * inside that, so no machine, dataset, or collator can land a batch on the wrong side of it — and a
 * batch that big is a bulk import, which the rebuild serves better anyway.
 */
export const INCREMENTAL_PATCH_LIMIT = 256;

/**
 * Why {@link updateViewIndex} declined the incremental path — `null` means it ran. See each valve's
 * own guard.
 */
export type IncrementalBailReason = "too-many-rows" | "search-active";

export type IncrementalViewIndexResult =
  | { viewIndex: number[]; bail: null }
  | { viewIndex: null; bail: IncrementalBailReason };

/**
 * A row's total-order position under one sort column, resolved once per row per call.
 * Empty sorts last in BOTH directions, so the direction multiplier applies only when neither
 * side is empty — {@link buildViewIndex}'s own rule, replicated here rather than shared, because the
 * rebuild stays the untouched reference implementation. `custom` is the column's resolved
 * `accessor.compare` when it has one; otherwise the text keys drive `defaultCompareText`.
 */
function compareOnColumn(
  accessor: CellAccessor,
  columnId: string,
  dir: 1 | -1,
  custom: ((a: number, b: number) => number) | undefined,
  a: number,
  b: number,
): number {
  if (custom) {
    const emptyA = isEmptyCell(accessor, a, columnId);
    const emptyB = isEmptyCell(accessor, b, columnId);
    if (emptyA && emptyB) return 0;
    if (emptyA) return 1;
    if (emptyB) return -1;
    return dir * custom(a, b);
  }
  const textA = accessor.getText(a, columnId);
  const textB = accessor.getText(b, columnId);
  if (textA === "" || textB === "") return defaultCompareText(textA, textB);
  return dir * defaultCompareText(textA, textB);
}

/**
 * The comparator chain {@link buildViewIndex} sorts by, expressed over data indices.
 *
 * Tiebreak equivalence: the rebuild decorates each row with its POSITION in the filtered index array
 * and breaks ties on that position. `indices` starts as `[0..n)` and every filter pass preserves
 * relative order, so position is strictly increasing in data index — `positionA - positionB` and
 * `a - b` always agree in sign. Comparing data indices directly is therefore the identical tiebreak,
 * and it makes the order TOTAL (no two rows ever compare equal), which is what lets a binary search
 * find one uniquely-correct insertion point.
 */
export function makeViewComparator(accessor: CellAccessor, sorts: readonly SortSpec[]): (a: number, b: number) => number {
  // Resolved ONCE per column here, not per comparison — mirrors the rebuild's per-sort resolution.
  const columns = sorts.map((sort) => ({
    columnId: sort.columnId,
    dir: (sort.direction === "asc" ? 1 : -1) as 1 | -1,
    custom: accessor.compare?.(sort.columnId),
  }));
  return (a, b) => {
    for (const { columnId, dir, custom } of columns) {
      const result = compareOnColumn(accessor, columnId, dir, custom, a, b);
      if (result !== 0) return result;
    }
    return a - b;
  };
}

/** Whether `row` survives the active filters — the same tests, group semantics, and text source the rebuild uses. */
export function makeFilterPredicate(accessor: CellAccessor, filters: readonly FilterNode[]): (row: number) => boolean {
  if (filters.length === 0) return () => true;
  const tests = filters.map((node) => makeFilterNodeTest(accessor, node));
  return (row) => tests.every((test) => test(row));
}

/** Index in `view` where `row` belongs under `compare`; `view` must already be sorted by it. */
export function lowerBound(view: readonly number[], row: number, compare: (a: number, b: number) => number): number {
  let lo = 0;
  let hi = view.length;
  while (lo < hi) {
    const mid = (lo + hi) >>> 1;
    if (compare(view[mid]!, row) < 0) lo = mid + 1;
    else hi = mid;
  }
  return lo;
}

/**
 * Rebuilds `prevViewIndex` for a value patch that touched `touchedRows` (data indices), instead of
 * re-sorting all `n` rows. Per touched row: remove it from the order, re-test filter membership
 * against the NEW values, and binary-search it back in under the identical comparator chain — so a
 * value change may also add a row to, or drop it from, the filtered set.
 *
 * `touchedRows` must name EVERY row whose values changed since `prevViewIndex` was built (a caller
 * holding deferred batches has to pass their rows too) — every other row's key is assumed unchanged,
 * which is what makes the remaining order a valid binary-search invariant.
 *
 * Returns `{viewIndex: null, bail}` whenever the incremental path cannot prove it reproduces
 * {@link buildViewIndex} exactly; the caller must then run the full rebuild. Correctness beats
 * cleverness: every valve below is a case where equivalence is not provable, not a case where it is
 * merely slower.
 *
 * A column with an `accessor.compare` needs NO valve: both paths now resolve the same comparator
 * under the same empty-last rule, and the accessor contract makes it a deterministic function of the
 * two rows' values — so an untouched row's key is unchanged and the remaining order stays a valid
 * binary-search invariant, exactly as for the default text comparator.
 */
export function updateViewIndex(
  prevViewIndex: readonly number[],
  touchedRows: readonly number[],
  accessor: CellAccessor,
  opts: ViewIndexOptions,
): IncrementalViewIndexResult {
  if (touchedRows.length > INCREMENTAL_PATCH_LIMIT) return { viewIndex: null, bail: "too-many-rows" };
  // buildViewIndex narrows by `search` before sorting; this path only knows sort + filter membership.
  if (opts.search?.trim() && opts.searchColumnIds) return { viewIndex: null, bail: "search-active" };
  const rows = Array.from(new Set(touchedRows));
  const survives = makeFilterPredicate(accessor, withRootJoin(opts.filters, opts.filterJoin));
  // With no sort columns the comparator degenerates to the data-index tiebreak alone, which is
  // exactly the order the rebuild leaves an unsorted filtered view in.
  const compare = makeViewComparator(accessor, opts.sorts);
  const positions = locateRows(prevViewIndex, rows);

  if (everyRowStaysPut(prevViewIndex, rows, positions, survives, compare)) return { viewIndex: prevViewIndex as number[], bail: null };
  if (rows.length === 1 && positions[0] !== -1 && survives(rows[0]!)) {
    return { viewIndex: moveRow(prevViewIndex, positions[0]!, compare), bail: null };
  }
  if (rows.length <= SPLICE_ROW_LIMIT) return { viewIndex: spliceRows(prevViewIndex, rows, survives, compare), bail: null };
  return { viewIndex: mergeRows(prevViewIndex, rows, survives, compare), bail: null };
}

/** At or below this many touched rows, `indexOf` plus `splice` beat the one-pass merge. */
const SPLICE_ROW_LIMIT = 4;

/** The index of each of `rows` in `view`, or -1 when absent: `indexOf` for a few rows, one scan otherwise. */
function locateRows(view: readonly number[], rows: readonly number[]): number[] {
  if (rows.length <= SPLICE_ROW_LIMIT) return rows.map((row) => view.indexOf(row));
  const slotOf = new Map<number, number>();
  rows.forEach((row, slot) => slotOf.set(row, slot));
  const mark = markRows(rows);
  const positions = new Array<number>(rows.length).fill(-1);
  for (let i = 0; i < view.length; i++) {
    const row = view[i]!;
    if (row < mark.length && mark[row] === 1) positions[slotOf.get(row)!] = i;
  }
  return positions;
}

function markRows(rows: readonly number[]): Uint8Array {
  let max = 0;
  for (const row of rows) if (row > max) max = row;
  const mark = new Uint8Array(max + 1);
  for (const row of rows) mark[row] = 1;
  return mark;
}

/**
 * Whether the view is still sorted and filtered without moving anything: every touched row keeps its
 * filter verdict and sorts strictly between its neighbours under the current values. Adjacent pairs in
 * order make the whole view in order, so the caller can keep the previous array.
 */
function everyRowStaysPut(
  view: readonly number[],
  rows: readonly number[],
  positions: readonly number[],
  survives: (row: number) => boolean,
  compare: (a: number, b: number) => number,
): boolean {
  for (let slot = 0; slot < rows.length; slot++) {
    const row = rows[slot]!;
    const position = positions[slot]!;
    if (position === -1 || !survives(row)) return false;
    if (position > 0 && compare(view[position - 1]!, row) >= 0) return false;
    if (position < view.length - 1 && compare(row, view[position + 1]!) >= 0) return false;
  }
  return true;
}

/** Moves the row at `position` to its sorted place: one copy of the view plus a shift of the rows it passes. */
function moveRow(view: readonly number[], position: number, compare: (a: number, b: number) => number): number[] {
  const next = view.slice();
  const row = next[position]!;
  let low = 0;
  let high = next.length - 1;
  while (low < high) {
    const mid = (low + high) >>> 1;
    if (compare(next[mid < position ? mid : mid + 1]!, row) < 0) low = mid + 1;
    else high = mid;
  }
  // `copyWithin` runs about 80x slower than a plain loop on a number[] in V8.
  for (let i = position; i < low; i++) next[i] = next[i + 1]!;
  for (let i = position; i > low; i--) next[i] = next[i - 1]!;
  next[low] = row;
  return next;
}

/** Pulls each touched row out and binary-searches the surviving ones back in, one `splice` pair per row. */
function spliceRows(
  view: readonly number[],
  rows: readonly number[],
  survives: (row: number) => boolean,
  compare: (a: number, b: number) => number,
): number[] {
  const next = view.slice();
  for (const row of rows) {
    const position = next.indexOf(row);
    if (position !== -1) next.splice(position, 1);
  }
  for (const row of rows) {
    if (!survives(row)) continue;
    next.splice(lowerBound(next, row, compare), 0, row);
  }
  return next;
}

/** One pass that drops the touched rows, then stitches the surviving ones back in at their sorted places. */
function mergeRows(
  view: readonly number[],
  rows: readonly number[],
  survives: (row: number) => boolean,
  compare: (a: number, b: number) => number,
): number[] {
  const mark = markRows(rows);
  const rest: number[] = [];
  for (let i = 0; i < view.length; i++) {
    const row = view[i]!;
    if (row >= mark.length || mark[row] !== 1) rest.push(row);
  }
  const inserts = rows.filter(survives).sort(compare);
  const parts: number[][] = [];
  let from = 0;
  for (const row of inserts) {
    const at = lowerBound(rest, row, compare);
    parts.push(rest.slice(from, at), [row]);
    from = at;
  }
  parts.push(rest.slice(from));
  return ([] as number[]).concat(...parts);
}

import { resolveSelectChoices } from "../cell-types/select";
import { textAccessorFor } from "../store/compute";
import type { CellAccessor } from "./index";
import type { CellType } from "../types";
import type { AnyColumnDef } from "../store/types";

type SetFilterValuesInput = {
  columns: readonly AnyColumnDef[];
  data: readonly unknown[];
  cellTypes: Record<string, CellType>;
  filterMode: "client" | "server";
  fetchFilterValues?: unknown;
};

const MIN_CHOICE_LIST_BOUND = 64;

const serverListsValues = (state: Pick<SetFilterValuesInput, "filterMode" | "fetchFilterValues">) => state.filterMode === "server" || state.fetchFilterValues !== undefined;

/**
 * The list bound of an `isAnyOf` or `isNoneOf` list restored from a link or a saved view:
 * `undefined` (the default of 1,000) when the server lists the column's values, else the larger of
 * 64 and the number of static `choices`; `undefined` for a column without `choices`.
 */
export function setFilterListBound(state: Pick<SetFilterValuesInput, "filterMode" | "fetchFilterValues">, column: { id?: string; options?: unknown } | undefined): number | undefined {
  const choices = (column?.options as { choices?: unknown } | undefined)?.choices;
  if (serverListsValues(state) || !Array.isArray(choices) || choices.length === 0) return undefined;
  return Math.max(choices.length, MIN_CHOICE_LIST_BOUND);
}

/**
 * The lowercased values an `isAnyOf` or `isNoneOf` list restored from a link or a saved view may
 * keep: the column's `choices` plus every loaded data value, so each value the header filter offers
 * survives. Returns `undefined` (check nothing) for a column without choices, when the server lists the values
 * (`filterMode="server"` or `fetchFilterValues`; the server evaluates them), and while no data has loaded. Builds each column's set on
 * first use.
 */
export function setFilterValuesOf(state: SetFilterValuesInput): (columnId: string) => ReadonlySet<string> | undefined {
  if (serverListsValues(state) || state.data.length === 0) return () => undefined;
  const cache = new Map<string, ReadonlySet<string> | undefined>();
  let accessor: CellAccessor | undefined;
  return (columnId) => {
    if (cache.has(columnId)) return cache.get(columnId);
    const choices = (state.columns.find((c) => c.id === columnId)?.options as { choices?: Parameters<typeof resolveSelectChoices>[0] } | undefined)?.choices;
    let allowed: Set<string> | undefined;
    if (Array.isArray(choices) && choices.length > 0) {
      allowed = new Set(resolveSelectChoices(choices).map((choice) => choice.value.toLowerCase()));
      accessor ??= textAccessorFor(state.columns, state.data, state.cellTypes);
      for (let row = 0; row < state.data.length; row++) {
        if (state.data[row] !== undefined) allowed.add(accessor.getText(row, columnId).toLowerCase());
      }
    }
    cache.set(columnId, allowed);
    return allowed;
  };
}

import { isDev } from "../is-dev";

export const DEFAULT_SORT_LOCALE = "en-US";
const MAX_CACHED_LOCALES = 20;

type Collators = { base: Intl.Collator };

const cache = new Map<string, Collators>();
const warned = new Set<string>();
let activeLocale = DEFAULT_SORT_LOCALE;

function buildCollators(locale: string): Collators {
  return { base: new Intl.Collator([locale, DEFAULT_SORT_LOCALE], { numeric: true, sensitivity: "base" }) };
}

function warnOnce(locale: string, message: string) {
  if (isDev() && warned.size < MAX_CACHED_LOCALES && !warned.has(locale)) {
    warned.add(locale);
    console.warn(message);
  }
}

type LocaleProp = "sortLocale" | "locale";

function collatorsFor(locale: string, prop: LocaleProp = "sortLocale"): Collators {
  const cached = cache.get(locale);
  if (cached) return cached;
  let built: Collators;
  try {
    built = buildCollators(locale);
    if (Intl.Collator.supportedLocalesOf(locale).length === 0) {
      warnOnce(locale, `[data-grid] ${prop} "${locale}" is not supported by this runtime. The grid sorts with "${DEFAULT_SORT_LOCALE}".`);
    }
  } catch {
    warnOnce(locale, `[data-grid] ${prop} "${locale}" is not a valid language tag. The grid sorts with "${DEFAULT_SORT_LOCALE}".`);
    built = collatorsFor(DEFAULT_SORT_LOCALE);
  }
  if (cache.size >= MAX_CACHED_LOCALES) cache.delete(cache.keys().next().value as string);
  cache.set(locale, built);
  return built;
}

let warnedThenable = false;

/** Runs `run` with `locale` as the sort locale of every built-in text compare. The scope ends when `run` returns, so the callback must be synchronous: work after an `await` sorts with "en-US". Grids with different locales never mix. */
export function withSortLocale<T>(locale: string | undefined, run: () => T): T {
  const previous = activeLocale;
  activeLocale = locale ?? DEFAULT_SORT_LOCALE;
  try {
    const result = run();
    if (isDev() && !warnedThenable && typeof (result as { then?: unknown } | null)?.then === "function") {
      warnedThenable = true;
      console.warn("[data-grid] withSortLocale received a promise. The sort locale scope ends when the callback returns, so work after an await sorts with the default locale. Pass a synchronous callback.");
    }
    return result;
  } finally {
    activeLocale = previous;
  }
}

/** Builds the collators for a grid's sort locale and warns in development, naming the prop the tag came from. */
export function checkSortLocale(locale: string, prop: LocaleProp): void {
  collatorsFor(locale, prop);
}

/** Numeric, case- and accent-insensitive collator for `locale`, or for the sort locale in scope when `locale` is omitted. */
export function sortCollator(locale?: string): Intl.Collator {
  return collatorsFor(locale ?? activeLocale).base;
}

import { sortCollator } from "./sort-collator";

/** The built-in `number` cell type's `compare`; the keyed sort recognizes a column that uses it by identity. */
export function compareNumbers(a: number | null, b: number | null): number {
  if (a == null && b == null) return 0;
  if (a == null) return -1;
  if (b == null) return 1;
  return a - b;
}

/** The built-in `text` cell type's `compare`; the keyed sort recognizes a column that uses it by identity. */
export function compareLocaleText(a: string, b: string): number {
  if (typeof a !== "string" || typeof b !== "string") return NaN;
  return sortCollator().compare(a, b);
}

/** The built-in `date` cell type's `compare`; ISO date strings order by code unit. */
export function compareIsoDates(a: string | null, b: string | null): number {
  if (a == null && b == null) return 0;
  if (a == null) return -1;
  if (b == null) return 1;
  return a < b ? -1 : a > b ? 1 : 0;
}

/** The built-in `checkbox` cell type's `compare`; `false` orders before `true`. */
export function compareChecked(a: unknown, b: unknown): number {
  return Number(a) - Number(b);
}

import { compareSelect } from "../cell-types/select";
import type { CellType } from "../types";
import { compareChecked, compareIsoDates, compareLocaleText, compareNumbers } from "./builtin-compare";
import type { SortKeyReader } from "./keyed-sort";

type KeyPlan = { kind: SortKeyReader["kind"]; compare?: (a: string, b: string) => number; value?: (raw: unknown) => unknown };

const checkedNumber = (raw: unknown): unknown => (typeof raw === "boolean" ? Number(raw) : raw);

/** How the keyed sort reads a column whose cell type still has its built-in `compare`; `undefined` for any other. */
export function builtinKeyPlan(cellType: CellType, options: unknown): KeyPlan | undefined {
  const { compare } = cellType;
  if (compare === compareNumbers) return { kind: "number" };
  if (compare === compareLocaleText) return { kind: "text" };
  if (compare === compareIsoDates) return { kind: "ranked", compare: (a, b) => (a < b ? -1 : a > b ? 1 : 0) };
  if (compare === compareChecked) return { kind: "number", value: checkedNumber };
  if (compare === compareSelect) return { kind: "ranked", compare: (a, b) => compareSelect(a, b, options as Parameters<typeof compareSelect>[2]) };
  return undefined;
}

import type { SortSpec } from "../types";
import type { CellAccessor } from "./build-view-index";
import { sortCollator } from "./sort-collator";

/** Below this many rows the comparator-chain sort wins on setup cost, so the keyed sort stays out. */
export const KEYED_SORT_MIN_ROWS = 256;

/** What a {@link SortKeyReader} returns for an empty cell. */
export const EMPTY_SORT_VALUE: unique symbol = Symbol("empty-sort-value");

/**
 * Reads one column's raw sort values for the keyed sort. `kind: "number"` promises that the column
 * orders finite numbers by `a - b`; `kind: "text"` promises that it orders strings by `localeCompare`;
 * `kind: "ranked"` promises that it orders strings by its own consistent `compare`, and strings that compare
 * as equal share a rank. `kind: "untyped"` orders finite numbers by `a - b` before any other value, which orders by its text.
 * `read` returns {@link EMPTY_SORT_VALUE} for a cell that sorts last in both directions.
 */
export type SortKeyReader =
  | { kind: "number" | "text" | "untyped"; read(rowIndex: number): unknown }
  | { kind: "ranked"; compare: (a: string, b: string) => number; read(rowIndex: number): unknown };

/** A value the untyped sort orders by number: a finite `number`. */
export const isSortNumber = (value: unknown): value is number => typeof value === "number" && Number.isFinite(value);

const LITTLE_ENDIAN = new Uint8Array(new Uint32Array([1]).buffer)[0] === 1;
/** Beyond this magnitude two finite numbers can differ by Infinity, which the comparator treats as unordered. */
const NUMBER_LIMIT = 1e300;

type Keys = { lo: Uint32Array; hi: Uint32Array | null; bytes: number };

/**
 * Number keys: the IEEE-754 bits, flipped so unsigned integer order equals numeric order. Descending
 * inverts every bit. An empty cell takes the all-ones key, which no finite number maps to, so it sorts
 * last in both directions. Returns `null` for a value the plain comparator would not order by `a - b`.
 */
function numberKeys(indices: readonly number[], read: (row: number) => unknown, descending: boolean): Keys | null {
  const count = indices.length;
  const lo = new Uint32Array(count);
  const hi = new Uint32Array(count);
  const float = new Float64Array(1);
  const bits = new Uint32Array(float.buffer);
  for (let position = 0; position < count; position++) {
    const value = read(indices[position]!);
    if (value === EMPTY_SORT_VALUE) {
      lo[position] = 0xffffffff;
      hi[position] = 0xffffffff;
      continue;
    }
    if (typeof value !== "number" || value > NUMBER_LIMIT || value < -NUMBER_LIMIT || value !== value) return null;
    float[0] = value === 0 ? 0 : value;
    let high = bits[1]!;
    let low = bits[0]!;
    if (high & 0x80000000) {
      high = ~high;
      low = ~low;
    } else {
      high |= 0x80000000;
    }
    if (descending) {
      high = ~high;
      low = ~low;
    }
    lo[position] = low;
    hi[position] = high;
  }
  return { lo, hi, bytes: 8 };
}

/**
 * Text keys: the dense rank of each row's string under `compare`, so equal strings (and strings the
 * comparator calls equal) share a key. Only the distinct strings are sorted. `readText` returns `null`
 * for an empty cell, which takes the largest key in both directions; it returns `undefined` for a value
 * the keyed sort cannot rank.
 */
function textKeys(
  count: number,
  readText: (position: number) => string | null | undefined,
  compare: (a: string, b: string) => number,
  descending: boolean,
): Keys | null {
  const ids = new Uint32Array(count);
  const idOf = new Map<string, number>();
  const distinct: string[] = [];
  const EMPTY_ID = 0xffffffff;
  for (let position = 0; position < count; position++) {
    const text = readText(position);
    if (text === undefined) return null;
    if (text === null) {
      ids[position] = EMPTY_ID;
      continue;
    }
    let id = idOf.get(text);
    if (id === undefined) {
      id = distinct.length;
      idOf.set(text, id);
      distinct.push(text);
    }
    ids[position] = id;
  }
  const ordered = distinct.sort(compare);
  const rankOfId = new Uint32Array(distinct.length);
  let rank = 0;
  for (let i = 0; i < ordered.length; i++) {
    if (i > 0 && compare(ordered[i - 1]!, ordered[i]!) !== 0) rank++;
    rankOfId[idOf.get(ordered[i]!)!] = rank;
  }
  const emptyKey = ordered.length === 0 ? 0 : rank + 1;
  const lo = ids;
  for (let position = 0; position < count; position++) {
    const id = ids[position]!;
    lo[position] = id === EMPTY_ID ? emptyKey : descending ? rank - rankOfId[id]! : rankOfId[id]!;
  }
  return { lo, hi: null, bytes: emptyKey > 0xffffff ? 4 : emptyKey > 0xffff ? 3 : emptyKey > 0xff ? 2 : 1 };
}

type Buffers = { order: Uint32Array; spareOrder: Uint32Array; lo: Uint32Array; spareLo: Uint32Array; hi: Uint32Array; spareHi: Uint32Array };

/**
 * One stable least-significant-digit radix sort of `buffers.order` by `keys`. A byte that is the same in
 * every key is skipped. Returns the buffers with `order` holding the new order.
 */
function radixStage(buffers: Buffers, keys: Keys, count: number): Buffers {
  let { order, spareOrder, lo, spareLo, hi, spareHi } = buffers;
  const hasHigh = keys.hi !== null;
  for (let i = 0; i < count; i++) {
    const row = order[i]!;
    lo[i] = keys.lo[row]!;
    if (hasHigh) hi[i] = keys.hi![row]!;
  }
  const counts = new Uint32Array(8 * 256);
  for (let i = 0; i < count; i++) {
    const low = lo[i]!;
    counts[low & 0xff]!++;
    counts[256 + ((low >>> 8) & 0xff)]!++;
    counts[512 + ((low >>> 16) & 0xff)]!++;
    counts[768 + (low >>> 24)]!++;
    if (hasHigh) {
      const high = hi[i]!;
      counts[1024 + (high & 0xff)]!++;
      counts[1280 + ((high >>> 8) & 0xff)]!++;
      counts[1536 + ((high >>> 16) & 0xff)]!++;
      counts[1792 + (high >>> 24)]!++;
    }
  }
  const offsets = new Uint32Array(256);
  for (let pass = 0; pass < keys.bytes; pass++) {
    const base = pass * 256;
    let single = false;
    let sum = 0;
    for (let bucket = 0; bucket < 256; bucket++) {
      const size = counts[base + bucket]!;
      if (size === count) single = true;
      offsets[bucket] = sum;
      sum += size;
    }
    if (single) continue;
    const useHigh = pass >= 4;
    const shift = (pass & 3) * 8;
    if (useHigh) {
      for (let i = 0; i < count; i++) {
        const high = hi[i]!;
        const target = offsets[(high >>> shift) & 0xff]!++;
        spareOrder[target] = order[i]!;
        spareLo[target] = lo[i]!;
        spareHi[target] = high;
      }
      [hi, spareHi] = [spareHi, hi];
    } else if (hasHigh) {
      for (let i = 0; i < count; i++) {
        const low = lo[i]!;
        const target = offsets[(low >>> shift) & 0xff]!++;
        spareOrder[target] = order[i]!;
        spareLo[target] = low;
        spareHi[target] = hi[i]!;
      }
      [hi, spareHi] = [spareHi, hi];
    } else {
      for (let i = 0; i < count; i++) {
        const low = lo[i]!;
        const target = offsets[(low >>> shift) & 0xff]!++;
        spareOrder[target] = order[i]!;
        spareLo[target] = low;
      }
    }
    [order, spareOrder] = [spareOrder, order];
    [lo, spareLo] = [spareLo, lo];
  }
  return { order, spareOrder, lo, spareLo, hi, spareHi };
}

function keysFor(indices: readonly number[], accessor: CellAccessor, sort: SortSpec): Keys | null {
  const descending = sort.direction === "desc";
  const reader = accessor.sortKeys?.(sort.columnId);
  if (reader?.kind === "untyped") {
    const numbers = numberKeys(indices, reader.read, descending);
    if (numbers) return numbers;
    // Numbers mixed with text need the two-tier comparator; text alone keys exactly by its collation.
    if (indices.some((row) => isSortNumber(reader.read(row)))) return null;
    return textKeys(
      indices.length,
      (position) => {
        const text = accessor.getText(indices[position]!, sort.columnId);
        return text === "" ? null : text;
      },
      sortCollator().compare,
      descending,
    );
  }
  if (reader) {
    if (reader.kind === "number") return numberKeys(indices, reader.read, descending);
    const compare = reader.kind === "ranked" ? reader.compare : sortCollator().compare;
    return textKeys(
      indices.length,
      (position) => {
        const value = reader.read(indices[position]!);
        if (value === EMPTY_SORT_VALUE) return null;
        return typeof value === "string" ? value : undefined;
      },
      compare,
      descending,
    );
  }
  if (accessor.compare?.(sort.columnId)) return null;
  return textKeys(
    indices.length,
    (position) => {
      const text = accessor.getText(indices[position]!, sort.columnId);
      return text === "" ? null : text;
    },
    sortCollator().compare,
    descending,
  );
}

/**
 * Sorts `indices` (ascending data indices) by `sorts` without a per-comparison callback: each sort
 * column becomes an unsigned integer key per row, and one stable radix pass per key byte orders the
 * rows from the last sort column to the first. A tie on every key keeps data order. Returns `null`
 * when any column cannot be keyed exactly, and the caller then runs the comparator-chain sort.
 */
export function sortByKeys(indices: readonly number[], accessor: CellAccessor, sorts: readonly SortSpec[]): number[] | null {
  if (!LITTLE_ENDIAN) return null;
  const count = indices.length;
  if (sorts.some((sort) => !accessor.sortKeys?.(sort.columnId) && accessor.compare?.(sort.columnId))) return null;
  const keys: Keys[] = [];
  for (const sort of sorts) {
    const column = keysFor(indices, accessor, sort);
    if (!column) return null;
    keys.push(column);
  }
  const order = new Uint32Array(count);
  for (let i = 0; i < count; i++) order[i] = i;
  let buffers: Buffers = {
    order,
    spareOrder: new Uint32Array(count),
    lo: new Uint32Array(count),
    spareLo: new Uint32Array(count),
    hi: new Uint32Array(keys.some((column) => column.hi) ? count : 0),
    spareHi: new Uint32Array(keys.some((column) => column.hi) ? count : 0),
  };
  for (let i = keys.length - 1; i >= 0; i--) buffers = radixStage(buffers, keys[i]!, count);
  const result = new Array<number>(count);
  for (let i = 0; i < count; i++) result[i] = indices[buffers.order[i]!]!;
  return result;
}

import { toSafeText } from "../cell-types/safe-text";
import { isDev } from "../is-dev";
import { EMPTY_SORT_VALUE, isSortNumber, type SortKeyReader } from "./keyed-sort";
import { sortCollator } from "./sort-collator";

const MAX_WARNED_MIXED_COLUMNS = 100;
const warnedMixedColumns = new Set<string>();

function warnMixedUntypedSort(columnId: string): void {
  if (!isDev() || warnedMixedColumns.has(columnId) || warnedMixedColumns.size >= MAX_WARNED_MIXED_COLUMNS) return;
  warnedMixedColumns.add(columnId);
  console.warn(`[data-grid] the untyped column "${columnId}" sorts numbers and text together, so its numbers sort before its text. Set \`type\` on the column, or give it one value type.`);
}

/**
 * The comparator and keyed-sort reader of a column without `type`: it holds whatever the rows hold, so finite
 * numbers order by value before any other value, which orders by its text under the sort collator.
 */
export function untypedSort(columnId: string, data: readonly unknown[], valueOf: (row: unknown) => unknown): { compare: (a: number, b: number) => number; sortKeys: SortKeyReader } {
  const compare = (a: number, b: number) => {
    const rowA = data[a];
    const rowB = data[b];
    if (rowA === undefined || rowB === undefined) return 0;
    const valueA = valueOf(rowA);
    const valueB = valueOf(rowB);
    const numberA = isSortNumber(valueA);
    const numberB = isSortNumber(valueB);
    if (numberA && numberB) return valueA - valueB || 0;
    if (numberA !== numberB) {
      warnMixedUntypedSort(columnId);
      return numberA ? -1 : 1;
    }
    return sortCollator().compare(toSafeText(valueA), toSafeText(valueB));
  };
  const read = (rowIndex: number) => {
    const row = data[rowIndex];
    if (row === undefined) return EMPTY_SORT_VALUE;
    const value = valueOf(row);
    return value == null || toSafeText(value) === "" ? EMPTY_SORT_VALUE : value;
  };
  return { compare, sortKeys: { kind: "untyped", read } };
}

import { sortCollator } from "./sort-collator";

/**
 * Default text comparator: numeric-aware localeCompare that ignores case and accents.
 * Empty strings always sort last, regardless of direction (callers must not
 * negate this result wholesale).
 * `collator` lets a caller reuse one Intl.Collator across many comparisons.
 */
export function defaultCompareText(a: string, b: string, collator: Intl.Collator = sortCollator()): number {
  const aEmpty = a === "";
  const bEmpty = b === "";
  if (aEmpty && bEmpty) return 0;
  if (aEmpty) return 1;
  if (bEmpty) return -1;
  return collator.compare(a, b);
}

import { searchTextReader, type CellAccessor } from "./build-view-index";
import type { SearchOptions } from "../types";

/** One search hit, in row-major order, for highlight and next/prev navigation. */
export type SearchMatch = { row: number; columnId: string };

/**
 * The cell-text predicate behind the quick search: the trimmed `search` as a literal substring (or,
 * with `wholeCell`, the whole text), case-insensitive unless `matchCase`. `null` for a blank search.
 */
export function createTextMatcher(search: string, options: SearchOptions = {}): ((text: string) => boolean) | null {
  const trimmed = search.trim();
  if (trimmed === "") return null;
  const { matchCase = false, wholeCell = false } = options;
  if (matchCase) return wholeCell ? (text) => text === trimmed : (text) => text.includes(trimmed);
  const needle = trimmed.toLowerCase();
  return wholeCell ? (text) => text.toLowerCase() === needle : (text) => text.toLowerCase().includes(needle);
}

/**
 * Finds every cell whose search text matches `search` (a literal substring, case-insensitive unless
 * `options.matchCase`; the whole text with `options.wholeCell`) across
 * `columnIds`, in row-major order — the order next/prev navigation and
 * highlight rendering expect. `maxMatches`, when given, early-exits the scan
 * the moment that many hits are collected (bounds worst-case work
 * at 100k+ rows for a common search term; omitted keeps the full scan).
 */
export function findSearchMatches(
  rowCount: number,
  accessor: CellAccessor,
  search: string,
  columnIds: string[],
  maxMatches?: number,
  options?: SearchOptions,
): SearchMatch[] {
  const matches: SearchMatch[] = [];
  const isMatch = createTextMatcher(search, options);
  if (isMatch === null) return matches;

  const readSearchText = searchTextReader(accessor);
  for (let row = 0; row < rowCount; row++) {
    for (const columnId of columnIds) {
      if (isMatch(readSearchText(row, columnId))) {
        matches.push({ row, columnId });
        if (maxMatches !== undefined && matches.length >= maxMatches) return matches;
      }
    }
  }
  return matches;
}

import type { FilterGroup, FilterJoinOperator, FilterNode, FilterSpec } from "../types";

/** Deepest group nesting a filter tree may have: a group (1) holds at most one more group (2). */
export const MAX_FILTER_GROUP_DEPTH = 2;

/** Most sort entries that URL state restores and `parseServerSpec` accepts by default. */
export const MAX_SPEC_SORTS = 64;

/** Longest search text that URL state and saved views restore and `parseServerSpec` accepts by default. */
export const MAX_SPEC_SEARCH_LENGTH = 500;

const orRoots = new WeakMap<readonly FilterNode[], FilterNode[]>();

/** The tree to evaluate for a root join: `"or"` over two or more entries is one `or` group, any other input is returned as is. The wrapper keeps its identity per list. */
export function withRootJoin(filters: readonly FilterNode[], join: FilterJoinOperator | undefined): readonly FilterNode[] {
  if (join !== "or" || filters.length < 2) return filters;
  let wrapped = orRoots.get(filters);
  if (!wrapped) orRoots.set(filters, (wrapped = [{ join: "or", filters: filters as FilterNode[] }]));
  return wrapped;
}

export function isFilterGroup(node: FilterNode): node is FilterGroup {
  return "filters" in node;
}

/** The children of a group; a controlled `filterState` can carry a non-array, which reads as empty. */
export function groupChildren(group: FilterGroup): readonly FilterNode[] {
  return Array.isArray(group.filters) ? group.filters : [];
}

/** Calls `visit` for every {@link FilterSpec} row at every level. */
export function forEachFilterSpec(nodes: readonly FilterNode[], visit: (spec: FilterSpec) => void): void {
  for (const node of nodes) {
    if (isFilterGroup(node)) forEachFilterSpec(groupChildren(node), visit);
    else visit(node);
  }
}

export function hasFilterOnColumn(nodes: readonly FilterNode[], columnId: string): boolean {
  return nodes.some((node) => (isFilterGroup(node) ? hasFilterOnColumn(groupChildren(node), columnId) : node.columnId === columnId));
}

export function countFilterSpecs(nodes: readonly FilterNode[]): number {
  let count = 0;
  forEachFilterSpec(nodes, () => (count += 1));
  return count;
}

/**
 * Keeps the rows `keep` accepts at every level and drops groups left empty. Returns the input array
 * itself when nothing changes, so a stable tree stays a stable reference. With `dropLossyNegated`, a negated group that loses any descendant goes whole, because fewer terms inside a negation match other rows.
 */
export function pruneFilterSpecs(nodes: readonly FilterNode[], keep: (spec: FilterSpec) => boolean, dropLossyNegated = false): FilterNode[] {
  let changed = false;
  const next: FilterNode[] = [];
  for (const node of nodes) {
    if (!isFilterGroup(node)) {
      if (keep(node)) next.push(node);
      else changed = true;
      continue;
    }
    const children = groupChildren(node);
    const kept = pruneFilterSpecs(children, keep, dropLossyNegated);
    if ((kept.length === 0 && children.length > 0) || (dropLossyNegated && node.not === true && kept !== children)) changed = true;
    else if (kept !== children) {
      next.push({ ...node, filters: kept });
      changed = true;
    } else next.push(node);
  }
  return changed ? next : (nodes as FilterNode[]);
}

/** Domain barrel — sort/filter/search: compare fns, filter matching, view-index, search matches. */
export { defaultCompareText } from "./default-compare-text";
export { matchesFilter, createFilterMatcher, isBuiltInOperator, type FilterMatcherOptions } from "./matches-filter";
export { buildViewIndex, isEmptyCell, makeFilterNodeTest, makeFilterTest, searchTextReader, type CellAccessor, type ViewIndexOptions } from "./build-view-index";
export { createTextMatcher, findSearchMatches, type SearchMatch } from "./find-search-matches";
export {
  updateViewIndex,
  makeViewComparator,
  makeFilterPredicate,
  lowerBound,
  INCREMENTAL_PATCH_LIMIT,
  type IncrementalBailReason,
  type IncrementalViewIndexResult,
} from "./incremental-view-index";
export {
  MAX_FILTER_GROUP_DEPTH,
  countFilterSpecs,
  forEachFilterSpec,
  groupChildren,
  hasFilterOnColumn,
  isFilterGroup,
  pruneFilterSpecs,
} from "./filter-tree";

import type { BuiltInFilterOperator, FilterSpec } from "../types";
import { defaultCompareText } from "./default-compare-text";

function parseNumber(text: string): number | null {
  if (text.trim() === "") return null;
  const n = Number(text);
  return Number.isNaN(n) ? null : n;
}

/** How a filter orders and evaluates text beyond the built-in rules; both come from the column. */
export type FilterMatcherOptions = {
  /** Orders cell text against a bound for `gt`, `gte`, `lt`, `lte`, `isBetween`; a throw or NaN falls back to the default order. */
  compare?: (text: string, bound: string) => number;
  /** Evaluates an operator that is not built in. */
  custom?: (text: string, filter: FilterSpec) => boolean;
  /** Respects letter case in the text and set operators. Default `false`: `"bonn"` equals `"Bonn"`. */
  matchCase?: boolean;
};

const lowerCase = (text: string) => text.toLowerCase();
const sameCase = (text: string) => text;

const BUILT_IN_OPERATORS: ReadonlySet<string> = new Set<BuiltInFilterOperator>([
  "contains",
  "notContains",
  "equals",
  "notEquals",
  "startsWith",
  "endsWith",
  "empty",
  "notEmpty",
  "gt",
  "gte",
  "lt",
  "lte",
  "isBetween",
  "isAnyOf",
  "isNoneOf",
]);

/** Whether `operator` is one of the built-in operators. */
export function isBuiltInOperator(operator: string): boolean {
  return BUILT_IN_OPERATORS.has(operator);
}

/** The column comparator's order, or `undefined` when it throws or returns NaN. */
function customOrder(compare: FilterMatcherOptions["compare"], text: string, bound: string): number | undefined {
  if (!compare) return undefined;
  try {
    const order = compare(text, bound);
    return Number.isNaN(order) ? undefined : order;
  } catch {
    return undefined;
  }
}

/** A custom operator's test: a throw fails the row; without an evaluator every row passes. */
function customOperatorTest(filter: FilterSpec, custom: FilterMatcherOptions["custom"]): (text: string) => boolean {
  if (!custom) return () => true;
  return (text) => {
    try {
      return custom(text, filter);
    } catch {
      return false;
    }
  };
}

/** Compares `text` against `bound` numerically when both parse as numbers, else via `defaultCompareText`. */
function compareTextTo(text: string, bound: string, compare?: FilterMatcherOptions["compare"]): number {
  const custom = customOrder(compare, text, bound);
  if (custom !== undefined) return custom;
  const a = parseNumber(text);
  const b = parseNumber(bound);
  if (a !== null && b !== null) return a - b;
  return defaultCompareText(text, bound);
}

/** The string entries of a list filter; a controlled `filterState` can carry other JSON values. */
function stringChoices(filter: FilterSpec): string[] {
  return Array.isArray(filter.value) ? filter.value.filter((choice): choice is string => typeof choice === "string") : [];
}

/**
 * Evaluates a single {@link FilterSpec} against a cell's text value.
 * `gt`/`gte`/`lt`/`lte` compare numerically when both sides parse as
 * numbers, else fall back to `defaultCompareText`; blank cell text never
 * satisfies these comparisons. `empty`/`notEmpty` ignore `filter.value`.
 * `isBetween` is inclusive on both ends; an empty bound (`""`) leaves that
 * side open (e.g. `["", "10"]` means "<= 10"). `isAnyOf` matches when the cell
 * text equals any entry of its `string[]`, compared case-insensitively like `equals`;
 * `isNoneOf` is the complement (an empty list matches every row).
 *
 * This is the correctness reference (re-parses `filter.value` on every call) — {@link createFilterMatcher}
 * is the same semantics with the bound(s) parsed once, for a hot per-row loop over many rows.
 */
export function matchesFilter(text: string, filter: FilterSpec, options: FilterMatcherOptions = {}): boolean {
  const op = filter.operator;
  if (!BUILT_IN_OPERATORS.has(op)) return customOperatorTest(filter, options.custom)(text);
  const fold = options.matchCase ? sameCase : lowerCase;
  if (op === "empty") return text === "";
  if (op === "notEmpty") return text !== "";

  if (op === "isAnyOf") {
    // an empty choice list matches nothing, so a half-built filter row hides every row rather than being a no-op
    const textLower = fold(text);
    return stringChoices(filter).some((choice) => fold(choice) === textLower);
  }

  if (op === "isNoneOf") {
    const textLower = fold(text);
    return !stringChoices(filter).some((choice) => fold(choice) === textLower);
  }

  if (op === "isBetween") {
    // Excel/AG Grid semantics: blank cells never satisfy a comparison filter.
    if (text === "") return false;
    const [min = "", max = ""] = Array.isArray(filter.value) ? filter.value : ["", ""];
    if (min !== "" && compareTextTo(text, min, options.compare) < 0) return false;
    if (max !== "" && compareTextTo(text, max, options.compare) > 0) return false;
    return true;
  }

  const value = typeof filter.value === "string" ? filter.value : "";
  const textLower = fold(text);
  const valueLower = fold(value);

  switch (op as BuiltInFilterOperator) {
    case "contains":
      return textLower.includes(valueLower);
    case "notContains":
      return !textLower.includes(valueLower);
    case "equals":
      return textLower === valueLower;
    case "notEquals":
      return textLower !== valueLower;
    case "startsWith":
      return textLower.startsWith(valueLower);
    case "endsWith":
      return textLower.endsWith(valueLower);
    case "gt":
    case "gte":
    case "lt":
    case "lte": {
      // Excel/AG Grid semantics: blank cells never satisfy a comparison filter.
      if (text === "") return false;
      const cmp = compareTextTo(text, value, options.compare);
      if (op === "gt") return cmp > 0;
      if (op === "gte") return cmp >= 0;
      if (op === "lt") return cmp < 0;
      return cmp <= 0;
    }
    default:
      return true;
  }
}

/** A bound pre-parsed once (outside the per-row loop) plus its original text for the string fallback path. */
type ParsedBound = { raw: string; num: number | null };

function parseBound(raw: string): ParsedBound {
  return { raw, num: parseNumber(raw) };
}

/** Compares `text` against a {@link ParsedBound}: numeric if `text` also parses, else falls back to `defaultCompareText`. */
function compareTextToParsedBound(text: string, bound: ParsedBound, compare?: FilterMatcherOptions["compare"]): number {
  const custom = customOrder(compare, text, bound.raw);
  if (custom !== undefined) return custom;
  if (bound.num !== null) {
    const a = parseNumber(text);
    if (a !== null) return a - bound.num;
  }
  return defaultCompareText(text, bound.raw);
}

/**
 * Builds a per-row matcher for `filter` with any numeric bound(s) in `filter.value` parsed exactly
 * once, instead of on every {@link matchesFilter} call — `gt`/`gte`/`lt`/`lte`/`isBetween` bounds are
 * the same string across every row of a `buildViewIndex` pass, so re-parsing them per row (as a
 * direct `matchesFilter` call in a `.filter()` predicate does) is O(n) redundant work. Same
 * semantics as `matchesFilter`, verified by build-view-index's own tests; kept in sync manually
 * since duplicating a switch this small behind a shared abstraction would obscure both.
 */
export function createFilterMatcher(filter: FilterSpec, options: FilterMatcherOptions = {}): (text: string) => boolean {
  const op = filter.operator;
  if (!BUILT_IN_OPERATORS.has(op)) return customOperatorTest(filter, options.custom);
  const { compare } = options;
  const fold = options.matchCase ? sameCase : lowerCase;
  if (op === "empty") return (text) => text === "";
  if (op === "notEmpty") return (text) => text !== "";

  if (op === "isAnyOf") {
    const set = new Set(stringChoices(filter).map((choice) => fold(choice)));
    return (text) => set.has(fold(text));
  }

  if (op === "isNoneOf") {
    const set = new Set(stringChoices(filter).map((choice) => fold(choice)));
    return (text) => !set.has(fold(text));
  }

  if (op === "isBetween") {
    const [minRaw = "", maxRaw = ""] = Array.isArray(filter.value) ? filter.value : ["", ""];
    const min = minRaw !== "" ? parseBound(minRaw) : null;
    const max = maxRaw !== "" ? parseBound(maxRaw) : null;
    return (text) => {
      if (text === "") return false;
      if (min && compareTextToParsedBound(text, min, compare) < 0) return false;
      if (max && compareTextToParsedBound(text, max, compare) > 0) return false;
      return true;
    };
  }

  const value = typeof filter.value === "string" ? filter.value : "";

  switch (op as BuiltInFilterOperator) {
    case "contains": {
      const needle = fold(value);
      return (text) => fold(text).includes(needle);
    }
    case "notContains": {
      const needle = fold(value);
      return (text) => !fold(text).includes(needle);
    }
    case "equals": {
      const needle = fold(value);
      return (text) => fold(text) === needle;
    }
    case "notEquals": {
      const needle = fold(value);
      return (text) => fold(text) !== needle;
    }
    case "startsWith": {
      const needle = fold(value);
      return (text) => fold(text).startsWith(needle);
    }
    case "endsWith": {
      const needle = fold(value);
      return (text) => fold(text).endsWith(needle);
    }
    case "gt":
    case "gte":
    case "lt":
    case "lte": {
      const bound = parseBound(value);
      return (text) => {
        if (text === "") return false;
        const cmp = compareTextToParsedBound(text, bound, compare);
        if (op === "gt") return cmp > 0;
        if (op === "gte") return cmp >= 0;
        if (op === "lt") return cmp < 0;
        return cmp <= 0;
      };
    }
    default:
      return () => true;
  }
}

/**
 * A matcher over raw numbers for `gt`/`gte`/`lt`/`lte`/`isBetween`, or `null` when the filter has a bound that does not
 * parse as a number. For a non-NaN number it returns what {@link createFilterMatcher} returns for `String(value)`,
 * minus the number-to-text-to-number round trip.
 */
export function createNumberMatcher(filter: FilterSpec): ((value: number) => boolean) | null {
  const op = filter.operator;
  if (op === "isBetween") {
    const [minRaw = "", maxRaw = ""] = Array.isArray(filter.value) ? filter.value : ["", ""];
    const min = minRaw !== "" ? parseNumber(minRaw) : null;
    const max = maxRaw !== "" ? parseNumber(maxRaw) : null;
    if ((minRaw !== "" && min === null) || (maxRaw !== "" && max === null)) return null;
    return (value) => !(min !== null && value - min < 0) && !(max !== null && value - max > 0);
  }
  if (op !== "gt" && op !== "gte" && op !== "lt" && op !== "lte") return null;
  const bound = parseNumber(typeof filter.value === "string" ? filter.value : "");
  if (bound === null) return null;
  if (op === "gt") return (value) => value - bound > 0;
  if (op === "gte") return (value) => value - bound >= 0;
  if (op === "lt") return (value) => value - bound < 0;
  return (value) => value - bound <= 0;
}

import type { StoreApi } from "zustand/vanilla";
import type { DataGridApi, DataGridStoreWrapper } from "../types";
import type { DataGridStoreState } from "./types";
import { holeRowId } from "./compute";
import { getInternalActions } from "./internal-actions";
import { resolveRefOrWarn } from "./data-write";
import { readSelectedRows } from "./selected-rows";
import { dataIndexAt } from "./view-rows";

const handles = new WeakMap<StoreApi<DataGridStoreState>, DataGridApi<unknown>>();
const wrappers = new WeakMap<StoreApi<DataGridStoreState>, DataGridStoreWrapper>();
const storesByWrapper = new WeakMap<DataGridStoreWrapper, StoreApi<DataGridStoreState>>();

/**
 * The grid's read-only store view ({@link DataGridStoreWrapper}), one identity per store.
 * `useDataGridStoreProps` owns the writable store; this is what `api.store` and the sdk's
 * `useDataGridStoreApi` expose to consumers and plugins.
 * @internal
 */
export function gridStoreWrapper(store: StoreApi<DataGridStoreState>): DataGridStoreWrapper {
  let wrapper = wrappers.get(store);
  if (!wrapper) {
    wrapper = {
      getState: () => store.getState(),
      getInitialState: () => store.getInitialState(),
      subscribe: (listener) => store.subscribe(listener),
    };
    wrappers.set(store, wrapper);
    storesByWrapper.set(wrapper, store);
  }
  return wrapper;
}

/**
 * Registers what `reconcileView()` and `reorder: "immediate"` call on a server grid; `null` removes it. The hook
 * `useDataGridServerRows` registers its reshape here.
 * @internal
 */
export function setServerReshapeHandler(wrapper: DataGridStoreWrapper, handler: ((trigger: "urgent" | "stale") => void) | null): void {
  const store = storesByWrapper.get(wrapper);
  if (store) store.getState().dataWrite.reshape = handler;
}

/**
 * The grid's imperative handle, one identity per store. Its DOM gestures run through the impls
 * the mounted `DataGridRoot` registers, so it works anywhere under the provider.
 * @internal
 */
export function apiHandleOf<TData>(storeApi: StoreApi<DataGridStoreState>): DataGridApi<TData> {
  let api = handles.get(storeApi);
  if (!api) {
    api = buildApiHandle(storeApi);
    handles.set(storeApi, api);
  }
  return api as DataGridApi<TData>;
}

function buildApiHandle(storeApi: StoreApi<DataGridStoreState>): DataGridApi<unknown> {
  const read = () => storeApi.getState();
  const actions = read().actions;
  return {
    actions,
    store: gridStoreWrapper(storeApi),
    scrollTo(ref) {
      const s = read();
      const coord = resolveRefOrWarn(s.dataWrite, s, ref);
      if (coord) s.scrollToCellImpl?.(coord);
    },
    focus() {
      const s = read();
      if (s.editing) return;
      if (s.activeCell) s.scrollToCellImpl?.(s.activeCell);
      s.focusImpl?.();
    },
    runShortcut(action) {
      read().runShortcutImpl?.(action);
    },
    getSelection() {
      return getInternalActions(storeApi)._deriveSelection();
    },
    getSelectedRows() {
      return readSelectedRows(read());
    },
    getRow(viewRowIndex) {
      const s = read();
      const dataRowIndex = dataIndexAt(s, viewRowIndex);
      return dataRowIndex === undefined ? undefined : s.data[dataRowIndex];
    },
    getViewRowIds(options) {
      const s = read();
      const ids: string[] = [];
      for (const dataRowIndex of s.viewIndex) {
        if (dataRowIndex < 0) continue;
        const row = s.data[dataRowIndex];
        if (row !== undefined) ids.push(s.getRowId(row, dataRowIndex));
        else if (!options?.loaded) ids.push(holeRowId(dataRowIndex));
      }
      return ids;
    },
  };
}

/** Whether an event-time gate answered with a promise instead of a plain value. */
export function isThenable<T = unknown>(value: unknown): value is PromiseLike<T> {
  return typeof value === "object" && value !== null && typeof (value as { then?: unknown }).then === "function";
}

import { createContext } from "react";
import type { StoreApi } from "zustand/vanilla";
import type { DataGridStoreState } from "./types";

/** The grid store's React context, in a module with no runtime imports of the store, so a cell type can read it without an import cycle. */
export const DataGridStoreContext = createContext<StoreApi<DataGridStoreState> | null>(null);

import type { DataGridStoreState } from "./types";

/** The consumer hooks that may answer with a promise; `import` is the import dialog's parse and build, `mapColumn` its column match, `processReplace` the find-replace panel's hook, `validate` an async column `validate` that holds a paste, fill, or clear. */
export type GateName = "processPaste" | "processCellFromClipboard" | "validateRow" | "onBeforeEditStart" | "createRow" | "duplicateRow" | "onBeforeDeleteRows" | "import" | "mapColumn" | "processReplace" | "validate" | "processFill" | "resolveTexts";

/** The last argument of an async gate: `signal` aborts when a newer run supersedes this one, the result can no longer apply, or the grid unmounts. */
export type GateContext = { signal: AbortSignal };

/** Shared identity while no gate is pending, so a selector on `gatesPending` does not churn. */
export const EMPTY_GATES_PENDING: ReadonlySet<GateName> = new Set<GateName>();

/** Returns true when the store change makes the run's result unable to apply. */
export type GateWatch = (now: DataGridStoreState, prev: DataGridStoreState) => boolean;

/**
 * One run of a gate. The `signal` getter creates its controller on first read, so a sync gate that
 * never reads it pays for no controller. The run itself is the `{ signal }` context of `validateRow`.
 */
export class GateRun {
  aborted = false;
  private controller: AbortController | null = null;

  constructor(
    readonly name: GateName,
    public watch?: GateWatch,
  ) {}

  get signal(): AbortSignal {
    if (!this.controller) {
      this.controller = new AbortController();
      if (this.aborted) this.controller.abort();
    }
    return this.controller.signal;
  }

  cancel(): void {
    this.aborted = true;
    this.controller?.abort();
  }
}

export type GateTracker = {
  /** Creates an untracked run: the gate is sync until {@link GateTracker.hold} is called. */
  begin(name: GateName, watch?: GateWatch): GateRun;
  /** Marks the run pending: it returned a promise. */
  hold(run: GateRun): void;
  /** Marks the run done; a no-op when it was aborted or already settled. */
  settle(run: GateRun): void;
  /** Aborts a run and takes it out of the pending set. */
  abortRun(run: GateRun, reason?: GateAbortReason): void;
  /** Aborts every live run, or only the runs of the named gates; `reason` defaults to `"reset"`. */
  abort(names?: readonly GateName[], reason?: GateAbortReason): void;
  /** Marks `name` pending for work the grid does not run itself (the import dialog); returns the release. */
  track(name: GateName): () => void;
};

/** Why a gate run stopped before its result applied: it ran longer than `gateTimeoutMs`, the rows, the mode, or the cell it asked about changed, a newer run replaced it, the user pressed Escape, or the grid reset or unmounted. */
export type GateAbortReason = "timeout" | "changed" | "superseded" | "cancelled" | "reset";

/** How long a pending run without a timeout waits before the host hears of it. */
export const STUCK_GATE_MS = 30_000;

export type GateTrackerHost = {
  /** Read on every hold; `undefined` or a non-positive number turns the timeout off. */
  timeoutMs?: (name: GateName) => number | undefined;
  /** Called when a run is still pending after {@link STUCK_GATE_MS} and no timeout aborts it. */
  stuck?: (name: GateName) => void;
  /** Called once per run that is aborted while pending. */
  aborted?: (name: GateName, reason: GateAbortReason) => void;
  publish: (pending: ReadonlySet<GateName>) => void;
  subscribe: (listener: (now: DataGridStoreState, prev: DataGridStoreState) => void) => () => void;
};

export function createGateTracker(host: GateTrackerHost): GateTracker {
  const live = new Set<GateRun>();
  const timers = new Map<GateRun, ReturnType<typeof setTimeout>>();
  const watchedRuns = new Set<GateRun>();
  const counts = new Map<GateName, number>();
  let unwatch: (() => void) | null = null;
  let watched = 0;

  const publish = (): void => {
    if (counts.size === 0) {
      host.publish(EMPTY_GATES_PENDING);
      return;
    }
    host.publish(new Set(counts.keys()));
  };

  const stopWatching = (): void => {
    if (watched > 0 || !unwatch) return;
    unwatch();
    unwatch = null;
  };

  const release = (run: GateRun): void => {
    if (!live.delete(run)) return;
    const timer = timers.get(run);
    if (timer !== undefined) {
      clearTimeout(timer);
      timers.delete(run);
    }
    if (run.watch) {
      watched--;
      watchedRuns.delete(run);
    }
    const count = (counts.get(run.name) ?? 1) - 1;
    const changed = count <= 0;
    if (changed) counts.delete(run.name);
    else counts.set(run.name, count);
    stopWatching();
    if (changed) publish();
  };

  const watchStore = (): void => {
    if (unwatch) return;
    unwatch = host.subscribe((now, prev) => {
      for (const run of Array.from(watchedRuns)) {
        if (run.watch?.(now, prev)) tracker.abortRun(run, "changed");
      }
    });
  };

  const tracker: GateTracker = {
    begin: (name, watch) => new GateRun(name, watch),
    hold(run) {
      if (run.aborted || live.has(run)) return;
      live.add(run);
      const count = counts.get(run.name) ?? 0;
      counts.set(run.name, count + 1);
      if (run.watch) {
        watched++;
        watchedRuns.add(run);
        watchStore();
      }
      if (count === 0) publish();
      const timeoutMs = host.timeoutMs?.(run.name);
      if (run.name === "import") return;
      if (typeof timeoutMs === "number" && Number.isFinite(timeoutMs) && timeoutMs > 0) timers.set(run, setTimeout(() => tracker.abortRun(run, "timeout"), Math.min(timeoutMs, 2_147_483_647)));
      else if (host.stuck) timers.set(run, setTimeout(() => host.stuck?.(run.name), STUCK_GATE_MS));
    },
    settle: release,
    abortRun(run, reason = "superseded") {
      const pending = live.has(run);
      run.cancel();
      release(run);
      if (pending) host.aborted?.(run.name, reason);
    },
    abort(names, reason = "reset") {
      for (const run of Array.from(live)) if (!names || names.includes(run.name)) tracker.abortRun(run, reason);
    },
    track(name) {
      const run = new GateRun(name);
      tracker.hold(run);
      return () => release(run);
    },
  };
  return tracker;
}

import { validateContextsFor, type CellValidateContext } from "../validation/validate-context";
import type { ViewCoord, CellType, DataChange, DataOp } from "../types";
import { getCellValue, setCellValue } from "../columns/column-helpers";
import { isDev, warnDev } from "../is-dev";
import { isStandardSchema, runValidateSync, type ValidateResult } from "../validation/validate-cell";
import { runValidateBatch, type ValidateBatchItem } from "../validation/validate-batch";
import { cellErrorKey, isColumnReadOnly } from "./compute";
import { resolveColumnValidate } from "../cell-types/capabilities";
import type { GateContext } from "./gate-signal";
import type { AnyColumnDef, CellErrorEntry, CellPatch, DataGridStoreState, InternalSyncProps, UpdateCellsSkip } from "./types";
import { dataIndexAt } from "./view-rows";

/**
 * `warnings` (only on the success/noop arms) carries `validationMode: "warn"` rejections that committed
 * anyway — the store merges them into `cellErrors` AFTER the gesture's auto-clear and `validateRow`
 * verdict, so the freshest per-cell signal wins.
 */
export type CommitResult =
  | { data: readonly unknown[]; change: DataChange<unknown>; warnings?: readonly CellErrorEntry[] }
  | { error: string }
  | { noop: true; warnings?: readonly CellErrorEntry[] };

/** Per-row accumulator: the row as edited so far, plus its per-column cell deltas (columnId -> entry). */
export type RowEdit = { row: unknown; cells: Map<string, { columnId: string; value: unknown; prev: unknown }> };

/**
 * Warns once per instance (per passed Set) for every column whose `type` resolves to nothing in
 * `registry`, the store's resolved (built-ins merged with the `cellTypes` prop) registry — a typo
 * or a `null` removal silently degrades the column to text rendering, and its edit/paste/delete
 * paths go dead (see `resolveEditTarget`). The single warn site for it; do not add a second one.
 */
export function checkUnresolvableColumnTypes(
  columns: readonly AnyColumnDef[],
  registry: Readonly<Record<string, unknown>>,
  warned: Set<string>,
): void {
  if (!isDev()) return;
  for (const column of columns) {
    if (column.type === undefined || registry[column.type] !== undefined) continue;
    const key = `${column.id}:${column.type}`;
    if (warned.has(key)) continue;
    warned.add(key);
    warnDev(`column "${column.id}" has type "${column.type}" which resolves to nothing in the cellTypes registry (a typo, or a null entry removed it); it renders as text and its edits, pastes, and deletes are dropped`);
  }
}

/** Per-grid set of the guardrail warnings already shown; a guardrail whose cause does not change across re-renders warns once per grid, not once per render. */
export type GuardrailWarnings = Set<string>;

/** `data` + `defaultData` are mutually exclusive (React value/defaultValue semantics); `data` wins. */
export function warnBothDataPropsOnce(warned: GuardrailWarnings): void {
  if (warned.has("both data props") || !isDev()) return;
  warned.add("both data props");
  warnDev("both `data` and `defaultData` were provided; `data` wins (controlled) and `defaultData` is ignored");
}

/** `store` next to a sync prop is a type error for typed callers; this catches a cast/untyped one. */
export function warnExternalStoreSyncPropsOnce(warned: GuardrailWarnings): void {
  if (warned.has("external store sync props") || !isDev()) return;
  warned.add("external store sync props");
  warnDev("<DataGridProvider store={…}> ignores the sync props next to it; pass them to useDataGridStoreProps instead");
}

/**
 * Warns once per instance (per passed Set) for every duplicated column id — the dev guardrails
 * run on every render, so without dedup a static duplicate id would warn on every render.
 */
export function checkDuplicateColumnIds(columns: readonly AnyColumnDef[], warned: Set<string>): void {
  if (!isDev()) return;
  const seen = new Set<string>();
  for (const column of columns) {
    if (seen.has(column.id)) {
      if (warned.has(column.id)) continue;
      warned.add(column.id);
      warnDev(`duplicate column id "${column.id}"`);
    }
    seen.add(column.id);
  }
}

const MAX_COLUMN_COMPARE_DEPTH = 4;

function isPlainContainer(value: unknown): value is Record<string, unknown> {
  if (typeof value !== "object" || value === null) return false;
  const proto: unknown = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === Array.prototype;
}

// Functions compare by identity: a rebuilt closure may capture new state, so only a proven churn warns. Plain objects, arrays, and JSX elements compare by content up to a depth cap (a deeper difference reads as unequal, so no false warning).
function sameColumnValue(a: unknown, b: unknown, depth = 0): boolean {
  if (Object.is(a, b)) return true;
  if (depth >= MAX_COLUMN_COMPARE_DEPTH || !isPlainContainer(a) || !isPlainContainer(b)) return false;
  if (Array.isArray(a) !== Array.isArray(b)) return false;
  const keys = Object.keys(a);
  if (keys.length !== Object.keys(b).length) return false;
  return keys.every((key) => sameColumnValue(a[key], b[key], depth + 1));
}

function columnsStructurallyEqual(a: readonly AnyColumnDef[], b: readonly AnyColumnDef[]): boolean {
  if (a.length !== b.length) return false;
  for (let i = 0; i < a.length; i++) {
    const x = a[i] as Record<string, unknown>;
    const y = b[i] as Record<string, unknown>;
    const keys = Object.keys(x);
    if (keys.length !== Object.keys(y).length) return false;
    for (const key of keys) if (!sameColumnValue(x[key], y[key])) return false;
  }
  return true;
}

/**
 * Dev-only guardrails for the recompute-slice props (the `_syncProps` inputs): missing getRowId,
 * the data/defaultData combo, unstable columns/data identity across renders. The config-slice
 * identity warnings (overlayPlugins, rowBands) live in the provider's config-phase effect.
 */
export function checkDevGuardrails(
  props: InternalSyncProps,
  prevColumns: readonly AnyColumnDef[] | undefined,
  prevData: readonly unknown[] | undefined,
  warned: GuardrailWarnings = new Set(),
): void {
  if (!isDev()) return;

  if (props.data !== undefined && props.defaultData !== undefined) {
    warnBothDataPropsOnce(warned);
  }

  if (props.data === undefined) {
    const seeded = (props.defaultData?.length ?? 0) > 0;
    if (!warned.has("seed:empty") && !warned.has("seed:filled")) warned.add(seeded ? "seed:filled" : "seed:empty");
    else if (seeded && warned.has("seed:empty") && !warned.has("seed:late")) {
      warned.add("seed:late");
      warnDev("defaultData seeds the grid once and ignores later changes, so these rows do not show; pass them in `data` with `onDataChange`, or remount the grid with a new `key`");
    }
  }

  if (!warned.has("columns identity") && prevColumns !== undefined && prevColumns !== props.columns && columnsStructurallyEqual(prevColumns, props.columns)) {
    warned.add("columns identity");
    warnDev(
      "columns array identity changed since the last render; pass a stable reference (e.g. useMemo) or every row re-renders",
    );
  }
  // Controlled mode only: in uncontrolled mode props.data is undefined (data lives in the store),
  // and the store's own array legitimately gets a new reference on every mutation — not a bug.
  if (!warned.has("data identity") && props.data !== undefined && prevData !== undefined && prevData !== props.data && prevData.length === props.data.length) {
    // Only identity churn with zero row changes is the anti-pattern (array rebuilt per render);
    // a legitimate immutable edit swaps ≥1 row reference — the early exit keeps this cheap for it.
    const data = props.data;
    let anyRowChanged = false;
    for (let i = 0; i < prevData.length; i++) {
      if (prevData[i] !== data[i]) {
        anyRowChanged = true;
        break;
      }
    }
    if (!anyRowChanged) {
      warned.add("data identity");
      warnDev("data array identity changed with no row changes; pass a stable reference (rebuilding it every render defeats row memoization)");
    }
  }
}

/** Flags for the cells of `update` and `insert` operations that a `validationMode: "warn"` column's sync validator rejects: one validator call per such cell, with one validate context per column for the whole change over `nextData`. */
export function warnFlagsForOps(s: DataGridStoreState, ops: readonly DataOp<unknown>[], nextData: readonly unknown[]): CellErrorEntry[] {
  const flags: CellErrorEntry[] = [];
  const warnColumns = s.columns.filter((column) => column.validationMode === "warn");
  if (warnColumns.length === 0) return flags;
  const byId = new Map(warnColumns.map((column) => [column.id, column] as const));
  const cells: { rowId: string; column: AnyColumnDef; columnId: string; row: unknown; value: unknown }[] = [];
  for (const op of ops) {
    if (op.type === "insert") {
      for (const column of warnColumns) cells.push({ rowId: op.rowId, column, columnId: column.id, row: op.row, value: getCellValue(op.row, column) });
    } else if (op.type === "update" && op.cells) {
      for (const cell of op.cells) {
        const column = byId.get(cell.columnId);
        if (column) cells.push({ rowId: op.rowId, column, columnId: column.id, row: op.row, value: cell.value });
      }
    }
  }
  const contexts = validateContextsFor(nextData, s.columns, cells);
  for (const { rowId, column, row, value } of cells) {
    const result = runValidateSync(resolveColumnValidate(column, s.cellTypes[column.type ?? "text"]), value, row, contexts.get(column.id));
    if ("error" in result && !result.thrown) flags.push({ rowId, columnId: column.id, message: result.error });
  }
  return flags;
}

/**
 * Shared value-write path for both `commitCellEdit` (editing session) and `commitCellValue` (direct
 * write, e.g. checkbox toggle). `value` may already be schema-validated+transformed (the async
 * editor-commit layer passes `result.value`, having awaited the schema itself) — this still
 * re-runs `validate` (cheap, idempotent for a well-behaved schema) so the sync/function-form path
 * is unchanged and a direct `commitCellValue` call always gets checked.
 *
 * `validationMode: "warn"` columns commit a rejected value (raw — a rejection carries no transformed
 * value) and report it in `warnings` so the store can flag the cell in `cellErrors`; a validator
 * that threw blocks there too. `rejection` is the async layer's awaited schema rejection, which the
 * sync re-run here cannot see (a schema Promise passes `runValidateSync` untouched).
 */
export function computeCommit(s: DataGridStoreState, coord: ViewCoord, value: unknown, rejection?: string): CommitResult {
  const target = resolveEditTarget(s, coord);
  if (!target) return { noop: true };
  const { column, dataRowIndex, row, cellType } = target;
  if (isColumnReadOnly(column, row)) return { noop: true };
  const validated = runValidateSync(resolveColumnValidate(column, cellType), value, row, validateContextsFor(s.data, s.columns, [{ columnId: column.id, row, value }]).get(column.id));
  let nextValue: unknown;
  let warning: string | undefined;
  if ("error" in validated) {
    if (column.validationMode !== "warn" || validated.thrown) return { error: validated.error };
    nextValue = value;
    warning = validated.error;
  } else {
    nextValue = validated.value;
    if (rejection !== undefined && column.validationMode === "warn") warning = rejection;
  }
  const prevValue = getCellValue(row, column);
  if (Object.is(prevValue, nextValue)) {
    // re-committing the SAME invalid value is a deliberate keep: the flag (re)lands
    return warning === undefined
      ? { noop: true }
      : { noop: true, warnings: [{ rowId: s.getRowId(row, dataRowIndex), columnId: column.id, message: warning }] };
  }

  const nextRow = setCellValue(row, column, nextValue);
  const nextData = s.data.slice();
  nextData[dataRowIndex] = nextRow;
  const rowId = s.getRowId(nextRow, dataRowIndex);
  const change: DataChange<unknown> = {
    source: "edit",
    ops: [
      {
        type: "update",
        rowId,
        row: nextRow,
        prev: row,
        cells: [{ columnId: column.id, value: nextValue, prev: prevValue }],
      },
    ],
  };
  return warning === undefined
    ? { data: nextData, change }
    : { data: nextData, change, warnings: [{ rowId, columnId: column.id, message: warning }] };
}

/** Looks up the column, data row, and cell type at a view coord; null when any part is unresolvable. */
export function resolveEditTarget(
  s: DataGridStoreState,
  coord: ViewCoord,
): { column: AnyColumnDef; dataRowIndex: number; row: unknown; cellType: CellType } | null {
  const column = s.visibleColumns[coord.col];
  if (!column) return null;
  const dataRowIndex = dataIndexAt(s, coord.row);
  if (dataRowIndex === undefined) return null;
  const row = s.data[dataRowIndex];
  if (row === undefined) return null;
  const cellType = s.cellTypes[column.type ?? "text"];
  if (!cellType) return null;
  return { column, dataRowIndex, row, cellType };
}

/**
 * Applies `writes` (view-row + column-id + already-resolved value) against `s`, deduping multiple
 * writes to the same row/column (last one wins), skipping readOnly cells, unresolvable rows/columns,
 * and no-op values (`Object.is` against the current value). Shared by `deleteSelection` and
 * `applyCellUpdates` so both funnel through one row-edit accumulation + operation-building path.
 */
export function computeRowEditsBatch(
  s: DataGridStoreState,
  writes: { viewRowIndex: number; columnId: string; value: unknown }[],
): { nextData: readonly unknown[]; ops: DataOp<unknown>[] } | null {
  const rowEdits = new Map<number, RowEdit>();
  const columnById = new Map(s.visibleColumns.map((column) => [column.id, column] as const));

  for (const write of writes) {
    const dataRowIndex = dataIndexAt(s, write.viewRowIndex);
    if (dataRowIndex === undefined) continue;
    const column = columnById.get(write.columnId);
    if (!column) continue;

    const entry = rowEdits.get(dataRowIndex);
    const baseRow = entry?.row ?? s.data[dataRowIndex];
    if (baseRow === undefined) continue;
    if (isColumnReadOnly(column, baseRow)) continue;

    // explicit TData=unknown: baseRow's `undefined`-narrowed type ({} | null) would otherwise drive
    // inference instead of column's own already-unknown TData, tripping ColumnDef<unknown>'s setValue.
    const prevValue = getCellValue<unknown, typeof column>(baseRow, column);
    if (Object.is(prevValue, write.value)) continue;

    const row = setCellValue<unknown, typeof column>(baseRow, column, write.value);
    const cells = entry?.cells ?? new Map<string, { columnId: string; value: unknown; prev: unknown }>();
    // last write to this row/column wins; `prev` stays the value before ANY write in this batch.
    const existingPrev = cells.get(column.id)?.prev ?? prevValue;
    cells.set(column.id, { columnId: column.id, value: write.value, prev: existingPrev });
    rowEdits.set(dataRowIndex, { row, cells });
  }

  if (rowEdits.size === 0) return null;

  const nextData = s.data.slice();
  const ops: DataOp<unknown>[] = [];
  for (const [dataRowIndex, { row, cells }] of rowEdits) {
    const prevRow = s.data[dataRowIndex];
    nextData[dataRowIndex] = row;
    ops.push({
      type: "update",
      rowId: s.getRowId(row, dataRowIndex),
      row,
      prev: prevRow,
      cells: Array.from(cells.values()),
    });
  }
  return { nextData, ops };
}

/**
 * Applies row-id-based {@link CellPatch}es against `s` — the direct-update path's counterpart to
 * {@link computeRowEditsBatch}. Differences, all deliberate: rows are addressed by STABLE ROW ID
 * through the caller-supplied `rowIndex` map (never a view index, so a patch survives an active
 * sort), and every column is resolvable, not only visible ones (a streaming producer must be able
 * to write a column the user has hidden). Unknown rows, unknown columns, unloaded rows (`"hole"`),
 * read-only cells, and `Object.is`-equal no-op writes are dropped. Under `source: "stream"` only a
 * column with no `accessorKey` and no `setValue` counts as read-only, and a row whose save is in
 * flight is held with reason `"saving"`. Duplicate patches to one cell dedupe last-write-wins with `prev` held
 * at the pre-batch value.
 *
 * `skipValidation` bypasses the per-column `validate` a 200-cell tick would otherwise re-run for a
 * producer that already validated; otherwise a cell whose value fails validation is skipped,
 * matching {@link computeRowEditsBatch}'s bulk contract (a stream has no UI surface to reject a
 * batch on and must never drop a whole batch for one bad value). Every skipped patch is named in
 * the returned `skipped` list for the action's verdict, and every rejected value in `rejected`
 * with its validator's message.
 */
export function computeCellPatchBatch(
  s: DataGridStoreState,
  patches: readonly CellPatch[],
  rowIndex: ReadonlyMap<string, number>,
  skipValidation: boolean,
  source: DataChange<unknown>["source"] = "stream",
): {
  nextData: readonly unknown[] | null;
  ops: DataOp<unknown>[];
  touchedRows: number[];
  skipped: UpdateCellsSkip[];
  rejected: PatchRejection[];
  warnings: CellErrorEntry[];
} {
  const columnsById = new Map(s.columns.map((c) => [c.id, c] as const));
  const rowEdits = new Map<number, RowEdit>();
  const skipped: UpdateCellsSkip[] = [];
  const rejected: PatchRejection[] = [];
  const warnings = new Map<string, CellErrorEntry>();
  let contexts: Map<string, CellValidateContext> | null = null;
  const contextOf = (columnId: string) =>
    (contexts ??= validateContextsFor(s.data, s.columns, patches.map((p) => ({ columnId: p.columnId, row: s.data[rowIndex.get(p.rowId) ?? -1], value: p.value })))).get(columnId);

  for (let patchIndex = 0; patchIndex < patches.length; patchIndex++) {
    const patch = patches[patchIndex]!;
    const dataRowIndex = rowIndex.get(patch.rowId);
    if (dataRowIndex === undefined) {
      skipped.push({ patchIndex, reason: "unknown-row" });
      continue;
    }
    const column = columnsById.get(patch.columnId);
    if (!column) {
      skipped.push({ patchIndex, reason: "unknown-column" });
      continue;
    }

    const entry = rowEdits.get(dataRowIndex);
    const baseRow = entry?.row ?? s.data[dataRowIndex];
    if (baseRow === undefined) {
      skipped.push({ patchIndex, reason: "hole" });
      continue;
    }
    if (source === "stream" ? !column.setValue && !column.accessorKey : isColumnReadOnly(column, baseRow)) {
      skipped.push({ patchIndex, reason: "readonly" });
      continue;
    }
    if (source === "stream" && s.saveStatus.get(patch.rowId) === "saving") {
      skipped.push({ patchIndex, reason: "saving" });
      continue;
    }

    let value = patch.value;
    let warning: string | undefined;
    if (!skipValidation) {
      const validate = resolveColumnValidate(column, s.cellTypes[column.type ?? "text"]);
      const validated = runValidateSync(validate, value, baseRow, typeof validate === "function" ? contextOf(column.id) : undefined);
      if ("error" in validated) {
        if (column.validationMode !== "warn" || validated.thrown) {
          skipped.push({ patchIndex, reason: "invalid" });
          rejected.push({ patchIndex, message: validated.error });
          continue;
        }
        warning = validated.error;
      } else value = validated.value;
    }

    const prevValue = getCellValue<unknown, typeof column>(baseRow, column);
    if (Object.is(prevValue, value)) {
      skipped.push({ patchIndex, reason: "no-op" });
      continue;
    }
    const warningKey = cellErrorKey(patch.rowId, column.id);
    if (warning === undefined) warnings.delete(warningKey);
    else warnings.set(warningKey, { rowId: patch.rowId, columnId: column.id, message: warning });

    const row = setCellValue<unknown, typeof column>(baseRow, column, value);
    const cells = entry?.cells ?? new Map<string, { columnId: string; value: unknown; prev: unknown }>();
    const existingPrev = cells.get(column.id)?.prev ?? prevValue;
    cells.set(column.id, { columnId: column.id, value, prev: existingPrev });
    rowEdits.set(dataRowIndex, { row, cells });
  }

  const flagged = Array.from(warnings.values());
  if (rowEdits.size === 0) return { nextData: null, ops: [], touchedRows: [], skipped, rejected, warnings: flagged };

  const nextData = s.data.slice();
  const ops: DataOp<unknown>[] = [];
  // The data indices whose values actually changed — the incremental view-index path's input.
  const touchedRows: number[] = [];
  for (const [dataRowIndex, { row, cells }] of rowEdits) {
    const prevRow = s.data[dataRowIndex];
    nextData[dataRowIndex] = row;
    touchedRows.push(dataRowIndex);
    ops.push({
      type: "update",
      rowId: s.getRowId(row, dataRowIndex),
      row,
      prev: prevRow,
      cells: Array.from(cells.values()),
    });
  }
  return { nextData, ops, touchedRows, skipped, rejected, warnings: flagged };
}

/**
 * Whether any column `patches` writes carries a Standard Schema, the only `validate` form that can
 * be async. A purely structural test — it never CALLS a validator, so the ordinary streaming tick
 * (no validators, or the function form) pays one map lookup per patch and nothing else, and
 * `computeCellPatchBatch` still runs every validator exactly once, inline, as it always has.
 */
export function patchesNeedAsyncCheck(s: DataGridStoreState, patches: readonly CellPatch[]): boolean {
  const columnsById = new Map(s.columns.map((c) => [c.id, c] as const));
  for (const patch of patches) {
    const column = columnsById.get(patch.columnId);
    if (!column) continue;
    if (isStandardSchema(resolveColumnValidate(column, s.cellTypes[column.type ?? "text"]))) return true;
  }
  return false;
}

/**
 * Validates `patches` for {@link DataGridActions.updateCells} ahead of the apply, so what reaches
 * {@link computeCellPatchBatch} carries only accepted, already-transformed values and runs with
 * validation off. There is still exactly ONE apply path — this only decides what enters it, and it
 * runs at all only when {@link patchesNeedAsyncCheck} says a schema is in play.
 *
 * Failing cells are dropped from the apply and reported by index, so one bad value never loses the
 * whole batch and the caller still learns which of its patches were rejected.
 */
export function prevalidatePatches(
  s: DataGridStoreState,
  patches: readonly CellPatch[],
  rowIndex: ReadonlyMap<string, number>,
): PrevalidatedPatches | Promise<PrevalidatedPatches> {
  const columnsById = new Map(s.columns.map((c) => [c.id, c] as const));
  const warnByPatch: boolean[] = [];
  const items: ValidateBatchItem[] = patches.map((patch) => {
    const dataRowIndex = rowIndex.get(patch.rowId);
    const column = columnsById.get(patch.columnId);
    warnByPatch.push(column?.validationMode === "warn");
    return {
      validate: column ? resolveColumnValidate(column, s.cellTypes[column.type ?? "text"]) : undefined,
      value: patch.value,
      row: dataRowIndex === undefined ? undefined : s.data[dataRowIndex],
    };
  });

  const contexts = validateContextsFor(s.data, s.columns, patches.map((patch, i) => ({ columnId: patch.columnId, row: items[i]!.row, value: patch.value })));
  for (let i = 0; i < items.length; i++) items[i]!.ctx = contexts.get(patches[i]!.columnId);
  const results = runValidateBatch(items);
  if (results instanceof Promise) return results.then((resolved) => keepAccepted(patches, resolved, warnByPatch));
  return keepAccepted(patches, results, warnByPatch);
}

/** A patch the column's validator refused: its index in the caller's array and the validator's message. */
export type PatchRejection = { patchIndex: number; message: string };

/** Accepted patches with their index in the caller's array, and the rejected ones. */
export type PrevalidatedPatches = { accepted: CellPatch[]; acceptedIndexes: number[]; rejected: PatchRejection[]; warnings: CellErrorEntry[] };

function keepAccepted(patches: readonly CellPatch[], results: readonly ValidateResult[], warnByPatch: readonly boolean[]): PrevalidatedPatches {
  const out: PrevalidatedPatches = { accepted: [], acceptedIndexes: [], rejected: [], warnings: [] };
  const warned = new Map<string, CellErrorEntry>();
  for (let i = 0; i < patches.length; i++) {
    const result = results[i];
    const cellKey = cellErrorKey(patches[i]!.rowId, patches[i]!.columnId);
    if (result && "error" in result && warnByPatch[i] && !result.thrown) {
      warned.set(cellKey, { rowId: patches[i]!.rowId, columnId: patches[i]!.columnId, message: result.error });
      out.accepted.push(patches[i]!);
      out.acceptedIndexes.push(i);
      continue;
    }
    if (result && !("error" in result)) warned.delete(cellKey);
    if (!result || "error" in result) {
      out.rejected.push({ patchIndex: i, message: result?.error ?? "" });
      continue;
    }
    out.accepted.push({ ...patches[i]!, value: result.value }); // i < patches.length by loop condition
    out.acceptedIndexes.push(i);
  }
  out.warnings.push(...warned.values());
  return out;
}

/** Builds a multi-row insert batch: `rows` spliced into `s.data` at `dataRowIndex`, plus one row-id-based insert operation per row (`index` is the row's final slot, `dataRowIndex + i`, ascending). */
export function computeInsertRowsBatch(
  s: DataGridStoreState,
  dataRowIndex: number,
  rows: readonly unknown[],
): { nextData: readonly unknown[]; ops: DataOp<unknown>[] } {
  const nextData = s.data.slice();
  nextData.splice(dataRowIndex, 0, ...rows);
  const ops: DataOp<unknown>[] = [];
  for (let i = 0; i < rows.length; i++) {
    const row = rows[i]!;
    ops.push({ type: "insert", rowId: s.getRowId(row, dataRowIndex + i), row, index: dataRowIndex + i });
  }
  return { nextData, ops };
}

/**
 * Builds a multi-row delete batch: `dataRowIndexes` (deduped, descending so earlier splices don't
 * shift later indexes) removed from `s.data`, plus their row-id-based delete operations in the original
 * (ascending) row order.
 */
export function computeDeleteBatch(
  s: DataGridStoreState,
  dataRowIndexes: readonly number[],
): { nextData: readonly unknown[]; ops: DataOp<unknown>[] } | null {
  const uniqueAscending = Array.from(new Set(dataRowIndexes)).sort((a, b) => a - b);
  if (uniqueAscending.length === 0) return null;

  const ops: DataOp<unknown>[] = [];
  for (const index of uniqueAscending) {
    const row = s.data[index];
    if (row === undefined) continue;
    ops.push({ type: "delete", rowId: s.getRowId(row, index), row, index });
  }

  const nextData = s.data.slice();
  for (let i = uniqueAscending.length - 1; i >= 0; i--) nextData.splice(uniqueAscending[i]!, 1); // i in-bounds by loop condition
  return { nextData, ops };
}

/**
 * Calls `duplicateRow` once per source row (descending, like {@link computeDuplicateBatch}) and keys
 * each result, a copy or a promise of one, by its source data index. `null` when nothing resolves.
 */
export function startDuplicateCopies(s: DataGridStoreState, dataRowIndexes: readonly number[], gate: GateContext): Map<number, unknown> | null {
  const duplicateRow = s.duplicateRow;
  const uniqueAscending = Array.from(new Set(dataRowIndexes)).sort((a, b) => a - b);
  if (!duplicateRow || uniqueAscending.length === 0) return null;
  const copies = new Map<number, unknown>();
  for (let i = uniqueAscending.length - 1; i >= 0; i--) {
    const sourceIndex = uniqueAscending[i]!; // i in-bounds by loop condition
    const sourceRow = s.data[sourceIndex];
    if (sourceRow === undefined) continue;
    copies.set(sourceIndex, duplicateRow(sourceRow, sourceIndex + 1 + i, gate));
  }
  return copies.size > 0 ? copies : null;
}

/**
 * Builds a multi-row duplicate batch: each of `dataRowIndexes` (deduped, ascending) is copied via
 * the required `s.duplicateRow` and spliced immediately after its source row. Processed descending
 * so earlier splices don't shift the still-pending source indexes; operations are returned in ascending
 * source order for a stable, predictable row-id-based batch. Caller (`duplicateRows`) guarantees
  * `duplicateRow` is present — a shallow-spread fallback would keep the source's `getRowId()`,
  * colliding two sibling rows' React key.
 */
export function computeDuplicateBatch(
  s: DataGridStoreState,
  dataRowIndexes: readonly number[],
  copies: ReadonlyMap<number, unknown>,
): { nextData: readonly unknown[]; ops: DataOp<unknown>[] } | null {
  const duplicateRow = s.duplicateRow;
  if (!duplicateRow) return null;
  const uniqueAscending = Array.from(new Set(dataRowIndexes)).sort((a, b) => a - b);
  if (uniqueAscending.length === 0) return null;

  const nextData = s.data.slice();
  const opsByIndex = new Map<number, DataOp<unknown>>();
  for (let i = uniqueAscending.length - 1; i >= 0; i--) {
    const sourceIndex = uniqueAscending[i]!; // i in-bounds by loop condition
    const sourceRow = s.data[sourceIndex];
    if (sourceRow === undefined) continue;
    const insertAt = sourceIndex + 1;
    const finalIndex = insertAt + i;
    const copy = copies.get(sourceIndex);
    if (copy === undefined) continue;
    nextData.splice(insertAt, 0, copy);
    opsByIndex.set(sourceIndex, { type: "insert", rowId: s.getRowId(copy, finalIndex), row: copy, index: finalIndex });
  }
  const ops = uniqueAscending.map((index) => opsByIndex.get(index)).filter((op): op is DataOp<unknown> => op != null);
  return { nextData, ops };
}

import type { CheckedRowsLifetime } from "../types";
import { resolveFilterMode, resolveSortMode } from "./compute";
import type { DataGridStoreState, InternalSyncProps } from "./types";

/**
 * The lifetime that applies: the default follows `totalRowCount` and the marker checkboxes, and `"across-filters"` on a server-sorted
 * or server-filtered grid without `totalRowCount` is `"until-cleared"`.
 */
export function resolveCheckedRowsLifetime(props: InternalSyncProps): CheckedRowsLifetime {
  const windowed = props.totalRowCount !== undefined;
  const lifetime = props.checkedRowsLifetime ?? (windowed ? "across-filters" : /(checkbox|both)$/.test(props.rowMarkers ?? "none") ? "until-cleared" : "until-click");
  const holdsEveryRow = windowed || (resolveSortMode(props) !== "server" && resolveFilterMode(props) !== "server");
  return lifetime === "across-filters" && !holdsEveryRow ? "until-cleared" : lifetime;
}

/** Resolves the optional selection-config sync props to their defaults, and a non-finite or negative `totalRowCount` to `null`. */
export function resolveSelectionConfig(props: InternalSyncProps): Pick<
  DataGridStoreState,
  | "rowMarkers"
  | "enableRowSelection"
  | "enableRowDelete"
  | "checkedRowsLifetime"
  | "totalRowCount"
  | "enableColumnSelection"
  | "enableRangeSelection"
  | "enableMultiRange"
  | "enableColumnResize"
  | "enableColumnReorder"
  | "enableColumnPinning"
  | "headerClickBehavior"
> {
  return {
    rowMarkers: props.rowMarkers ?? "none",
    enableRowSelection: props.enableRowSelection ?? true,
    enableRowDelete: props.enableRowDelete ?? true,
    checkedRowsLifetime: resolveCheckedRowsLifetime(props),
    totalRowCount: typeof props.totalRowCount === "number" && !(Number.isFinite(props.totalRowCount) && props.totalRowCount >= 0) ? null : props.totalRowCount,
    enableColumnSelection: props.enableColumnSelection ?? true,
    enableRangeSelection: props.enableRangeSelection ?? true,
    enableMultiRange: props.enableMultiRange ?? true,
    enableColumnResize: props.enableColumnResize ?? true,
    enableColumnReorder: props.enableColumnReorder ?? true,
    enableColumnPinning: props.enableColumnPinning ?? true,
    headerClickBehavior: props.headerClickBehavior ?? (props.totalRowCount !== undefined ? "sort" : "select"),
  };
}

