import type { StoreApi } from "zustand/vanilla";
import type { DataOp } from "../types";
import { toSafeText } from "../cell-types/safe-text";
import { isThenable } from "./async-gate";
import { cellErrorKey } from "./compute";
import type { GateRun, GateTracker } from "./gate-signal";
import type { RowIndexCache } from "./row-index";
import type { DataGridStoreState } from "./types";

type RowVerdict = Record<string, string> | null;

export type RowValidationDeps = {
  getStore: () => StoreApi<DataGridStoreState>;
  rowIndexCache: RowIndexCache;
  gates: GateTracker;
  warnOnce: (key: string, message: string | (() => string)) => void;
};

export type RowValidation = {
  /**
   * Runs `validateRow` once per touched row of a committed write gesture, AFTER `clearErrorsForOps`
   * — the row in `nextData` already has every cell of the gesture applied, which is the whole
   * point: the verdict cannot depend on column order inside a paste. Returns the same map identity
   * when the prop is absent or nothing changed.
   */
  apply: (
    s: DataGridStoreState,
    cellErrors: ReadonlyMap<string, string>,
    nextData: readonly unknown[],
    ops: readonly DataOp<unknown>[],
  ) => ReadonlyMap<string, string>;
  prune: (data: readonly unknown[], getRowId: (row: unknown, index: number) => string) => void;
  renameRow: (oldId: string, newId: string) => void;
};

export function createRowValidation({ getStore, rowIndexCache, gates, warnOnce }: RowValidationDeps): RowValidation {
  // cellErrors keys of each row's last validateRow verdict, so a re-run clears only its own messages.
  const rowValidationKeys = new Map<string, string[]>();
  // rowId -> its newest pending async verdict; a newer run for the row supersedes and aborts the older one.
  const pendingRowVerdicts = new Map<string, GateRun>();
  // Verdicts that settled in this tick and wait for their write; a newer run for the row drops its entry.
  const settledVerdicts = new Map<string, RowVerdict>();
  let unwatchRowVerdicts: (() => void) | null = null;

  // An unpruned entry for a deleted rowId lets the next validateRow wipe a reused row's consumer errors.
  const prune: RowValidation["prune"] = (data, getRowId) => {
    if (rowValidationKeys.size === 0) return;
    const live = new Set<string>();
    for (let i = 0; i < data.length; i++) live.add(getRowId(data[i], i));
    for (const rowId of rowValidationKeys.keys()) if (!live.has(rowId)) rowValidationKeys.delete(rowId);
  };
  const foldRowVerdict = (
    current: () => ReadonlyMap<string, string>,
    ensure: () => Map<string, string>,
    rowId: string,
    verdict: RowVerdict,
  ): void => {
    const prevKeys = rowValidationKeys.get(rowId);
    if (prevKeys) for (const key of prevKeys) if (current().has(key)) ensure().delete(key);
    const entries = verdict ? Object.entries(verdict) : [];
    if (entries.length === 0) {
      rowValidationKeys.delete(rowId);
      return;
    }
    const keys: string[] = [];
    for (const [columnId, message] of entries) {
      const key = cellErrorKey(rowId, columnId);
      if (current().get(key) !== message) ensure().set(key, message);
      keys.push(key);
    }
    rowValidationKeys.set(rowId, keys);
  };
  const supersedeRowVerdict = (rowId: string): void => {
    settledVerdicts.delete(rowId);
    const older = pendingRowVerdicts.get(rowId);
    if (!older) return;
    pendingRowVerdicts.delete(rowId);
    gates.abortRun(older);
  };
  const watchRowVerdicts = (): void => {
    if (unwatchRowVerdicts) return;
    unwatchRowVerdicts = getStore().subscribe((now, prev) => {
      if (pendingRowVerdicts.size === 0) {
        unwatchRowVerdicts?.();
        unwatchRowVerdicts = null;
        return;
      }
      if (now.data === prev.data) return;
      const index = rowIndexCache.resolve(now.data, now.getRowId);
      for (const rowId of Array.from(pendingRowVerdicts.keys())) if (!index.has(rowId)) supersedeRowVerdict(rowId);
    });
  };
  const renameRow: RowValidation["renameRow"] = (oldId, newId) => {
    const keys = rowValidationKeys.get(oldId);
    if (keys) {
      rowValidationKeys.delete(oldId);
      rowValidationKeys.set(newId, keys.map((key) => cellErrorKey(newId, key.slice(oldId.length + 1))));
    }
    supersedeRowVerdict(oldId);
  };
  // Verdicts that settle in the same tick merge into cellErrors with one copy and one write.
  const flushSettledVerdicts = (): void => {
    const batch = Array.from(settledVerdicts);
    settledVerdicts.clear();
    const store = getStore();
    const s = store.getState();
    const index = rowIndexCache.resolve(s.data, s.getRowId);
    let next: Map<string, string> | null = null;
    for (const [rowId, verdict] of batch) {
      if (!index.has(rowId)) continue;
      foldRowVerdict(
        () => next ?? s.cellErrors,
        () => next ?? (next = new Map(s.cellErrors)),
        rowId,
        verdict,
      );
    }
    const merged = next as Map<string, string> | null;
    if (merged) store.setState({ cellErrors: merged });
  };
  const holdRowVerdict = (rowId: string, run: GateRun, verdict: PromiseLike<RowVerdict>): void => {
    supersedeRowVerdict(rowId);
    pendingRowVerdicts.set(rowId, run);
    gates.hold(run);
    watchRowVerdicts();
    const release = (): boolean => {
      gates.settle(run);
      if (run.aborted || pendingRowVerdicts.get(rowId) !== run) return false;
      pendingRowVerdicts.delete(rowId);
      return true;
    };
    verdict.then(
      (resolved) => {
        if (!release()) return;
        settledVerdicts.set(rowId, resolved);
        if (settledVerdicts.size === 1) queueMicrotask(flushSettledVerdicts);
      },
      (error: unknown) => {
        if (release()) warnOnce("validateRow rejected", () => `validateRow rejected, so the row gets no verdict: ${toSafeText(error)}`);
      },
    );
  };
  const apply: RowValidation["apply"] = (s, cellErrors, nextData, ops) => {
    const validateRow = s.validateRow;
    if (!validateRow) return cellErrors;
    const touched = new Set<string>();
    for (const op of ops) if (op.type === "update") touched.add(op.rowId);
    if (touched.size === 0) return cellErrors;
    const rowIndex = rowIndexCache.resolve(nextData, s.getRowId);
    let next: Map<string, string> | null = null;
    const ensure = () => next ?? (next = new Map(cellErrors));
    const current = () => next ?? cellErrors;
    for (const rowId of touched) {
      const dataRowIndex = rowIndex.get(rowId);
      if (dataRowIndex === undefined) continue;
      const row = nextData[dataRowIndex];
      const run = gates.begin("validateRow");
      let verdict: RowVerdict | PromiseLike<RowVerdict>;
      try {
        verdict = validateRow(row, rowId, { get signal() { return run.signal; } });
      } catch (error) {
        if (pendingRowVerdicts.size > 0 || settledVerdicts.size > 0) supersedeRowVerdict(rowId);
        warnOnce("validateRow threw", () => `validateRow threw, so the row gets no verdict: ${toSafeText(error)}`);
        continue;
      }
      if (isThenable<RowVerdict>(verdict)) {
        holdRowVerdict(rowId, run, verdict);
        continue;
      }
      if (pendingRowVerdicts.size > 0 || settledVerdicts.size > 0) supersedeRowVerdict(rowId);
      foldRowVerdict(current, ensure, rowId, verdict);
    }
    return next ?? cellErrors;
  };

  return { apply, prune, renameRow };
}

import { useLayoutEffect, useState } from "react";

type Tree = Record<string, unknown>;

const isTree = (value: unknown): value is Tree => typeof value === "object" && value !== null;

function sameShape(a: unknown, b: unknown): boolean {
  if (typeof a === "function" && typeof b === "function") return true;
  if (!isTree(a) || !isTree(b)) return Object.is(a, b);
  const keys = Object.keys(a);
  return keys.length === Object.keys(b).length && keys.every((key) => Object.hasOwn(b, key) && sameShape(a[key], b[key]));
}

function readPath(root: unknown, path: readonly string[]): unknown {
  return path.reduce<unknown>((node, key) => (isTree(node) ? node[key] : undefined), root);
}

function forward(source: unknown, latest: { current: unknown }, path: readonly string[]): unknown {
  if (typeof source === "function") return (...args: unknown[]) => (readPath(latest.current, path) as (...a: unknown[]) => unknown)(...args);
  if (!isTree(source)) return source;
  return Object.fromEntries(Object.entries(source).map(([key, value]) => [key, forward(value, latest, [...path, key])]));
}

function publish(box: { current: unknown }, value: unknown): void {
  box.current = value;
}

/**
 * Keeps the labels object the same while only function identities change; each function label calls the
 * function of the latest render, so an inline function label neither rebuilds the view nor goes stale.
 */
export function useStableLabels<T>(labels: T): T {
  const [latest] = useState<{ current: unknown }>(() => ({ current: labels }));
  const [held, setHeld] = useState(() => ({ source: labels as unknown, stable: forward(labels, latest, []) }));
  useLayoutEffect(() => {
    publish(latest, labels);
  });
  if (sameShape(held.source, labels)) return held.stable as T;
  const next = { source: labels as unknown, stable: forward(labels, latest, []) };
  setHeld(next);
  return next.stable as T;
}

type AnyFn = (...args: never[]) => unknown;
type SaveFn = (change: never, ctx: never) => unknown;

/** What a server hook registers for the `data` array it hands out: its own provider props, and a wrapper that tracks a provider `onSave`. */
export type ServerWiring = {
  props: Readonly<Record<string, unknown>>;
  wrapSave: (save: SaveFn) => SaveFn;
};

/** Each observer joins the hook's while the grid reads the matching state from the hook; `null` means always. */
const OBSERVERS = [
  ["onDataChange", null],
  ["onRenderedRowsChange", null],
  ["onSortChange", "sortState"],
  ["onFilterChange", "filterState"],
  ["onFilterJoinChange", "filterJoin"],
  ["onSearchTextChange", "searchText"],
] as const;

const wirings = new WeakMap<object, ServerWiring>();
const bothCache = new WeakMap<AnyFn, WeakMap<AnyFn, AnyFn>>();
const pluginCache = new WeakMap<
  readonly unknown[],
  WeakMap<readonly unknown[], readonly unknown[]>
>();
const savesCache = new WeakMap<ServerWiring, WeakMap<SaveFn, SaveFn>>();

/** Lets `applyServerWiring` find the hook that produced `data`, so a provider prop after the `gridProps` spread joins the hook's handler instead of replacing it. */
export function registerServerWiring(data: object, wiring: ServerWiring) {
  wirings.set(data, wiring);
}

function cached<K extends object, V extends object>(
  outer: WeakMap<K, WeakMap<K, V>>,
  first: K,
  second: K,
  make: () => V,
): V {
  let inner = outer.get(first);
  if (!inner) outer.set(first, (inner = new WeakMap()));
  let value = inner.get(second);
  if (!value) inner.set(second, (value = make()));
  return value;
}

const runBoth = (own: AnyFn, theirs: AnyFn): AnyFn =>
  cached(bothCache, own, theirs, () => (...args: never[]) => {
    try {
      own(...args);
    } finally {
      theirs(...args);
    }
  });

/** The hook's plugins first, then the provider's that the hook does not hold. */
const mergePlugins = (own: readonly unknown[], theirs: readonly unknown[]) =>
  cached(pluginCache, own, theirs, () => [
    ...own,
    ...theirs.filter((plugin) => !own.includes(plugin)),
  ]);

/**
 * Joins the props of a grid whose `data` came from a server hook with the hook's own handlers and plugins.
 * Observers run the hook's handler, then the provider's. `plugins` keeps the hook's first. A provider `onSave` runs in place of
 * the hook's `onSave` option and stays tracked for `refreshAfterSave`.
 */
export function applyServerWiring<T extends object>(props: T): T {
  const data = (props as { data?: unknown }).data;
  const wiring =
    typeof data === "object" && data !== null ? wirings.get(data) : undefined;
  if (!wiring) return props;
  const given = props as Record<string, unknown>;
  const own = wiring.props;
  let next: Record<string, unknown> | null = null;
  const set = (key: string, value: unknown) => {
    if (given[key] === value) return;
    next ??= { ...given };
    next[key] = value;
  };
  for (const [key, state] of OBSERVERS) {
    if (state && given[state] !== own[state]) continue;
    const hook = own[key] as AnyFn | undefined;
    const provider = given[key] as AnyFn | undefined;
    if (hook)
      set(key, provider && provider !== hook ? runBoth(hook, provider) : hook);
  }
  const hookPlugins = own["plugins"] as readonly unknown[] | undefined;
  const providerPlugins = given["plugins"] as readonly unknown[] | undefined;
  if (hookPlugins)
    set(
      "plugins",
      providerPlugins && providerPlugins !== hookPlugins
        ? mergePlugins(hookPlugins, providerPlugins)
        : hookPlugins,
    );
  const hookSave = own["onSave"] as SaveFn | undefined;
  const providerSave = given["onSave"] as SaveFn | undefined;
  if (providerSave && providerSave !== hookSave) {
    let wrapped = savesCache.get(wiring);
    if (!wrapped) savesCache.set(wiring, (wrapped = new WeakMap()));
    let tracked = wrapped.get(providerSave);
    if (!tracked)
      wrapped.set(providerSave, (tracked = wiring.wrapSave(providerSave)));
    set("onSave", tracked);
  } else if (hookSave) set("onSave", hookSave);
  return (next ?? props) as T;
}

import { useEffect, useRef } from "react";
import { isDev } from "./is-dev";

export function useUnnamedGridWarning(ariaLabel: string | undefined, ariaLabelledBy: string | undefined): void {
  const warned = useRef(false);
  useEffect(() => {
    if (!isDev() || warned.current || ariaLabel || ariaLabelledBy) return;
    warned.current = true;
    console.warn("[data-grid] The grid has no accessible name. Set aria-label or aria-labelledby on the grid.");
  }, [ariaLabel, ariaLabelledBy]);
}

export function useSecondRootWarning(): (storeHasRoot: boolean) => void {
  const warned = useRef(false);
  return (storeHasRoot) => {
    if (!isDev() || !storeHasRoot || warned.current) return;
    warned.current = true;
    console.warn("[data-grid] a second DataGridRoot mounted on a store that another root already serves; the last mount takes the keyboard, scroll, and focus commands. Give each grid its own store.");
  };
}

