function withoutDeadBindings(keymap: Keymap): Keymap {
  const live: Keymap = {};
  for (const [action, bindings] of Object.entries(keymap) as [GridAction, string[] | undefined][]) {
    if (bindings) live[action] = bindings.filter(bindingCanMatch);
  }
  return live;
