 * (`accessorFn`/`setValue`/function-form `readOnly` accept an `unknown` row with no cast) since the
 * default `TData = unknown` matches the store's own internal row type; pass your own row type
 * (`useDataGridVisibleColumns<Employee>()`) to get back `ColumnDef<Employee, unknown>[]` instead —
 * sound because these columns always originated from the same consumer-typed `columns` prop.
 */
export function useDataGridVisibleColumns<TData = unknown>(): readonly ColumnDefOf<TData>[] {
  return useDataGridStore(useShallow((s) => s.visibleColumns)) as readonly ColumnDefOf<TData>[];
}

/**
 * Every column (including currently-hidden ones), in `columnOrder` order (definition order when
 * unset; a column that `columnOrder` does not list follows it in definition order, inside its group) — the columns-visibility/pin menu's full inventory, unlike {@link useDataGridVisibleColumns}
 * which excludes hidden columns. Same optional `TData` typed-narrowing as `useDataGridVisibleColumns`.
 */
export function useDataGridAllColumns<TData = unknown>(): readonly ColumnDefOf<TData>[] {
  return useDataGridStore(
    useShallow((s) => {
      const orderedIds = completeColumnOrder(s.columns, s.columnOrder, s.columnGroupModel);
      const byId = new Map(s.columns.map((c) => [c.id, c] as const));
      return orderedIds.map((id) => byId.get(id)).filter((c): c is AnyColumnDef => c != null);
    }),
  ) as readonly ColumnDefOf<TData>[];
}

/** The validated `columnGroups` model; null when the grid has no groups. */
export function useDataGridColumnGroupModel(): ColumnGroupModel | null {
  return useDataGridStore((s) => s.columnGroupModel);
}

/** Whether a column id is currently hidden (def-level `hidden: true` seeds this set; `setColumnHidden` wins until the `columns` prop identity changes). */
export function useDataGridIsColumnHidden(columnId: string): boolean {
  return useDataGridStore((s) => s.hiddenColumns.includes(columnId));
}

/** A single column's current width in px, or undefined when unset (falls back to the column def). */
export function useDataGridColumnWidth(columnId: string): number | undefined {
  return useDataGridStore((s) => savedColumnWidth(s.columnWidths, columnId));
}

/** Live width overrides for a set of column ids, in the same order — one subscription, safe under a changing column count. */
export function useDataGridColumnWidths(columnIds: readonly string[]): (number | undefined)[] {
  return useDataGridStore(useShallow((s) => columnIds.map((id) => savedColumnWidth(s.columnWidths, id))));
}

/** The active multi-column sort spec. */
export function useDataGridSortState(): SortSpec[] {
  return useDataGridStore(useShallow((s) => s.sortState));
}

/** How a plain header click behaves; see {@link HeaderClickBehavior}. */
export function useDataGridHeaderClickBehavior(): HeaderClickBehavior {
  return useDataGridStore((s) => s.headerClickBehavior);
}

/** The resolved (defaulted) column-feature flags: resize/reorder/pin enablement grid-wide. */
export function useDataGridColumnFeatureFlags(): {
  enableColumnResize: boolean;
  enableColumnReorder: boolean;
  enableColumnPinning: boolean;
} {
  return useDataGridStore(
    useShallow((s) => ({
      enableColumnResize: s.enableColumnResize,
      enableColumnReorder: s.enableColumnReorder,
      enableColumnPinning: s.enableColumnPinning,
    })),
  );
}

/** The active filter tree: top-level rows and groups. */
export function useDataGridFilterState(): FilterNode[] {
  return useDataGridStore(useShallow((s) => s.filterState));
}

/** Whether the column has an active filter. Subscribes to the boolean only, so a header re-renders when its own column starts or stops being filtered. */
export function useDataGridIsColumnFiltered(columnId: string): boolean {
  return useDataGridStore((s) => hasFilterOnColumn(s.filterState, columnId));
}

/** The current quick-search text. */
export function useDataGridSearchText(): string {
  return useDataGridStore((s) => s.searchText);
}

/**
 * Every cell matching the current `searchText`, in view-index row-major order, capped at 1000 hits.
 * Reads the store's precomputed slice — `setSearch`/`setSorts`/`setFilters`/`_syncProps` are the
 * only places that (re)run `findSearchMatches`, exactly once each, never per-subscriber.
 */
export function useDataGridSearchMatches(): SearchMatch[] {
  return useDataGridStore(useShallow((s) => s.searchMatches));
}

/** True when more than 1000 cells match, so `searchMatches` holds the first 1000 — drives the toolbar's "1000+" badge. */
export function useDataGridSearchCapped(): boolean {
  return useDataGridStore((s) => s.searchMatchesCapped);
}

/** Whether `coord` (view-index) is a search-match highlight target — an O(1) Set lookup, never a per-cell scan ({@link DataGridCell}'s `data-search-match`). */
export function useDataGridIsSearchMatch(coord: ViewCoord): boolean {
  const column = useDataGridStore((s) => s.visibleColumns[coord.col]);
  return useDataGridStore((s) => (column ? s.searchMatchSet.has(searchMatchKey(coord.row, column.id)) : false));
}

/** The data row at a given view (display) row index; re-renders only when that row's identity changes. Annotate `TData` with the grid's row type (or let the return type infer it). */
export function useDataGridRow<TData = unknown>(viewRowIndex: number): TData | undefined {
  return useDataGridStore((s) => {
    const dataRowIndex = dataIndexAt(s, viewRowIndex);
    return dataRowIndex === undefined ? undefined : s.data[dataRowIndex];
  }) as TData | undefined;
}

/** Stable `getRowId` result for the row at a given view row index — a hole in `data` resolves to the index-derived placeholder id. Used as the React key so rows survive sort/filter/insert/delete. */
export function useDataGridRowId(viewRowIndex: number): string | undefined {
  return useDataGridStore((s) => {
    const dataRowIndex = dataIndexAt(s, viewRowIndex);
    if (dataRowIndex === undefined) return groupIdAt(s, viewRowIndex);
    const row = s.data[dataRowIndex];
    return row === undefined ? holeRowId(dataRowIndex) : s.getRowId(row, dataRowIndex);
  });
}

/** The group id of the group row at `viewRow`; `undefined` for a missing row. */
function groupIdAt(s: DataGridStoreState, viewRow: number): string | undefined {
  return recordKeyAt(s.viewIndex, viewRow) as string | undefined;
}

/** The group row at a view row index with its level, position, and open state; `null` for any other row. Re-renders only when that group row changes. */
export function useDataGridGroupRow(viewRowIndex: number): GroupRowMeta | null {
  return useDataGridStore(useShallow((s) => groupRowMetaAt(s, viewRowIndex)));
}

/** `getRowId` results for a set of view row indices, in the same order — one subscription, safe under a changing window size. */
export function useDataGridRowIds(viewRowIndices: readonly number[]): (string | undefined)[] {
  return useDataGridStore(
    useShallow((s) =>
      viewRowIndices.map((viewRowIndex) => {
        const dataRowIndex = dataIndexAt(s, viewRowIndex);
        if (dataRowIndex === undefined) return groupIdAt(s, viewRowIndex);
        const row = s.data[dataRowIndex];
        return row === undefined ? holeRowId(dataRowIndex) : s.getRowId(row, dataRowIndex);
      }),
    ),
  );
}

type RowIdToViewRowEntry = { version: number; getRowId: DataGridStoreState["getRowId"]; map: ReadonlyMap<string, number> };

// keyed on the viewIndex array so one map survives every store write that keeps the view and row identity
const rowIdToViewRowCache = new WeakMap<readonly number[], RowIdToViewRowEntry>();

function selectRowIdToViewRow(s: DataGridStoreState): ReadonlyMap<string, number> {
  const cached = rowIdToViewRowCache.get(s.viewIndex);
  if (cached && cached.version === s.rowIdentityVersion && cached.getRowId === s.getRowId) return cached.map;
  const map = new Map<string, number>();
  for (let viewRow = 0; viewRow < s.viewIndex.length; viewRow++) {
    const rowId = rowIdAtViewRow(s, viewRow);
    if (rowId !== undefined && !map.has(rowId)) map.set(rowId, viewRow);
  }
  rowIdToViewRowCache.set(s.viewIndex, { version: s.rowIdentityVersion, getRowId: s.getRowId, map });
  return map;
}

/**
 * Full `rowId -> view row index` map for the current view; a duplicate row id maps to its first
 * view row, and an unloaded row is left out. The map is cached per `viewIndex`
 * array, `rowIdentityVersion`, and `getRowId` identity, so the O(n) build cost is paid once per
 * actual row-identity change (sort/filter/insert/delete/reorder or a consumer `data`
 * replacement) or `getRowId` swap, never per streaming tick: a value-only write replaces `data`
 * (immutability) without moving any row, so the map keeps its reference and the host does not
 * re-render. Relies on `getRowId` returning stable ids across value-only writes (ids are
 * identity, not content) — the same invariant the store's rowId index cache holds. Consumers
 * needing view -> rowId (the other direction) already have {@link useDataGridRowId}/
 * {@link useDataGridRowIds}.
 */
export function useDataGridRowIdToViewRow(): ReadonlyMap<string, number> {
  return useDataGridStore(selectRowIdToViewRow);
}

/** Number of rows in the view after the client filters, the current page only when paged; quick search never narrows it. */
export function useDataGridRowCount(): number {
  return useDataGridStore((s) => s.viewIndex.length);
}

/** Shared range-membership predicate: true when `viewRowIndex` falls inside the active range or any stacked range. */
function isRowInRangeChannel(selection: GridSelection, viewRowIndex: number): boolean {
  if (!selection.current) return false;
  const { range, rangeStack } = selection.current;
  const inRect = (r: { x: number; y: number; width: number; height: number }) => viewRowIndex >= r.y && viewRowIndex < r.y + r.height;
  return inRect(range) || rangeStack.some(inRect);
}

/** Whether the row at a given view row index is selected via the rows channel or a cell range; the columns channel does not count. Selection state is view-index, so no viewIndex mapping here. */
export function useDataGridIsRowSelected(viewRowIndex: number): boolean {
  return useDataGridStore((s) => s.selection.rows.hasIndex(viewRowIndex) || isRowInRangeChannel(s.selection, viewRowIndex));
}

/** The ROWS channel only: this row is selected as a whole (marker press/drag, Shift+Space). Deliberately excludes the cell/column channels — the marker renderer's `isSelected` must flip on row selection alone, never on a cell click (see {@link MarkerCellRenderCtx}). */
export function useDataGridIsRowChannelSelected(viewRowIndex: number): boolean {
  return useDataGridStore((s) => s.selection.rows.hasIndex(viewRowIndex));
}

/** Whether the cell channel (active range/range stack) or the column channel covers at least one cell of this view row. The rows-channel-free half of the marker renderer's `isRowChannelSelected`/`isCellSelected` pair. */
export function useDataGridIsRowCellSelected(viewRowIndex: number): boolean {
  return useDataGridStore((s) => s.selection.columns.length > 0 || isRowInRangeChannel(s.selection, viewRowIndex));
}

/** `editingError` of the cell at `coord` while it is being edited; null for every other cell. */
export function useDataGridCellEditingError(coord: ViewCoord): string | null {
  return useDataGridStore((s) =>
    s.editing !== null && s.editing.coord.col === coord.col && s.editing.coord.row === coord.row ? s.editingError : null,
  );
}

/**
 * Consolidated per-cell state: one `useShallow` subscription instead of the ~6 separate store reads
 * the individual cell hooks cost together — 7.4→2.7 store.subscribe registrations per mounted cell.
 * The 5-tuple object is genuinely fresh per relevant state change, so `useShallow` is the correct
 * tool here: it still bails when none of the 5 values changed.
 */
export function useDataGridCellState(coord: ViewCoord): DataGridCellState {
  return useDataGridStore(
    useShallow((s) => {
      const isActive = s.activeCell !== null && s.activeCell.col === coord.col && s.activeCell.row === coord.row;
      const isSelected = isActive || selectionContainsCell(s.selection, coord);
      const editing = s.editing;
      const editingHere = editing !== null && editing.coord.col === coord.col && editing.coord.row === coord.row;
      const column = s.visibleColumns[coord.col];
      const isSearchMatch = column ? s.searchMatchSet.has(searchMatchKey(coord.row, column.id)) : false;
      const cellError = column ? (s.cellErrors.size === 0 ? null : (cellErrorAt(s, coord.row, column.id) ?? null)) : null;
      return {
        isActive,
        isSelected,
        isEditing: editingHere,
        initialText: editingHere ? editing.initialText : undefined,
        editSession: editingHere ? editing.session : undefined,
        isSearchMatch,
        cellError,
      };
    }),
  );
}

/** Resolves `cellErrors`' message for a view coord's row + a known column id, or undefined when none. */
function cellErrorAt(s: DataGridStoreState, viewRow: number, columnId: string): string | undefined {
  const dataRowIndex = dataIndexAt(s, viewRow);
  if (dataRowIndex === undefined) return undefined;
  const row = s.data[dataRowIndex];
  if (row === undefined) return undefined;
  const rowId = s.getRowId(row, dataRowIndex);
  return s.cellErrors.get(cellErrorKey(rowId, columnId));
}

const EMPTY_COL_RANGES: readonly ColRange[] = [];

/**
 * This row's errored columns (view-col index -> message), or null when none — mirrors
 * `searchMatchRows`' null-not-empty-Set convention. Unlike search matches (precomputed once per
 * search-text change, since a hit set can be huge over 100k rows), `cellErrors` is expected to stay
 * small — a handful of post-commit server rejections, not a per-row scan target — so this resolves
 * the row's id once and does a plain `${rowId}:${columnId}` Map.get per visible column, gated
 * entirely behind the `cellErrors.size === 0` fast path that costs nothing when no error is active.
 */
function rowErrorCols(s: DataGridStoreState, viewRow: number): ReadonlyMap<number, string> | null {
  if (s.cellErrors.size === 0) return null;
  const dataRowIndex = dataIndexAt(s, viewRow);
  if (dataRowIndex === undefined) return null;
  const row = s.data[dataRowIndex];
  if (row === undefined) return null;
  const rowId = s.getRowId(row, dataRowIndex);
  let errorCols: Map<number, string> | null = null;
  for (let col = 0; col < s.visibleColumns.length; col++) {
    const column = s.visibleColumns[col];
    if (!column) continue;
    const message = s.cellErrors.get(cellErrorKey(rowId, column.id));
    if (message === undefined) continue;
    if (!errorCols) errorCols = new Map();
    errorCols.set(col, message);
  }
  return errorCols;
}

/** This row's currently-flashing columns (view-col index set), or null when no flash key covers the row — same null-not-empty-Set convention as `searchMatchRows`. */
function flashingColsForRow(s: DataGridStoreState, viewRow: number): ReadonlySet<number> | null {
  if (s.flashingCells.size === 0) return null;
  const rowId = rowIdAtViewRow(s, viewRow);
  if (rowId === undefined) return null;
  let cols: Set<number> | null = null;
  for (let col = 0; col < s.visibleColumns.length; col++) {
    const column = s.visibleColumns[col];
    if (!column) continue;
    if (!s.flashingCells.has(flashCellKey(rowId, column.id))) continue;
    if (!cols) cols = new Set();
    cols.add(col);
  }
  return cols;
}

function computeRowCellState(s: DataGridStoreState, viewRow: number): DataGridRowCellState {
  const activeCol = s.activeCell !== null && s.activeCell.row === viewRow ? s.activeCell.col : null;
  const editing = s.editing;
  const editingHere = editing !== null && editing.coord.row === viewRow;
  const editingCol = editingHere ? editing.coord.col : null;
  const editingInitialText = editingHere ? editing.initialText : undefined;
  const editingSession = editingHere ? editing.session : undefined;
  const editingError = editingHere ? s.editingError : null;
  const editingRejectionCount = editingHere ? s.editingRejectionCount : 0;

  // One map lookup per row instead of a per-column Set scan: 29x faster at 100k rows by 8 columns.
  const searchMatchCols: ReadonlySet<number> | null = s.searchMatchRows.get(viewRow) ?? null;

  const errorCols = rowErrorCols(s, viewRow);

  const flashingCols = flashingColsForRow(s, viewRow);

  const selectionEmpty = isSelectionEmpty(s.selection);
  const selectedColRanges = selectionEmpty
    ? EMPTY_COL_RANGES
    : selectedColRangesForRow(s.selection, viewRow, s.visibleColumns.length);

  const rowId = s.saveStatus.size === 0 && s.staleRowIds.size === 0 ? undefined : rowIdAtViewRow(s, viewRow);
  const saveStatus = rowId === undefined ? undefined : s.saveStatus.get(rowId);
  const stale = rowId !== undefined && s.staleRowIds.has(rowId);

  return { activeCol, editingCol, editingInitialText, editingSession, editingError, editingRejectionCount, searchMatchCols, errorCols, flashingCols, selectedColRanges, saveStatus, stale };
}

/** Content equality for two nullable `Set<number>`s — {@link computeRowCellState} allocates a fresh Set per call, so `searchMatchCols` needs content (not reference) comparison to stay referentially stable across unrelated store updates. */
function searchMatchColsEqual(a: ReadonlySet<number> | null, b: ReadonlySet<number> | null): boolean {
  if (a === b) return true;
  if (a === null || b === null || a.size !== b.size) return false;
  for (const col of a) if (!b.has(col)) return false;
  return true;
}

/** Content equality for two nullable `Map<number, string>`s — same rationale as {@link searchMatchColsEqual}, for `errorCols` (a fresh Map per `computeRowCellState` call). */
function errorColsEqual(a: ReadonlyMap<number, string> | null, b: ReadonlyMap<number, string> | null): boolean {
  if (a === b) return true;
  if (a === null || b === null || a.size !== b.size) return false;
  for (const [col, message] of a) if (b.get(col) !== message) return false;
  return true;
}

/** Content equality for {@link DataGridRowCellState} — the comparator `useDataGridRowCellState` uses to keep its selector output referentially stable when nothing in the row actually changed. */
function rowCellStateEqual(a: DataGridRowCellState, b: DataGridRowCellState): boolean {
  if (a === b) return true;
  return (
    a.activeCol === b.activeCol &&
    a.editingCol === b.editingCol &&
    a.editingInitialText === b.editingInitialText &&
    a.editingSession === b.editingSession &&
    a.editingError === b.editingError &&
    a.editingRejectionCount === b.editingRejectionCount &&
    a.saveStatus === b.saveStatus &&
    a.stale === b.stale &&
    searchMatchColsEqual(a.searchMatchCols, b.searchMatchCols) &&
    errorColsEqual(a.errorCols, b.errorCols) &&
    searchMatchColsEqual(a.flashingCols, b.flashingCols) &&
    colRangesEqual(a.selectedColRanges, b.selectedColRanges)
  );
}

/**
 * One subscription per ROW instead of one per CELL: a max-velocity full-window swap mounts ~544
 * cells, and per-cell subscriptions are 544 subscribe/unsubscribe cycles per tick; this is one
 * per row. Mirrors `useShallow`'s ref-memo pattern with {@link rowCellStateEqual} — the shape
 * needs custom comparison (a `Set` by reference, a tuple array by content) that `shallow` cannot
 * express. A selection change recomputes every row's selector, but only the affected row's
 * comparator sees new content — only that row re-renders. Selection membership flips are the one
 * sanctioned cell re-render (aria-selected).
 */
export function useDataGridRowCellState(viewRow: number): DataGridRowCellState {
  const prev = useRef<DataGridRowCellState | undefined>(undefined);
  return useDataGridStore((s) => {
    const next = computeRowCellState(s, viewRow);
    if (prev.current !== undefined && rowCellStateEqual(prev.current, next)) return prev.current;
    return (prev.current = next);
  });
}

/** The resolved (defaulted) marker-column mode; see {@link RowMarkersMode}. */
export function useDataGridRowMarkers(): RowMarkersMode {
  return useDataGridStore((s) => s.rowMarkers);
}

/** The resolved (defaulted) selection-gesture config; see {@link SelectionConfig}. */
export function useDataGridSelectionConfig(): {
  enableRowSelection: boolean;
  enableRowDelete: boolean;
  enableColumnSelection: boolean;
  enableRangeSelection: boolean;
  enableMultiRange: boolean;
  checkedRowsLifetime: CheckedRowsLifetime;
} {
  return useDataGridStore(
    useShallow((s) => ({
      checkedRowsLifetime: s.checkedRowsLifetime,
      enableRowSelection: s.enableRowSelection,
      enableRowDelete: s.enableRowDelete,
      enableColumnSelection: s.enableColumnSelection,
      enableRangeSelection: s.enableRangeSelection,
      enableMultiRange: s.enableMultiRange,
    })),
  );
}

/**
 * The checked rows as a value for a bulk action: ids (the checked loaded rows plus the remembered ones), or
 * "all matching except these ids" after `actions.selectAllMatching()`. Needs `totalRowCount` and `checkedRowsLifetime="across-filters"`
 * to cover rows outside `data`. The value changes when the selection, the data, the view (sort, filter, search), or `totalRowCount` does.
 */
export function useDataGridSelectedRows(): DataGridSelectedRows {
  const rows = useDataGridStore((s) => s.selection.rows);
  const hiddenCheckedRowIds = useDataGridStore((s) => s.hiddenCheckedRowIds);
  const allMatching = useDataGridStore((s) => s.allMatching);
  const viewIndex = useDataGridStore((s) => s.viewIndex);
  const getRowId = useDataGridStore((s) => s.getRowId);
  const totalRowCount = useDataGridStore((s) => s.totalRowCount);
  const sortState = useDataGridStore((s) => s.sortState);
  const filterState = useDataGridStore((s) => s.filterState);
  const filterJoin = useDataGridStore((s) => s.filterJoin);
  const searchText = useDataGridStore((s) => s.searchText);
  const rowIdentityVersion = useDataGridStore((s) => s.rowIdentityVersion);
  const serverHeld = useDataGridStore((s) => s.serverHeld);
  const storeApi = useDataGridStoreApi();
  // Value writes keep the row ids, so `data` is read at compute time and is not a dependency.
  return useMemo(
    () => readSelectedRows({ selection: { rows } as DataGridStoreState["selection"], hiddenCheckedRowIds, allMatching, data: storeApi.getState().data, viewIndex, getRowId, totalRowCount, sortState, filterState, filterJoin, searchText, groupLayout: storeApi.getState().groupLayout, groupMode: storeApi.getState().groupMode, serverHeld }),
    // oxlint-disable-next-line react-hooks/exhaustive-deps
    [rows, hiddenCheckedRowIds, allMatching, viewIndex, getRowId, totalRowCount, sortState, filterState, filterJoin, searchText, rowIdentityVersion, serverHeld, storeApi],
  );
}

/** The grid's `inputDebounceMs`: the wait in ms between the last keystroke and the commit of its text inputs. Default 200. */
export function useDataGridInputDebounce(): number {
  return useDataGridStore((s) => s.inputDebounceMs ?? 200);
}

/** The save status of a row whose `onSave` promise is pending (`"saving"`) or was refused and reverted (`"failed"`); `undefined` otherwise. */
export function useDataGridRowSaveStatus(rowId: string): RowSaveStatus | undefined {
  return useDataGridStore((s) => s.saveStatus.get(rowId));
}

/** The number of acknowledged changes (an `onSave` promise) that have not settled. */
export function useDataGridPendingSaveCount(): number {
  return useDataGridStore((s) => s.pendingSaveCount);
}

/** The consumer hooks whose promise has not settled (`processPaste`, `processCellFromClipboard`, `validateRow`, `onBeforeEditStart`, `createRow`, `duplicateRow`, `onBeforeDeleteRows`, `import`, `mapColumn`, `processReplace`, and `validate` while an async column `validate` holds a paste, fill, or clear); the same empty set while none is pending. */
export function useDataGridGatePending(): ReadonlySet<GateName> {
  return useDataGridStore((s) => s.gatesPending);
}

/** Marks `name` pending in {@link useDataGridGatePending} while `active` is true; for add-ons that run a gate of their own. */
export function useDataGridMarkGatePending(name: GateName, active: boolean): void {
  const gates = useDataGridInternalActions()._gates();
  useEffect(() => (active ? gates.track(name) : undefined), [gates, name, active]);
}

/** The number of checked rows that left the view (a filter, a page change, a window move), remembered by `checkedRowsLifetime="across-filters"`; `0` otherwise and while "all matching" is on. */
export function useDataGridHiddenCheckedCount(): number {
  return useDataGridStore((s) => (s.allMatching ? 0 : s.hiddenCheckedRowIds.size));
}

/**
 * Select-all header-marker checkbox tri-state: 'checked' (every view row is checked), 'indeterminate'
 * (some), 'unchecked' (none). It reads the rows channel only: a cell range (Ctrl+A) is not a checked row.
 * An empty grid reads 'unchecked'. `CompactSelection.hasAll` answers in O(its own run count).
 */
export function allRowsSelectedState(s: DataGridStoreState): "checked" | "indeterminate" | "unchecked" {
  const rowCount = s.viewIndex.length;
  const { rows } = s.selection;
  if (rowCount === 0 || rows.length === 0) return "unchecked";
  return rows.hasAll([0, rowCount]) ? "checked" : "indeterminate";
}

/** Reactive {@link allRowsSelectedState}. */
export function useDataGridAllRowsSelected(): "checked" | "indeterminate" | "unchecked" {
  return useDataGridStore(allRowsSelectedState);
}

import type { StoreApi } from "zustand/vanilla";
import type { GateTracker } from "./gate-signal";
import type { DataGridActions, DataGridInternalActions, DataGridStoreState } from "./types";

/**
 * One actions table per store, kept OUT of the store state: `state.actions` (and the
 * `useDataGridActions()`/`api.actions`/`DataGridReadState` views of it) expose the public actions
 * only, while the `_`-prefixed internals the core wiring calls (`_syncProps`, `_register*`,
 * `_moveActiveCell`, …) live here. The accessor returns both merged into one stable object, so
 * internal call sites and tests get a single table. Reached only through {@link getInternalActions}
 * from inside the block — neither the consumer barrel nor the sdk barrel exports it.
 */
const internalActionsByStore = new WeakMap<StoreApi<DataGridStoreState>, DataGridInternalActions>();
const mergedActionsByStore = new WeakMap<StoreApi<DataGridStoreState>, DataGridInternalActions & DataGridActions>();

/** Records the store's internal-actions table (called once at store creation). */
export function registerInternalActions(store: StoreApi<DataGridStoreState>, actions: DataGridInternalActions): void {
  internalActionsByStore.set(store, actions);
}

/** The async-gate tracker of a real grid store; `undefined` for any other object (a test double). */
export function gateTrackerOf(store: object): GateTracker | undefined {
  return internalActionsByStore.get(store as StoreApi<DataGridStoreState>)?._gates();
}

/**
 * The store's actions table, public and internal. Built lazily on first access (the registration
 * runs inside the store's initializer, before state exists), and cached: both source tables keep
 * their identity for the store's lifetime, so the merge does too.
 */
export function getInternalActions(store: StoreApi<DataGridStoreState>): DataGridInternalActions & DataGridActions {
  let merged = mergedActionsByStore.get(store);
  if (!merged) {
    const internal = internalActionsByStore.get(store);
    if (!internal) throw new Error("[data-grid] no internal actions registered for this store");
    merged = { ...store.getState().actions, ...internal };
    mergedActionsByStore.set(store, merged);
  }
  return merged;
}

import type { StoreApi } from "zustand/vanilla";
import { isDev } from "../is-dev";
import { warnDev } from "../is-dev";
import type { DataGridStoreState } from "./types";

function hasHole(data: readonly unknown[]): boolean {
  for (let i = 0; i < data.length; i++) if (data[i] === undefined) return true;
  return false;
}

/** Warns once per store when a client sort or filter changes while `data` holds unloaded rows or fewer rows than `totalRowCount`. */
export function watchClientViewOverHoles(store: StoreApi<DataGridStoreState>): () => void {
  let warned = false;
  return store.subscribe((state, prev) => {
    if (warned || !isDev()) return;
    const sortChanged = state.sortMode !== "server" && state.sortState !== prev.sortState;
    const filterChanged = state.filterMode !== "server" && (state.filterState !== prev.filterState || state.filterJoin !== prev.filterJoin);
    if (!sortChanged && !filterChanged) return;
    if (!hasHole(state.data) && !(state.totalRowCount != null && state.totalRowCount > state.data.length)) return;
    warned = true;
    warnDev(
      'a client sort or filter changed while data holds unloaded rows or fewer rows than totalRowCount. The client cannot sort or filter rows it has not fetched; use sortMode="server" and filterMode="server" and send the sort and filter to your backend.',
    );
  });
}

import type { ServerAggregate } from "./server-spec";
import type { PivotView } from "./store/pivot-view";

/** The stored value a row group shares; `null` is the empty group (`null`, `undefined`, and `""`). */
export type GroupKey = string | number | boolean | null;

/** One step of a group path: the group column and the key at that level. */
export type GroupPathSegment = { columnId: string; key: GroupKey };

/** Which groups are open: the groups that differ from `mode`, named by group id. `{ mode: "collapsed", ids: [] }` shows only the top level. */
export type ExpandedState = { mode: "collapsed" | "expanded"; ids: readonly string[] };

/** The view row that heads a row group. It holds no data. */
export type GroupNode = {
  readonly id: string;
  /** 0 for the outermost level. */
  readonly depth: number;
  readonly columnId: string;
  readonly key: GroupKey;
  /** The cell type's display text of the key; empty for the empty group. */
  readonly label: string;
  /** Rows of the group, all levels below it counted. */
  readonly count: number;
  /** Direct children: groups of the next level, or rows in the innermost group. */
  readonly childCount: number;
  /** One value per `aggregate` column; `null` when no value counted. */
  readonly aggregates: Readonly<Record<string, unknown>>;
  /** Under pivot: the slot's pivot cells, in held order; `NaN` when no value counted. */
  readonly pivotCells?: Float64Array;
  /** A server group whose rows load or failed to load. */
  readonly status?: "loading" | "failed";
};

type ReduceFn<TData> = { reduce(values: readonly unknown[], rows: readonly TData[]): unknown }["reduce"];

/**
 * What `ColumnDef.aggregate` and the pinned-rows add-on reduce a column with. `count` counts values other than `null`, `undefined`, and `""`.
 * `sum`, `avg`, `min`, and `max` read finite numbers and skip the rest. A reducer with no counted value gives `null` (`count` gives `0`).
 * A function receives every value and its rows, empty values included, and runs on the client only.
 */
export type AggregateReducer<TData = unknown> = "sum" | "avg" | "min" | "max" | "count" | ReduceFn<TData>;

/** One reducer per column id. */
export type AggregateSpecs<TData = unknown> = Record<string, AggregateReducer<TData>>;

/**
 * The group rows of a grouped view. A `viewIndex` entry below 0 names `rows[-entry - 1]`.
 * `state.groupLayout` is `null` when the grid is not grouped.
 */
export type GroupLayout = {
  readonly rows: readonly GroupNode[];
  /** Rows of the whole result, collapsed groups included. */
  readonly leafCount: number;
  /** @internal The client buckets; a server layout has none. */
  readonly tree?: unknown;
  /** @internal The held set of a client pivot; a server layout keeps its own in `ServerGroupLayout.pivot`. */
  readonly pivot?: ServerPivotLayout;
};

/** One group row of a {@link ServerGroupLayout}: where it sits in `data`, the group it heads, and what the server said about it. */
export type ServerGroupSlot = {
  /** The row of `data` that stands for the group row. Strictly increasing across `rows`. */
  viewRow: number;
  /** From the outermost level to this group: one segment per level, following `groupBy`. */
  path: readonly GroupPathSegment[];
  label?: string;
  count: number;
  childCount: number;
  aggregates?: Readonly<Record<string, unknown>>;
  /** Under pivot: one pivot cell per held column, in held order; `NaN` when no value counted. */
  pivotCells?: Float64Array;
  status?: "loading" | "failed";
};

/** One generated column of a pivot answer: one key per pivot column, and the index of its value in `spec.aggregates`. */
export type PivotColumnDescriptor = { readonly path: readonly GroupKey[]; readonly valueIndex: number };

/** The held set of a server pivot. Its `columns` keep one identity while the generated ids stay equal; a new `omitted` makes a new object over the same `columns`. */
export type ServerPivotLayout = {
  /** The pivot column. */
  readonly columnId: string;
  /** The values: `spec.aggregates` of the request. */
  readonly values: readonly ServerAggregate[];
  /** The held columns, key-major, at most 200. */
  readonly columns: readonly PivotColumnDescriptor[];
  /** Generated columns the server or the grid cut. */
  readonly omitted: number;
};

/**
 * The group rows of a server grid, in view order. `data` holds one entry per view row, a placeholder at each group row.
 * Only the server hook builds it; the core derives the group ids from the paths.
 */
export type ServerGroupLayout = {
  readonly rows: readonly ServerGroupSlot[];
  /** Rows of the whole result, collapsed groups included. */
  readonly leafCount: number;
  /** The held set. Present under pivot. */
  readonly pivot?: ServerPivotLayout;
  /** `false` while the source cannot send `spec.pivot` (no aggregates, more than 4 `groupBy` levels); the header menu then hides "Pivot by". */
  readonly pivotable?: false;
};

/** A pivot: the pivot column, the one entry of `columnIds`. */
export type PivotSpec = { readonly columnIds: readonly string[] };

/** What `renderGroupLabel` receives for a group row. */
export type GroupLabelCtx = {
  groupId: string;
  columnId: string;
  key: GroupKey;
  label: string;
  count: number;
  depth: number;
  expanded: boolean;
};

/** What the grouping actions return: `ok`, or the reason nothing changed. */
export type GroupActionResult = { ok: true } | { ok: false; reason: "server-groups" };

/** The grouping state of the store. */
export type GroupStoreState = {
  groupBy: readonly string[];
  expanded: ExpandedState;
  groupLayout: GroupLayout | null;
  /** `"server"` shows the group rows of `serverGroupLayout` and never buckets rows. */
  groupMode: "client" | "server";
  /** The `groupLayout` prop as given; `groupLayout` above is the layout the core derived from it. */
  serverGroupLayout: ServerGroupLayout | null;
  /** @internal Under pivot: the generated columns of the held set (`serverGroupLayout.pivot`, or `groupLayout.pivot` of a client pivot); `null` otherwise. */
  pivot: PivotView | null;
  /** Whether a grouping prop was given: the menus and keys show only then. */
  groupingEnabled: boolean;
  groupByControlled: boolean;
  expandedControlled: boolean;
  /** The pivot column as given (at most 1 id); a rebuild checks it against the live columns and ignores it without `groupBy`. */
  pivotColumnIds: readonly string[];
  pivotControlled: boolean;
};

import type { AggregateReducer } from "./group-types";

export type { AggregateReducer, AggregateSpecs } from "./group-types";

/** Whether `count` counts a value: anything but `null`, `undefined`, and `""`. */
export const isCounted = (value: unknown): boolean => value !== null && value !== undefined && value !== "";

/** Reduces the `value` of each of `rows` like {@link aggregateValues}, without building an array for a named reducer. */
export function aggregateRows<TData = unknown>(reducer: AggregateReducer<TData>, rows: readonly number[], value: (row: number) => unknown, rowAt?: (row: number) => unknown): unknown {
  if (typeof reducer === "function") return reducer(rows.map((row) => value(row)), rows.map((row) => rowAt?.(row) as TData));
  let counted = 0;
  let total = 0;
  let min = Infinity;
  let max = -Infinity;
  for (const row of rows) {
    const v = value(row);
    if (reducer === "count") {
      if (isCounted(v)) counted++;
    } else if (typeof v === "number" && Number.isFinite(v)) {
      counted++;
      total += v;
      if (v < min) min = v;
      if (v > max) max = v;
    }
  }
  return finish(reducer, counted, total, min, max);
}

/**
 * Reduces `values` (one per source row, in row order) with `reducer`. `count` counts values that are
 * not `null`, `undefined`, or `""`. `sum`, `avg`, `min`, and `max` read finite numbers and skip the rest.
 * A reducer with no counted value gives `null` (`count` gives `0`). A function receives every value and
 * its rows, empty values included, and owns its result; a function that throws throws out of this call.
 */
export function aggregateValues<TData = unknown>(reducer: AggregateReducer<TData>, values: readonly unknown[], rows: readonly TData[] = []): unknown {
  if (typeof reducer === "function") return reducer(values, rows);
  if (reducer === "count") {
    let counted = 0;
    for (const value of values) if (isCounted(value)) counted++;
    return counted;
  }
  let total = 0;
  let min = Infinity;
  let max = -Infinity;
  let counted = 0;
  for (const value of values) {
    if (typeof value !== "number" || !Number.isFinite(value)) continue;
    counted++;
    total += value;
    if (value < min) min = value;
    if (value > max) max = value;
  }
  return finish(reducer, counted, total, min, max);
}

function finish(reducer: string, counted: number, total: number, min: number, max: number): unknown {
  if (reducer === "count") return counted;
  if (counted === 0) return null;
  switch (reducer) {
    case "sum":
      return total;
    case "avg":
      return total / counted;
    case "min":
      return min;
    case "max":
      return max;
    default:
      return null;
  }
}

import { aggregateRows } from "../aggregate";
import type { AggregateReducer, ExpandedState, GroupKey, GroupLayout, GroupNode, GroupPathSegment, ServerPivotLayout } from "../group-types";
import { expandedTest, groupIdOf, groupKeyOf, groupKeyText } from "../store/group-state";
import type { CellAccessor } from "./build-view-index";
import { sortCollator } from "./sort-collator";

export type GroupAggregateSpec = { columnId: string; reducer: AggregateReducer<unknown> };

export type GroupBuildInput = {
  /** Data indices after the filters and the sorts that are not on a group column, in leaf order. */
  leaves: readonly number[];
  accessor: CellAccessor;
  groupBy: readonly string[];
  /** The direction of an active sort on a group column; a column without one orders ascending. */
  directions?: ReadonlyMap<string, "asc" | "desc">;
  aggregates?: readonly GroupAggregateSpec[];
  /** The data row at an index, for function reducers; `undefined` marks an unloaded row, which makes the build give up. */
  rowAt?: (rowIndex: number) => unknown;
  labelOf?: (columnId: string, key: GroupKey, rowIndex: number) => string;
  onReducerError?: (columnId: string, error: unknown) => void;
};

/** One group with its children; the innermost level holds `leaves`, the others `groups`. */
export type GroupBucket = { node: GroupNode; parent: GroupBucket | null; groups: GroupBucket[] | null; leaves: number[] | null };

/** `pivot` holds the held set of a client pivot: its innermost groups never lay out their rows. */
export type GroupTree = { roots: GroupBucket[]; leafCount: number; owners?: Map<number, GroupBucket>; leavesInOrder?: number[]; pivot?: ServerPivotLayout };

export type GroupedView = { viewIndex: number[]; layout: GroupLayout };

/** Gives the reader of one column: a function from a data index to the raw value. */
type Source = (columnId: string) => (rowIndex: number) => unknown;

const rawSource = (accessor: CellAccessor): Source => (columnId) => (accessor.getValue ? (rowIndex) => accessor.getValue!(rowIndex, columnId) : (rowIndex) => accessor.getText(rowIndex, columnId));

/** A source that gets each column of `rows` through the accessor once, then answers from a dense array. */
function denseSource(accessor: CellAccessor, rows: readonly number[]): Source {
  const raw = rawSource(accessor);
  let size = 0;
  for (const row of rows) if (row >= size) size = row + 1;
  const readers = new Map<string, (rowIndex: number) => unknown>();
  return (columnId) => {
    let reader = readers.get(columnId);
    if (!reader) {
      const get = raw(columnId);
      const values = new Array<unknown>(size);
      for (const row of rows) values[row] = get(row);
      reader = (rowIndex) => values[rowIndex];
      readers.set(columnId, reader);
    }
    return reader;
  };
}

function aggregatesOf(rows: readonly number[], input: Pick<GroupBuildInput, "aggregates" | "rowAt" | "onReducerError">, source: Source): Record<string, unknown> {
  const out = Object.create(null) as Record<string, unknown>;
  for (const { columnId, reducer } of input.aggregates ?? []) {
    try {
      out[columnId] = aggregateRows(reducer, rows, source(columnId), input.rowAt);
    } catch (error) {
      input.onReducerError?.(columnId, error);
      out[columnId] = null;
    }
  }
  return out;
}

function orderedGroups(groups: Map<string, { key: GroupKey; rows: number[] }>, columnId: string, input: GroupBuildInput): { key: GroupKey; rows: number[] }[] {
  const empty = groups.get("");
  const rest = [...groups.entries()].filter(([text]) => text !== "");
  const direction = input.directions?.get(columnId) === "desc" ? -1 : 1;
  const compare = input.accessor.compare?.(columnId);
  const collator = sortCollator();
  rest.sort(([textA, a], [textB, b]) => {
    const raw = compare ? compare(a.rows[0]!, b.rows[0]!) : collator.compare(textA, textB);
    const result = Number.isFinite(raw) ? raw : 0;
    if (result !== 0) return direction * result;
    return textA < textB ? -1 : textA > textB ? 1 : 0;
  });
  const ordered = rest.map(([, group]) => group);
  return empty ? [...ordered, empty] : ordered;
}

function bucketLevel(rows: readonly number[], level: number, path: readonly GroupPathSegment[], input: GroupBuildInput, source: Source): GroupBucket[] {
  const columnId = input.groupBy[level]!;
  const value = source(columnId);
  const groups = new Map<string, { key: GroupKey; rows: number[] }>();
  for (const row of rows) {
    const key = groupKeyOf(value(row));
    const text = typeof key === "string" ? key : groupKeyText(key);
    const group = groups.get(text);
    if (group) group.rows.push(row);
    else groups.set(text, { key, rows: [row] });
  }
  const innermost = level === input.groupBy.length - 1;
  return orderedGroups(groups, columnId, input).map(({ key, rows: members }) => {
    const here = [...path, { columnId, key }];
    const children = innermost ? null : bucketLevel(members, level + 1, here, input, source);
    const node: GroupNode = {
      id: groupIdOf(here),
      depth: level,
      columnId,
      key,
      label: key === null ? "" : (input.labelOf?.(columnId, key, members[0]!) ?? groupKeyText(key)),
      count: members.length,
      childCount: children ? children.length : members.length,
      aggregates: aggregatesOf(members, input, source),
    };
    const bucket: GroupBucket = { node, parent: null, groups: children, leaves: innermost ? members : null };
    if (children) for (const child of children) child.parent = bucket;
    return bucket;
  });
}

/** Buckets `input.leaves` by `input.groupBy`, level by level, keeping each group's rows in leaf order. `null` when a leaf is an unloaded row. */
export function buildGroupTree(input: GroupBuildInput): GroupTree | null {
  if (input.rowAt) for (const row of input.leaves) if (input.rowAt(row) === undefined) return null;
  return { roots: bucketLevel(input.leaves, 0, [], input, denseSource(input.accessor, input.leaves)), leafCount: input.leaves.length };
}

/** Lays the tree out as view entries: a group entry (below 0) per group, and its rows only while it is open. */
export function flattenGroupTree(tree: GroupTree, expanded: ExpandedState): GroupedView {
  const isOpen = expandedTest(expanded);
  const viewIndex: number[] = [];
  const rows: GroupNode[] = [];
  const visit = (buckets: readonly GroupBucket[]): void => {
    for (const bucket of buckets) {
      rows.push(bucket.node);
      viewIndex.push(-rows.length);
      if (!isOpen(bucket.node.id)) continue;
      if (bucket.groups) visit(bucket.groups);
      else if (!tree.pivot) for (const row of bucket.leaves!) viewIndex.push(row);
    }
  };
  visit(tree.roots);
  return { viewIndex, layout: tree.pivot ? { rows, leafCount: tree.leafCount, tree, pivot: tree.pivot } : { rows, leafCount: tree.leafCount, tree } };
}

/** The grouped view of `input.leaves`, or `null` when a leaf is an unloaded row. */
export function buildGroupView(input: GroupBuildInput, expanded: ExpandedState): GroupedView | null {
  const tree = buildGroupTree(input);
  return tree ? flattenGroupTree(tree, expanded) : null;
}

/** Every row of the result in view order, collapsed groups included. */
export function leavesOfTree(tree: GroupTree): number[] {
  if (tree.leavesInOrder) return tree.leavesInOrder;
  const out: number[] = [];
  const visit = (buckets: readonly GroupBucket[]): void => {
    for (const bucket of buckets) {
      if (bucket.groups) visit(bucket.groups);
      else for (const row of bucket.leaves!) out.push(row);
    }
  };
  visit(tree.roots);
  tree.leavesInOrder = out;
  return out;
}

/** The innermost bucket of each row of the tree, by data index. */
export function ownersOf(tree: GroupTree): Map<number, GroupBucket> {
  if (tree.owners) return tree.owners;
  const owners = new Map<number, GroupBucket>();
  const visit = (buckets: readonly GroupBucket[]): void => {
    for (const bucket of buckets) {
      if (bucket.groups) visit(bucket.groups);
      else for (const row of bucket.leaves!) owners.set(row, bucket);
    }
  };
  visit(tree.roots);
  tree.owners = owners;
  return owners;
}

/** The group ids that hold the row at `dataIndex`, innermost first; empty when the row is in no group. */
export function groupIdsOfRow(tree: GroupTree, dataIndex: number): string[] {
  const ids: string[] = [];
  for (let bucket = ownersOf(tree).get(dataIndex) ?? null; bucket; bucket = bucket.parent) ids.push(bucket.node.id);
  return ids;
}

/**
 * Reduces again the groups that hold the touched rows, and their parents, over the kept buckets; `null` reduces every group.
 * Returns the replaced nodes by id; the buckets point at the new nodes afterwards.
 */
export function refreshGroupAggregates(tree: GroupTree, touchedRows: readonly number[] | null, input: Pick<GroupBuildInput, "accessor" | "aggregates" | "rowAt" | "onReducerError">): Map<string, GroupNode> {
  const source = rawSource(input.accessor);
  const stale = new Set<GroupBucket>();
  if (touchedRows === null) {
    const visit = (buckets: readonly GroupBucket[]): void => {
      for (const bucket of buckets) {
        stale.add(bucket);
        if (bucket.groups) visit(bucket.groups);
      }
    };
    visit(tree.roots);
  } else {
    const owners = ownersOf(tree);
    for (const row of touchedRows) for (let bucket = owners.get(row) ?? null; bucket && !stale.has(bucket); bucket = bucket.parent) stale.add(bucket);
  }
  const replaced = new Map<string, GroupNode>();
  const leavesOf = (bucket: GroupBucket): number[] => (bucket.leaves ? bucket.leaves : bucket.groups!.flatMap(leavesOf));
  for (const bucket of stale) {
    bucket.node = { ...bucket.node, aggregates: aggregatesOf(leavesOf(bucket), input, source) };
    replaced.set(bucket.node.id, bucket.node);
  }
  return replaced;
}

import { isCounted } from "../aggregate";
import type { GroupKey, GroupNode, PivotColumnDescriptor, ServerPivotLayout } from "../group-types";
import { MAX_PIVOT_COLUMNS, pivotColumnId as generatedIdOf } from "../pivot-columns";
import type { ServerAggregate } from "../server-spec";
import { groupKeyOf, groupKeyText } from "../store/group-state";
import { buildGroupTree, ownersOf, type GroupBucket, type GroupBuildInput, type GroupTree } from "./build-group-view";
import type { CellAccessor } from "./build-view-index";
import { sortCollator } from "./sort-collator";

/** Most cells a client pivot holds: group rows times generated columns, the cap of the server pivot store. */
export const MAX_PIVOT_CELLS = 1_000_000;

/** Longest generated id the grid keeps, as the server pivot reader does. */
const MAX_GENERATED_ID_LENGTH = 2048;

export type PivotBuildInput = GroupBuildInput & {
  /** The pivot column; `directions` holds its sort direction. */
  pivotColumnId: string;
  /** One generated column per held key and value. */
  values: readonly ServerAggregate[];
  /** The held set of the last build: its `columns` array returns while the generated ids stay equal. */
  previous?: ServerPivotLayout;
};

/** The group tree, each node carrying the `pivotCells` of its subtree, and the held set of the whole result. */
export type PivotBuild = { tree: GroupTree; pivot: ServerPivotLayout };

/** The pivot holds more than {@link MAX_PIVOT_CELLS}; no cell was allocated. */
export type PivotTooLarge = { tooLarge: true };

type Key = { key: GroupKey; text: string; row: number; id: number };

type Cells = { cells: Float64Array; counted: Float64Array | null };

const combine = (reducer: ServerAggregate["reducer"], was: number, v: number): number =>
  Number.isNaN(was) ? v : reducer === "min" ? Math.min(was, v) : reducer === "max" ? Math.max(was, v) : was + v;

/** The first `limit` keys in `compare` order, the empty key last; a key past the cut costs one comparison. */
function heldKeys(keys: Iterable<Key>, limit: number, compare: (a: Key, b: Key) => number, accepts: (key: Key) => boolean): Key[] {
  const held: Key[] = [];
  if (limit === 0) return held;
  let empty: Key | undefined;
  for (const key of keys) {
    if (key.text === "") {
      empty = key;
      continue;
    }
    if (held.length === limit && compare(key, held[limit - 1]!) >= 0) continue;
    if (!accepts(key)) continue;
    let lo = 0;
    let hi = held.length;
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (compare(key, held[mid]!) < 0) hi = mid;
      else lo = mid + 1;
    }
    held.splice(lo, 0, key);
    if (held.length > limit) held.pop();
  }
  if (empty && held.length < limit && accepts(empty)) held.push(empty);
  return held;
}

const sameIds = (previous: ServerPivotLayout, columnId: string, values: readonly ServerAggregate[], columns: readonly PivotColumnDescriptor[]): boolean =>
  previous.columnId === columnId &&
  previous.values.length === values.length &&
  previous.values.every((value, i) => value.columnId === values[i]!.columnId && value.reducer === values[i]!.reducer) &&
  previous.columns.length === columns.length &&
  previous.columns.every((column, i) => column.valueIndex === columns[i]!.valueIndex && groupKeyText(column.path[0] ?? null) === groupKeyText(columns[i]!.path[0] ?? null));

/**
 * The client pivot of `input.leaves`: the keys of the pivot column in group order, the empty key last, at most
 * {@link MAX_PIVOT_COLUMNS} divided by the value count, and per group node one key-major `Float64Array` (`NaN` for no value).
 * `null` when a leaf is an unloaded row; {@link PivotTooLarge} above {@link MAX_PIVOT_CELLS}.
 */
export function buildPivot(input: PivotBuildInput): PivotBuild | PivotTooLarge | null {
  const tree = buildGroupTree(input);
  if (!tree) return null;
  const { values, pivotColumnId, accessor, leaves } = input;
  const valueCount = values.length;

  let size = 0;
  for (const row of leaves) if (row >= size) size = row + 1;
  const keyIdOf = new Int32Array(size);
  const byText = new Map<string, Key>();
  if (valueCount > 0) {
    const read = accessor.getValue ? (row: number) => accessor.getValue!(row, pivotColumnId) : (row: number) => accessor.getText(row, pivotColumnId);
    for (const row of leaves) {
      const key = groupKeyOf(read(row));
      const text = typeof key === "string" ? key : groupKeyText(key);
      let entry = byText.get(text);
      if (!entry) {
        entry = { key, text, row, id: byText.size };
        byText.set(text, entry);
      }
      keyIdOf[row] = entry.id;
    }
  }
  const rowCompare = accessor.compare?.(pivotColumnId);
  const collator = sortCollator();
  const direction = input.directions?.get(pivotColumnId) === "desc" ? -1 : 1;
  // The order of the group levels in `buildGroupTree`, so a pivot key sits where its group would.
  const compare = (a: Key, b: Key): number => {
    const raw = rowCompare ? rowCompare(a.row, b.row) : collator.compare(a.text, b.text);
    const result = Number.isFinite(raw) ? raw : 0;
    if (result !== 0) return direction * result;
    return a.text < b.text ? -1 : a.text > b.text ? 1 : 0;
  };
  const fits = (key: Key): boolean => {
    try {
      return values.every((value) => generatedIdOf(pivotColumnId, key.key, value).length <= MAX_GENERATED_ID_LENGTH);
    } catch {
      return false;
    }
  };
  const held = heldKeys(byText.values(), valueCount === 0 ? 0 : Math.floor(MAX_PIVOT_COLUMNS / valueCount), compare, fits);
  const keyCount = held.length;
  const width = keyCount * valueCount;

  let nodes = 0;
  const countNodes = (buckets: readonly GroupBucket[]): void => {
    for (const bucket of buckets) {
      nodes++;
      if (bucket.groups) countNodes(bucket.groups);
    }
  };
  countNodes(tree.roots);
  if (nodes * width > MAX_PIVOT_CELLS) return { tooLarge: true };

  const columns: PivotColumnDescriptor[] = [];
  for (const { key } of held) for (let valueIndex = 0; valueIndex < valueCount; valueIndex++) columns.push({ path: [key], valueIndex });
  const { previous } = input;
  const pivot: ServerPivotLayout = {
    columnId: pivotColumnId,
    values,
    columns: previous && sameIds(previous, pivotColumnId, values, columns) ? previous.columns : columns,
    omitted: (byText.size - keyCount) * valueCount,
  };

  const rankOf = new Int32Array(byText.size).fill(-1);
  held.forEach((key, rank) => (rankOf[key.id] = rank));
  const reducer = pivotReducer(accessor, values, width, (row) => rankOf[keyIdOf[row]!]!);
  for (const root of tree.roots) reducer.finish(root, reducer.fill(root, null));
  tree.pivot = pivot;
  return { tree, pivot };
}

/**
 * Reduces again the pivot cells of the groups that hold `touchedRows` (data indices) and of their parents, over the kept buckets
 * and the held set of `pivot`; the result equals a full {@link buildPivot} while every touched row keeps its pivot key and its group.
 * Returns the replaced nodes by id; the buckets point at the new nodes afterwards.
 */
export function refreshPivotCells(tree: GroupTree, pivot: ServerPivotLayout, touchedRows: readonly number[], accessor: CellAccessor): Map<string, GroupNode> {
  const stale = new Set<GroupBucket>();
  const owners = ownersOf(tree);
  for (const row of touchedRows) for (let bucket = owners.get(row) ?? null; bucket && !stale.has(bucket); bucket = bucket.parent) stale.add(bucket);
  const replaced = new Map<string, GroupNode>();
  if (stale.size === 0) return replaced;
  const valueCount = pivot.values.length;
  const rankByText = new Map<string, number>();
  for (let rank = 0; rank * valueCount < pivot.columns.length; rank++) rankByText.set(groupKeyText(pivot.columns[rank * valueCount]!.path[0] ?? null), rank);
  const read = readerOf(accessor, pivot.columnId);
  const reducer = pivotReducer(accessor, pivot.values, pivot.columns.length, (row) => {
    const key = groupKeyOf(read(row));
    return rankByText.get(typeof key === "string" ? key : groupKeyText(key)) ?? -1;
  });
  for (const root of tree.roots) if (stale.has(root)) reducer.finish(root, reducer.fill(root, stale));
  for (const bucket of stale) replaced.set(bucket.node.id, bucket.node);
  return replaced;
}

const readerOf = (accessor: CellAccessor, columnId: string) => (accessor.getValue ? (row: number) => accessor.getValue!(row, columnId) : (row: number) => accessor.getText(row, columnId));

/** The reduction that {@link buildPivot} and {@link refreshPivotCells} share, so both sum in the same order. */
function pivotReducer(accessor: CellAccessor, values: readonly ServerAggregate[], width: number, rankOfRow: (row: number) => number) {
  const valueCount = values.length;
  const readers = values.map(({ columnId }) => readerOf(accessor, columnId));
  const reducers = values.map((value) => value.reducer);
  const hasAvg = reducers.includes("avg");

  const empty = (): Cells => {
    const cells = new Float64Array(width);
    for (let i = 0; i < width; i++) cells[i] = reducers[i % valueCount] === "count" ? 0 : NaN;
    return { cells, counted: hasAvg ? new Float64Array(width) : null };
  };

  const addValue = (into: Cells, slot: number, reducer: ServerAggregate["reducer"], v: unknown): void => {
    if (reducer === "count") {
      if (isCounted(v)) into.cells[slot]!++;
      return;
    }
    if (typeof v !== "number" || !Number.isFinite(v)) return;
    if (reducer === "avg") into.counted![slot]!++;
    into.cells[slot] = combine(reducer, into.cells[slot]!, v);
  };

  const merge = (into: Cells, from: Cells): void => {
    for (let slot = 0; slot < width; slot++) {
      const v = from.cells[slot]!;
      if (Number.isNaN(v)) continue;
      const reducer = reducers[slot % valueCount]!;
      if (reducer === "avg") into.counted![slot]! += from.counted![slot]!;
      into.cells[slot] = combine(reducer, into.cells[slot]!, v);
    }
  };

  const finish = (bucket: GroupBucket, own: Cells): void => {
    if (own.counted) for (let slot = 0; slot < width; slot++) if (reducers[slot % valueCount] === "avg" && own.counted[slot]! > 0) own.cells[slot]! /= own.counted[slot]!;
    bucket.node = { ...bucket.node, pivotCells: own.cells, ...(bucket.leaves ? { childCount: 0 } : null) };
  };

  // Sums and counts roll up before `finish` turns a node's sums into averages. Without `avg` a finished node equals its sums,
  // so a refresh merges a kept child's cells instead of reducing its rows again.
  const fill = (bucket: GroupBucket, stale: ReadonlySet<GroupBucket> | null): Cells => {
    const own = empty();
    if (bucket.leaves) {
      for (const row of bucket.leaves) {
        const k = rankOfRow(row);
        if (k < 0) continue;
        for (let a = 0; a < valueCount; a++) addValue(own, k * valueCount + a, reducers[a]!, readers[a]!(row));
      }
    } else {
      for (const child of bucket.groups!) {
        if (stale && !stale.has(child) && !hasAvg) {
          merge(own, { cells: child.node.pivotCells!, counted: null });
          continue;
        }
        const sub = fill(child, stale);
        merge(own, sub);
        if (!stale || stale.has(child)) finish(child, sub);
      }
    }
    return own;
  };
  return { fill, finish };
}

import { toSafeText } from "../cell-types/safe-text";
import type { ExpandedState, GroupKey, GroupPathSegment } from "../group-types";
import type { AnyColumnDef } from "./types";

export const GROUP_ID_PREFIX = "__group:";
export const MAX_GROUP_LEVELS = 4;
export const MAX_EXPANDED_IDS = 10_000;

export const COLLAPSED: ExpandedState = { mode: "collapsed", ids: [] };
export const EXPANDED: ExpandedState = { mode: "expanded", ids: [] };
export const NO_GROUPS: readonly string[] = [];

/** Whether `rowId` names a group row. */
export function isGroupRowId(rowId: string): boolean {
  return rowId.startsWith(GROUP_ID_PREFIX);
}

/** The text a key contributes to a group id; the empty group has none. */
export function groupKeyText(key: GroupKey): string {
  return key === null ? "" : toSafeText(key);
}

/** The id of the group at the end of `path`: one `column=key` segment per level, percent-encoded so a value cannot forge another id. */
export function groupIdOf(path: readonly GroupPathSegment[]): string {
  return GROUP_ID_PREFIX + path.map((s) => `${encodeURIComponent(s.columnId)}=${encodeURIComponent(groupKeyText(s.key))}`).join("/");
}

/** The stored value as a group key: empty values form the one empty group, other primitives keep their type, anything else keys by its text. */
export function groupKeyOf(value: unknown): GroupKey {
  if (value === null || value === undefined || value === "") return null;
  if (typeof value === "string" || typeof value === "boolean") return value;
  if (typeof value === "number" && Number.isFinite(value)) return value;
  return toSafeText(value);
}

/** The requested group columns that name a known, groupable column, once each, at most {@link MAX_GROUP_LEVELS}. Returns `requested` itself when nothing dropped. */
export function normalizeGroupBy(requested: readonly string[] | undefined, columns: readonly AnyColumnDef[]): readonly string[] {
  if (!requested || requested.length === 0) return NO_GROUPS;
  const groupable = new Set(columns.filter((c) => c.groupable !== false).map((c) => c.id));
  const kept: string[] = [];
  for (const id of requested) {
    if (typeof id === "string" && groupable.has(id) && !kept.includes(id) && kept.length < MAX_GROUP_LEVELS) kept.push(id);
  }
  if (kept.length === 0) return NO_GROUPS;
  return kept.length === requested.length && kept.every((id, i) => id === requested[i]) ? requested : kept;
}

export function sameGroupBy(a: readonly string[], b: readonly string[]): boolean {
  return a === b || (a.length === b.length && a.every((id, i) => id === b[i]));
}

/** An {@link ExpandedState} from untrusted input: a bad mode reads as collapsed, ids are unique strings, at most {@link MAX_EXPANDED_IDS}. `onCut` runs when ids were cut. */
export function normalizeExpanded(value: unknown, onCut?: () => void): ExpandedState {
  if (value === null || typeof value !== "object") return COLLAPSED;
  const { mode, ids } = value as { mode?: unknown; ids?: unknown };
  const safeMode = mode === "expanded" ? "expanded" : "collapsed";
  if (!Array.isArray(ids) || ids.length === 0) return safeMode === "expanded" ? EXPANDED : COLLAPSED;
  const unique = new Set<string>();
  for (const id of ids) {
    if (typeof id !== "string") continue;
    if (unique.size >= MAX_EXPANDED_IDS && !unique.has(id)) {
      onCut?.();
      break;
    }
    unique.add(id);
  }
  return { mode: safeMode, ids: [...unique] };
}

export function sameExpanded(a: ExpandedState, b: ExpandedState): boolean {
  if (a === b) return true;
  if (a.mode !== b.mode || a.ids.length !== b.ids.length) return false;
  const ids = new Set(a.ids);
  return b.ids.every((id) => ids.has(id));
}

/** Whether the group `id` is open under `expanded`. For many lookups use {@link expandedTest}. */
export function isExpanded(expanded: ExpandedState, id: string): boolean {
  return expanded.ids.includes(id) === (expanded.mode === "collapsed");
}

/** A membership test for one flatten: the ids become a set once. */
export function expandedTest(expanded: ExpandedState): (id: string) => boolean {
  if (expanded.ids.length === 0) return expanded.mode === "expanded" ? () => true : () => false;
  const ids = new Set(expanded.ids);
  return expanded.mode === "expanded" ? (id) => !ids.has(id) : (id) => ids.has(id);
}

/** `expanded` with the group `id` flipped. */
export function toggleExpanded(expanded: ExpandedState, id: string): ExpandedState {
  if (expanded.ids.length >= MAX_EXPANDED_IDS && !expanded.ids.includes(id)) return expanded;
  const ids = expanded.ids.includes(id) ? expanded.ids.filter((x) => x !== id) : [...expanded.ids, id];
  return { mode: expanded.mode, ids };
}

import type { StoreApi } from "zustand/vanilla";
import { toSafeText } from "../cell-types/safe-text";
import type { CellType, FilterNode, SortSpec } from "../types";
import type { GroupKey, ExpandedState, ServerGroupLayout, ServerPivotLayout } from "../group-types";
import type { ServerAggregate } from "../server-spec";
import { buildViewIndex, type CellAccessor } from "../sort-filter/build-view-index";
import { buildGroupView, flattenGroupTree, type GroupAggregateSpec, type GroupBuildInput, type GroupedView } from "../sort-filter/build-group-view";
import { buildPivot, MAX_PIVOT_CELLS } from "../sort-filter/build-pivot";
import { createWarnOnce } from "../is-dev";
import type { AnyColumnDef, DataGridStoreState } from "./types";
import { buildServerGroupView } from "./server-group-view";
import { groupLayoutOfView } from "./view-rows";

/** What a grouped rebuild reads: the group columns, which groups are open, and where to warn. */
export type GroupingInput = {
  groupBy: readonly string[];
  expanded: ExpandedState;
  warn?: (key: string, message: string) => void;
  /** Set under `groupMode="server"`: the view comes from the layout and no row is bucketed. */
  server?: { layout: ServerGroupLayout | null };
  /** Set for a client pivot: the pivot column, its values, and the held set of the last build, whose `columns` a build with equal ids keeps. */
  pivot?: { columnId: string; values: readonly ServerAggregate[]; previous: ServerPivotLayout | undefined };
};

type GroupingState = Pick<DataGridStoreState, "groupBy" | "expanded" | "totalRowCount" | "sortMode" | "dataWrite" | "groupMode" | "serverGroupLayout" | "pivotColumnIds" | "columns" | "groupLayout">;

const warners = new WeakMap<object, (key: string, message: string) => void>();

export function warnGroupOnce(owner: object, key: string, message: string): void {
  warnerOf(owner)(key, message);
}

function warnerOf(owner: object): (key: string, message: string) => void {
  let warn = warners.get(owner);
  if (!warn) {
    warn = createWarnOnce();
    warners.set(owner, warn);
  }
  return warn;
}

/** The mode of a grid: `"server"` when the prop says so, else when a server layout is given. */
export function groupModeOf(props: { groupMode?: "client" | "server"; groupLayout?: unknown }): "client" | "server" {
  return props.groupMode ?? (props.groupLayout === undefined ? "client" : "server");
}

/** The grouping a rebuild applies; `null` for a grid that does not group, and for a result the client cannot group (a window of a larger result, rows sorted by the server). */
export function groupingOf(s: GroupingState): GroupingInput | null {
  if (s.groupBy.length === 0) {
    if (s.pivotColumnIds.length > 0) warnerOf(s.dataWrite)("pivot without groupBy", "pivot needs groupBy: the grid ignores the pivot until groupBy names a column");
    return null;
  }
  const warn = warnerOf(s.dataWrite);
  if (s.groupMode === "server") return { groupBy: s.groupBy, expanded: s.expanded, warn, server: { layout: s.serverGroupLayout } };
  if (s.totalRowCount !== undefined || s.sortMode === "server") {
    warn("ungrouped window", "groupBy needs every row on the client: with totalRowCount or sortMode=\"server\" the grid shows the rows ungrouped");
    return null;
  }
  const pivot = clientPivotOf(s, warn);
  return pivot ? { groupBy: s.groupBy, expanded: s.expanded, warn, pivot } : { groupBy: s.groupBy, expanded: s.expanded, warn };
}

function clientPivotOf(s: GroupingState, warn: (key: string, message: string) => void): GroupingInput["pivot"] {
  const columnId = s.pivotColumnIds[0];
  if (columnId === undefined) return undefined;
  const column = s.columns.find((c) => c.id === columnId);
  if (!column || column.groupable === false || s.groupBy.includes(columnId)) {
    warn("pivot column", `pivot names the column ${JSON.stringify(columnId.slice(0, 64))}, which is unknown, not groupable, or a groupBy column, so the grid ignores the pivot`);
    return undefined;
  }
  return { columnId, values: pivotValues(s.columns), previous: s.groupLayout?.pivot };
}

/** The values of a client pivot: one per column with a built-in `aggregate`, in column order. A function reducer has no pivot cell. */
export function pivotValues(columns: readonly AnyColumnDef[]): ServerAggregate[] {
  const values: ServerAggregate[] = [];
  for (const column of columns) if (typeof column.aggregate === "string") values.push({ columnId: column.id, reducer: column.aggregate });
  return values;
}

/** The sorts that order rows inside groups: a sort on a group column orders that level instead. */
export function sortsBesideGroups(sorts: readonly SortSpec[], groupBy: readonly string[]): SortSpec[] {
  return sorts.filter((sort) => !groupBy.includes(sort.columnId));
}

export function aggregateSpecs(columns: readonly AnyColumnDef[]): GroupAggregateSpec[] {
  const specs: GroupAggregateSpec[] = [];
  for (const column of columns) if (column.aggregate !== undefined) specs.push({ columnId: column.id, reducer: column.aggregate });
  return specs;
}

function labelReader(columns: readonly AnyColumnDef[], cellTypes: Record<string, CellType> | undefined, accessor: CellAccessor): GroupBuildInput["labelOf"] {
  const byId = new Map(columns.map((column) => [column.id, column] as const));
  return (columnId: string, key: GroupKey, rowIndex: number) => {
    const column = byId.get(columnId);
    const cellType = column?.type ? cellTypes?.[column.type] : undefined;
    const format = cellType?.toDisplayText ?? cellType?.toText;
    if (!format) return toSafeText(key);
    try {
      return toSafeText(format(accessor.getValue?.(rowIndex, columnId), column?.options));
    } catch {
      return toSafeText(key);
    }
  };
}

/** The inputs of {@link buildGroupView} for the reducers and the reader of a grid's columns. */
export function groupBuildInput(
  data: readonly unknown[],
  columns: readonly AnyColumnDef[],
  accessor: CellAccessor,
  cellTypes: Record<string, CellType> | undefined,
  grouping: GroupingInput,
  sortState: readonly SortSpec[],
  leaves: readonly number[],
): GroupBuildInput {
  const directions = new Map<string, "asc" | "desc">();
  for (const sort of sortState) if ((grouping.groupBy.includes(sort.columnId) || sort.columnId === grouping.pivot?.columnId) && !directions.has(sort.columnId)) directions.set(sort.columnId, sort.direction);
  return {
    leaves,
    accessor,
    groupBy: grouping.groupBy,
    directions,
    aggregates: aggregateSpecs(columns),
    rowAt: (rowIndex) => data[rowIndex],
    labelOf: labelReader(columns, cellTypes, accessor),
    onReducerError: (columnId, error) => grouping.warn?.(`reducer ${columnId}`, `the aggregate of column "${columnId}" threw, so its groups show null: ${toSafeText(error)}`),
  };
}

/**
 * The grouped view of `data`: the leaf order of the filters and the sorts beside the group columns, bucketed by `grouping`.
 * `null` when a row is unloaded (a lazy source), which leaves the grid ungrouped.
 */
export function computeGroupedView(args: {
  data: readonly unknown[];
  columns: readonly AnyColumnDef[];
  accessor: CellAccessor;
  sortState: readonly SortSpec[];
  filterState: readonly FilterNode[];
  cellTypes?: Record<string, CellType>;
  grouping: GroupingInput;
}): GroupedView | null {
  const { data, columns, accessor, sortState, filterState, cellTypes, grouping } = args;
  if (grouping.server) return serverGroupedView(data.length, grouping);
  if (grouping.pivot) return pivotGroupedView(args, grouping.pivot);
  const leaves = buildViewIndex(data.length, accessor, { sorts: sortsBesideGroups(sortState, grouping.groupBy), filters: filterState });
  const grouped = buildGroupView(groupBuildInput(data, columns, accessor, cellTypes, grouping, sortState, leaves), grouping.expanded);
  if (!grouped) grouping.warn?.("ungrouped holes", "groupBy needs loaded rows: while rows are unloaded (a lazy source) the grid shows them ungrouped");
  return grouped;
}

// The rows of a pivot never show, so their order is the data order: no sort reorders the sums.
function pivotGroupedView(args: Parameters<typeof computeGroupedView>[0], pivot: NonNullable<GroupingInput["pivot"]>): GroupedView | null {
  const { data, columns, accessor, sortState, filterState, cellTypes, grouping } = args;
  const leaves = buildViewIndex(data.length, accessor, { sorts: [], filters: filterState });
  const input = groupBuildInput(data, columns, accessor, cellTypes, grouping, sortState, leaves);
  const built = buildPivot({ ...input, aggregates: [], pivotColumnId: pivot.columnId, values: pivot.values, previous: pivot.previous });
  if (!built) {
    grouping.warn?.("ungrouped holes", "groupBy needs loaded rows: while rows are unloaded (a lazy source) the grid shows them ungrouped");
    return null;
  }
  if ("tooLarge" in built) {
    grouping.warn?.("pivot too large", `the pivot holds more than ${MAX_PIVOT_CELLS.toLocaleString("en-US")} cells (group rows times generated columns), so the grid shows the rows ungrouped; filter the rows, or pivot or group by a column with fewer keys`);
    return null;
  }
  return flattenGroupTree(built.tree, grouping.expanded);
}

function serverGroupedView(dataLength: number, grouping: GroupingInput): GroupedView | null {
  const layout = grouping.server?.layout;
  if (!layout) {
    grouping.warn?.("server layout", 'groupMode="server" needs a groupLayout prop: the grid shows the rows ungrouped. useDataGridServerRows passes it through gridProps');
    return null;
  }
  const result = buildServerGroupView(layout, dataLength, grouping.groupBy);
  if ("invalid" in result) grouping.warn?.("server layout invalid", `the groupLayout prop is invalid (${result.invalid}), so the grid shows the rows ungrouped`);
  return "view" in result ? result.view : null;
}

/** The held set the pivot view shows: the server layout's under `groupMode="server"`, else the client build's. */
export function heldSetOf(s: Pick<DataGridStoreState, "groupMode" | "serverGroupLayout" | "groupLayout">): ServerPivotLayout | undefined {
  return s.groupMode === "server" ? s.serverGroupLayout?.pivot : s.groupLayout?.pivot;
}

/** A `setState` that fills `groupLayout` from the view a patch writes, so `viewIndex` and the group rows land in one write. */
export function withGroupLayout(
  set: StoreApi<DataGridStoreState>["setState"],
  derive: (s: DataGridStoreState, patch: Partial<DataGridStoreState>) => Partial<DataGridStoreState> = (_, patch) => patch,
): StoreApi<DataGridStoreState>["setState"] {
  return ((partial: unknown, replace?: boolean) => {
    if (replace) return set(partial as DataGridStoreState, true);
    return set((s) => {
      const patch = (typeof partial === "function" ? (partial as (state: DataGridStoreState) => Partial<DataGridStoreState>)(s) : partial) as Partial<DataGridStoreState>;
      if (patch === s) return s;
      return derive(s, patch.viewIndex !== undefined && patch.viewIndex !== s.viewIndex && !("groupLayout" in patch) ? { ...patch, groupLayout: groupLayoutOfView(patch.viewIndex) } : patch);
    });
  }) as StoreApi<DataGridStoreState>["setState"];
}

import { toSafeText } from "../cell-types/safe-text";
import type { GroupKey, GroupLayout, GroupNode, ServerGroupLayout } from "../group-types";
import type { GroupedView } from "../sort-filter/build-group-view";
import { groupIdOf } from "./group-state";

const MAX_KEY_LENGTH = 1024;

/** `stale` marks a layout built for other group columns; it is a transient state, not a mistake. */
export type ServerGroupViewResult = { view: GroupedView } | { stale: true } | { invalid: string };

const isCount = (value: unknown): value is number => typeof value === "number" && Number.isSafeInteger(value) && value >= 0;

const isKey = (key: unknown): key is GroupKey =>
  key === null || typeof key === "boolean" || (typeof key === "string" && key.length <= MAX_KEY_LENGTH) || (typeof key === "number" && Number.isFinite(key));

function readAggregates(raw: unknown): Readonly<Record<string, unknown>> {
  const out = Object.create(null) as Record<string, unknown>;
  if (typeof raw !== "object" || raw === null) return out;
  for (const id of Object.keys(raw).filter((key) => key !== "__proto__")) {
    const value = (raw as Record<string, unknown>)[id];
    if (typeof value === "number") out[id] = Number.isFinite(value) ? value : null;
    else out[id] = typeof value === "string" && value.length <= MAX_KEY_LENGTH ? toSafeText(value) : null;
  }
  return out;
}

const cache = new WeakMap<ServerGroupLayout, { dataLength: number; groupBy: readonly string[]; result: ServerGroupViewResult }>();

/**
 * Lays the view out from a server layout: `data` holds one entry per view row, so a view row is its own data index except at
 * the group rows, which get the entries below 0. The core derives every group id from the validated paths and never trusts an id.
 */
export function buildServerGroupView(layout: ServerGroupLayout, dataLength: number, groupBy: readonly string[]): ServerGroupViewResult {
  const cached = cache.get(layout);
  if (cached && cached.dataLength === dataLength && cached.groupBy === groupBy) return cached.result;
  const result = lay(layout, dataLength, groupBy);
  cache.set(layout, { dataLength, groupBy, result });
  return result;
}

function lay(layout: ServerGroupLayout, dataLength: number, groupBy: readonly string[]): ServerGroupViewResult {
  if (!layout.rows || !isCount(layout.leafCount)) return { invalid: "the layout needs a rows array and a leafCount" };
  const entries = Array.from({ length: dataLength }, (_, i) => i);
  const nodes: GroupNode[] = [];
  const seen = new Set<string>();
  let previousRow = -1;
  for (const slot of layout.rows) {
    const { viewRow, path } = slot;
    if (!path || path.length === 0 || path.length > groupBy.length) return { invalid: "a group path is empty or longer than groupBy" };
    if (path.some((segment, level) => segment?.columnId !== groupBy[level])) return { stale: true };
    if (!path.every((segment) => isKey(segment.key))) return { invalid: `a group key must be a string of at most ${MAX_KEY_LENGTH} characters, a finite number, a boolean, or null` };
    if (!Number.isInteger(viewRow) || viewRow <= previousRow || viewRow >= dataLength) return { invalid: "viewRow must be an increasing index into data" };
    if (!isCount(slot.count) || !isCount(slot.childCount)) return { invalid: "count and childCount must be non-negative integers" };
    const id = groupIdOf(path);
    if (seen.has(id)) return { invalid: `the group ${id} appears twice` };
    seen.add(id);
    previousRow = viewRow;
    entries[viewRow] = -(nodes.length + 1);
    nodes.push(nodeOf(slot, id));
  }
  const groupLayout: GroupLayout = { rows: nodes, leafCount: layout.leafCount };
  return { view: { viewIndex: entries, layout: groupLayout } };
}

type Slot = ServerGroupLayout["rows"][number];

// A slot passed again keeps its node, so its group row skips the render.
const nodeOfSlot = new WeakMap<Slot, GroupNode>();

function nodeOf(slot: Slot, id: string): GroupNode {
  const cached = nodeOfSlot.get(slot);
  if (cached?.id === id) return cached;
  const last = slot.path[slot.path.length - 1]!;
  const node: GroupNode = {
    id,
    depth: slot.path.length - 1,
    columnId: last.columnId,
    key: last.key,
    label: typeof slot.label === "string" ? slot.label.slice(0, MAX_KEY_LENGTH) : last.key === null ? "" : toSafeText(last.key),
    count: slot.count,
    childCount: slot.childCount,
    aggregates: readAggregates(slot.aggregates),
    ...(slot.pivotCells instanceof Float64Array ? { pivotCells: slot.pivotCells } : null),
    ...(slot.status === "loading" || slot.status === "failed" ? { status: slot.status } : null),
  };
  nodeOfSlot.set(slot, node);
  return node;
}

import type { ExpandedState, GroupLayout, GroupNode } from "../group-types";
import type { AnyColumnDef } from "./types";
import { expandedTest } from "./group-state";
import { dataIndexAt, groupIndexAt } from "./view-rows";

/** Where a view row sits in the tree of a grouped view: `level` and `posInSet` count from 1, like `aria-level` and `aria-posinset`. */
export type GroupPosition = { level: number; posInSet: number; setSize: number };

/** What a group row renders from. `expandable` is false for an innermost pivot row, which never opens and reports `expanded: false`. */
export type GroupRowMeta = GroupPosition & { node: GroupNode; expanded: boolean; expandable: boolean };

/** Whether a group row can open: always without pivot, and only above the innermost `groupBy` level under pivot. */
export function groupRowExpandable(s: { pivot?: object | null; groupBy?: readonly string[] }, node: GroupNode): boolean {
  return !s.pivot || node.depth < (s.groupBy?.length ?? 0) - 1;
}

/** How many visible columns the label covers: up to the first `aggregate` column, at least one. */
export function groupLabelSpan(columns: readonly Pick<AnyColumnDef, "aggregate">[]): number {
  const firstAggregate = columns.findIndex((column) => column.aggregate !== undefined);
  return Math.max(1, firstAggregate === -1 ? columns.length : firstAggregate);
}

type StepState = { viewIndex: ArrayLike<number>; visibleColumns: readonly Pick<AnyColumnDef, "aggregate">[] };

/** The label span of the group row at `viewRow`; 0 for any other row. */
function labelSpanAt(s: StepState, viewRow: number): number {
  return groupIndexAt(s.viewIndex, viewRow) === undefined ? 0 : Math.min(groupLabelSpan(s.visibleColumns), s.visibleColumns.length);
}

/** The column a horizontal step of `dx` from `col` lands on: the label of a group row is one stop over the columns `[0, span)`. */
export function stepColumn(s: StepState, viewRow: number, col: number, dx: number): number {
  const maxCol = Math.max(0, s.visibleColumns.length - 1);
  const next = Math.max(0, Math.min(maxCol, col + dx));
  const span = dx === 0 ? 0 : labelSpanAt(s, viewRow);
  if (col < span) return dx > 0 && span <= maxCol ? span : col;
  return next < span ? 0 : next;
}

/** {@link stepColumn} for a range edge: a step that stays inside the label reaches the label's far end, so a range edge always moves. */
export function stepRangeEdge(s: StepState, viewRow: number, col: number, dx: number): number {
  const step = stepColumn(s, viewRow, col, dx);
  if (step !== col || dx === 0) return step;
  return dx < 0 ? 0 : Math.max(0, s.visibleColumns.length - 1);
}

/** Per view row: the group index of its parent (-1 at the top level) and its position among the parent's children. */
type GroupIndex = { expanded: ExpandedState | undefined; parent: Int32Array; posInSet: Int32Array; topLevel: number };
type PositionState = { viewIndex: ArrayLike<number>; groupLayout: GroupLayout | null; expanded?: ExpandedState; pivot?: object | null; groupBy?: readonly string[] };

const indexByView = new WeakMap<object, GroupIndex>();
const openByExpanded = new WeakMap<ExpandedState, (id: string) => boolean>();

function openTest(expanded: ExpandedState): (id: string) => boolean {
  let isOpen = openByExpanded.get(expanded);
  if (!isOpen) {
    isOpen = expandedTest(expanded);
    openByExpanded.set(expanded, isOpen);
  }
  return isOpen;
}

// A server layout is sparse: an unloaded row is no group row, so an open group's children are its next `childCount` view rows.
function buildIndex(s: PositionState, layout: GroupLayout): GroupIndex {
  const view = s.viewIndex;
  const rows = layout.rows;
  const isOpen = s.expanded ? openTest(s.expanded) : () => false;
  const parent = new Int32Array(view.length);
  const posInSet = new Int32Array(view.length);
  const frames: { group: number; left: number; count: number }[] = [];
  let topLevel = 0;
  for (let viewRow = 0; viewRow < view.length; viewRow++) {
    const entry = view[viewRow]!; // viewRow < length by loop condition
    const node: GroupNode | undefined = entry < 0 ? rows[-entry - 1] : undefined;
    while (frames.length > 0 && (frames.at(-1)!.left === 0 || (node !== undefined && node.depth < frames.length))) frames.pop();
    const frame = frames.at(-1);
    if (frame) {
      frame.left--;
      parent[viewRow] = frame.group;
      posInSet[viewRow] = ++frame.count;
    } else {
      parent[viewRow] = -1;
      posInSet[viewRow] = ++topLevel;
    }
    const next = view[viewRow + 1];
    const deeper = next !== undefined && next < 0 && node !== undefined && rows[-next - 1]!.depth > node.depth;
    if (node && node.childCount > 0 && (deeper || (isOpen(node.id) && groupRowExpandable(s, node)))) frames.push({ group: -entry - 1, left: node.childCount, count: 0 });
  }
  return { expanded: s.expanded, parent, posInSet, topLevel };
}

function indexOfView(s: PositionState, layout: GroupLayout): GroupIndex {
  let index = indexByView.get(s.viewIndex);
  if (!index || index.expanded !== s.expanded) {
    index = buildIndex(s, layout);
    indexByView.set(s.viewIndex, index);
  }
  return index;
}

/** Level, position, and set size of a view row of a grouped view; `null` when the grid does not group or the row is missing. */
export function groupPositionAt(s: PositionState, viewRow: number): GroupPosition | null {
  const layout = s.groupLayout;
  if (!layout) return null;
  const at = groupIndexAt(s.viewIndex, viewRow);
  if (at === undefined && dataIndexAt(s, viewRow) === undefined) return null;
  const index = indexOfView(s, layout);
  const parent = index.parent[viewRow]!;
  const owner = parent < 0 ? undefined : layout.rows[parent]!;
  const level = at !== undefined ? layout.rows[at]!.depth + 1 : owner ? owner.depth + 2 : 1;
  return { level, posInSet: index.posInSet[viewRow]!, setSize: owner ? owner.childCount : index.topLevel };
}

/** The group row at `viewRow` with its position and open state; `null` for a data row, a hole, or a grid that does not group. */
export function groupRowMetaAt(
  s: { viewIndex: ArrayLike<number>; groupLayout: GroupLayout | null; expanded: ExpandedState; pivot?: object | null; groupBy?: readonly string[] },
  viewRow: number,
): GroupRowMeta | null {
  const at = groupIndexAt(s.viewIndex, viewRow);
  if (!s.groupLayout || at === undefined) return null;
  const node = s.groupLayout.rows[at];
  const position = groupPositionAt(s, viewRow);
  if (!node || !position) return null;
  const expandable = groupRowExpandable(s, node);
  return { ...position, node, expanded: expandable && openTest(s.expanded)(node.id), expandable };
}

import { displayText, exportText } from "../cell-types/display-text";
import { toSafeText } from "../cell-types/safe-text";
import { buildColumnGroupModel, type ColumnGroupModel } from "../columns/column-groups";
import type { CellType } from "../types";
import type { GroupLayout, GroupNode, ServerGroupLayout, ServerPivotLayout } from "../group-types";
import { isDev } from "../is-dev";
import type { DataGridPivotLabels } from "../labels";
import { buildPivotColumns, type PivotColumnDef } from "../pivot-columns";
import type { AnyColumnDef } from "./types";
import { groupIndexAt, groupLayoutOfView } from "./view-rows";

/** The generated columns of the held set and their header groups. Present only under pivot. */
export type PivotView = {
  readonly columnId: string;
  readonly columns: readonly PivotColumnDef<unknown>[];
  readonly groupModel: ColumnGroupModel | null;
  readonly omitted: number;
};

const GENERATED_PREFIXES = ["__pivot:", "__pivotgroup:"] as const;

const hasGeneratedPrefix = (id: string) => GENERATED_PREFIXES.some((prefix) => id.startsWith(prefix));

// Keyed on the held columns, so a landing that changes only `omitted` keeps the generated column defs.
const views = new WeakMap<ServerPivotLayout["columns"], { valueColumns: readonly (AnyColumnDef | undefined)[]; labels: DataGridPivotLabels; view: PivotView }>();

/**
 * The pivot view of a server layout, or `null` without a held set. Its `columns` keep one identity per held columns, value
 * column defs, and labels; a new `omitted` makes a new view over the same `columns`.
 * Under pivot, a consumer column or group id with a generated prefix drops, and `onPrefixClash` reports it.
 */
export function pivotViewOf(
  layout: Pick<ServerGroupLayout, "pivot"> | null,
  columns: readonly AnyColumnDef[],
  consumerGroupIds: Iterable<string>,
  labels: DataGridPivotLabels,
  onPrefixClash: (ids: readonly string[]) => void,
): PivotView | null {
  const held = layout?.pivot;
  if (!held) return null;
  const valueColumns = held.values.map((value) => columns.find((column) => column.id === value.columnId));
  const cached = views.get(held.columns);
  if (cached && cached.labels === labels && cached.valueColumns.every((column, i) => column === valueColumns[i])) {
    const omitted = Math.max(0, held.omitted) + Math.max(0, held.columns.length - cached.view.columns.length);
    if (cached.view.omitted !== omitted) cached.view = { ...cached.view, omitted };
    return cached.view;
  }
  const clashes = [...columns.map((column) => column.id), ...consumerGroupIds].filter(hasGeneratedPrefix);
  if (clashes.length > 0) onPrefixClash(clashes);
  const sources = clashes.length > 0 ? columns.filter((column) => !hasGeneratedPrefix(column.id)) : columns;
  const built = buildPivotColumns(held, sources, labels);
  const view: PivotView = {
    columnId: held.columnId,
    columns: built.columns as PivotColumnDef<unknown>[],
    groupModel: buildColumnGroupModel(built.groups, built.columns.map((column) => column.id)),
    omitted: Math.max(0, held.omitted) + Math.max(0, held.columns.length - built.columns.length),
  };
  views.set(held.columns, { valueColumns, labels, view });
  return view;
}

const visibleCache = new WeakMap<PivotView["columns"], { groupColumn: AnyColumnDef | undefined; visible: readonly AnyColumnDef[] }>();

/** Under pivot the visible columns are the `groupBy` column, first and never end-pinned, and the generated columns. */
export function pivotVisibleColumns(view: PivotView, columns: readonly AnyColumnDef[], groupBy: readonly string[]): readonly AnyColumnDef[] {
  const groupColumn = columns.find((column) => column.id === groupBy[0] && !hasGeneratedPrefix(column.id));
  const cached = visibleCache.get(view.columns);
  if (cached && cached.groupColumn === groupColumn) return cached.visible;
  const lead = groupColumn === undefined ? [] : [groupColumn.pin === "end" ? { ...groupColumn, pin: undefined } : groupColumn];
  const visible = [...lead, ...view.columns];
  visibleCache.set(view.columns, { groupColumn, visible });
  return visible;
}

/** Whether `column` is a generated column. */
export function isPivotColumn(column: AnyColumnDef | undefined): column is PivotColumnDef<unknown> {
  return column !== undefined && typeof (column as Partial<PivotColumnDef<unknown>>).pivotIndex === "number";
}

/**
 * The pivot cell at a view row: a finite number, `null` when no value counted, the value is not finite, or the row holds no
 * cells, and `undefined` when `column` is not a generated column.
 */
export function pivotCellAt(s: { readonly viewIndex: ArrayLike<number>; readonly groupLayout: GroupLayout | null }, viewRow: number, column: AnyColumnDef | undefined): number | null | undefined {
  if (!isPivotColumn(column)) return undefined;
  const groupIndex = groupIndexAt(s.viewIndex, viewRow);
  return pivotCellOf(groupIndex === undefined ? undefined : s.groupLayout?.rows[groupIndex], column);
}

/** A group row's pivot cell: a finite number, or `null` when no value counted, the value is not finite, or the row holds no cells. */
export function pivotCellOf(node: GroupNode | undefined, column: PivotColumnDef<unknown>): number | null {
  const value = node?.pivotCells?.[column.pivotIndex];
  return value === undefined || !Number.isFinite(value) ? null : value;
}

const DEFAULT_AGGREGATE_FORMAT: Intl.NumberFormatOptions = { maximumFractionDigits: 2 };

const aggregateOptions = new WeakMap<AnyColumnDef, { locale: string; options: unknown }>();

/** An average has no natural precision, so a number column without its own `format` or `decimals` shows at most two fraction digits. */
function aggregateOptionsOf(column: AnyColumnDef, locale: string): unknown {
  const cached = aggregateOptions.get(column);
  if (cached?.locale === locale) return cached.options;
  const own = (column.options ?? {}) as { format?: unknown; decimals?: unknown; locale?: string };
  const options = own.format === undefined && own.decimals === undefined ? { ...own, format: DEFAULT_AGGREGATE_FORMAT, locale: own.locale ?? locale } : column.options;
  aggregateOptions.set(column, { locale, options });
  return options;
}

/** The display text of a group aggregate or a pivot cell: empty for no value, else the column's cell type text. */
export function aggregateText(column: AnyColumnDef, value: unknown, cellTypes: Readonly<Record<string, CellType | undefined>>, locale: string): string {
  if (value === null || value === undefined) return "";
  const cellType = cellTypes[column.type ?? "text"];
  try {
    const options = column.type === "number" && (typeof value === "number" || typeof value === "string") ? aggregateOptionsOf(column, locale) : column.options;
    return toSafeText(cellType ? displayText(cellType as Parameters<typeof displayText>[0], value, options) : value);
  } catch {
    return toSafeText(value);
  }
}

type PivotTextState = { readonly viewIndex: ArrayLike<number>; readonly groupLayout: GroupLayout | null; readonly cellTypes: Readonly<Record<string, CellType | undefined>>; readonly locale: string };

/**
 * The text of a pivot row in `column`, which copy, export, print, find, and autosize read: for a generated column the shown text
 * (`"display"`, the default) or the cell type's `toText` (`"export"`), empty for no value; the row's own key text in the first
 * `groupBy` column at every depth; `undefined` off a pivot row.
 */
export function pivotCellText(s: PivotTextState & { readonly pivot: PivotView | null; readonly groupBy?: readonly string[] }, viewRow: number, column: AnyColumnDef | undefined, text: "display" | "export" = "display"): string | undefined {
  if (s.pivot === null || column === undefined) return undefined;
  const groupIndex = groupIndexAt(s.viewIndex, viewRow);
  const node = groupIndex === undefined ? undefined : s.groupLayout?.rows[groupIndex];
  if (node === undefined) return undefined;
  if (isPivotColumn(column)) {
    const value = pivotCellOf(node, column);
    if (text === "display") return aggregateText(column, value, s.cellTypes, s.locale);
    const cellType = s.cellTypes[column.type ?? "text"];
    return value === null ? "" : cellType ? exportText(cellType as Parameters<typeof exportText>[0], value, column.options) : toSafeText(value);
  }
  return column.id === (s.groupBy?.[0] ?? node.columnId) ? node.label : "";
}

/** The quick-search text of the pivot rows of `view`: the pivot cells, the row's key text in the `groupBy` column, `undefined` elsewhere. */
export function pivotTextReader(view: readonly number[], visibleColumns: readonly AnyColumnDef[], cellTypes: Readonly<Record<string, CellType | undefined>>, locale: string): (viewRow: number, columnId: string) => string | undefined {
  const pivotColumns = new Map(visibleColumns.filter(isPivotColumn).map((column) => [column.id, column] as const));
  if (pivotColumns.size === 0) return () => undefined;
  // Under pivot the only visible column that is not generated is the `groupBy` column.
  const keyColumnId = visibleColumns.find((column) => !isPivotColumn(column))?.id;
  const rows = groupLayoutOfView(view)?.rows;
  return (viewRow, columnId) => {
    const column = pivotColumns.get(columnId);
    if (column === undefined && columnId !== keyColumnId) return undefined;
    const groupIndex = groupIndexAt(view, viewRow);
    const node = groupIndex === undefined ? undefined : rows?.[groupIndex];
    if (column === undefined) return node?.label;
    return aggregateText(column, pivotCellOf(node, column), cellTypes, locale);
  };
}

/** The widths of the generated columns of `view` in `widths`, for a layout write that drops unknown ids. */
export function pivotWidthsOf(widths: Readonly<Record<string, number>>, view: PivotView | null): Record<string, number> {
  const out: Record<string, number> = {};
  if (!view) return out;
  for (const column of view.columns) {
    const width = widths[column.id];
    if (width !== undefined) out[column.id] = width;
  }
  return out;
}

/** `widths` without the generated ids that `columns` does not hold: the layout snapshot never names a generated column. */
export function withoutGeneratedWidths(widths: Record<string, number>, columns: readonly AnyColumnDef[]): Record<string, number> {
  const generated = Object.keys(widths).filter(hasGeneratedPrefix);
  if (generated.length === 0) return widths;
  const known = new Set(columns.map((column) => column.id));
  const out = { ...widths };
  for (const id of generated) if (!known.has(id)) delete out[id];
  return out;
}

/** A reporter for {@link pivotViewOf} that logs one development error per grid. */
export function createPrefixClashReporter(): (ids: readonly string[]) => void {
  let reported = false;
  return (ids) => {
    if (reported || !isDev()) return;
    reported = true;
    console.error(`[data-grid] under pivot, the ids ${ids.slice(0, 5).map((id) => `"${id}"`).join(", ")} start with "__pivot:" or "__pivotgroup:", which generated columns own, so the grid drops them; rename them`);
  };
}

import type { GroupKey, ServerPivotLayout } from "./group-types";
import type { ServerAggregate } from "./server-spec";
import { groupKeyText } from "./store/group-state";
import type { ColumnDef, ColumnGroupDef, SortSpec } from "./types";

/** Most generated columns a pivot grid holds. */
export const MAX_PIVOT_COLUMNS = 200;

const encode = (text: string): string => {
  try {
    return encodeURIComponent(text);
  } catch {
    throw new TypeError(`the pivot text ${JSON.stringify(text.slice(0, 40))} is not well-formed`);
  }
};

const keySegment = (pivotColumnId: string, key: GroupKey) => `${encode(pivotColumnId)}=${encode(groupKeyText(key))}`;

/** The generated column id of one key and one value. Throws a `TypeError` when a text holds a lone surrogate. */
export function pivotColumnId(pivotColumnId: string, key: GroupKey, value: ServerAggregate): string {
  return `__pivot:${keySegment(pivotColumnId, key)}|${encode(value.columnId)}=${value.reducer}`;
}

/** The header group id of one key. */
export function pivotGroupId(pivotColumnId: string, key: GroupKey): string {
  return `__pivotgroup:${keySegment(pivotColumnId, key)}`;
}

/** The sorts of a pivot request: only the `groupBy` and pivot column entries. The other entries stay in `sortState` for when pivot turns off. */
export function pivotSorts(sorts: readonly SortSpec[], groupBy: readonly string[], pivotColumnIds: readonly string[]): readonly SortSpec[] {
  const kept = sorts.filter((sort) => groupBy.includes(sort.columnId) || pivotColumnIds.includes(sort.columnId));
  return kept.length === sorts.length ? sorts : kept;
}

/** A generated column: `pivotIndex` indexes the held columns and the slot's `pivotCells`; `pivotLabel` is its full accessible name. */
export type PivotColumnDef<TData> = ColumnDef<TData> & { readonly pivotIndex: number; readonly pivotLabel: string };

export type PivotHeaderLabels = {
  /** Header of the empty key. */
  empty: string;
  /** Header of one value, such as "Sum of Amount". */
  value: (reducer: ServerAggregate["reducer"], column: string) => string;
  /** Full name of one generated column, such as "2025, Sum of Amount". */
  columnName: (key: string, value: string) => string;
};

const headerTextOf = <TData>(column: ColumnDef<TData> | undefined, id: string) => column?.headerText ?? (typeof column?.header === "string" ? column.header : id);

/**
 * The generated columns of a held set, in held order, at most {@link MAX_PIVOT_COLUMNS}. Pure: equal inputs give equal output,
 * so a caller memoizes it on the held set. With 2 or more values, `groups` holds one `__pivotgroup:` header group per key.
 */
export function buildPivotColumns<TData>(pivot: ServerPivotLayout, sourceColumns: readonly ColumnDef<TData>[], labels: PivotHeaderLabels): { columns: PivotColumnDef<TData>[]; groups: ColumnGroupDef[] } {
  const byId = new Map(sourceColumns.map((column) => [column.id, column]));
  const grouped = pivot.values.length > 1;
  const groups = new Map<string, ColumnGroupDef & { children: string[] }>();
  const columns = pivot.columns.slice(0, MAX_PIVOT_COLUMNS).map((descriptor, pivotIndex): PivotColumnDef<TData> => {
    const key = descriptor.path[0] ?? null;
    const value = pivot.values[descriptor.valueIndex]!;
    const source = byId.get(value.columnId);
    const keyText = groupKeyText(key);
    const keyLabel = keyText === "" ? labels.empty : keyText;
    const valueLabel = labels.value(value.reducer, headerTextOf(source, value.columnId));
    const header = grouped ? valueLabel : keyLabel;
    const id = pivotColumnId(pivot.columnId, key, value);
    if (grouped) {
      const groupId = pivotGroupId(pivot.columnId, key);
      const group = groups.get(groupId);
      if (group) group.children.push(id);
      else groups.set(groupId, { id: groupId, header: keyLabel, headerText: keyLabel, children: [id] });
    }
    const type = value.reducer === "count" ? "number" : source?.type;
    const options = value.reducer === "count" ? undefined : source?.options;
    return {
      id,
      header,
      headerText: header,
      ...(type === undefined ? null : { type }),
      ...(options === undefined ? null : { options }),
      readOnly: true,
      sortable: false,
      filterable: false,
      reorderable: false,
      pinnable: false,
      groupable: false,
      aggregate: value.reducer,
      pivotIndex,
      pivotLabel: labels.columnName(keyLabel, valueLabel),
    };
  });
  return { columns, groups: [...groups.values()] };
}

"use client";

import type { ReactNode } from "react";
import type { ColumnGroupModel } from "./columns/column-groups";
import { useDataGridColumnGroupModel, useDataGridInstanceId, useDataGridLabels, useDataGridStore } from "./store";

/** The header groups the grid draws: the generated `__pivotgroup:` groups under pivot, else the consumer's `columnGroups`. */
export function useHeaderGroupModel(): ColumnGroupModel | null {
  const consumer = useDataGridColumnGroupModel();
  const pivot = useDataGridStore((s) => s.pivot);
  return pivot ? pivot.groupModel : consumer;
}

/** The id of the "+N more columns" note, present only when generated columns were cut. */
export function usePivotNoteId(): string | undefined {
  const instanceId = useDataGridInstanceId();
  const cut = useDataGridStore((s) => (s.pivot?.omitted ?? 0) > 0);
  return cut ? `${instanceId}-pivot-note` : undefined;
}

/** The note below a pivot grid that counts the generated columns the server or the grid cut. */
export function DataGridPivotNote({ id }: { id: string }): ReactNode {
  const omitted = useDataGridStore((s) => s.pivot?.omitted ?? 0);
  const labels = useDataGridLabels();
  return (
    <p id={id} data-grid-pivot-note="" className="px-2 py-1 text-xs text-muted-foreground">
      {labels.pivot.moreColumns(omitted)}
    </p>
  );
}

"use client";

import { useLayoutEffect, useRef, type CSSProperties, type ReactNode } from "react";

/** The error bar unmounts with a focused control inside it; focus moves to the grid unless the user moved it elsewhere. */
export function ErrorBar({ focusGrid, className, style, children }: { focusGrid: () => void; className: string; style: CSSProperties; children: ReactNode }) {
  const ref = useRef<HTMLDivElement>(null);
  const latest = useRef(focusGrid);
  useLayoutEffect(() => {
    latest.current = focusGrid;
  });
  useLayoutEffect(
    () => () => {
      if (ref.current !== null && ref.current.contains(document.activeElement)) latest.current();
    },
    [],
  );
  return (
    <div ref={ref} data-grid-error-state="" role="alert" className={className} style={style}>
      {children}
    </div>
  );
}

import type { GroupLayout } from "../group-types";
import type { FilterNode, SortSpec } from "../types";
import { ownersOf, refreshGroupAggregates, type GroupBucket, type GroupTree } from "../sort-filter/build-group-view";
import { refreshPivotCells } from "../sort-filter/build-pivot";
import { makeFilterPredicate } from "../sort-filter/incremental-view-index";
import { fullViewOf, textAccessorFor, viewSorts } from "./compute";
import { groupKeyOf, groupKeyText } from "./group-state";
import { aggregateSpecs } from "./group-view";
import type { DataGridStoreState } from "./types";
import { registerGroupLayout } from "./view-rows";

/**
 * The sorts that decide where a row sits: the sorts the grid applies, then the group columns. A write to one of them leaves the view stale.
 * Under a client pivot the rows never show, so only the group columns and the pivot column decide.
 */
export function viewInputSorts(s: Pick<DataGridStoreState, "sortMode" | "sortState" | "groupBy" | "groupLayout">): SortSpec[] {
  const pivotColumnId = s.groupLayout?.pivot?.columnId;
  if (pivotColumnId !== undefined) return [...s.groupBy, pivotColumnId].map((columnId): SortSpec => ({ columnId, direction: "asc" }));
  const sorts = viewSorts(s.sortMode, s.sortState);
  return s.groupBy.length === 0 ? sorts : [...sorts, ...s.groupBy.map((columnId): SortSpec => ({ columnId, direction: "asc" }))];
}

/**
 * The patch that re-reduces the aggregates of a grouped view after a write to an `aggregate` column: the groups
 * that hold `touchedRows` (data indices), or every group when `touchedRows` is `null`. Empty for a grid that does not group.
 */
export function refreshedGroups(s: DataGridStoreState, nextData: readonly unknown[], touchedRows: readonly number[] | null, written: readonly { rowId?: string; columnId: string }[]): Partial<DataGridStoreState> {
  const layout = s.groupLayout;
  if (!layout?.tree) return {};
  const writtenIds = new Set(written.map((cell) => cell.columnId));
  if (layout.pivot) {
    if (!layout.pivot.values.some((value) => writtenIds.has(value.columnId))) return {};
    const touched = touchedRows ?? rowsOf(s, nextData, written);
    const replaced = refreshPivotCells(layout.tree as GroupTree, layout.pivot, touched, textAccessorFor(s.columns, nextData, s.cellTypes));
    if (replaced.size === 0) return {};
    const next = { ...layout, rows: layout.rows.map((node) => replaced.get(node.id) ?? node) };
    registerGroupLayout(s.viewIndex, next);
    registerGroupLayout(fullViewOf(s.viewIndex), next);
    return { groupLayout: next };
  }
  if (!aggregateSpecs(s.columns).some((spec) => writtenIds.has(spec.columnId))) return {};
  const accessor = textAccessorFor(s.columns, nextData, s.cellTypes);
  const replaced = refreshGroupAggregates(layout.tree as GroupTree, touchedRows, { accessor, aggregates: aggregateSpecs(s.columns), rowAt: (row) => nextData[row] });
  const next = { ...layout, rows: layout.rows.map((node) => replaced.get(node.id) ?? node) };
  registerGroupLayout(s.viewIndex, next);
  return { groupLayout: next };
}

/** The data indices of the rows `written` names by id; a write without row ids touches every row. */
function rowsOf(s: DataGridStoreState, nextData: readonly unknown[], written: readonly { rowId?: string }[]): number[] {
  const indexOf = s.dataWrite.rowIndexCache.resolve(nextData, s.getRowId);
  const rows: number[] = [];
  for (const { rowId } of written) {
    if (rowId === undefined) return nextData.map((_, index) => index);
    const index = indexOf.get(rowId);
    if (index !== undefined) rows.push(index);
  }
  return rows;
}

/**
 * The layout of a client pivot after `nextData` appended rows to `s.data`, when each appended row lands in a group and under a key
 * that the layout holds: the rows join their buckets in place, so the view and the generated columns keep their identity.
 * `null` when the view needs a full build.
 */
export function appendedPivotLayout(s: DataGridStoreState, nextData: readonly unknown[], filters: readonly FilterNode[]): GroupLayout | null {
  const layout = s.groupLayout;
  const pivot = layout?.pivot;
  const tree = layout?.tree as GroupTree | undefined;
  // A pending rebuild may move rows that the buckets still hold.
  if (!layout || !pivot || !tree || nextData.length <= s.data.length || s.viewStale || (s.dataWrite.deferredRows?.size ?? 0) > 0) return null;
  for (let row = 0; row < s.data.length; row++) if (nextData[row] !== s.data[row]) return null;
  const accessor = textAccessorFor(s.columns, nextData, s.cellTypes);
  const keep = filters.length === 0 ? null : makeFilterPredicate(accessor, filters);
  const valueCount = pivot.values.length;
  const held = new Set<string>();
  for (let at = 0; at < pivot.columns.length; at += valueCount) held.add(groupKeyText(pivot.columns[at]!.path[0] ?? null));
  const keyText = (row: number, columnId: string): string => {
    const key = groupKeyOf(accessor.getValue ? accessor.getValue(row, columnId) : accessor.getText(row, columnId));
    return typeof key === "string" ? key : groupKeyText(key);
  };
  const placed: { bucket: GroupBucket; row: number }[] = [];
  for (let row = s.data.length; row < nextData.length; row++) {
    if (nextData[row] === undefined) return null;
    if (keep && !keep(row)) continue;
    if (valueCount > 0 && !held.has(keyText(row, pivot.columnId))) return null;
    let level: readonly GroupBucket[] = tree.roots;
    let bucket: GroupBucket | undefined;
    for (const columnId of s.groupBy) {
      const text = keyText(row, columnId);
      bucket = level.find((candidate) => groupKeyText(candidate.node.key) === text);
      if (!bucket) return null;
      level = bucket.groups ?? [];
    }
    if (!bucket?.leaves) return null;
    placed.push({ bucket, row });
  }
  if (placed.length === 0) return layout;
  const owners = ownersOf(tree);
  for (const { bucket, row } of placed) {
    bucket.leaves!.push(row);
    owners.set(row, bucket);
    for (let at: GroupBucket | null = bucket; at; at = at.parent) at.node = { ...at.node, count: at.node.count + 1 };
  }
  tree.leafCount += placed.length;
  delete tree.leavesInOrder;
  const replaced = refreshPivotCells(tree, pivot, placed.map(({ row }) => row), accessor);
  const next: GroupLayout = { ...layout, leafCount: tree.leafCount, rows: layout.rows.map((node) => replaced.get(node.id) ?? node) };
  registerGroupLayout(s.viewIndex, next);
  registerGroupLayout(fullViewOf(s.viewIndex), next);
  return next;
}

import type { ExpandedState, PivotSpec } from "../group-types";
import { NO_GROUPS, normalizeExpanded, normalizeGroupBy, sameExpanded, sameGroupBy } from "./group-state";
import type { AnyColumnDef, DataGridStoreState, InternalSyncProps } from "./types";

const MAX_ECHOES = 32;

export const EXPANDED_CUT_MESSAGE = "expanded holds more than 10,000 group ids, so the grid keeps the first 10,000";

/** What the sync pass remembers about the controlled group props: the last prop seen, and the values the grid emitted that no prop has confirmed yet. */
export type GroupSyncMemory = {
  groupByProp: readonly string[] | undefined;
  expandedProp: ExpandedState | undefined;
  groupByEcho: (readonly string[])[];
  expandedEcho: ExpandedState[];
  pivotProp: PivotSpec | undefined;
  pivotEcho: PivotSpec[];
  /** The group columns emitted under a server layout that the `groupBy` prop has not brought yet. */
  requestedGroupBy: readonly string[] | null;
};

export function initGroupMemory(init: Pick<InternalSyncProps, "groupBy" | "expanded" | "pivot">): GroupSyncMemory {
  return { groupByProp: init.groupBy, expandedProp: init.expanded, groupByEcho: [], expandedEcho: [], pivotProp: init.pivot, pivotEcho: [], requestedGroupBy: null };
}

/** The pivot column of an untrusted spec: its first id when that is a string, else none. */
export function normalizePivot(spec: PivotSpec | undefined): readonly string[] {
  const id: unknown = Array.isArray(spec?.columnIds) ? spec.columnIds[0] : undefined;
  return typeof id === "string" ? [id] : NO_GROUPS;
}

/** The pivot column after a sync, with the echo and equality rules of {@link syncGroupState}. */
export function syncPivotState(current: readonly string[], prop: PivotSpec | undefined, memory: GroupSyncMemory): readonly string[] {
  let next = current;
  if (prop === undefined) memory.pivotEcho.length = 0;
  else if (prop !== memory.pivotProp) {
    const echoed = memory.pivotEcho.indexOf(prop);
    if (echoed !== -1) memory.pivotEcho.splice(0, echoed + 1);
    else {
      memory.pivotEcho.length = 0;
      const given = normalizePivot(prop);
      if (!sameGroupBy(given, current)) next = given;
    }
  }
  memory.pivotProp = prop;
  return next;
}

/** Records a value the grid emitted so its echo from the controlled prop changes nothing. */
export function rememberEmitted<T>(queue: T[], value: T): void {
  queue.push(value);
  if (queue.length > MAX_ECHOES) queue.shift();
}

/** The first group columns: the prop, else the seed, normalized. */
export function initialGroupBy(init: Pick<InternalSyncProps, "groupBy" | "defaultGroupBy">, columns: readonly AnyColumnDef[]): readonly string[] {
  const seed = typeof init.defaultGroupBy === "function" ? undefined : init.defaultGroupBy;
  return normalizeGroupBy(init.groupBy ?? seed, columns);
}

export function initialExpanded(init: Pick<InternalSyncProps, "expanded" | "defaultExpanded">, onCut: () => void): ExpandedState {
  return normalizeExpanded(init.expanded ?? init.defaultExpanded, onCut);
}

/**
 * The group columns and the open groups after a sync. A controlled prop applies when it is a new value that no emitted
 * value explains; the echo of an emitted value, and a prop equal in content, change nothing. A prop that did not change
 * since the last sync never overrides a gesture. Equal values keep the identity of the current ones.
 */
export function syncGroupState(
  s: Pick<DataGridStoreState, "groupBy" | "expanded">,
  props: Pick<InternalSyncProps, "groupBy" | "expanded">,
  columns: readonly AnyColumnDef[],
  memory: GroupSyncMemory,
  onCut: () => void,
): GroupSyncInputsResult {
  let groupBy = s.groupBy;
  if (props.groupBy === undefined) memory.groupByEcho.length = 0;
  else if (props.groupBy !== memory.groupByProp) {
    memory.requestedGroupBy = null;
    const echoed = memory.groupByEcho.indexOf(props.groupBy);
    if (echoed !== -1) memory.groupByEcho.splice(0, echoed + 1);
    else {
      memory.groupByEcho.length = 0;
      const next = normalizeGroupBy(props.groupBy, columns);
      if (!sameGroupBy(next, groupBy)) groupBy = next;
    }
  }
  memory.groupByProp = props.groupBy;
  const kept = normalizeGroupBy(groupBy, columns);
  if (!sameGroupBy(kept, groupBy)) groupBy = kept;

  let expanded = s.expanded;
  if (props.expanded === undefined) memory.expandedEcho.length = 0;
  else if (props.expanded !== memory.expandedProp) {
    const echoed = memory.expandedEcho.indexOf(props.expanded);
    if (echoed !== -1) memory.expandedEcho.splice(0, echoed + 1);
    else {
      memory.expandedEcho.length = 0;
      const next = normalizeExpanded(props.expanded, onCut);
      if (!sameExpanded(next, expanded)) expanded = next;
    }
  }
  memory.expandedProp = props.expanded;
  return { groupBy, expanded, groupByControlled: props.groupBy !== undefined, expandedControlled: props.expanded !== undefined };
}

export type GroupSyncInputsResult = { groupBy: readonly string[]; expanded: ExpandedState; groupByControlled: boolean; expandedControlled: boolean };

import type { StoreApi } from "zustand/vanilla";
import type { ExpandedState, PivotSpec } from "../group-types";
import { selectCell } from "../selection";
import { flattenGroupTree, groupIdsOfRow, type GroupTree } from "../sort-filter/build-group-view";
import { computeSearchMatches, computeViewIndex, viewFilters, viewSorts, viewWindowOf, windowView } from "./compute";
import { emitAfterWrites, resetDeferredRows, type DataWriteContext } from "./data-write";
import { groupAnnouncementLabel, nextAnnouncement } from "./announcements";
import { EXPANDED, COLLAPSED, expandedTest, normalizeExpanded, normalizeGroupBy, sameExpanded, sameGroupBy, toggleExpanded } from "./group-state";
import { groupRowExpandable } from "./group-positions";
import { normalizePivot, rememberEmitted } from "./group-sync";
import { groupingOf, warnGroupOnce } from "./group-view";
import { viewRowOfDataIndex } from "./row-index";
import { clearStaleRows } from "./server-stale";
import type { FollowView, SyncMemory } from "./sync-props";
import type { DataGridActions, DataGridStoreState } from "./types";
import { dataIndexAt, registerGroupLayout, viewRowOfGroupId } from "./view-rows";

const NO_PIVOT: readonly string[] = [];

type GroupActions =Pick<DataGridActions, "setGroupBy" | "toggleGroupBy" | "setPivot" | "setExpanded" | "toggleGroup" | "expandAll" | "collapseAll">;

type Deps = {
  set: StoreApi<DataGridStoreState>["setState"];
  get: StoreApi<DataGridStoreState>["getState"];
  dataWrite: DataWriteContext;
  followView: FollowView;
  memory: SyncMemory;
};

/** When the cursor sat on a row that a collapse hid, the cursor and the selection move to the nearest group row that still shows. */
function anchorOnGroup(s: DataGridStoreState, view: readonly number[], tree: GroupTree, followed: Partial<DataGridStoreState>): Partial<DataGridStoreState> {
  const active = s.activeCell;
  const dataIndex = active ? dataIndexAt(s, active.row) : undefined;
  if (!active || dataIndex === undefined || viewRowOfDataIndex(view, dataIndex) !== -1) return {};
  for (const id of groupIdsOfRow(tree, dataIndex)) {
    const row = viewRowOfGroupId(view, id);
    if (row === -1) continue;
    const coord = { row, col: active.col };
    return { activeCell: coord, selection: { ...(followed.selection ?? s.selection), current: selectCell(coord).current } };
  }
  return {};
}

export function createGroupActions({ set, get, dataWrite, followView, memory }: Deps): GroupActions {
  const patchFor = (s: DataGridStoreState, viewIndex: number[]): Partial<DataGridStoreState> => ({
    viewIndex,
    ...followView(s, viewIndex, s.visibleColumns),
    ...computeSearchMatches(s.data, s.columns, viewIndex, s.visibleColumns, s.searchText, s.cellTypes, s.searchOptions, s.locale),
  });

  const regroup = (s: DataGridStoreState, groupBy: readonly string[], pivotColumnIds = s.pivotColumnIds): Partial<DataGridStoreState> => {
    const grouping = groupingOf({ ...s, groupBy, pivotColumnIds });
    const page = s.pageSize === null || s.pageControlled ? s.page : 1;
    const viewIndex = computeViewIndex(s.data, s.columns, viewSorts(s.sortMode, s.sortState), viewFilters(s.filterMode, s.filterState, s.filterJoin), s.viewIndex, s.cellTypes, viewWindowOf({ ...s, page }), s.sortLocale, grouping);
    resetDeferredRows(dataWrite);
    return { groupBy, pivotColumnIds, page, ...clearStaleRows(dataWrite), ...patchFor(s, viewIndex) };
  };

  const reopen = (s: DataGridStoreState, expanded: ExpandedState): Partial<DataGridStoreState> => {
    const tree = s.groupLayout?.tree as GroupTree | undefined;
    if (!tree) return { expanded };
    const { viewIndex: full, layout } = flattenGroupTree(tree, expanded);
    registerGroupLayout(full, layout);
    const viewIndex = windowView(full, viewWindowOf(s), s.viewIndex);
    const patch = patchFor(s, viewIndex);
    return { expanded, ...patch, ...anchorOnGroup(s, viewIndex, tree, patch) };
  };

  // A server layout matches only the group columns it was built for, so the grid keeps them until the prop brings the new layout.
  const heldForServer = (s: DataGridStoreState) => s.groupMode === "server" && s.groupByControlled;
  const latestGroupBy = (s: DataGridStoreState) => (heldForServer(s) ? (memory.group.requestedGroupBy ?? s.groupBy) : s.groupBy);

  const commitGroupBy = (requested: readonly string[]): void => {
    const s = get();
    const groupBy = normalizeGroupBy(requested, s.columns);
    if (sameGroupBy(groupBy, latestGroupBy(s))) return;
    const resetPage = () => {
      if (s.pageSize !== null && s.page !== 1) s.onPageChange?.(1);
    };
    // A pivot needs groupBy, so the last ungroup turns it off too.
    const pivotOff = groupBy.length === 0 && s.pivotColumnIds.length > 0 ? { columnIds: NO_PIVOT } : null;
    const emitPivotOff = () => pivotOff && s.onPivotChange?.(pivotOff);
    if (heldForServer(s)) {
      memory.group.requestedGroupBy = groupBy;
      emitAfterWrites(dataWrite, () => s.onGroupByChange?.(groupBy), emitPivotOff, resetPage);
      return;
    }
    set((s2) => regroup(s2, groupBy, pivotOff ? NO_PIVOT : s2.pivotColumnIds));
    memory.lastSyncInputs = { ...memory.lastSyncInputs, groupBy, ...(pivotOff ? { pivotColumnIds: NO_PIVOT } : null) };
    if (s.groupByControlled) rememberEmitted(memory.group.groupByEcho, groupBy);
    if (pivotOff && s.pivotControlled) rememberEmitted(memory.group.pivotEcho, pivotOff);
    emitAfterWrites(dataWrite, () => s.onGroupByChange?.(groupBy), emitPivotOff, resetPage);
  };

  const commitPivot = (requested: PivotSpec | undefined): void => {
    const s = get();
    const pivotColumnIds = normalizePivot(requested);
    if (sameGroupBy(pivotColumnIds, s.pivotColumnIds)) return;
    const emitted = { columnIds: pivotColumnIds };
    set((s2) => regroup(s2, s2.groupBy, pivotColumnIds));
    memory.lastSyncInputs = { ...memory.lastSyncInputs, pivotColumnIds };
    if (s.pivotControlled) rememberEmitted(memory.group.pivotEcho, emitted);
    emitAfterWrites(dataWrite, () => s.onPivotChange?.(emitted), () => {
      if (s.pageSize !== null && s.page !== 1) s.onPageChange?.(1);
    });
  };

  const commitExpanded = (requested: ExpandedState): void => {
    const s = get();
    const normalized = normalizeExpanded(requested);
    const expanded = s.groupMode === "server" && normalized.mode === "expanded" ? COLLAPSED : normalized;
    if (expanded !== normalized) warnGroupOnce(s.dataWrite, "server expand all", 'expanded mode "expanded" is not available under groupMode="server": the grid keeps every group collapsed');
    if (sameExpanded(expanded, s.expanded)) return;
    set((s2) => reopen(s2, expanded));
    memory.lastSyncInputs = { ...memory.lastSyncInputs, expanded };
    if (s.expandedControlled) rememberEmitted(memory.group.expandedEcho, expanded);
    emitAfterWrites(dataWrite, () => s.onExpandedChange?.(expanded));
  };

  return {
    setGroupBy: commitGroupBy,
    toggleGroupBy(columnId) {
      const groupBy = latestGroupBy(get());
      commitGroupBy(groupBy.includes(columnId) ? groupBy.filter((id) => id !== columnId) : [...groupBy, columnId]);
    },
    setPivot: commitPivot,
    setExpanded: commitExpanded,
    toggleGroup(groupId) {
      const s = get();
      const node = s.groupLayout?.rows.find((row) => row.id === groupId);
      if (s.pivot && !(node && groupRowExpandable(s, node))) return;
      const opens = !expandedTest(s.expanded)(groupId);
      const next = toggleExpanded(s.expanded, groupId);
      if (next === s.expanded) {
        if (opens) set((s2) => ({ liveAnnouncement: nextAnnouncement(s2.liveAnnouncement, "groupTooManyOpen", 0) }));
        return;
      }
      commitExpanded(next);
      if (!node) return;
      set((s2) => ({ liveAnnouncement: nextAnnouncement(s2.liveAnnouncement, opens ? "groupExpanded" : "groupCollapsed", node.count, false, groupAnnouncementLabel(s2, node)) }));
    },
    expandAll() {
      if (get().groupMode === "server") return { ok: false, reason: "server-groups" };
      commitExpanded(EXPANDED);
      return { ok: true };
    },
    collapseAll() {
      commitExpanded(COLLAPSED);
      return { ok: true };
    },
  };
}

import { leavesOfTree, type GroupTree } from "../sort-filter/build-group-view";
import type { GroupNode } from "../group-types";
import { fullViewOf } from "./compute";
import type { DataGridStoreState } from "./types";

type GroupedState = Pick<DataGridStoreState, "viewIndex" | "groupLayout">;

/** Every data row of the result in view order: the rows of collapsed groups included, group rows left out. The view itself when the grid does not group. */
export function leafViewOf(s: GroupedState): readonly number[] {
  const tree = s.groupLayout?.tree as GroupTree | undefined;
  return tree ? leavesOfTree(tree) : fullViewOf(s.viewIndex);
}

/** The number of data rows in the result, collapsed groups included. */
export function leafCountOf(s: GroupedState): number {
  return s.groupLayout ? s.groupLayout.leafCount : fullViewOf(s.viewIndex).length;
}

/** The group rows of the view, in view order of their first appearance; empty when the grid does not group. */
export function groupRowsOf(s: Pick<DataGridStoreState, "groupLayout">): readonly GroupNode[] {
  return s.groupLayout?.rows ?? [];
}

import { groupLayoutOfView } from "./view-rows";

const startsByView = new WeakMap<readonly number[], number[]>();

/** Where each top-level group row sits in the full grouped `view`; `null` for a view that holds no group rows. */
export function topGroupStarts(view: readonly number[]): readonly number[] | null {
  const layout = groupLayoutOfView(view);
  if (!layout) return null;
  let starts = startsByView.get(view);
  if (!starts) {
    starts = [];
    for (let row = 0; row < view.length; row++) {
      const entry = view[row]!;
      if (entry < 0 && layout.rows[-entry - 1]?.depth === 0) starts.push(row);
    }
    startsByView.set(view, starts);
  }
  return starts;
}

/** What one page of a paged view counts: top-level groups while the view is grouped, else rows. */
export function pageUnitsOf(view: readonly number[]): number {
  return topGroupStarts(view)?.length ?? view.length;
}

/** The slice of a grouped full `view` that page `page` shows: `size` top-level groups with the rows opened under them; `null` for a view that holds no group rows. */
export function groupedPageSpan(view: readonly number[], page: number, size: number): { start: number; end: number } | null {
  const starts = topGroupStarts(view);
  if (!starts) return null;
  const lastPage = Math.max(1, Math.ceil(starts.length / size));
  const first = (Math.min(Math.max(1, Math.floor(page) || 1), lastPage) - 1) * size;
  return { start: starts[first] ?? view.length, end: starts[first + size] ?? view.length };
}

/** The page that shows row `row` of the full `view` at `size` units per page. */
export function pageOfFullRow(view: readonly number[], row: number, size: number): number {
  const starts = topGroupStarts(view);
  if (!starts) return Math.floor(row / size) + 1;
  let low = 0;
  let high = starts.length - 1;
  while (low < high) {
    const mid = (low + high + 1) >> 1;
    if (starts[mid]! <= row) low = mid;
    else high = mid - 1;
  }
  return Math.floor(low / size) + 1;
}

import type { DataGridStoreState } from "./types";
import { fullViewOf } from "./compute";

/** The size of the result "all matching" covers: the leaf count a server lays out (`groupLayout.leafCount`), else `totalRowCount`, else the whole client list behind a paged or collapsed view (group rows left out); `undefined` when the view shows the whole result. */
export function matchingRowTotal(s: Pick<DataGridStoreState, "totalRowCount" | "viewIndex" | "groupLayout"> & Partial<Pick<DataGridStoreState, "groupMode" | "serverHeld">>): number | null | undefined {
  // The held rows belong to the previous spec, so their count is no count of the current one.
  if (s.serverHeld) return null;
  if (s.groupMode === "server" && s.groupLayout) return s.groupLayout.leafCount;
  if (s.totalRowCount !== undefined) return s.totalRowCount;
  const full = fullViewOf(s.viewIndex);
  const layout = s.groupLayout;
  if (layout) return full === s.viewIndex && full.length - layout.rows.length === layout.leafCount ? undefined : layout.leafCount;
  return full === s.viewIndex ? undefined : full.length;
}

import type { SelectionState } from "../types";
import { selectionStatesEqual } from "./selection-state";
import type { DataGridStoreState } from "./types";
import { rowIdAtViewRow } from "./view-rows";

type ViewState = Pick<DataGridStoreState, "viewIndex" | "data" | "getRowId">;

const EMPTY: readonly string[] = [];

function idsInView(s: ViewState): Set<string> {
  const ids = new Set<string>();
  for (let viewRow = 0; viewRow < s.viewIndex.length; viewRow++) {
    const id = rowIdAtViewRow(s, viewRow);
    if (id !== undefined) ids.add(id);
  }
  return ids;
}

/** Whether `next` differs from `last` only because the group layout moved rows into or out of the view. */
export function isRelayoutOnly(last: SelectionState, next: SelectionState, before: ViewState, after: ViewState): boolean {
  if (!selectionStatesEqual({ ...next, rowIds: EMPTY }, { ...last, rowIds: EMPTY })) return false;
  const was = new Set(last.rowIds);
  const now = new Set(next.rowIds);
  const unchecked = last.rowIds.filter((id) => !now.has(id));
  const checked = next.rowIds.filter((id) => !was.has(id));
  if (unchecked.length > 0) {
    const stillShown = idsInView(after);
    if (unchecked.some((id) => stillShown.has(id))) return false;
  }
  if (checked.length > 0) {
    const wasShown = idsInView(before);
    if (checked.some((id) => wasShown.has(id))) return false;
  }
  return true;
}

import type { ColumnGroupModel } from "../columns/column-groups";
import type { CellType, FilterNode, SortSpec } from "../types";
import type { ExpandedState, ServerGroupLayout } from "../group-types";
import type { AnyColumnDef } from "./types";

/**
 * Everything `computeViewIndex`/`computeSearchMatches`/`computeVisibleColumns` read on a
 * `_syncProps` sync, captured by reference. All fields `===`-equal to the previous sync's means
 * their outputs (`viewIndex`/`searchMatches`/`visibleColumns`) are also unchanged, so `_syncProps`
 * can skip recomputing them and reuse the previous references (a controlled parent re-rendering
 * for unrelated reasons — e.g. its own local state — shouldn't pay full buildViewIndex cost).
 */
export type SyncInputs = {
  data: readonly unknown[];
  columns: readonly AnyColumnDef[];
  /** Sort reads each column's cell-type `compare`, so a swapped registry changes `viewIndex`. */
  cellTypes: Record<string, CellType>;
  sortState: SortSpec[];
  filterState: FilterNode[];
  searchText: string;
  columnOrder: string[] | null;
  hiddenColumns: readonly string[];
  columnGroupModel: ColumnGroupModel | null;
  /** `"<page>|<pageSize>"`: a page change rebuilds the paged view. */
  pageKey: string;
  sortLocale: string;
  groupBy: readonly string[];
  expanded: ExpandedState;
  groupMode: "client" | "server";
  serverGroupLayout: ServerGroupLayout | null;
  pivotColumnIds: readonly string[];
};

export function syncInputsEqual(a: SyncInputs, b: SyncInputs): boolean {
  return (
    a.data === b.data &&
    a.columns === b.columns &&
    a.cellTypes === b.cellTypes &&
    a.sortState === b.sortState &&
    a.filterState === b.filterState &&
    a.searchText === b.searchText &&
    a.columnOrder === b.columnOrder &&
    a.hiddenColumns === b.hiddenColumns &&
    a.columnGroupModel === b.columnGroupModel &&
    a.pageKey === b.pageKey &&
    a.sortLocale === b.sortLocale &&
    a.groupBy === b.groupBy &&
    a.expanded === b.expanded &&
    a.groupMode === b.groupMode &&
    a.serverGroupLayout === b.serverGroupLayout &&
    a.pivotColumnIds === b.pivotColumnIds
  );
}

import type { GroupLayout } from "../group-types";
import type { DataGridStoreState } from "./types";

const layoutsByView = new WeakMap<object, GroupLayout>();

/** Remembers the group rows that the entries below 0 of `view` name. */
export function registerGroupLayout(view: readonly number[], layout: GroupLayout): void {
  layoutsByView.set(view, layout);
}

/** The group rows of a grouped view; `null` for a view that holds none. */
export function groupLayoutOfView(view: ArrayLike<number>): GroupLayout | null {
  return layoutsByView.get(view) ?? null;
}

/** What a view row stands for across rebuilds: a data index, or the group id of a group row. `undefined` for a missing row. */
export function recordKeyAt(view: ArrayLike<number>, viewRow: number): number | string | undefined {
  const entry = view[viewRow];
  if (entry === undefined || entry >= 0) return entry;
  return groupLayoutOfView(view)?.rows[-entry - 1]?.id;
}

/** The view row that shows the group `groupId`, or -1. */
export function viewRowOfGroupId(view: readonly number[], groupId: string): number {
  const rows = groupLayoutOfView(view)?.rows;
  const at = rows ? rows.findIndex((row) => row.id === groupId) : -1;
  return at === -1 ? -1 : view.indexOf(-at - 1);
}

/**
 * The view row in `nextView` of the nearest group above the row `prevViewRow` of `prevView` that `nextView` still shows, or -1.
 * For a data row whose own group stays, -1: the row only left, and the caller clamps.
 */
export function viewRowOfSurvivingParent(prevView: readonly number[], prevViewRow: number, nextView: readonly number[]): number {
  const rows = groupLayoutOfView(prevView)?.rows;
  if (!rows) return -1;
  let header = prevViewRow;
  while (header > 0 && !(prevView[header]! < 0)) header--;
  if (!(prevView[header]! < 0)) return -1;
  const at = -prevView[header]! - 1;
  if (header !== prevViewRow && viewRowOfGroupId(nextView, rows[at]!.id) !== -1) return -1;
  let depth = rows[at]!.depth;
  for (let i = at; i >= 0 && depth > 0; i--) {
    if (rows[i]!.depth >= depth) continue;
    depth = rows[i]!.depth;
    const next = viewRowOfGroupId(nextView, rows[i]!.id);
    if (next !== -1) return next;
  }
  return -1;
}

type ViewRowsState = { readonly viewIndex: ArrayLike<number>; readonly data: readonly unknown[] };

/** What a view row shows: a data row, a group row (an entry below 0), or a hole (out of range or an unloaded row). */
export type ViewEntry =
  | { readonly kind: "data"; readonly dataIndex: number }
  | { readonly kind: "group"; readonly groupIndex: number }
  | { readonly kind: "hole"; readonly dataIndex?: number };

/** The data index at `viewRow` of `view`; `undefined` when the row is out of range or an entry below 0 names a group row. */
export function dataIndexOf(view: ArrayLike<number>, viewRow: number): number | undefined {
  const dataIndex = view[viewRow];
  return dataIndex !== undefined && dataIndex >= 0 ? dataIndex : undefined;
}

/** The data index shown at `viewRow`; `undefined` for a missing row or a group row. */
export function dataIndexAt(s: { readonly viewIndex: ArrayLike<number> }, viewRow: number): number | undefined {
  return dataIndexOf(s.viewIndex, viewRow);
}

/** The data row shown at `viewRow`; `undefined` for a missing row, an unloaded row, or a group row. */
export function rowAtViewRow(s: ViewRowsState, viewRow: number): unknown {
  const dataIndex = dataIndexOf(s.viewIndex, viewRow);
  return dataIndex === undefined ? undefined : s.data[dataIndex];
}

export function viewEntryAt(s: ViewRowsState, viewRow: number): ViewEntry {
  const entry = s.viewIndex[viewRow];
  if (entry === undefined) return { kind: "hole" };
  if (entry < 0) return { kind: "group", groupIndex: -entry - 1 };
  return s.data[entry] === undefined ? { kind: "hole", dataIndex: entry } : { kind: "data", dataIndex: entry };
}

/** Calls `fn` for every entry of `view` that names a data row, in view order. */
export function forEachDataIndex(view: ArrayLike<number>, fn: (dataIndex: number, viewRow: number) => void): void {
  for (let viewRow = 0; viewRow < view.length; viewRow++) {
    const dataIndex = view[viewRow]!; // viewRow < length by loop condition
    if (dataIndex >= 0) fn(dataIndex, viewRow);
  }
}

/** Row id shown at `viewRow`: the group id for a group row, `undefined` for a missing or unloaded row. */
export function rowIdAtViewRow(
  s: ViewRowsState & { getRowId: DataGridStoreState["getRowId"] },
  viewRow: number,
): string | undefined {
  const dataIndex = dataIndexOf(s.viewIndex, viewRow);
  if (dataIndex === undefined) return recordKeyAt(s.viewIndex, viewRow) as string | undefined;
  const row = s.data[dataIndex];
  return row === undefined ? undefined : s.getRowId(row, dataIndex);
}

/** The index into `groupLayout.rows` of the group row at `viewRow`; `undefined` for a data row or a missing row. */
export function groupIndexAt(view: ArrayLike<number>, viewRow: number): number | undefined {
  const entry = view[viewRow];
  return entry !== undefined && entry < 0 ? -entry - 1 : undefined;
}

import type { AnyColumnDef } from "./types";
import type { FilterNode, SortSpec } from "../types";

/** `sorts` without the specs of unknown columns; the array itself when none drops. */
export function keepKnownSorts(sorts: SortSpec[], columns: readonly AnyColumnDef[]): SortSpec[] {
  const known = new Set(columns.map((c) => c.id));
  const kept = sorts.filter((spec) => known.has(spec.columnId));
  return kept.length === sorts.length ? sorts : kept;
}

/** `nodes` without the filter rows of unknown columns, groups included; the array itself when none drops. */
export function keepKnownFilters(nodes: FilterNode[], columns: readonly AnyColumnDef[]): FilterNode[] {
  return keepKnown(nodes, new Set(columns.map((c) => c.id)));
}

function keepKnown(nodes: FilterNode[], known: ReadonlySet<string>): FilterNode[] {
  let changed = false;
  const kept: FilterNode[] = [];
  for (const node of nodes) {
    if (!("filters" in node)) {
      if (known.has(node.columnId)) kept.push(node);
      else changed = true;
      continue;
    }
    const children = keepKnown(node.filters, known);
    if (children === node.filters) kept.push(node);
    else {
      changed = true;
      kept.push({ ...node, filters: children });
    }
  }
  return changed ? kept : nodes;
}

import type { CompactSelectionLike } from "../types";
import { CompactSelection } from "../selection/compact-selection";
import type { DataGridStoreState } from "./types";
import { dataIndexOf, forEachDataIndex } from "./view-rows";

/** Whether cell and column selections leave the checked rows alone. */
export function keepsCheckedRows(s: Pick<DataGridStoreState, "checkedRowsLifetime">): boolean {
  return s.checkedRowsLifetime !== "until-click";
}

export const MAX_HIDDEN_CHECKED_ROWS = 100_000;

export const NO_HIDDEN_CHECKED_ROWS: ReadonlySet<string> = new Set<string>();

/** The store patch that forgets every remembered id and leaves "all matching". */
export const NO_REMEMBERED_ROWS = { hiddenCheckedRowIds: NO_HIDDEN_CHECKED_ROWS, allMatching: false } as const;

type RowIdOf = (row: unknown, index: number) => string;

/** Whether `data` is declared a window of a larger result (`totalRowCount`, `null` for an unknown size). */
export function windowModeActive(s: Pick<DataGridStoreState, "totalRowCount">): boolean {
  return s.totalRowCount !== undefined;
}

/**
 * Whether checked rows that leave the view are remembered: `checkedRowsLifetime="across-filters"`, with `totalRowCount`
 * (any mode) or on a client-sorted, client-filtered grid.
 */
export function hiddenCheckedRowsActive(
  s: Pick<DataGridStoreState, "checkedRowsLifetime" | "sortMode" | "filterMode" | "totalRowCount">,
): boolean {
  return s.checkedRowsLifetime === "across-filters" && (windowModeActive(s) || (s.sortMode !== "server" && s.filterMode !== "server"));
}

function sameIds(a: ReadonlySet<string>, b: ReadonlySet<string>): boolean {
  if (a.size !== b.size) return false;
  for (const id of a) if (!b.has(id)) return false;
  return true;
}

/**
 * Whether a row action finds no checked row to act on, so the action does nothing: every checked row is hidden,
 * or "all matching" is on (the grid does not hold those rows).
 */
export function onlyHiddenRowsChecked(s: Pick<DataGridStoreState, "checkedRowsLifetime" | "selection" | "hiddenCheckedRowIds" | "allMatching">): boolean {
  return keepsCheckedRows(s) && (s.allMatching || (s.selection.rows.length === 0 && s.hiddenCheckedRowIds.size > 0));
}

export type CarriedCheckedRows = {
  rows: CompactSelectionLike;
  /** Remembered ids: checked rows that left the view, or in `allMatching` mode the excluded (unchecked) rows. */
  hidden: ReadonlySet<string>;
  /** `false` when the exclusions outgrew {@link MAX_HIDDEN_CHECKED_ROWS} and "all matching" was dropped. */
  allMatching: boolean;
  /** The data holds unloaded rows: nothing was carried and the option does not apply. */
  lazy: boolean;
  /** Rows beyond {@link MAX_HIDDEN_CHECKED_ROWS} were dropped instead of remembered. */
  capped: boolean;
};

/**
 * Carries the checked rows into a rebuilt view by row id. A checked row that left the view moves
 * into `hidden`; a hidden row that is back in the view returns to the row channel; a row that is
 * gone from the data drops out. Returns `rows` and `hidden` themselves when nothing moved.
 */
export function carryCheckedRows(input: {
  rows: CompactSelectionLike;
  hidden: ReadonlySet<string>;
  prevData: readonly unknown[];
  prevViewIndex: readonly number[];
  prevGetRowId: RowIdOf;
  nextData: readonly unknown[];
  nextGetRowId: RowIdOf;
  nextViewIndex: readonly number[];
  /** `rowId -> data index` of `nextData`; called only after `nextData` is known to hold no unloaded row. */
  resolveNextRowIds: () => ReadonlyMap<string, number>;
  /** The records are the same objects at the same indexes (a value-only write). */
  sameRecords: boolean;
  /** `data` is a window of a larger result: ids that are absent from the data stay remembered, and unloaded rows are tolerated. */
  windowMode: boolean;
  /** "All matching" is on: `rows` are the checked rows and `hidden` holds the excluded ids. */
  allMatching: boolean;
}): CarriedCheckedRows {
  const { rows, hidden, prevData, prevViewIndex, prevGetRowId, nextData, nextGetRowId, nextViewIndex, resolveNextRowIds, sameRecords, windowMode, allMatching } = input;
  const unchanged: CarriedCheckedRows = { rows, hidden, allMatching, lazy: false, capped: false };
  if (!allMatching && rows.length === 0 && hidden.size === 0) return unchanged;
  if ((prevData === nextData || sameRecords) && prevViewIndex === nextViewIndex) return unchanged;
  if (!windowMode && nextData.includes(undefined)) return { rows, hidden: NO_HIDDEN_CHECKED_ROWS, allMatching: false, lazy: true, capped: false };
  const dataRowById = resolveNextRowIds();
  const viewRowOfDataRow = new Int32Array(nextData.length).fill(-1);
  forEachDataIndex(nextViewIndex, (dataIndex, viewRow) => {
    viewRowOfDataRow[dataIndex] = viewRow;
  });

  if (allMatching) {
    const excluded = new Set(hidden);
    const runs = rows.runs();
    let run = 0;
    for (let viewRow = 0; viewRow < prevViewIndex.length; viewRow++) {
      while (run < runs.length && runs[run]![1] <= viewRow) run++;
      const wasChecked = run < runs.length && runs[run]![0] <= viewRow;
      const prevDataRow = dataIndexOf(prevViewIndex, viewRow);
      const record = prevDataRow === undefined ? undefined : prevData[prevDataRow];
      if (prevDataRow === undefined || record === undefined) continue;
      const id = prevGetRowId(record, prevDataRow);
      if (wasChecked) excluded.delete(id);
      else excluded.add(id);
      if (excluded.size > MAX_HIDDEN_CHECKED_ROWS) {
        return { rows: CompactSelection.empty(), hidden: NO_HIDDEN_CHECKED_ROWS, allMatching: false, lazy: false, capped: true };
      }
    }
    const checked: number[] = [];
    for (let viewRow = 0; viewRow < nextViewIndex.length; viewRow++) {
      const nextDataRow = dataIndexOf(nextViewIndex, viewRow);
      if (nextDataRow === undefined) continue;
      const record = nextData[nextDataRow];
      if (record === undefined || !excluded.has(nextGetRowId(record, nextDataRow))) checked.push(viewRow);
    }
    const nextRows = CompactSelection.fromArray(checked);
    return {
      rows: rows.equals(nextRows) ? rows : nextRows,
      hidden: sameIds(hidden, excluded) ? hidden : excluded,
      allMatching: true,
      lazy: false,
      capped: false,
    };
  }

  const found: number[] = [];
  const nextHidden = new Set<string>();
  let capped = false;
  const remember = (id: string): void => {
    if (nextHidden.size < MAX_HIDDEN_CHECKED_ROWS || nextHidden.has(id)) nextHidden.add(id);
    else capped = true;
  };
  for (const id of hidden) {
    const nextDataRow = dataRowById.get(id);
    if (nextDataRow === undefined) {
      if (windowMode) remember(id);
      continue;
    }
    const nextViewRow = viewRowOfDataRow[nextDataRow]!;
    if (nextViewRow >= 0) found.push(nextViewRow);
    else remember(id);
  }
  for (const [runStart, runEnd] of rows.runs()) {
    for (let viewRow = runStart; viewRow < runEnd; viewRow++) {
      const prevDataRow = dataIndexOf(prevViewIndex, viewRow);
      if (prevDataRow === undefined) continue;
      const record = prevData[prevDataRow];
      if (record === undefined) {
        // A checked unloaded row stays checked at its index; a page load fills the same index.
        const nextViewRow = windowMode && prevDataRow < nextData.length ? viewRowOfDataRow[prevDataRow]! : -1;
        if (nextViewRow >= 0) found.push(nextViewRow);
        continue;
      }
      const id = prevGetRowId(record, prevDataRow);
      const nextDataRow = dataRowById.get(id);
      if (nextDataRow === undefined) {
        if (windowMode) remember(id);
        continue;
      }
      const nextViewRow = viewRowOfDataRow[nextDataRow]!;
      if (nextViewRow >= 0) found.push(nextViewRow);
      else remember(id);
    }
  }
  const nextRows = CompactSelection.fromArray(found);
  return {
    rows: rows.equals(nextRows) ? rows : nextRows,
    hidden: sameIds(hidden, nextHidden) ? hidden : nextHidden,
    allMatching: false,
    lazy: false,
    capped,
  };
}

/** `hidden` without the ids in `rowIds`; `hidden` itself when none of them is in it. */
export function withoutHiddenCheckedRows(hidden: ReadonlySet<string>, rowIds: Iterable<string>): ReadonlySet<string> {
  if (hidden.size === 0) return hidden;
  let next: Set<string> | null = null;
  for (const id of rowIds) {
    if (!(next ?? hidden).has(id)) continue;
    next ??= new Set(hidden);
    next.delete(id);
  }
  return next ?? hidden;
}

import { getSelectedViewRows } from "../selection";
import { keepsCheckedRows, onlyHiddenRowsChecked } from "./hidden-checked-rows";
import type { DataGridStoreState, RowActionSkipReason } from "./types";

type TargetSource = Pick<DataGridStoreState, "checkedRowsLifetime" | "selection" | "hiddenCheckedRowIds" | "allMatching">;

export type RowOperationTargets = { rows: number[]; reason?: undefined } | { rows: []; reason: Extract<RowActionSkipReason, "all-matching" | "hidden-rows-only"> };

/**
 * The view rows a delete, duplicate, or move acts on: the checked rows, else every row the cell
 * ranges cover, else `fallbackRow`. No rows and a reason when the checked rows are not in the grid.
 */
export function rowOperationTargets(s: TargetSource, fallbackRow: number | null | undefined): RowOperationTargets {
  if (onlyHiddenRowsChecked(s)) return { rows: [], reason: s.allMatching ? "all-matching" : "hidden-rows-only" };
  const selected = getSelectedViewRows(s.selection, { checkedRowsOnly: keepsCheckedRows(s) });
  if (selected.length > 0) return { rows: selected };
  return { rows: fallbackRow == null ? [] : [fallbackRow] };
}

import type { DataGridStoreState, RowActionName, RowActionResult, RowActionSkipReason } from "./types";

/** Calls `onRowActionSkipped` and returns the failed result; a throwing handler logs a console error. */
export function reportRowActionSkipped(state: Pick<DataGridStoreState, "onRowActionSkipped">, action: RowActionName, reason: RowActionSkipReason, count?: number): RowActionResult {
  const handler = state.onRowActionSkipped;
  if (handler) {
    try {
      handler(count === undefined ? { action, reason } : { action, reason, count });
    } catch (error) {
      console.error("[data-grid] onRowActionSkipped threw:", error);
    }
  }
  return { ok: false, reason };
}

import { serverSpecOf, type ServerSpec } from "../server-spec";
import type { DataGridStoreState } from "./types";
import { viewRowOfDataIndex } from "./row-index";
import { matchingRowTotal } from "./matching-total";
import { dataIndexAt, rowAtViewRow } from "./view-rows";

/** The selection as a value a bulk action sends to a server. */
export type DataGridSelectedRows =
  | {
      mode: "ids";
      /** Row ids of the checked loaded rows and the remembered ones. Unloaded rows have no id and are left out. */
      ids: readonly string[];
      excludedIds: readonly [];
      count: number;
    }
  | {
      mode: "allMatching";
      ids: readonly [];
      /** Every row of the result is selected except these: the remembered exclusions and the unchecked loaded rows. */
      excludedIds: readonly string[];
      /** `totalRowCount` minus the exclusions; `null` when the size of the result is unknown. */
      count: number | null;
      /** The sort, filters, and search text the grid held when the value was read. */
      spec: ServerSpec;
    };

type Source = Pick<DataGridStoreState, "selection" | "hiddenCheckedRowIds" | "allMatching" | "data" | "viewIndex" | "getRowId" | "totalRowCount" | "sortState" | "filterState" | "filterJoin" | "searchText" | "groupLayout"> & Partial<Pick<DataGridStoreState, "groupMode" | "serverHeld">>;

type CountSource = Pick<DataGridStoreState, "selection" | "hiddenCheckedRowIds" | "data" | "viewIndex" | "totalRowCount" | "groupLayout"> & Partial<Pick<DataGridStoreState, "groupMode" | "serverHeld">>;

const excludedOutsideViewCache = new WeakMap<ReadonlySet<string>, { data: readonly unknown[]; viewIndex: readonly number[]; count: number }>();

function excludedOutsideView(s: CountSource, resolveRowIds: () => ReadonlyMap<string, number>): number {
  const excluded = s.hiddenCheckedRowIds;
  if (excluded.size === 0) return 0;
  const cached = excludedOutsideViewCache.get(excluded);
  if (cached && cached.data === s.data && cached.viewIndex === s.viewIndex) return cached.count;
  const dataRowById = resolveRowIds();
  let count = 0;
  for (const id of excluded) {
    const dataRow = dataRowById.get(id);
    if (dataRow === undefined || viewRowOfDataIndex(s.viewIndex, dataRow) < 0) count++;
  }
  excludedOutsideViewCache.set(excluded, { data: s.data, viewIndex: s.viewIndex, count });
  return count;
}

/**
 * The `count` of {@link readSelectedRows} in "all matching" mode without listing the ids: `totalRowCount`
 * minus the unchecked loaded view rows and the exclusions outside the view. Linear in the unchecked view rows and the exclusions; the row-id map is built on a cache miss.
 */
export function allMatchingCheckedCount(s: CountSource, resolveRowIds: () => ReadonlyMap<string, number>): number | null {
  const total = matchingRowTotal(s);
  if (typeof total !== "number") return null;
  const viewLength = s.viewIndex.length;
  let unchecked = 0;
  const countGap = (start: number, end: number): void => {
    for (let viewRow = start; viewRow < end; viewRow++) if (rowAtViewRow(s, viewRow) !== undefined) unchecked++;
  };
  let cursor = 0;
  for (const [start, end] of s.selection.rows.runs()) {
    countGap(cursor, Math.min(start, viewLength));
    cursor = Math.max(cursor, end);
  }
  countGap(cursor, viewLength);
  return Math.max(0, total - unchecked - excludedOutsideView(s, resolveRowIds));
}

/** Reads the checked rows as ids, or as "all matching except these ids". */
export function readSelectedRows(s: Source): DataGridSelectedRows {
  const { rows } = s.selection;
  if (!s.allMatching) {
    const ids: string[] = [];
    for (const [start, end] of rows.runs()) {
      for (let viewRow = start; viewRow < end; viewRow++) {
        const dataRow = dataIndexAt(s, viewRow);
        const record = dataRow === undefined ? undefined : s.data[dataRow];
        if (dataRow !== undefined && record !== undefined) ids.push(s.getRowId(record, dataRow));
      }
    }
    for (const id of s.hiddenCheckedRowIds) ids.push(id);
    return { mode: "ids", ids, excludedIds: [], count: ids.length };
  }
  const excluded = new Set(s.hiddenCheckedRowIds);
  // Walk the checked runs and the gaps between them; the unchecked rows are the gaps.
  const uncheckedGap = (start: number, end: number): void => {
    for (let viewRow = start; viewRow < end; viewRow++) {
      const dataRow = dataIndexAt(s, viewRow);
      const record = dataRow === undefined ? undefined : s.data[dataRow];
      if (record !== undefined) excluded.add(s.getRowId(record, dataRow!));
    }
  };
  let cursor = 0;
  for (const [start, end] of rows.runs()) {
    uncheckedGap(cursor, Math.min(start, s.viewIndex.length));
    for (let viewRow = start; viewRow < Math.min(end, s.viewIndex.length); viewRow++) {
      const dataRow = dataIndexAt(s, viewRow);
      const record = dataRow === undefined ? undefined : s.data[dataRow];
      if (record !== undefined && excluded.size > 0) excluded.delete(s.getRowId(record, dataRow!));
    }
    cursor = Math.max(cursor, end);
  }
  uncheckedGap(cursor, s.viewIndex.length);
  const total = matchingRowTotal(s);
  return {
    mode: "allMatching",
    ids: [],
    excludedIds: [...excluded],
    count: typeof total === "number" ? Math.max(0, total - excluded.size) : null,
    spec: serverSpecOf(s),
  };
}

import type { CellPatch, UpdateCellsOptions, UpdateCellsVerdict } from "./types";

type HeldPatch = { patch: CellPatch; options: UpdateCellsOptions };

/**
 * Holds `"stream"` patches whose row has a save in flight (verdict reason `"saving"`) and applies
 * them when the row's save settles, after the acknowledgement or the rollback. A later push to a
 * held cell replaces the held value.
 */
export function createStreamQueue(apply: (patches: readonly CellPatch[], options: UpdateCellsOptions) => void) {
  const held = new Map<string, Map<string, HeldPatch>>();

  const holdQueued = (patches: readonly CellPatch[], options: UpdateCellsOptions, verdict: UpdateCellsVerdict): void => {
    for (const skip of verdict.skipped) {
      if (skip.reason !== "saving") continue;
      const patch = patches[skip.patchIndex]!;
      let cells = held.get(patch.rowId);
      if (!cells) held.set(patch.rowId, (cells = new Map<string, HeldPatch>()));
      cells.delete(patch.columnId);
      cells.set(patch.columnId, { patch, options });
    }
  };

  return {
    hold(patches: readonly CellPatch[], options: UpdateCellsOptions, verdict: UpdateCellsVerdict): UpdateCellsVerdict {
      if (verdict.settled) void verdict.settled.then((settled) => holdQueued(patches, options, settled), () => {});
      else holdQueued(patches, options, verdict);
      return verdict;
    },
    /** Applies the held patches of every row that is no longer `"saving"` in `saveStatus`. */
    release(saveStatus: ReadonlyMap<string, string>): void {
      if (held.size === 0) return;
      const byOptions = new Map<UpdateCellsOptions, CellPatch[]>();
      for (const [rowId, cells] of held) {
        if (saveStatus.get(rowId) === "saving") continue;
        held.delete(rowId);
        for (const { patch, options } of cells.values()) {
          const group = byOptions.get(options);
          if (group) group.push(patch);
          else byOptions.set(options, [patch]);
        }
      }
      for (const [options, patches] of byOptions) apply(patches, options);
    },
  };
}

import { getCellValue } from "../columns/column-helpers";
import type { AnyColumnDef } from "../store/types";

/** The third argument of a function `validate`: the rows around the write, so a rule can compare a value with other rows. */
export type CellValidateContext<TData = unknown, TValue = unknown> = {
  /** The grid's rows before the write; an unloaded row of a scroll-mode grid is `undefined`. */
  rows: readonly (TData | undefined)[];
  /** Every cell of this column that the same write sets, this one included: one entry for an edit, one per cell of a paste, fill, clear, import, or `updateCells`. */
  batch: readonly { row: TData; value: TValue }[];
  /** The column's value of a row, as the grid reads it. */
  valueOf: (row: TData) => TValue;
};

/** Builds one context per column of a write, shared by every cell of that column. */
export function validateContextsFor(
  rows: readonly unknown[],
  columns: readonly AnyColumnDef[],
  cells: readonly { columnId: string; row: unknown; value: unknown }[],
): Map<string, CellValidateContext> {
  const contexts = new Map<string, CellValidateContext & { batch: { row: unknown; value: unknown }[] }>();
  for (const cell of cells) {
    let context = contexts.get(cell.columnId);
    if (!context) {
      const column = columns.find((c) => c.id === cell.columnId);
      context = { rows, batch: [], valueOf: (row) => (column ? getCellValue(row, column) : undefined) };
      contexts.set(cell.columnId, context);
    }
    context.batch.push({ row: cell.row, value: cell.value });
  }
  return contexts;
}

const countsByContext = new WeakMap<object, Map<unknown, number>>();

const isBlank = (value: unknown) => value === null || value === undefined || value === "";

/** Options of {@link unique}. */
export type UniqueOptions = {
  /** The error message. Default `"Must be unique"`. */
  message?: string;
  /** Compares text without regard to letter case. Default `false`. */
  ignoreCase?: boolean;
};

/**
 * A function `validate` that rejects a value another row of the column holds after the write, also a second cell of the same
 * paste or fill. Blank values (`null`, `undefined`, `""`) pass. It counts the rows once per write: `validate: unique()`.
 */
export function unique<TData = unknown, TValue = unknown>(options: UniqueOptions = {}): (value: TValue, row: TData, ctx: CellValidateContext<TData, TValue>) => string | null {
  const { message = "Must be unique", ignoreCase = false } = options;
  const keyOf = (value: unknown) => (ignoreCase && typeof value === "string" ? value.toLowerCase() : value);
  return (value, _row, ctx) => {
    if (isBlank(value)) return null;
    let counts = countsByContext.get(ctx);
    if (!counts) {
      counts = new Map();
      const written = new Set<unknown>(ctx.batch.map((cell) => cell.row));
      const add = (v: unknown) => {
        if (!isBlank(v)) counts!.set(keyOf(v), (counts!.get(keyOf(v)) ?? 0) + 1);
      };
      for (const other of ctx.rows) if (other !== undefined && !written.has(other)) add(ctx.valueOf(other));
      for (const cell of ctx.batch) add(cell.value);
      countsByContext.set(ctx, counts);
    }
    return (counts.get(keyOf(value)) ?? 0) > 1 ? message : null;
  };
}

import type { StoreApi } from "zustand/vanilla";
import { toSafeText } from "../cell-types/safe-text";
import { warnDev } from "../is-dev";
import type { PivotSpec } from "../group-types";
import type { FilterNode, SortSpec } from "../types";
import type { DataGridStoreState, InternalSyncProps } from "./types";

/** A seed prop's value, or nothing for a function seed: the store starts empty and {@link applyFunctionSeeds} fills it after mount. */
export const plainSeed = <T>(seed: T | undefined): Exclude<T, () => unknown> | undefined => (typeof seed === "function" ? undefined : (seed as Exclude<T, () => unknown>));

function readSeed(name: string, seed: unknown): unknown {
  if (typeof seed !== "function") return undefined;
  try {
    return (seed as () => unknown)();
  } catch (error) {
    warnDev(`${name} threw, so the grid keeps its first state: ${toSafeText(error)}`);
    return undefined;
  }
}

const seededStores = new WeakSet<object>();

/** Calls each function seed once per store on the client after mount and applies what it returns; a controlled prop wins as with a plain seed. */
export function applyFunctionSeeds(store: StoreApi<DataGridStoreState>, init: InternalSyncProps): void {
  if (seededStores.has(store)) return;
  seededStores.add(store);
  warnIgnoredSeeds(init);
  const { actions } = store.getState();
  const sorts = init.sortState === undefined ? readSeed("defaultSortState", init.defaultSortState) : undefined;
  if (Array.isArray(sorts)) actions.setSorts(sorts as SortSpec[]);
  const groupBy = init.groupBy === undefined ? readSeed("defaultGroupBy", init.defaultGroupBy) : undefined;
  if (Array.isArray(groupBy)) actions.setGroupBy(groupBy as string[]);
  const pivot = init.pivot === undefined ? readSeed("defaultPivot", init.defaultPivot) : undefined;
  if (pivot !== null && typeof pivot === "object") actions.setPivot(pivot as PivotSpec);
  const filters = init.filterState === undefined ? readSeed("defaultFilterState", init.defaultFilterState) : undefined;
  if (Array.isArray(filters)) actions.setFilters(filters as FilterNode[]);
  const search = init.searchText === undefined ? readSeed("defaultSearchText", init.defaultSearchText) : undefined;
  if (typeof search === "string") actions.setSearch(search);
  const layout = init.columnLayout === undefined ? readSeed("defaultColumnLayout", init.defaultColumnLayout) : undefined;
  if (layout !== null && typeof layout === "object") actions.setColumnLayout(layout);
}

const CONTROLLED_SEEDS = [
  ["defaultSortState", "sortState"],
  ["defaultFilterState", "filterState"],
  ["defaultSearchText", "searchText"],
  ["defaultGroupBy", "groupBy"],
  ["defaultExpanded", "expanded"],
  ["defaultPivot", "pivot"],
] as const;

function warnIgnoredSeeds(init: InternalSyncProps): void {
  for (const [seed, controlled] of CONTROLLED_SEEDS) {
    if (init[seed] !== undefined && init[controlled] !== undefined) {
      warnDev(`${seed} is ignored because ${controlled} is controlled. Seed the owner of ${controlled} instead; for a server grid, pass defaultSpec to useDataGridServerRows.`);
    }
  }
}

/** `"drag"` while a pointer drag still moves the selection; `"end"` for a settled selection. */
export type SelectionChangePhase = "drag" | "end";

export type SelectionChangeDetails = {
  /** Raw cell VALUES (not clipboard text) over the primary range, view-row-major: `values[0][0]` is the range's top-left cell. */
  getValues: () => unknown[][];
  /** Row ids of every selected row, view order, across both the row channel (checkboxes) and any cell range. */
  getRowIds: () => string[];
  /** `"drag"` for each step of a pointer drag after the press, `"end"` for the press, the release after a drag, and every other change. */
  phase: SelectionChangePhase;
};

import { savedColumnWidth } from "./resolve-column-width";

/** The width step of Widen column and Narrow column, in px. */
export const COLUMN_WIDTH_STEP = 16;

/** The width a column shows, flex growth included: its rendered header, else its saved width, its `width`, or 150. */
export function shownColumnWidth(scrollRoot: Element | null | undefined, column: { id: string; width?: number }, widths: Record<string, number>): number {
  const header = scrollRoot?.querySelector(`[role="columnheader"][data-column-id="${CSS.escape(column.id)}"]`);
  return header?.getBoundingClientRect().width || savedColumnWidth(widths, column.id) || column.width || 150;
}

import type { ColumnGroupModel } from "../columns/column-groups";
import { columnFlag, completeColumnOrder, pinZone, reorderColumnIds, reorderGroupBlock } from "./compute";
import type { AnyColumnDef } from "./types";

/**
 * Why `setColumnOrder` did not move: `"disabled"` — `enableColumnReorder` is `false`; `"unknown-column"` — `id` or
 * `targetId` names no column or group; `"not-reorderable"` — the column, the target, or a group member has
 * `reorderable: false`; `"pin-zone"` — the target sits in another pin zone, or a group's members span two zones; `"nothing-to-do"` — the move keeps the order.
 */
export type ColumnOrderSkipReason = "disabled" | "unknown-column" | "not-reorderable" | "pin-zone" | "nothing-to-do";

/** What `setColumnOrder` and `canSetColumnOrder` return: `ok` when the move changes the order, else the reason it does not. */
export type ColumnOrderResult = { ok: true } | { ok: false; reason: ColumnOrderSkipReason };

type ColumnOrderInput = {
  columns: readonly AnyColumnDef[];
  columnOrder: readonly string[] | null;
  enableColumnReorder: boolean;
};

const skip = (reason: ColumnOrderSkipReason) => ({ result: { ok: false, reason } as const });
const sameOrder = (a: readonly string[], b: readonly string[]) => a.length === b.length && a.every((id, index) => id === b[index]);

/** The order a move produces, or the reason it changes nothing. */
export function planColumnOrder(
  s: ColumnOrderInput,
  groups: ColumnGroupModel | null | undefined,
  id: string,
  targetId: string,
  position: "before" | "after",
): { result: ColumnOrderResult; order?: string[] } {
  if (!s.enableColumnReorder) return skip("disabled");
  const target = s.columns.find((c) => c.id === targetId);
  const currentIds = completeColumnOrder(s.columns, s.columnOrder, groups);
  if (groups?.groups.has(id)) {
    const members = s.columns.filter((c) => groups.paths.get(c.id)?.includes(id));
    if (!target) return skip("unknown-column");
    if (!columnFlag(target, "reorderable") || members.some((c) => !columnFlag(c, "reorderable"))) return skip("not-reorderable");
    if (members.some((c) => pinZone(c) !== pinZone(target))) return skip("pin-zone");
    const order = reorderGroupBlock(currentIds, s.columns, groups, id, targetId, position);
    return sameOrder(order, currentIds) ? skip("nothing-to-do") : { result: { ok: true }, order };
  }
  const column = s.columns.find((c) => c.id === id);
  if (!column || !target) return skip("unknown-column");
  if (!columnFlag(column, "reorderable") || !columnFlag(target, "reorderable")) return skip("not-reorderable");
  if (pinZone(column) !== pinZone(target)) return skip("pin-zone");
  const order = reorderColumnIds(currentIds, s.columns, id, targetId, position, groups);
  return sameOrder(order, currentIds) ? skip("nothing-to-do") : { result: { ok: true }, order };
}

import { GateRun, type GateWatch } from "./gate-signal";
import { gateTrackerOf } from "./internal-actions";

/** Starts the `"validate"` gate for a batch that an async schema holds; it shows in `gatesPending` until it settles. */
export function holdValidateGate(store: object | undefined, watch?: GateWatch): GateRun {
  const run = new GateRun("validate", watch);
  if (store) gateTrackerOf(store)?.hold(run);
  return run;
}

/** Ends the run; `false` when it was aborted (`gateTimeoutMs`, Escape, a newer batch, a reset), so the held batch drops. */
export function settleValidateGate(store: object | undefined, run: GateRun): boolean {
  if (store) gateTrackerOf(store)?.settle(run);
  return !run.aborted;
}

import type { DataGridStoreState } from "./types";

type WarnOnce = (key: string, message: string) => void;

/** Dev-warns once per grid when a sort or filter change lands on a server-mode part that no `onSortChange` or `onFilterChange` handles, so no request carries it. */
export function warnUnhandledServerSpec(state: DataGridStoreState, prev: DataGridStoreState, warn: WarnOnce): void {
  if (state.sortState !== prev.sortState && state.sortMode === "server" && state.onSortChange === undefined) {
    warn("unhandled server sort", 'the sort changed, but sortMode is "server" (totalRowCount sets it by default) and nothing handles onSortChange, so no request carries it and the rows keep their order. Pass onSortChange and sortState to your fetch, or set sortMode="client"');
  }
  if (state.filterState !== prev.filterState && state.filterMode === "server" && state.onFilterChange === undefined) {
    warn("unhandled server filter", 'the filters changed, but filterMode is "server" (totalRowCount sets it by default) and nothing handles onFilterChange, so no request carries them and the rows stay. Pass onFilterChange and filterState to your fetch, or set filterMode="client"');
  }
}

import type { DataChange } from "../types";

/** Fills `beforeRowId` and `afterRowId` of each move that has neither (an undo, a redo, or an app batch) from the data after the batch. */
export function withMoveNeighbors(change: DataChange<unknown>, nextData: readonly unknown[], getRowId: (row: unknown, index: number) => string): DataChange<unknown> {
  if (!change.ops.some((op) => op.type === "move" && op.beforeRowId === undefined && op.afterRowId === undefined)) return change;
  let indexOf: Map<string, number> | null = null;
  const idAt = (index: number) => (nextData[index] === undefined ? undefined : getRowId(nextData[index], index));
  const ops = change.ops.map((op) => {
    if (op.type !== "move" || op.beforeRowId !== undefined || op.afterRowId !== undefined) return op;
    let at: number | undefined = op.to;
    if (idAt(at) !== op.rowId) at = (indexOf ??= new Map(nextData.map((row, index) => [row === undefined ? "" : getRowId(row, index), index]))).get(op.rowId);
    if (at === undefined) return op;
    const beforeRowId = idAt(at + 1);
    const afterRowId = idAt(at - 1);
    return { ...op, ...(beforeRowId !== undefined && { beforeRowId }), ...(afterRowId !== undefined && { afterRowId }) };
  });
  return { ...change, ops };
}

import type { DataChange, DataOp } from "../types";
import type { DataGridActions } from "./types";

/** One refusal in a {@link SaveAck}: the row the server refused, and optionally one of its columns. */
export type SaveRejection<TData = unknown> = {
  rowId: string;
  /** Limits the refusal to this column of an update; omitted, every entry of the row is refused. */
  columnId?: string;
  /** Display text for `onSaveRejected`; the grid does not render it. */
  message?: string;
  /** Keeps the refused value and marks its cells with `message` instead of reverting. Default `false`. */
  keep?: boolean;
  /** Set by the grid: `"timeout"` marks a refusal because `onSave` outlived `saveTimeoutMs`. */
  reason?: "timeout";
  /**
   * The row as the server holds it now. The revert puts this row in place of the refused one, unless a newer
   * write to the row is pending. A refused delete restores it; a refused insert removes the row. The row's
   * id must equal `rowId`, otherwise the grid does a plain revert.
   */
  current?: TData;
};

/** The second argument of `onSave`. */
export type SaveContext = {
  /** The grid's actions, so a save can write the server's answer back without a grid ref. */
  actions: DataGridActions;
  /** Aborts when the grid unmounts or `saveTimeoutMs` runs out; pass it to `fetch`. */
  signal: AbortSignal;
};

/** Hands a throw of a consumer callback to the page (`reportError`), or to `console.error` where the platform has none. */
export function reportCallbackError(message: string, error: unknown): void {
  const report = (globalThis as { reportError?: (error: unknown) => void }).reportError;
  if (typeof report === "function") report(error);
  else console.error(`[data-grid] ${message}`, error);
}

/** The error a save that outlived `saveTimeoutMs` settles with. */
export class SaveTimeoutError extends Error {
  constructor(ms: number) {
    super(`onSave did not settle within ${ms} ms`);
    this.name = "SaveTimeoutError";
  }
}

/** What a promise returned by `onSave` resolves with. `void` accepts the whole change. */
export type SaveAck<TData = unknown> = void | { rejected?: readonly SaveRejection<TData>[] };

/** Context of `onSaveRejected`. */
export type SaveRejectedContext<TData> = {
  /** The change `onSave` received. */
  change: DataChange<TData>;
  /** After an id swap (`replaceRowId`) the entries carry the new ids, while `change` keeps the ids it had. */
  rejected: readonly SaveRejection<TData>[];
  /** The rejection reason of the `onSave` promise; `null` when it resolved with `{ rejected }`. */
  error: unknown;
  /** `true` when the grid wrote a revert; `false` when every refused entry set `keep` or nothing was left to revert. */
  reverted: boolean;
};

/** What `resolveSaveConflict` receives for one refused row that has a usable `current`. */
export type SaveConflictContext<TData> = {
  rowId: string;
  /** The row in the grid now. */
  mine: TData;
  /** The server's row (`SaveRejection.current`). */
  theirs: TData;
  /** The refused change `onSave` received. */
  change: DataChange<TData>;
  /** `SaveRejection.message`. */
  message?: string;
  /** Aborts when a newer write to the row starts or the grid unmounts; an answer after that is ignored. */
  signal: AbortSignal;
};

/** The answer of `resolveSaveConflict`: take the server's row, keep the grid's row, or save a merged row. */
export type SaveResolution<TData> = "theirs" | "mine" | { row: TData } | void;

/** Status of a row with an acknowledged write: pending, or refused and reverted. */
export type RowSaveStatus = "saving" | "failed";

export const EMPTY_SAVE_STATUS: ReadonlyMap<string, RowSaveStatus> = new Map();

/** The grid reads at most this many rejections of one ack. */
export const MAX_WRITE_REJECTIONS = 10_000;

/** The rejections of a settled ack: a thrown error or more than {@link MAX_WRITE_REJECTIONS} rejections refuse every row of the change; a malformed ack keeps its valid entries. */
export function readRejections(change: DataChange<unknown>, ack: SaveAck, error: unknown, failed: boolean, warn?: (key: string, message: string) => void): SaveRejection[] {
  const rejected = ack?.rejected;
  if (!failed && Array.isArray(rejected) && rejected.length > MAX_WRITE_REJECTIONS) {
    warn?.("rejection bound", `an onSave answer listed more than ${MAX_WRITE_REJECTIONS} rejections, so the grid refuses every row of that change. Send at most ${MAX_WRITE_REJECTIONS} rejections, or reject with an error`);
    return readRejections(change, undefined, undefined, true);
  }
  if (failed) {
    const message = error instanceof Error ? error.message : undefined;
    const reason = error instanceof SaveTimeoutError ? ({ reason: "timeout" } as const) : {};
    return [...new Set(change.ops.map((op) => op.rowId))].map((rowId) => ({ rowId, ...(message === undefined ? {} : { message }), ...reason }));
  }
  if (!Array.isArray(rejected)) return [];
  const out: SaveRejection[] = [];
  for (const entry of rejected as readonly unknown[]) {
    if (typeof entry !== "object" || entry === null || typeof (entry as SaveRejection).rowId !== "string") continue;
    const { rowId, columnId, message, current, keep } = entry as SaveRejection;
    out.push({
      rowId,
      ...(typeof columnId === "string" ? { columnId } : {}),
      ...(typeof message === "string" ? { message } : {}),
      ...(keep === true ? { keep } : {}),
      ...(current !== undefined && current !== null ? { current } : {}),
    });
  }
  return out;
}

/** The `change.ops` entries that `rejected` refuses; a cell-level update keeps only its refused cells. */
export function refusedOps(change: DataChange<unknown>, rejected: readonly SaveRejection[]): DataOp<unknown>[] {
  const wholeRows = new Set<string>();
  const cellsByRow = new Map<string, Set<string>>();
  for (const { rowId, columnId } of rejected) {
    if (columnId === undefined) wholeRows.add(rowId);
    else (cellsByRow.get(rowId) ?? cellsByRow.set(rowId, new Set()).get(rowId)!).add(columnId);
  }
  const ops: DataOp<unknown>[] = [];
  for (const op of change.ops) {
    if (wholeRows.has(op.rowId)) {
      ops.push(op);
      continue;
    }
    const columns = cellsByRow.get(op.rowId);
    if (!columns) continue;
    if (op.type !== "update" || !op.cells) {
      ops.push(op);
      continue;
    }
    const cells = op.cells.filter((cell) => columns.has(cell.columnId));
    if (cells.length > 0) ops.push({ ...op, cells });
  }
  return ops;
}

import { nextAnnouncement } from "./announcements";
import { isThenable } from "./async-gate";
import { buildRollback } from "../interaction/rollback";
import { createWarnOnce, warnDev } from "../is-dev";
import type { DataWriteContext } from "./data-write";
import { EMPTY_SAVE_STATUS, readRejections, refusedOps, reportCallbackError, SaveTimeoutError, type RowSaveStatus, type SaveAck, type SaveRejection, type SaveResolution } from "./write-ack";
import type { DataChange, DataOp } from "../types";
import type { DataGridStoreState } from "./types";

type SetState = (partial: Partial<DataGridStoreState>) => void;
type GetState = () => DataGridStoreState;

/** The acknowledged-save bookkeeping of one grid: pending and failed rows, refusal chains, conflict resolution, and the save status it publishes. */
export type SaveTracker = {
  /** Moves everything keyed by `oldId` to `newId`. */
  renameRow(oldId: string, newId: string): void;
  /** Drops the `failed` marks and publishes the status. */
  clearFailed(): void;
  publishSaveStatus(): void;
};

export function createSaveTracker(set: SetState, get: GetState, ctx: DataWriteContext): SaveTracker {
  const warnGateOnce = createWarnOnce();
  const pendingByRow = new Map<string, number>();
  const latestWriteOfRow = new Map<string, number>();
  const failedRows = new Set<string>();
  let writeSeq = 0;
  let pendingSaves = 0;
  // Refused cell value -> the value it replaced, so a second refusal on the same cell reverts past the first refused value.
  const refusedPrev = new Map<string, Map<string, Map<unknown, unknown>>>();
  const MAX_FAILED_ROWS = 10_000;
  const MAX_CHAINED_ROWS = 10_000;
  const dropChains = (rowId: string): void => {
    refusedPrev.delete(rowId);
  };
  const chainRefusedPrev = (ops: DataOp<unknown>[]): DataOp<unknown>[] =>
    ops.map((op) => {
      if (op.type !== "update" || !op.cells) return op;
      const cells = op.cells.map((cell) => {
        const byColumn = refusedPrev.get(op.rowId) ?? new Map<string, Map<unknown, unknown>>();
        const chain = byColumn.get(cell.columnId) ?? new Map<unknown, unknown>();
        const prev = chain.has(cell.prev) ? chain.get(cell.prev) : cell.prev;
        chain.set(cell.value, prev);
        byColumn.set(cell.columnId, chain);
        refusedPrev.set(op.rowId, byColumn);
        return { ...cell, prev };
      });
      return { ...op, cells };
    });
  let warnedCurrentRowId = false;
  /** The `current` rows of the rejections that may replace a row: its id matches, the change holds no insert of it, and no newer write is pending. */
  const usableCurrentRows = (
    s: DataGridStoreState,
    change: DataChange<unknown>,
    rejected: readonly SaveRejection[],
    seq: number,
    deleteOps: ReadonlyMap<string, { index: number }>,
  ): Map<string, unknown> => {
    const usable = new Map<string, unknown>();
    const inserted = new Set(change.ops.flatMap((op) => (op.type === "insert" ? [op.rowId] : [])));
    for (const { rowId, current } of rejected) {
      // A newer write to the row, pending or already accepted, makes the server's row older than the grid's.
      if (current === undefined || inserted.has(rowId) || pendingByRow.has(rowId) || latestWriteOfRow.get(rowId) !== seq) continue;
      const index = deleteOps.get(rowId)?.index ?? 0;
      let currentId: string | undefined;
      try {
        currentId = s.getRowId(current, index);
      } catch {
        currentId = undefined;
      }
      if (currentId !== rowId) {
        if (!warnedCurrentRowId) {
          warnedCurrentRowId = true;
          warnDev(`SaveRejection.current for row "${rowId}" has another id, so it was ignored and the change was reverted in place`);
        }
        continue;
      }
      usable.set(rowId, current);
    }
    return usable;
  };
  /** One `change.ops` entry per `current` row: replace the row in the data, or re-insert a deleted row as the server holds it. */
  const currentRowOps = (s: DataGridStoreState, currentRows: ReadonlyMap<string, unknown>, deleteOps: ReadonlyMap<string, { index: number }>): DataOp<unknown>[] => {
    if (currentRows.size === 0) return [];
    const dataIndexById = ctx.rowIndexCache.resolve(s.data, s.getRowId);
    const ops: DataOp<unknown>[] = [];
    for (const [rowId, current] of currentRows) {
      const index = dataIndexById.get(rowId);
      if (index !== undefined) {
        ops.push({ type: "update", rowId, row: current, prev: s.data[index] });
        continue;
      }
      const deleted = deleteOps.get(rowId);
      if (deleted) ops.push({ type: "insert", rowId, row: current, index: deleted.index });
    }
    return ops;
  };
  /** The `"merge"` updates for rows whose resolver kept the user's intent (`"mine"` or a merged row) on top of the server's row. */
  const mergeOpsOf = (s: DataGridStoreState, currentRows: ReadonlyMap<string, unknown>, answers: ReadonlyMap<string, SaveResolution<unknown>>): DataOp<unknown>[] => {
    const ops: DataOp<unknown>[] = [];
    if (answers.size === 0 || currentRows.size === 0) return ops;
    const dataIndexById = ctx.rowIndexCache.resolve(s.data, s.getRowId);
    for (const [rowId, theirs] of currentRows) {
      const answer = answers.get(rowId);
      if (answer === undefined || answer === "theirs") continue;
      const index = dataIndexById.get(rowId);
      if (index === undefined) continue;
      let target: unknown = s.data[index];
      if (answer !== "mine") {
        const merged = (answer as { row: unknown }).row;
        let mergedId: string | undefined;
        try {
          mergedId = merged === undefined || merged === null ? undefined : s.getRowId(merged, index);
        } catch {
          mergedId = undefined;
        }
        if (mergedId !== rowId) {
          warnGateOnce("merged row id", `resolveSaveConflict returned a row that does not have the id "${rowId}", so the server's row is taken`);
          continue;
        }
        target = merged;
      }
      ops.push({ type: "update", rowId, row: target, prev: theirs });
    }
    return ops;
  };
  /** An acknowledged write in flight; `alias` maps the row ids it was tracked under to the ids a swap gave them since. */
  type LiveWrite = { rowIds: Set<string>; alias: Map<string, string>; origin: Map<string, string> };
  const liveWrites = new Set<LiveWrite>();
  const retargetLiveWrites = (oldId: string, newId: string): void => {
    for (const write of liveWrites) {
      const origin = write.origin.get(oldId) ?? (write.rowIds.has(oldId) && !write.alias.has(oldId) ? oldId : undefined);
      if (origin === undefined) continue;
      write.alias.set(origin, newId);
      write.origin.delete(oldId);
      write.origin.set(newId, origin);
    }
  };
  const resolvingRows = new Map<string, number>();
  const conflictAborts = new Map<string, AbortController>();
  const saveAborts = new Set<AbortController>();
  ctx.abortConflicts = () => {
    for (const controller of conflictAborts.values()) controller.abort();
    conflictAborts.clear();
    for (const controller of saveAborts) controller.abort();
    saveAborts.clear();
  };
  const publishSaveStatus = (): void => {
    const status = new Map<string, RowSaveStatus>();
    for (const rowId of failedRows) status.set(rowId, "failed");
    for (const rowId of pendingByRow.keys()) status.set(rowId, "saving");
    for (const rowId of resolvingRows.keys()) status.set(rowId, "saving");
    for (const rowId of latestWriteOfRow.keys()) if (!status.has(rowId)) latestWriteOfRow.delete(rowId);
    set({ saveStatus: status.size === 0 ? EMPTY_SAVE_STATUS : status, pendingSaveCount: pendingSaves });
  };
  /** Marks the cells of `keep` entries: the entry's column, or every refused cell of its row. */
  const markKeptCells = (s: DataGridStoreState, change: DataChange<unknown>, kept: readonly SaveRejection[]): void => {
    if (kept.length === 0) return;
    const entries: { rowId: string; columnId: string; message: string }[] = [];
    const fallback = s.labels.grid.saveRejected(1);
    for (const entry of kept) {
      const message = entry.message ?? fallback;
      if (entry.columnId !== undefined) {
        entries.push({ rowId: entry.rowId, columnId: entry.columnId, message });
        continue;
      }
      for (const op of refusedOps(change, [entry])) if (op.type === "update") for (const cell of op.cells ?? []) entries.push({ rowId: op.rowId, columnId: cell.columnId, message });
    }
    if (entries.length > 0) s.actions.setCellErrors(entries);
  };
  const normalizeResolution = (answer: unknown): SaveResolution<unknown> => {
    if (answer === "mine") return "mine";
    if (typeof answer === "object" && answer !== null && (answer as { row?: unknown }).row != null) return answer as { row: unknown };
    return "theirs";
  };
  ctx.trackWrite = (change, result, controller) => {
    const rowIds = [...new Set(change.ops.map((op) => op.rowId))];
    const write: LiveWrite = { rowIds: new Set(rowIds), alias: new Map(), origin: new Map() };
    const liveId = (rowId: string): string => write.alias.get(rowId) ?? rowId;
    liveWrites.add(write);
    const seq = ++writeSeq;
    for (const rowId of rowIds) {
      pendingByRow.set(rowId, (pendingByRow.get(rowId) ?? 0) + 1);
      latestWriteOfRow.set(rowId, seq);
      failedRows.delete(rowId);
      conflictAborts.get(rowId)?.abort();
      conflictAborts.delete(rowId);
    }
    pendingSaves += 1;
    publishSaveStatus();
    const settle = (ack: SaveAck, error: unknown, failed: boolean): void => {
      if (ctx.disposed) return;
      const ids = rowIds.map(liveId);
      for (const rowId of ids) {
        const left = (pendingByRow.get(rowId) ?? 1) - 1;
        if (left > 0) pendingByRow.set(rowId, left);
        else pendingByRow.delete(rowId);
      }
      pendingSaves -= 1;
      const rejectedAtSettle = readRejections(change, ack, error, failed, warnGateOnce);
      const refusedAtSettle = new Set(rejectedAtSettle.map((entry) => liveId(entry.rowId)));
      // A chain only bridges writes that overlap in flight; an accepted write or an idle row ends it.
      for (const rowId of ids) if (!refusedAtSettle.has(rowId) && !pendingByRow.has(rowId)) dropChains(rowId);
      if (rejectedAtSettle.length === 0) {
        liveWrites.delete(write);
        publishSaveStatus();
        return;
      }
      const originOf = new Map(ids.map((id, i) => [id, rowIds[i]!] as const));
      const view = () => {
        const retarget = write.alias.size > 0;
        const rejected = retarget ? rejectedAtSettle.map((entry) => ({ ...entry, rowId: liveId(entry.rowId) })) : rejectedAtSettle;
        const aliased = retarget ? { ...change, ops: change.ops.map((op) => (write.alias.has(op.rowId) ? { ...op, rowId: liveId(op.rowId) } : op)) } : change;
        const deleteOps = new Map(aliased.ops.flatMap((op) => (op.type === "delete" ? [[op.rowId, op] as const] : [])));
        return { rejected, aliased, deleteOps, refusedRows: new Set(rejected.map((entry) => entry.rowId)) };
      };
      const asked = new Map<string, { controller: AbortController; answer?: SaveResolution<unknown> }>();
      const waiting: PromiseLike<void>[] = [];
      const first = get();
      const resolver = first.readOnly ? undefined : first.resolveSaveConflict;
      const start = view();
      if (resolver) {
        const dataIndexById = ctx.rowIndexCache.resolve(first.data, first.getRowId);
        const messageById = new Map<string, string>();
        for (const entry of start.rejected) if (entry.message !== undefined && !messageById.has(entry.rowId)) messageById.set(entry.rowId, entry.message);
        for (const [rowId, theirs] of usableCurrentRows(first, start.aliased, start.rejected, seq, start.deleteOps)) {
          const index = dataIndexById.get(rowId);
          if (index === undefined) continue;
          const controller = new AbortController();
          conflictAborts.set(rowId, controller);
          const entry: { controller: AbortController; answer?: SaveResolution<unknown> } = { controller };
          asked.set(originOf.get(rowId) ?? rowId, entry);
          const message = messageById.get(rowId);
          let answer: SaveResolution<unknown> | PromiseLike<SaveResolution<unknown>>;
          try {
            answer = resolver({ rowId, mine: first.data[index], theirs, change: start.aliased, ...(message === undefined ? {} : { message }), signal: controller.signal });
          } catch (callbackError) {
            reportCallbackError("resolveSaveConflict threw, so the server's row is taken:", callbackError);
            continue;
          }
          if (!isThenable<SaveResolution<unknown>>(answer)) {
            entry.answer = normalizeResolution(answer);
            continue;
          }
          const aborted = new Promise<void>((resolve) => {
            if (controller.signal.aborted) resolve();
            else controller.signal.addEventListener("abort", () => resolve(), { once: true });
          });
          waiting.push(
            Promise.race([
              aborted,
              Promise.resolve(answer).then(
                (resolved) => void (entry.answer = normalizeResolution(resolved)),
                (callbackError: unknown) => void reportCallbackError("resolveSaveConflict rejected, so the server's row is taken:", callbackError),
              ),
            ]),
          );
        }
      }
      const finish = (): void => {
        const { rejected, aliased, deleteOps, refusedRows } = view();
        const s = get();
        const kept = rejected.filter((entry) => entry.keep === true);
        const reverting = kept.length === 0 ? rejected : rejected.filter((entry) => entry.keep !== true);
        let reverted = false;
        markKeptCells(s, aliased, kept);
        try {
          if (refusedPrev.size > MAX_CHAINED_ROWS) refusedPrev.clear();
          const currentRows = usableCurrentRows(s, aliased, reverting, seq, deleteOps);
          const answers = new Map<string, SaveResolution<unknown>>();
          for (const [origin, entry] of asked) {
            const id = liveId(origin);
            if (entry.controller.signal.aborted) currentRows.delete(id);
            else if (entry.answer !== undefined) answers.set(id, entry.answer);
          }
          const mergeOps = mergeOpsOf(s, currentRows, answers);
          // A row with a usable `current` gets its content from it; only a move of it reverts in place.
          const plainOps = refusedOps(aliased, reverting).filter((op) => !(currentRows.has(op.rowId) && (op.type === "update" || op.type === "delete")));
          const revert = buildRollback({ ops: chainRefusedPrev(plainOps), source: "rollback" }, s);
          const ops = [...revert.ops, ...currentRowOps(s, currentRows, deleteOps)];
          const serverRowIds = [...currentRows.keys()];
          reverted = ops.length > 0;
          try {
            if (ops.length > 0) s.actions.commitChange({ ...revert, ops, reverts: change, ...(serverRowIds.length > 0 ? { serverRowIds } : {}) });
          } catch (error) {
            reportCallbackError("the revert of a refused save threw in a callback:", error);
          }
          try {
            if (mergeOps.length > 0) s.actions.commitChange({ source: "merge", ops: mergeOps, reverts: change, serverRowIds: mergeOps.map((op) => op.rowId) });
          } catch (error) {
            reportCallbackError("the merge of a save conflict threw in a callback:", error);
          }
        } catch (error) {
          reportCallbackError("the revert of a refused save failed:", error);
        }
        for (const [origin, entry] of asked) if (conflictAborts.get(liveId(origin)) === entry.controller) conflictAborts.delete(liveId(origin));
        for (const rowId of refusedRows) if (!pendingByRow.has(rowId)) dropChains(rowId);
        for (const { rowId } of rejected) {
          if (latestWriteOfRow.get(rowId) !== seq) continue;
          if (failedRows.size >= MAX_FAILED_ROWS) failedRows.delete(failedRows.values().next().value!);
          failedRows.add(rowId);
        }
        const liveIds = new Set(rowIds.map(liveId));
        const refusedInChange = [...refusedRows].filter((rowId) => liveIds.has(rowId)).length;
        set({ liveAnnouncement: nextAnnouncement(get().liveAnnouncement, "saveRejected", refusedInChange) });
        liveWrites.delete(write);
        publishSaveStatus();
        const onSaveRejected = get().onSaveRejected;
        if (!onSaveRejected) return;
        try {
          onSaveRejected({ change, rejected, error: failed ? error : null, reverted });
        } catch (callbackError) {
          reportCallbackError("onSaveRejected threw:", callbackError);
        }
      };
      if (waiting.length === 0) {
        finish();
        return;
      }
      const held = [...start.refusedRows].filter((id) => originOf.has(id)).map((id) => originOf.get(id)!);
      for (const rowId of held) resolvingRows.set(rowId, (resolvingRows.get(rowId) ?? 0) + 1);
      publishSaveStatus();
      void Promise.all(waiting).then(() => {
        for (const origin of held) {
          const rowId = liveId(origin);
          const left = (resolvingRows.get(rowId) ?? 1) - 1;
          if (left > 0) resolvingRows.set(rowId, left);
          else resolvingRows.delete(rowId);
        }
        if (ctx.disposed) return;
        finish();
      });
    };
    let timer: ReturnType<typeof setTimeout> | undefined;
    let settled = false;
    const settleOnce = (ack: SaveAck, error: unknown, failed: boolean): void => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      saveAborts.delete(controller);
      settle(ack, error, failed);
    };
    saveAborts.add(controller);
    const timeoutMs = get().saveTimeoutMs;
    if (typeof timeoutMs === "number" && timeoutMs > 0 && Number.isFinite(timeoutMs)) {
      timer = setTimeout(() => {
        controller.abort();
        settleOnce(undefined, new SaveTimeoutError(timeoutMs), true);
      }, timeoutMs);
    }
    Promise.resolve(result).then(
      (ack) => settleOnce(ack, undefined, false),
      (error: unknown) => settleOnce(undefined, error, true),
    );
  };

  return {
    renameRow(oldId, newId) {
      for (const map of [pendingByRow, latestWriteOfRow, resolvingRows, conflictAborts] as Map<string, unknown>[]) {
        if (!map.has(oldId)) continue;
        map.set(newId, map.get(oldId));
        map.delete(oldId);
      }
      if (failedRows.delete(oldId)) failedRows.add(newId);
      const chains = refusedPrev.get(oldId);
      if (chains) {
        refusedPrev.set(newId, chains);
        refusedPrev.delete(oldId);
      }
      retargetLiveWrites(oldId, newId);
    },
    clearFailed() {
      if (failedRows.size === 0) return;
      failedRows.clear();
      publishSaveStatus();
    },
    publishSaveStatus,
  };
}

import type { DataChange } from "../types";

/** How a `updateCells`/`updateRows` batch reconciles with an active sort or filter. */
export type UpdateCellsReorder = "defer" | "immediate" | "frame" | "never";

/** Options for {@link DataGridActions.updateCells} and {@link DataGridActions.updateRows}. */
export type UpdateCellsOptions = {
  /**
   * Default `"defer"`.
   * - `"defer"` — values update in place and rows keep their view position; `viewStale` flips.
   *   The view reconciles on the next sort/filter/search change, or on `reconcileView()`. A
   *   `"defer"` batch that touches no active sort or filter column downgrades to `"never"`
   *   automatically, so `viewStale` never flips for a ticker on a non-sort column.
   * - `"immediate"` — moves the patched rows to their new positions now, by removing each one,
   *   re-testing filter membership, and binary-searching it back in under the same comparator chain
   *   a full sort uses. Cost scales with the batch size, not the row count: measured 0.3 / 0.9 /
   *   7.6 ms for 1 / 20 / 256 patched rows at 100k. Batches over
   *   {@link INCREMENTAL_PATCH_LIMIT} rows or a same-tick sort/filter change fall back to the full
   *   O(n log n) rebuild; a column with its own comparator keeps the incremental path.
   * - `"frame"` — values update in place now and the patched rows keep their position until the next
   *   animation frame, when one re-place covers every row touched since the last one (without
   *   `requestAnimationFrame`, after 16 ms). `viewStale` stays `false`. `reconcileView()` runs the
   *   pending re-place now. A batch that touches no active sort or filter column downgrades to
   *   `"never"`. With a server-sorted view it follows the `"defer"` rule.
   * - `"never"` — updates in place and never marks the view stale. The caller asserts that no
   *   touched column feeds the sort or filter.
   */
  reorder?: UpdateCellsReorder;
  /** `DataChange` source tag. `"stream"` is a push from the server; `"edit"` is a user edit and makes the batch undoable. A call without it writes nothing and skips each patch with reason `"no-source"`. */
  source: DataChange<unknown>["source"];
  /** Skips each column's `validate`. Default `false`. */
  skipValidation?: boolean;
  /**
   * Flashes the cells the call applied, as {@link DataGridActions.flashCells} does: at once for a synchronous
   * batch, after `settled` for a held one. Only cells of visible columns flash. Default `false`.
   */
  flash?: boolean;
};

/** One entry of {@link UpdateCellsVerdict.skipped}: a patch that was not applied, with the reason. */
export type UpdateCellsSkip = {
  /** Index of the patch in the `patches` array the action received. */
  patchIndex: number;
  /**
   * `"unknown-row"` — the row id is not in `data`; `"unknown-column"` — the column id is not a
   * known column; `"hole"` — the row is an unloaded lazy hole; `"readonly"` — the grid, the column, or the
   * row (via `readOnly(row)`) is read-only for a batch with a `source` other than `"stream"`, or a
   * `"stream"` patch met a column with no write path (no `accessorKey` and no `setValue`); `"invalid"` — the column's `validate` rejected the
   * value; `"no-op"` — the value is `Object.is`-equal to the current one; `"saving"` — a
   * `"stream"` batch met a row whose save is in flight; the grid holds the patch and applies it once the save settles (after the acknowledgement or the rollback), and a later push to the same cell replaces the held value;
   * `"limit"` — a `"stream"` call carried more than 100,000 patches, and this one came after them;
   * `"no-source"` — the call passed no `source`.
   */
  reason: "unknown-row" | "unknown-column" | "hole" | "readonly" | "invalid" | "no-op" | "saving" | "limit" | "no-source";
};

/**
 * Verdict of {@link DataGridActions.updateCells} / {@link DataGridActions.updateRows}: what the
 * batch actually did. `applied` counts the cell writes that landed; `skipped` names every patch
 * that did not land and why, so a streaming producer can observe its feed being silently dropped.
 *
 * `pending` is `true` when the batch is HELD for async validation — the verdict then reports
 * nothing about its outcome, and a held batch that is later superseded (a newer held batch, or most
 * other writes and view rebuilds; a plain deferred `updateCells` keeps it) is dropped silently by
 * design; track supersession on your own feed.
 */
export type UpdateCellsVerdict = {
  /** Cell writes applied (0 when nothing applied or the batch is `pending`). */
  applied: number;
  /** Patches that did not apply, with the reason. Empty when `pending`. */
  skipped: UpdateCellsSkip[];
  /** True when the batch is held for async validation. */
  pending: boolean;
  /** Present when `pending`: resolves with the final verdict, or with nothing applied when a newer write superseded the batch. */
  settled?: Promise<UpdateCellsVerdict>;
};

import type { DataChange } from "../types";

const changedByGrid = new WeakMap<object, WeakSet<object>>();

/** The sources of a change the user made on purpose; a push, an undo, a rollback, or an id swap marks no row. */
const USER_SOURCES: ReadonlySet<DataChange<unknown>["source"]> = new Set(["edit", "paste", "fill", "delete", "cut", "replace", "import", "row-operation"]);

/**
 * Marks the row objects a user change wrote, keyed by the grid's `actions` table. A later write gives a
 * row a new object, so an undo, a push, a rollback, or new `data` clears the mark without bookkeeping.
 */
export function markChangedRows(grid: object, change: DataChange<unknown>, rowOf: (rowId: string) => unknown): void {
  if (!USER_SOURCES.has(change.source)) return;
  let changed = changedByGrid.get(grid);
  if (!changed) changedByGrid.set(grid, (changed = new WeakSet()));
  for (const op of change.ops) {
    if (op.type !== "update" && op.type !== "insert") continue;
    const row = rowOf(op.rowId);
    if (typeof row === "object" && row !== null) changed.add(row);
  }
}

/** Whether a user change wrote this row object. */
export function isRowChanged(grid: object, row: unknown): boolean {
  return typeof row === "object" && row !== null && changedByGrid.get(grid)?.has(row) === true;
}

import { resolveColumnValidate } from "../cell-types/capabilities";
import { resolveBulkWrites, type BulkCandidate, type BulkResolution } from "../validation/validate-batch";
import type { DataGridStoreState } from "./types";
import { dataIndexAt } from "./view-rows";

export type ClearWrite = { viewRowIndex: number; columnId: string; value: unknown };

/** Validates cleared cells like a paste: a rejected cell stays, a `validationMode: "warn"` column clears and flags it, and an async schema returns a Promise. */
export function resolveClearWrites(s: DataGridStoreState, writes: readonly ClearWrite[]): BulkResolution | Promise<BulkResolution> {
  const columns = new Map(s.columns.map((c) => [c.id, c] as const));
  const candidates: BulkCandidate[] = [];
  for (const write of writes) {
    const column = columns.get(write.columnId);
    const dataRowIndex = dataIndexAt(s, write.viewRowIndex);
    const row = dataRowIndex === undefined ? undefined : s.data[dataRowIndex];
    if (!column || row === undefined) continue;
    const validate = resolveColumnValidate(column, s.cellTypes[column.type ?? "text"]);
    candidates.push({ ...write, validate, row, rowId: s.getRowId(row, dataRowIndex!), warn: column.validationMode === "warn" });
  }
  return resolveBulkWrites(candidates, s);
}

/** Runs `apply` on the resolution at once, or after an async schema settles. */
export function resolveClearWritesThen(s: DataGridStoreState, writes: readonly ClearWrite[], apply: (resolved: BulkResolution) => void): void {
  const resolution = resolveClearWrites(s, writes);
  if (resolution instanceof Promise) void resolution.then(apply);
  else apply(resolution);
}

"use client";

import { useMemo, useSyncExternalStore } from "react";
import { isMacPlatform } from "./platform";
import { formatShortcut } from "./shortcut-label";

const subscribeNever = () => () => {};
const serverIsMac = () => false;

/**
 * The key labels of `binding` ("mod+shift+z"): word names (`["Ctrl", "Shift", "Z"]`) during server
 * rendering and hydration, then glyphs on macOS (`["⌘", "⇧", "Z"]`), so the HTML always hydrates.
 */
export function useShortcutLabel(binding: string): string[] {
  const isMac = useSyncExternalStore(subscribeNever, isMacPlatform, serverIsMac);
  return useMemo(() => formatShortcut(binding, isMac), [binding, isMac]);
}

import type { AnyColumnDef, CellPatch, DataGridStoreState, UpdateCellsOptions } from "./types";
import { forEachFilterSpec } from "../sort-filter/filter-tree";
import type { CellRef, FilterNode, SortSpec, ViewCoord } from "../types";
import { forEachDataIndex } from "./view-rows";

/**
 * Lazily-built, incrementally-maintained `rowId -> dataIndex` map for {@link DataGridActions.updateCells}.
 *
 * Building it costs O(n) (measured 10.1 ms at 100k rows), so a per-call rebuild would reintroduce
 * exactly the per-tick O(n) cost the direct-update API exists to remove. Instead every store path
 * that changes which row sits at which data index calls {@link RowIndexCache.invalidate}, and the
 * next `updateCells` rebuilds once. A pure value patch never moves a row, so the common streaming
 * tick keeps the cache warm forever.
 *
 * The cache is deliberately keyed on the `data` array identity it was built from: any path that
 * replaces `data` without invalidating (a bug, or a future action) is caught on the next lookup
 * instead of silently writing to the wrong row.
 */
export type RowIndexCache = {
  /** `rowId -> dataIndex` for `data`, rebuilding when stale. */
  resolve(data: readonly unknown[], getRowId: (row: unknown, index: number) => string): ReadonlyMap<string, number>;
  /** Data index of one `rowId`, or `undefined` when the row is not in `data`; a cold cache scans for the id instead of building the full map. */
  resolveOne(data: readonly unknown[], getRowId: (row: unknown, index: number) => string, rowId: string): number | undefined;
  /** Drops the cached map. Call from every path that inserts, deletes, reorders, or replaces rows. */
  invalidate(): void;
  /**
   * Carries the cached map across a value-only edit that rebuilt the `data` array without moving any
   * row (every cell-write path: `commitCellEdit`, `commitCellValue`, `deleteSelection`,
   * `applyCellUpdates`, `updateCells`). Without this a single user edit between two streaming ticks
   * would force a full O(n) rebuild on the next patch. No-op when the cache is already cold.
   */
  rebase(nextData: readonly unknown[]): void;
};

export function createRowIndexCache(): RowIndexCache {
  let cachedData: readonly unknown[] | null = null;
  let cachedMap: ReadonlyMap<string, number> | null = null;
  return {
    resolve(data, getRowId) {
      if (cachedMap && cachedData === data) return cachedMap;
      const map = new Map<string, number>();
      for (let i = 0; i < data.length; i++) {
        const rowId = getRowId(data[i], i);
        if (!map.has(rowId)) map.set(rowId, i);
      }
      cachedData = data;
      cachedMap = map;
      return map;
    },
    resolveOne(data, getRowId, rowId) {
      if (cachedMap && cachedData === data) return cachedMap.get(rowId);
      for (let i = 0; i < data.length; i++) if (getRowId(data[i], i) === rowId) return i;
      return undefined;
    },
    invalidate() {
      cachedData = null;
      cachedMap = null;
    },
    rebase(nextData) {
      if (cachedMap) cachedData = nextData;
    },
  };
}

// `dataIndex -> viewRow` inverse, keyed on the viewIndex array: every rebuild returns a fresh array, so the identity key never goes stale.
const viewInverseCache = new WeakMap<readonly number[], Map<number, number>>();

/** The view row of `dataRowIndex` under `viewIndex`, or -1 when the row is not in the view. */
export function viewRowOfDataIndex(viewIndex: readonly number[], dataRowIndex: number): number {
  let inverse = viewInverseCache.get(viewIndex);
  if (!inverse) {
    const built = new Map<number, number>();
    forEachDataIndex(viewIndex, (dataIndex, viewRow) => built.set(dataIndex, viewRow));
    inverse = built;
    viewInverseCache.set(viewIndex, inverse);
  }
  return inverse.get(dataRowIndex) ?? -1;
}

/**
 * Resolves a stable {@link CellRef} against the CURRENT view: `rowId` to a data index through the
 * cache's single-id scan, that index to a view row through the {@link viewRowOfDataIndex} inverse,
 * and `columnId` to a visible-column index. `null` when the row is no longer in `data`, the
 * filter hides it, or the column is hidden — the caller dev-warns.
 */
export function resolveCellRef(s: DataGridStoreState, cache: RowIndexCache, ref: CellRef): ViewCoord | null {
  const dataRowIndex = cache.resolveOne(s.data, s.getRowId, ref.rowId);
  const viewRow = dataRowIndex === undefined ? -1 : viewRowOfDataIndex(s.viewIndex, dataRowIndex);
  const col = s.visibleColumns.findIndex((column) => column.id === ref.columnId);
  if (viewRow < 0 || col < 0) return null;
  return { row: viewRow, col };
}

/**
 * Rebuilds the map from scratch and compares it against `cached`, returning the mismatching row ids.
 * Dev-only assertion surface for the invalidation invariant: a missed invalidation lands patches
 * on the wrong rows, a silent data-corruption class of bug.
 */
export function diffRowIndex(
  cached: ReadonlyMap<string, number>,
  data: readonly unknown[],
  getRowId: (row: unknown, index: number) => string,
): string[] {
  const mismatches: string[] = [];
  const seen = new Set<string>();
  for (let i = 0; i < data.length; i++) {
    const rowId = getRowId(data[i], i);
    seen.add(rowId);
    if (cached.get(rowId) !== i) mismatches.push(rowId);
  }
  for (const rowId of cached.keys()) {
    if (!seen.has(rowId)) mismatches.push(rowId);
  }
  return mismatches;
}

/**
 * Resolves `reorder` to what the store must actually do this tick. `"defer"` downgrades to `"never"`
 * when no touched column feeds the active sort or filter, so a ticker streaming into a
 * non-sort column never flips `viewStale` and never needs a reconcile.
 */
export function resolveReorder(
  requested: UpdateCellsOptions["reorder"],
  patches: readonly CellPatch[],
  sortState: readonly SortSpec[],
  filterState: readonly FilterNode[],
): "defer" | "immediate" | "frame" | "never" {
  const mode = requested ?? "defer";
  if (mode !== "defer" && mode !== "frame") return mode;
  return touchesViewInputs(patches, sortState, filterState) ? mode : "never";
}

/** True when any patch writes a column that the active sort or filter reads. */
export function touchesViewInputs(
  patches: readonly CellPatch[],
  sortState: readonly SortSpec[],
  filterState: readonly FilterNode[],
): boolean {
  if (sortState.length === 0 && filterState.length === 0) return false;
