  if (!rangeEqual(a.range, b.range)) return false;
  if (a.rangeStack.length !== b.rangeStack.length) return false;
  for (let i = 0; i < a.rangeStack.length; i++) if (!rangeEqual(a.rangeStack[i]!, b.rangeStack[i]!)) return false;
