    if (dataRowIndex === undefined) dataRowIndex = holeRowIndex(rowId);
    if (dataRowIndex === undefined) return -1;
    const viewRow = viewRowOfDataIndex(s.viewIndex, dataRowIndex);
    if (viewRow === -1) return -1;
    return viewRow;
  };
