    if (typeof ref !== "object" || ref === null) {
      warn();
      return null;
    }
    const r = ref as CellRef;
    const row = resolveRow(r.rowId);
    const col = resolveCol(r.columnId);
    if (row === -1 || col === -1) {
      warn();
      return null;
    }
    return { rowId: r.rowId, columnId: r.columnId, row, col };
  };

