export type { GateAbortReason, GateContext, GateName } from "./gate-signal";
import type { UpdateCellsOptions, UpdateCellsVerdict } from "./update-cells-types";
export type { UpdateCellsOptions, UpdateCellsReorder, UpdateCellsSkip, UpdateCellsVerdict } from "./update-cells-types";
import type { RowSaveStatus, SaveAck, SaveConflictContext, SaveContext, SaveRejectedContext, SaveResolution } from "./write-ack";
export type { RowSaveStatus, SaveAck, SaveConflictContext, SaveContext, SaveRejectedContext, SaveRejection, SaveResolution } from "./write-ack";

/** The result of `actions.selectAllMatching()`. */
export type SelectAllMatchingResult = { ok: true } | { ok: false; reason: "disabled" | "needs-across-filters" | "needs-total-row-count" };

/** The input that wrote the current selection. */
export type SelectionPointer = "touch" | "mouse" | "pen" | "keyboard";

/** The lazily-read context `DataGridRoot` registers for {@link DataGridActions.autosizeColumns}. */
export type AutosizeMeasureContext = AutosizeFonts & {
  /** The currently mounted view-row window `[start, end)`, or `null` when no rows are mounted. */
  window: { start: number; end: number } | null;
  /** The consumer renders a per-column header-menu trigger (adds its fixed width allowance). */
  hasHeaderMenu: boolean;
  /** The consumer renders a per-column header-filter button (adds its fixed width allowance to columns with a set filter). */
  hasHeaderFilter: boolean;
};

/** Live props synced from the consumer's render into the store on every change, typed over the consumer's row shape. */
export type DataGridSyncProps<TData = unknown> = {
  /**
   * Controlled row array (React `value` semantics): the app owns it, and every mutation
   * (edit/paste/fill/delete/row-ops) shows at once and reaches it only through `onDataChange`. An
   * unstored change lasts until the next sync of `data` (a new `data` array, or a change of another
   * view input such as `columns` or `sortState`) replaces it. Mutually exclusive with
   * `defaultData`; when both are given, `data` wins (dev-mode warns once). Omit `data` and pass
   * `defaultData` instead for the uncontrolled mode.
   */
  data?: readonly TData[];
  /**
   * Uncontrolled row array (React `defaultValue` semantics): seeds the store ONCE at creation and
   * the store then OWNS it — every mutation applies internally with no app-side state required;
   * `onDataChange` still fires as an optional notification. Changing this prop on a later render is
   * ignored (uncontrolled, matching `<input defaultValue>`). Mutually exclusive with `data` — see
   * that prop's doc for precedence.
   */
  defaultData?: readonly TData[];
  // ColumnDef's 3rd param (TValidate) erases to `any`, not `unknown` — see AnyColumnDef's doc in
  // this file: `validate`'s function-or-schema union can't stay bivariant as a plain property, so
  // a defineColumns literal's narrow-TValue `validate` needs this documented widening to fit here.
  columns: readonly ColumnDefOf<TData>[];
  /**
   * Stable, unique id of a row. Defaults to the row's `id` field (string or number) and throws
   * for a row without one. Pass it when rows have no `id` or the id lives elsewhere.
   */
  getRowId?: (row: TData, index: number) => string;
  /**
   * Disables every user write grid-wide, independent of any per-column `readOnly`: editing, delete, paste, fill, cut,
   * row operations, row id swaps, undo, and redo. Setting it to `true` cancels an open edit session.
   * A `"stream"` push (`updateCells`, `updateRows`, `deleteRows`) still writes. Default `false`.
   */
  readOnly?: boolean;
  /**
   * Merged over `DEFAULT_KEYMAP`: per-action bindings here take precedence, and an action mapped to `[]` is unbound.
   * An inline object literal is fine.
   */
  keymap?: Keymap;
  /** Fired once per change (a user gesture, an action, or a `"stream"` push) with the next data array and a row-id-based delta batch, after the grid stores that array. */
  onDataChange?: (next: readonly TData[], change: DataChange<TData>) => void;
  /**
   * Saves a change on a server. Runs once per change after `onDataChange`, for every `source` except
   * `"rollback"` (the revert of a refusal), `"stream"` (a server push must not echo back), and `"id-swap"`. Return a promise
   * to acknowledge the change: it resolves with nothing (accepted) or `{ rejected }` (see {@link SaveAck}),
   * or rejects (the whole change is refused). While the promise is pending the rows are `saving`. A refusal
   * reverts the refused entries through `onDataChange` with `source: "rollback"`.
   *
   * `ctx.signal` aborts when the grid unmounts or `saveTimeoutMs` runs out; `ctx.actions` is the grid's actions.
   *
   * Call order: `onDataChange`, `onSave`, plugin observers. After a refusal: the rollback `onDataChange`,
   * then `onSaveRejected`.
   */
  onSave?: (change: DataChange<TData>, ctx: SaveContext) => void | Promise<SaveAck<TData>>;
  /**
   * Refuses a save whose promise has not settled after this many ms: its `ctx.signal` aborts, the rows revert, and
   * `onSaveRejected` receives `reason: "timeout"` on each rejection. A later answer is ignored. Default: off (a save waits for its promise).
   */
  saveTimeoutMs?: number;
  /**
   * Fired once per acknowledged change that the server refused, after the grid reverted it; see {@link SaveAck}.
   * A throw is logged and isolated.
   */
  onSaveRejected?: (ctx: SaveRejectedContext<TData>) => void;
  /**
   * Decides what a refused row becomes when the server sent its current row (`SaveRejection.current`).
   * Return `"theirs"` (or nothing) to take the server's row, `"mine"` to keep the row in the grid, or
   * `{ row }` for a merged row. `"mine"` and `{ row }` commit one `"merge"` change on top of the server's row, which
   * `onSave` receives. A promise keeps the row `saving` until it settles; see {@link SaveConflictContext}.
   */
  resolveSaveConflict?: (ctx: SaveConflictContext<TData>) => SaveResolution<TData> | PromiseLike<SaveResolution<TData>>;
  /**
   * Row-level cross-field validation, run once per touched row after a write gesture commits
   * (edit, paste, fill, delete-contents, updateCells/updateRows, and every `commitChange` except a `"stream"`
   * change, where it validates the inserted and updated rows, so an import, an undo and a rollback validate too) — the row already has ALL of the
   * gesture's cells applied, so the verdict is independent of column order inside a paste. Return
   * `columnId -> message` to surface errors (they land in `cellErrors`, same display as server
   * errors), `null` when the row is fine. Values still commit either way. Not run on
   * `insertRow`/`duplicateRows`/delete or on consumer `data` replacement. A promise does not hold the write:
   * its verdict merges into `cellErrors` when it settles. A newer verdict for the same row
   * supersedes a pending one, and a verdict for a row that is gone is dropped. A
   * rejection adds no error. `signal` aborts when a newer run for the same row supersedes this one,
   * when the row is gone, and when the grid unmounts; an aborted verdict is dropped. An id swap
   * (`replaceRowId`) cancels a pending verdict of the row and runs `validateRow` again for the swapped row.
   */
  validateRow?: (row: TData, rowId: string, ctx: GateContext) => Record<string, string> | null | Promise<Record<string, string> | null>;
  /**
   * Custom cell types keyed by `ColumnDef.type`, merged OVER the built-in registry — built-ins
   * you do not name keep working. A `null` entry removes a built-in (or a previously provided
   * type); the grid then renders its columns with the `text` fallback, drops their edits, pastes,
   * and deletes, and dev-warns about the unresolvable type. An inline object literal is fine: the grid rebuilds the registry only
   * when an entry changes identity, so define each type once, outside render.
   */
  cellTypes?: Record<string, AnyCellType | null>;
  /** Overrides a cell's clipboard-copy text. `ctx.text` is the cell type's own text, for the cells you do not change. */
  processCellForClipboard?: (value: unknown, ctx: ClipboardCopyCtx<TData>) => string;
  /**
   * Overrides parsing pasted text into a cell value. `ctx.fromText` is the column's own parser, for the cells you do not change.
   * A promise holds the paste until every cell settles. A second paste aborts a pending one with the reason `"superseded"`.
   * A rejection cancels the paste.
   */
  processCellFromClipboard?: (text: string, ctx: ClipboardPasteCtx<TData>) => NonNullable<unknown> | null | undefined | Promise<unknown>;
  /**
   * Runs on the parsed paste grid before it's applied; returning `false` (or a promise of `false`)
   * vetoes the paste entirely. A second paste aborts a pending one with the reason `"superseded"`. A rejection cancels the
   * paste. The cell cap applies to the settled grid. `signal` aborts when the grid goes read-only,
   * an edit starts, `gateTimeoutMs` runs out, or the grid unmounts; an aborted result is dropped.
   */
  processPaste?: (ctx: { cells: string[][]; target: ViewCoord; signal: AbortSignal }) => string[][] | false | Promise<string[][] | false>;
  /**
   * Prefixes formula-like copied cells (leading `=`, `+`, `-`, `@`, TAB, or CR; plain numbers
   * exempt) with `'` in the clipboard text and HTML, for Ctrl+C/Ctrl+X and the context menu's
   * Copy/Cut. A paste back into gridcn still restores the raw value. Default `true`; `false` copies raw text.
   */
  sanitizeClipboardFormulas?: boolean;
  /** Marker column mode; default 'none'. See {@link RowMarkersMode}. */
  rowMarkers?: RowMarkersMode;
  /** Whole-row selection channel gestures (marker click, Shift+Space); default true. */
  enableRowSelection?: boolean;
  /** Whether the delete-rows key (and the cell menu's Delete rows item) deletes; default true. `false` skips with reason `"disabled"`. `actions.deleteRows` and `actions.deleteRowsAt` keep working. */
  enableRowDelete?: boolean;
  /**
   * How long the checked rows last. Default `'across-filters'` with `totalRowCount`, else `'until-cleared'` when `rowMarkers` shows a checkbox, else `'until-click'`; an explicit value always wins. `useDataGridSelectionConfig` returns the value that applies.
   * - `'until-click'`: a cell or column selection (click, arrows, Shift or Ctrl click, a header click, Ctrl+Space) clears the checked rows.
   * - `'until-cleared'`: the checked rows stay across those gestures, and row operations (delete, duplicate, move, the cell menu's
   *   row items) act only on the checked rows while any exist. Escape, the checkboxes, Ctrl+A, a click on a row number, a row delete,
   *   and `clearSelection` still change the checks.
   * - `'across-filters'`: like `'until-cleared'`, and a checked row is remembered by id when it leaves the view (a page change, a window
   *   move, a filter that hides it) and checked again when it returns. Remembered rows stay out of every row action, the controlled
   *   `selection`, and select all; `useDataGridHiddenCheckedCount` reads their number, and `actions.selectAllMatching()` needs it with
   *   `totalRowCount`. A server-sorted or server-filtered grid without `totalRowCount`, and a scroll-mode grid without `totalRowCount`, behave like `'until-cleared'`.
   */
  checkedRowsLifetime?: CheckedRowsLifetime;
  /**
   * Wait in ms between the last keystroke and the commit of the grid's own text inputs: the toolbar search, the
   * filter value inputs, the set-filter search, find & replace, and the lookup editor. `0` commits each keystroke. A component's own
   * prop (such as `DataGridSearch debounceMs`) wins. Default 200.
   */
  inputDebounceMs?: number;
  /**
   * Shows `pageSize` rows of the sorted and filtered view at a time. The grid keeps the whole `data`, so sort, filter, aggregates, and streamed patches work across every page. Set it to turn paging on (`defaultPageSize` seeds it, `pageSize` controls it with `onPageSizeChange`). `null` or unset shows every row. A filter change goes back to page 1.
   * `pageSizeOptions` lists the sizes the footer offers (default 10, 25, 50, 100); the bar's own `pageSizeOptions` wins.
   */
  pageSize?: number | null;
  defaultPageSize?: number | null;
  onPageSizeChange?: (pageSize: number | null) => void;
  pageSizeOptions?: readonly number[];
  /** The current page, 1-based. Controls it with `onPageChange`; `defaultPage` seeds it. A page past the last one shows the last. Default 1. */
  page?: number;
  defaultPage?: number;
  onPageChange?: (page: number) => void;
  /**
   * Aborts an async gate (`onBeforeDeleteRows`, `validateRow`, `onBeforeEditStart`, `createRow`, `duplicateRow`, `processPaste`, `processCellFromClipboard`, `processReplace`, the import `mapColumn`, an async `validate` holding a paste, fill, or clear) whose promise
   * has not settled after this many ms (one number for every gate, or a number per gate name): its `signal` aborts, the action is cancelled, and the next action may start. Default: off
   * (a gate waits for its promise).
   */
  gateTimeoutMs?: number | Partial<Record<Exclude<GateName, "import">, number>>;
  /** Fires when a row action (`insertRows`, `duplicateRows`, `deleteRows`, `moveRows`) does nothing, with its name and the reason; the insert, duplicate, and delete actions also return it, and `reorderRows` and `moveRowsBy` (both report as `moveRows`) return `false`. `deleteRowsAt` reports as `deleteRows`, and its `source: "stream"` path never reports. Shortcuts and menu items run through the same actions, so one handler can toast every skip. */
  onRowActionSkipped?: (ctx: { action: RowActionName; reason: RowActionSkipReason; count?: number }) => void;
  /**
   * Fires once for every async gate the grid stopped waiting for, with the gate's name and why: `"timeout"` (see `gateTimeoutMs`),
   * `"changed"` (the rows, the checked rows, or `readOnly` changed, the active cell moved during `onBeforeEditStart`, or an edit started during `processPaste`), `"superseded"` (a newer run replaced it), `"cancelled"` (the user pressed Escape), or `"reset"`.
   */
  onGateAborted?: (ctx: { gate: GateName; reason: GateAbortReason }) => void;
  /**
   * Declares that `data` is a window of a larger result of this many rows (`null`: the size is unknown),
   * such as the current server page, the loaded part of a scroll-mode source, or a server-filtered window. With
   * `checkedRowsLifetime="across-filters"`, a checked row that leaves `data` is remembered by row id in every mode and checked
   * again when it returns, and `actions.selectAllMatching()` can check the whole result.
   * Setting it, even to `null`, makes `checkedRowsLifetime` default to `'across-filters'` and `sortMode` and `filterMode` default to `"server"`.
   * `useDataGridSelectedRows` reads the outcome. Default: `undefined` (`data` is the whole result).
   */
  totalRowCount?: number | null;
  /**
   * Announces the view's row count through the grid's live region after a filter, sort, or
   * filter-group change. A server sort or filter commit stays quiet; the count is read when the load
   * ends, and a changed numeric `totalRowCount` is read as the count. A client filter still announces
   * under `sortMode="server"`. A scroll-mode source counts its loaded rows only. Default `false`.
   */
  announceResults?: boolean;
  /**
   * Runs before every row delete the grid starts: the Delete rows shortcut, the context-menu
   * item, and `actions.deleteRows` / `deleteRowsAt` (except `deleteRows` with `source: "stream"`). `rowIds` are the rows that go; `hiddenCount`
   * counts the hidden checked rows that stay. Return `false` (or a promise of `false`) to cancel.
   * A pending promise blocks a second delete. A throw or a rejection cancels. `signal` aborts when
   * the grid goes read-only, the rows or the checked rows change, or the grid unmounts; an aborted
   * result is dropped.
   */
  onBeforeDeleteRows?: (ctx: { rowIds: readonly string[]; hiddenCount: number; signal: AbortSignal }) => boolean | Promise<boolean>;
  /**
   * Supplies the values of the header filter popover and the `isAnyOf` input from a backend, one list
   * per search. Columns with `options.choices` keep their declared list. Without it, both lists come
   * from the loaded rows.
   */
  fetchFilterValues?: FetchFilterValues;
  /** Whole-column selection channel gestures (header click); default true. */
  enableColumnSelection?: boolean;
  /** Multi-cell rectangular range gestures (shift-click/drag, shift+arrow); false collapses to single-cell active only. Default true. */
  enableRangeSelection?: boolean;
  /** Ctrl/Cmd-click multi-range (rangeStack); false makes it behave as a plain click. Default true. */
  enableMultiRange?: boolean;
  /** Enables the header resize handle grid-wide; default true. Per-column `resizable: false` still wins. */
  enableColumnResize?: boolean;
  /** Enables drag-to-reorder columns grid-wide; default true. `false` also makes `setColumnOrder` do nothing. Per-column `reorderable: false` still wins. */
  enableColumnReorder?: boolean;
  /** Enables pin/unpin actions grid-wide; default true. `false` also makes `setColumnPin` do nothing. Per-column `pinnable: false` still wins. */
  enableColumnPinning?: boolean;
  /** How a plain header click behaves; default 'sort' with `totalRowCount`, else 'select'. See {@link HeaderClickBehavior}. */
  headerClickBehavior?: HeaderClickBehavior;
  /** Partial i18n override, deep-merged over {@link DEFAULT_LABELS}; see {@link useDataGridLabels}. */
  labels?: DeepPartialLabels;
  /**
   * BCP 47 language tag, such as `"de-DE"`. It formats the numbers and dates of `number` and `date` columns, the status bar, and the default labels.
   * It also sets the sort language unless `sortLocale` is set. A column `options.locale` and the status bar `formatValue` win. Default `"en-US"`, so the server and the browser render the same text.
   */
  locale?: string;
  /**
   * Builds a new row for `insertRow` (`index` is the data index at request time); absent makes `insertRow` a dev-warning no-op (duplicateRows/deleteRows don't need it).
   * A promise holds the insert until every row settles; a pending promise blocks a second insert
   * and a rejection cancels it. `signal` aborts when the grid goes read-only, the row the insert
   * was anchored to is gone, or the grid unmounts; an aborted result is dropped.
   */
  createRow?: (index: number, ctx: GateContext) => TData | Promise<TData>;
  /**
   * Builds a duplicated row's identity for `duplicateRows`: given the
   * source row and its new data index, returns the row to insert (with a distinct id, e.g. a fresh
   * UUID, so the copy's `getRowId()` never collides with its source's React key). Absent makes
   * `duplicateRows` a dev-warning no-op — mirrors `createRow`/`insertRow`. A promise holds the
   * duplicate until every copy settles; a pending promise blocks a second duplicate and a
   * rejection cancels it. `signal` aborts when the grid goes read-only, every source row is gone,
   * or the grid unmounts; an aborted result is dropped.
   */
  duplicateRow?: (row: TData, index: number, ctx: GateContext) => TData | Promise<TData>;
  /**
   * Consumer-defined keyboard commands keyed by name — the dispatch target of keymap bindings
   * that name no built-in action (see {@link GridCommand}). A name that shadows a built-in action
   * wins over it (dev-warned once). Pass a stable reference.
   */
  commands?: Record<string, GridCommand<TData>>;
  /**
   * Controlled multi-sort spec. Omitted (undefined), the grid owns the sort. Provided (even `[]`), this prop is the
   * source of truth: `onSortChange` still fires on every user-driven change (header click, `setSorts`), but the
   * displayed order moves only when the prop changes.
   */
  sortState?: SortSpec[];
  /**
   * Who orders the rows. `"client"`: the grid sorts `data` by `sortState`. `"server"`:
   * the grid only tracks the spec (header click cycle, `aria-sort`, sort indicator, `onSortChange`)
   * and never reorders `data`; the consumer fetches rows in that order, e.g. with `useDataGridServerRows`.
   * Default: `"server"` while `totalRowCount` is set (`data` is a window of the result), else `"client"`. Set `"client"` to sort the window locally.
   */
  sortMode?: "client" | "server";
  /**
   * BCP 47 tag that decides the client text sort, the text range filters, and the filter value lists. It covers `gt`, `gte`, `lt`, `lte`, and `isBetween`, and the lists of the header filter and the filter menu. Defaults to `locale`, then `"en-US"`: the server render and the browser order rows alike.
   * To follow the browser, read `navigator.language` after mount. Under `sortMode="server"` the grid does not sort rows; the server owns their order. A malformed or unsupported tag falls back to `"en-US"` with one development warning.
   */
  sortLocale?: string;
  /** Seeds the sort ONCE at store creation (uncontrolled, like `defaultData`); later changes are ignored. `sortState` wins when both are given. A function runs once on the client after mount, never on the server, so it can read `localStorage` without a hydration mismatch. */
  defaultSortState?: SortSpec[] | (() => SortSpec[] | null | undefined);
  /** Fires after the user (or `actions.toggleSort`/`setSorts`) changes the sort: uncontrolled, after the grid writes it; controlled, with the next sort. See `sortState`. */
  onSortChange?: (next: SortSpec[]) => void;
  /** Controlled group columns, outermost first. Unknown, `groupable: false`, and repeated ids drop; at most 4 levels. */
  groupBy?: readonly string[];
  /** Seeds the group columns once at store creation. A function runs once on the client after mount. */
  defaultGroupBy?: readonly string[] | (() => readonly string[] | null | undefined);
  /** Fires after the user (or `setGroupBy`, `toggleGroupBy`) changes the group columns. */
  onGroupByChange?: (next: readonly string[]) => void;
  /** Controlled pivot: one generated column per key of the pivot column and per built-in `aggregate`; needs `groupBy`. `{ columnIds: [] }` is off. */
  pivot?: PivotSpec;
  /** Seeds the pivot once at store creation. A function runs once on the client after mount. */
  defaultPivot?: PivotSpec | (() => PivotSpec | null | undefined);
  /** Fires after `setPivot` changes the pivot, with `{ columnIds: [] }` when it turns off. */
  onPivotChange?: (next: PivotSpec) => void;
  /** Controlled open groups. A toggle applies at once and emits. Default: every group collapsed. */
  expanded?: ExpandedState;
  /** Seeds the open groups once at store creation. */
  defaultExpanded?: ExpandedState;
  /** `"server"` shows the group rows of `groupLayout` and never buckets rows. Default: `"server"` when `groupLayout` is set, else `"client"`. The server hook sets it. */
  groupMode?: "client" | "server";
  /** The group rows of a server grid, laid out by the server hook. Without it `groupMode="server"` renders ungrouped. */
  groupLayout?: ServerGroupLayout;
  /** Fires after the user (or `toggleGroup`, `expandAll`, `collapseAll`) changes the open groups. */
  onExpandedChange?: (next: ExpandedState) => void;
  /** Controlled filter tree; same controlled/uncontrolled semantics as `sortState`. The top level combines with `filterJoin`; a {@link FilterGroup} has its own join. */
  filterState?: FilterNode[];
  /** Controlled join of the top-level filters: `"and"` (default) matches every entry, `"or"` any one. Same controlled/uncontrolled semantics as `filterState`. */
  filterJoin?: FilterJoinOperator;
  /** Seeds the top-level join ONCE at store creation. Default: `"and"`. */
  defaultFilterJoin?: FilterJoinOperator;
  /** Fires after the user (or `actions.setFilterJoin`) changes the top-level join: uncontrolled, after the grid writes it; controlled, with the next join. */
  onFilterJoinChange?: (next: FilterJoinOperator) => void;
  /**
   * Who filters the rows. `"client"`: the grid filters `data` by `filterState`. `"server"`:
   * the grid only tracks the spec (filter menu, header filters, `data-filtered`, `onFilterChange`) and
   * never filters `data`; the consumer fetches the matching rows, e.g. with `useDataGridServerRows`.
   * Default: `"server"` while `totalRowCount` is set, else `"client"`. Set `"client"` to filter the window locally.
   */
  filterMode?: "client" | "server";
  /** Seeds the filters ONCE at store creation; see `defaultSortState`, also for the function form. */
  defaultFilterState?: FilterNode[] | (() => FilterNode[] | null | undefined);
  /** Fires after the user (or `actions.setFilters`) changes the filters: uncontrolled, after the grid writes them; controlled, with the next filters. See `filterState`. */
  onFilterChange?: (next: FilterNode[]) => void;
  /** Controlled quick-search text; same controlled/uncontrolled semantics as `sortState`. */
  searchText?: string;
  /** Seeds the quick-search text ONCE at store creation; see `defaultSortState`, also for the function form. */
  defaultSearchText?: string | (() => string | null | undefined);
  /** Fires after the user (or `actions.setSearch`) changes the search text: uncontrolled, after the grid writes it; controlled, with the next text. See `searchText`. */
  onSearchTextChange?: (next: string) => void;
  /**
   * Installed plugins (add-ons that reach into the grid): overlay layers, row bands, data-change
   * observers, commands, keymap bindings, and root mounts — one seam instead of one per add-on.
   * Resolved at store creation (so SSR has band heights and `aria-rowcount`) and re-resolved in
   * the config phase only when the list actually changes: an entry is unchanged when its `name`
   * and every member keep their identity, so an inline `plugins={[fill.plugin, …]}` array is fine.
   * Array order is precedence and visual order (overlays paint in order, later on top; top bands
   * stack from the header down; bottom bands stack top to bottom; `Mount`s and observers run in
   * order). A plugin object attaches to ONE grid — a second grid resolving the same object is a
   * dev error. The list is row-shape-agnostic: a typed `DataGridPlugin<TData>` is assignable to it,
   * and an inline plugin's `onDataChange` observer sees `unknown` rows. See {@link DataGridPlugin}.
   */
  plugins?: readonly DataGridPlugin<unknown>[];
  /**
   * Seeds column widths, order, hidden columns, and pins once, over the `columns` prop's own defaults; the layout wins
   * over a column's `width` and `pin`. Later changes to this value are ignored. Pair it with `onColumnLayoutChange` to
   * save and restore a user's layout. A partial layout is normalized like `columnLayout`: unknown column ids are dropped,
   * `order` gets missing ids appended in column order, widths are clamped, and pins on `pinnable: false` columns are ignored.
   * A function runs once on the client after mount, never on the server, like the function form of `defaultSortState`.
   */
  defaultColumnLayout?: Partial<ColumnLayout> | (() => Partial<ColumnLayout> | null | undefined);
  /**
   * Controlled column layout (React `value` semantics, gesture-first like `selection`): each
   * provided part (`widths`, `order`, `pins`, `hidden`) replaces that part, and an omitted part
   * stays uncontrolled — the store keeps its current value for it, so
   * `columnLayout={{ widths }}` controls only widths and a user reorder survives. A gesture
   * writes the store at once and fires `onColumnLayoutChange`; a `columnLayout` prop that changes
   * identity, is not an echo of a value the grid just fired, and differs from the grid's current
   * snapshot then overrides the store. Omitted (undefined) keeps the uncontrolled behavior
   * (store-owned, with events).
   */
  columnLayout?: Partial<ColumnLayout>;
  /**
   * Shared headers above runs of columns, by column id; groups nest. The columns stay flat. A group
   * keeps its columns next to each other: reorder moves a column inside its group and a group as a
   * block, and a saved or restored `order` that splits a group is repaired. Unknown ids, a column
   * listed twice, a repeated group id, and nesting deeper than 8 levels are dropped. Pass a stable
   * identity for `header` nodes.
   */
  columnGroups?: readonly ColumnGroupDef[];
  /**
   * Runs one {@link DataGridActions.autosizeColumns} pass after mount, when the view first has
   * rows (a scroll-mode grid waits for its first block); it runs once per mount. Columns with a saved
   * width (`columnWidths`) keep it — a saved layout wins. `true` uses the action's defaults;
   * an options object narrows the pass.
   */
  autosizeOnMount?: boolean | AutosizeOptions;
  /**
   * Fires once per committed column-layout change (resize drag release/autosize, reorder drop,
   * pin/unpin, show/hide, `setColumnLayout`) with the full current `ColumnLayout` snapshot -
   * never per drag frame, and never when nothing changed. Fired from the store actions layer, no
   * React-render dependency. See `defaultColumnLayout` for the seed path and `columnLayout` for
   * the controlled one.
   */
  onColumnLayoutChange?: (next: ColumnLayout) => void;
  /**
   * Controlled selection (React `value` semantics, gesture-first): a gesture writes the store at
   * once and fires this callback; a `selection` prop that changes identity, is not an echo of a
   * value the grid just fired, and differs structurally from the grid's current value then
   * overrides the store. An applied value with an `anchor` moves the active cell to the anchor
   * (a normal active cell move: `onActiveCellChange` fires); without an anchor the active cell stays.
   * Omitted (undefined) keeps the uncontrolled behavior (store-owned, with events). Mutually
   * exclusive with `defaultSelection`; when both are given, `selection` wins (dev-mode warns once).
   */
  selection?: SelectionState;
  /**
   * Seeds the selection ONCE at store creation (React `defaultValue` semantics): the value
   * resolves against the initial data/columns, and a resolved `anchor` also seeds the initial
   * active cell. Later changes to this value are ignored (uncontrolled, like `defaultData`),
   * which also means a consumer `data` swap never re-applies it. Mutually exclusive with
   * `selection` - see that prop's doc for precedence.
   */
  defaultSelection?: SelectionState;
  /**
   * Fires on every committed selection change (click, extend step, range push, row/column/all selection, clear)
   * with the current selection in stable {@link SelectionState} terms plus a lazy `details.getValues()` accessor.
   * Fires only when the selection differs structurally from the last one, so a sort that keeps the selection's rows
   * fires nothing. `details.phase` is `"end"` for a settled selection: a click, a key, an API call. A pointer drag fires `"drag"` for each
   * step after the press, then once more with `"end"` on release, so `phase === "end"` skips the steps. `getValues()` reads the values only when you call it.
   */
  onSelectionChange?: (next: SelectionState, details: SelectionChangeDetails) => void;
   /**
    * Fires when the active cell changes to a different cell, when it follows its record or column to
    * another view position (a sort, filter, data change, column hide, reorder, or pin), when another
    * record comes under it (a lazy row load, or a clamp after its row or column left the view), or
    * when it is cleared (`null`). Re-selecting the same cell on the same record and column does not fire.
    */
   onActiveCellChange?: (next: ViewCellRef | null) => void;
   /**
    * Fired when an edit session is about to start (Enter/F2, type-to-replace, double-click) with
    * the target cell's ids and view position. Return `false` to VETO the edit — `startEditing`
    * then makes no state change at all (no session, no active cell move). A checkbox cell opens no editor;
    * the veto holds or blocks its toggle instead. A promise holds the editor: it opens when
    * the promise settles, unless the promise is `false`, the user moved to another cell, or the
    * grid went read-only. A pending promise ignores a second edit start, so keys typed meanwhile add no text. A rejection cancels.
    * `signal` aborts when the active cell moves to another cell, the edit is cancelled (Escape), the grid
    * goes read-only, or the grid unmounts; an aborted result is dropped.
    */
   onBeforeEditStart?: (cell: ViewCellRef, ctx: GateContext) => boolean | void | Promise<boolean | void>;
   /**
    * Fired when an edit session ends or a commit attempt is refused — `commit` after the session
    * closes, `cancel` when the draft is discarded (including a remap that drops the edited cell),
    * `rejected` when validation refused a commit and the session stays open (fires per attempt).
    * See {@link GridEditEndEvent}.
    */
   onEditEnd?: (event: GridEditEndEvent) => void;
   /**
    * Fires after a bulk paste, a fill, or an `updateCells` call settles, only when at least one cell
    * was rejected by validation — the accepted cells are applied first. See {@link GridValidationErrorEvent}.
    */
   onValidationError?: (event: GridValidationErrorEvent) => void;
   /** Fired on a double-click on any non-pinned, non-skeleton cell — pure notification, no veto. See {@link OnCellDoubleClick}. */
   onCellDoubleClick?: OnCellDoubleClick<TData>;
   /** Fired when the user right-clicks any non-pinned, non-skeleton cell — pure notification. See {@link OnCellContextMenu}. */
   onCellContextMenu?: OnCellContextMenu<TData>;
    /** Fired on a plain click on any cell — see {@link OnCellClick}. An inline function is fine. */
    onCellClick?: OnCellClick<TData>;
    /**
     * Fired after a row-window commit with the rendered view-row range `[start, end)` (inclusive
     * start, exclusive end — same convention as `useRowWindow`'s `RowWindow`). It is a data-row range
     * only while the view is the identity: no client-side sort or filter is active (`sortMode="server"`
     * and `filterMode="server"` keep it so). Only fires when the
     * range actually changed since the last call, including once for the initial mount commit; a
     * scroll tick that stays within the current window's overscan buffer does not re-fire it.
     * Useful for lazy-loading/prefetch/analytics add-ons; core has no fetching logic of its own.
     */
    onRenderedRowsChange?: (range: { start: number; end: number }) => void;
    /** @internal `useDataGridServerRows` sets it while it holds the rows of the previous spec on screen. */
    serverHeld?: boolean;
    /**
     * Fires on every live width write during a resize drag (`actions.previewColumnWidth`, per drag
    * frame) — the in-progress counterpart to `onColumnLayoutChange`'s once-per-commit snapshot.
   * Fired from the store actions layer, no React-render dependency. Not called for the commit
   * itself (drag release/autosize) — pair with `onColumnLayoutChange` if you need that too.
   */
  onColumnResizing?: (ctx: { columnId: string; width: number }) => void;
};

/**
 * Second argument to `onSelectionChange`. `getValues()` reads the CURRENT `next.range` only — a
 * multi-range selection (ctrl-click stack) is not flattened or concatenated, matching clipboard
 * copy's own "primary range only" scope (`resolveCopyScope`) — call it once per range in
 * `next.rangeStack` yourself if you need the others. Returns `[]` when there's no active range
 * (row/column-channel-only selection, or a clear). Deliberately lazy: built fresh from the store
 * snapshot only when called, so a consumer that ignores it (the common case) never pays for
 * reading/allocating a value matrix on every drag step.
 */
export type { SelectionChangeDetails, SelectionChangePhase } from "./selection-change";

// The store is generic-erased to TData = unknown past this boundary (InternalSyncProps below): one
// runtime engine serves every consumer's row type, and unknown (not never) keeps every ColumnDef
// function field (accessorFn/setValue/readOnly/validate) callable with the store's own `row: unknown`
// values with no cast needed — safe because a column and the row it's called with always came from
// the same consumer-typed `data` array passed in through DataGridSyncProps<TData>. This is also what
// useDataGridVisibleColumns/useDataGridAllColumns return, so a consumer building custom column UI can
// call those same fields without a cast either.
/** `DataGridSyncProps` cast to the store's internal row-agnostic shape; the one unsafe cast, applied once at the boundary. */
export type InternalSyncProps = Omit<DataGridSyncProps<unknown>, "getRowId"> & { getRowId: (row: unknown, index: number) => string };

/** The overlay contribution of one resolved plugin: the component plus its `name` (the React key). */
export type ResolvedPluginOverlay = { name: string; Overlay: ComponentType<OverlayPluginCtx> };

/** The root-mount contribution of one resolved plugin: the component plus its `name` (the React key). */
export type ResolvedPluginMount = { name: string; Mount: ComponentType };

/** One band segment of the resolved row bands: one plugin's rows plus its painter. Segments stack in plugin array order (top: header down; bottom: top to bottom). */
export type ResolvedBandSegment = {
  name: string;
  rows: readonly unknown[];
  render: (ctx: RowBandRenderCtx) => ReactNode;
};

/** A data-change observer resolved from a plugin's `onDataChange`: runs after the store write and the consumer's `onDataChange`, each in its own try/catch. */
export type PluginDataChangeObserver = (next: readonly unknown[], change: DataChange<unknown>, ctx: { api: DataGridApi<unknown> }) => void;

/**
 * The `plugins` sync prop resolved into what core consumes, written as ONE store field so the
 * config phase can keep its reference (and the merged `commands`/`keymap` that feed from it)
 * while the list is unchanged. `list` holds the kept plugins: the prop array without plugins
 * another grid holds and without later duplicate names (the prop array itself when it drops none).
 */
export type ResolvedPlugins = {
  list: readonly DataGridPlugin[];
  overlays: readonly ResolvedPluginOverlay[];
  bands: { top: readonly ResolvedBandSegment[]; bottom: readonly ResolvedBandSegment[] };
  mounts: readonly ResolvedPluginMount[];
  observers: readonly PluginDataChangeObserver[];
  cellMenuItems: readonly NonNullable<DataGridPlugin["cellMenuItems"]>[];
};

/**
 * `ColumnDef` widened to the store's internal row-agnostic shape (see the erasure comment above).
 * `validate`'s own value type erases to `any` (the third param, not `unknown`) — a union of a
 * function and a non-callable Standard Schema can't stay bivariant as a plain property the way a
 * pure method-shorthand function could, so narrow-`TValue` columns need this one documented,
 * single-field cast to widen into this shared type (see types.ts's `ColumnDef.validate` doc).
 */
export type AnyColumnDef = ColumnDef<unknown, unknown, any>; // eslint-disable-line @typescript-eslint/no-explicit-any

/**
 * `ColumnDef<TData, unknown, any>` — the same TValidate-erased-to-`any` widening as `AnyColumnDef`
 * (see its doc comment), but keeping `TData` open for call sites that are still generic over the
 * consumer's row type (sync-prop declarations, the public `useDataGridVisibleColumns`/`useDataGridAllColumns`
 * hooks) rather than already erased to `unknown`. Named once here so the widening reason lives in one place.
 */
export type ColumnDefOf<TData> = ColumnDef<TData, unknown, any>; // eslint-disable-line @typescript-eslint/no-explicit-any

/** The row and column that the clipboard callbacks share. */
export type ClipboardProcessCtx<TData> = { row: TData; column: ColumnDefOf<TData> };

/** `processCellForClipboard`'s context. */
export type ClipboardCopyCtx<TData> = ClipboardProcessCtx<TData> & {
  /** The cell type's own copy text. */
  text: string;
};

/** `processCellFromClipboard`'s context. */
export type ClipboardPasteCtx<TData> = ClipboardProcessCtx<TData> & GateContext & {
  /** The column's own parser (the cell type's `fromText` with the column options). */
  fromText: (text: string) => unknown;
};

/**
 * `CellType<any, any, any>` — the `cellTypes` registry-prop widening (same single-point `any`
 * erasure as {@link AnyColumnDef}): `Cell`/`Editor` are `FC<...>` (strictly contravariant in their
 * props), so without erasing TData/TValue/TOptions neither the built-ins (concrete TValue) nor a
 * consumer's per-column `CellType<TData, TValue, TOptions>` is cast-free assignable to an
 * erased-to-`unknown` entry type — the registry prop is the one place a spread of the exported
 * `cellTypes` plus a custom type must compile with no cast.
 */
export type AnyCellType = CellType<any, any, any>; // eslint-disable-line @typescript-eslint/no-explicit-any

/** Row id used when `getRowId` is omitted: the row's `id` field. */
export function defaultGetRowId(row: unknown): string {
  const id = (row as { id?: unknown } | null | undefined)?.id;
  if (typeof id === "string" || typeof id === "number") return String(id);
  throw new Error("[data-grid] a row has no string or number `id` field. Pass `getRowId` to identify rows.");
}

export function toInternalSyncProps<TData>(props: DataGridSyncProps<TData>): InternalSyncProps {
  return (props.getRowId ? props : { ...props, getRowId: defaultGetRowId }) as unknown as InternalSyncProps;
}

/** Options passed to selectRow/selectColumn actions; mirrors lib/selection's SelectLineOptions. */
export type SelectLineActionOptions = SelectLineOptions;

/**
 * One targeted cell write for {@link DataGridActions.updateCells}, addressed by STABLE ROW ID —
 * never a view or data index. A streaming producer cannot know view coordinates under an active
 * sort, and row ids are already what {@link DataOp} uses, so history survives sort/filter.
 *
 * `TColumnId` defaults to `string` — the store's own untyped shape, which the actions keep (one
 * runtime engine serves every row type). Instantiate it with the union of your columns' `id`s
 * (e.g. `(typeof columns)[number]["id"]` from `defineColumns`'s const output) when building a
 * typed patch list: a typo'd column id then fails to compile instead of skipping at runtime.
 */
export type CellPatch<TColumnId extends string = string> = {
  /** The row's `getRowId()` value. An id not present in `data` is skipped. */
  rowId: string;
  /** Any column id, including a hidden one. An unknown id is skipped. */
  columnId: TColumnId;
  value: unknown;
};

/** One whole-row update for {@link DataGridActions.updateRows}: a partial row shallow-merged per column id. `TColumnId` follows {@link CellPatch}. */
export type RowPatch<TColumnId extends string = string> = {
  rowId: string;
  /** Column id -> new value. Each entry is applied exactly as the matching {@link CellPatch} would be. */
  changes: Readonly<Partial<Record<TColumnId, unknown>>>;
};

/** One rowId+columnId target, addressed the same STABLE-ROW-ID way as {@link CellPatch} (no `value` — used only to name a cell for {@link DataGridActions.setCellErrors}/{@link DataGridActions.clearCellErrors}). */
export type CellErrorTarget = {
  /** The row's `getRowId()` value. An id not present in `data` is stored/cleared anyway (see `cellErrors`' doc) and simply never renders. */
  rowId: string;
  columnId: string;
};

/** One entry for {@link DataGridActions.setCellErrors}: the target cell plus its rejection message. */
export type CellErrorEntry = CellErrorTarget & { message: string };

/** Options for {@link DataGridActions.deleteRows}. */
export type DeleteRowsOptions = {
  /** `"row-operation"` (default) runs the delete gate and reaches `onSave`. `"stream"` is a push from the server. */
  source?: "row-operation" | "stream";
};

/** Full per-grid interaction + derived state; internally typed over `unknown` rows. */
export type DataGridStoreState = Omit<
  InternalSyncProps,
  | "data"
  | "groupLayout" | "pivot" | "defaultPivot"
  | "defaultData"
  | "cellTypes"
  | "commands"
  | "rowMarkers"
  | "enableRowSelection"
  | "enableRowDelete"
  | "checkedRowsLifetime"
  | "totalRowCount"
  | "announceResults"
  | "enableColumnSelection"
  | "enableRangeSelection"
  | "enableMultiRange"
  | "enableColumnResize"
  | "enableColumnReorder"
  | "enableColumnPinning"
  | "headerClickBehavior"
  | "labels"
  | "plugins"
  | "defaultColumnLayout"
  | "defaultSelection"
  | "defaultSortState"
  | "defaultFilterState" | "defaultFilterJoin"
  | "defaultSearchText"
  | "pageSize"
  | "page"
  | "defaultPageSize"
  | "defaultPage"
  | "onPageChange"
  | "onPageSizeChange"
  | "selection"
  | "columnLayout"
  | "readOnly"
  | "keymap"
> & GroupStoreState & {
  /** Always defined: controlled mode mirrors the `data` prop every sync; uncontrolled mode seeds from `defaultData` once and the store owns it thereafter (mutated in place by the commit actions). */
  data: readonly unknown[];
  /** Whether `data` is controlled (the `data` prop was defined on the last `_syncProps`/init) — see `data`'s doc comment and `defaultData`. Mirrors the `sortControlled`-style pattern below. */
  dataControlled: boolean;
  /** Row-agnostic view of the cell-type registry; the typed sync prop is widened once at the store boundary. */
  cellTypes: Record<string, CellType>;
  /** Defaulted (never undefined) — see `resolveSelectionConfig`. */
  rowMarkers: RowMarkersMode;
  enableRowSelection: boolean;
  enableRowDelete: boolean;
  checkedRowsLifetime: CheckedRowsLifetime;
  announceResults: boolean;
  /** Row ids of checked rows that left the view (a filter, a page change, a window move), or the excluded rows in "all matching"; empty unless `checkedRowsLifetime` is `'across-filters'` and in effect. */
  hiddenCheckedRowIds: ReadonlySet<string>;
  /** "All matching" is on: the checked rows are every row of the result except the ids in `hiddenCheckedRowIds` (the excluded rows). */
  allMatching: boolean;
  /** Rows with an acknowledged write in flight (`"saving"`) or refused and reverted (`"failed"`). Empty when `onSave` returns no promise. */
  saveStatus: ReadonlyMap<string, RowSaveStatus>;
  /** Acknowledged changes whose promise has not settled. */
  pendingSaveCount: number;
  /** The gates whose promise has not settled; the same empty set while none is pending. */
  gatesPending: ReadonlySet<GateName>;
  /** `data` is a window of a larger result of this size (`null`: unknown); `undefined` when `data` is the whole result. */
  totalRowCount: number | null | undefined;
  enableColumnSelection: boolean;
  enableRangeSelection: boolean;
  enableMultiRange: boolean;
  enableColumnResize: boolean;
  enableColumnReorder: boolean;
  enableColumnPinning: boolean;
  headerClickBehavior: HeaderClickBehavior;
  /** The cell with focus. On a group row, any `col` inside the label span means the label is active; ArrowUp and ArrowDown keep `col`. */
  activeCell: ViewCoord | null;
  selection: GridSelection;
  /**
   * Two-stage Ctrl+A progression (select-all-progression.ts): which stage the last `selectAll`
   * produced, plus the exact `selection`/`activeCell` object identities it produced them against.
   * Any other action that replaces `selection` or `activeCell` (selectCell/extendTo/pushRange/
   * selectRow/selectColumn/_moveActiveCell/edits/row operations) changes that identity, so `selectAll`
   * detects the mismatch and restarts from stage 1 — no need to instrument every reset site.
   */
  selectAllStage: { stage: "region" | "all"; selection: GridSelection; activeCell: ViewCoord | null } | null;
  /**
   * `coord` is the view anchor, remapped by every viewIndex/visibleColumns rebuild so the editor
   * follows its row; `rowId`/`columnId` are the identity anchor the commit resolves against, so a
   * missed remap can never write the draft into a different row. When the row (or column) leaves
   * the view the session is cancelled and the draft dropped. `session` is unique per started
   * session, so a restart on the same cell still gets a fresh editor.
   */
  editing: { coord: ViewCoord; rowId: string; columnId: string; initialText?: string; session: number } | null;
  /** Transient rejection message from the last failed commitCellEdit; cleared on the next startEditing/commit/cancel. */
  editingError: string | null;
  /**
   * Rejection nonce for the current edit session: increments on every rejected commit attempt
   * (the sync `validate` rejection in `commitCellEdit`, or an async schema resolving with issues
   * via `_setEditingError`) and resets to 0 on `startEditing`. Editors re-arm their one-shot commit
   * guard when this changes: a REJECTION is the only signal that the edit is still open and a
   * fresh commit attempt is expected, never "pending cleared", which also happens on
   * Escape/cancel right before the editor unmounts. The store is the single source of truth for
   * both rejection paths.
   */
  editingRejectionCount: number;
  /**
   * Post-commit server-rejection messages, keyed `"rowId:columnId"` — set via
   * `actions.setCellErrors` after an async `onDataChange` round-trip rejects (e.g. a 422), painted
   * with the SAME visual language as a sync `validate` rejection (ring/tint + message,
   * `aria-invalid`). Deliberately NOT part of the edit lifecycle: `setCellErrors`/`clearCellErrors`
   * never touch `data`, never emit a `DataChange`/`onDataChange`, and are excluded from history —
   * this is metadata ABOUT a cell, not a data change. Auto-cleared for a cell the instant ANY write
   * path (`commitCellEdit`, `commitCellValue`, `applyCellUpdates`, `updateCells`, `deleteSelection`)
   * successfully commits a new value there — the user fixed it, so the stale error must not linger;
   * the server can always re-set it if the fix is still wrong. Pruned of any rowId no longer present
   * in `data` on every row-shape change (delete/duplicate/insert/a consumer `data` replacement) —
   * same maintenance discipline as `RowIndexCache`. Always {@link EMPTY_CELL_ERRORS} when empty, so
   * `useDataGridCellErrors`-style reads never allocate on the common no-error path.
   */
   cellErrors: ReadonlyMap<string, string>;
   /**
    * Transient "highlight-what-changed" keys (row id plus column id) currently flashing,
    * auto-cleared per key after `flashCells`'s duration (default 1400 ms — the 1.2 s fade pulse
    * finishes before the key lifts, so the cell never visibly snaps back). NOT a data change: no
    * `DataChange`, no history entry.
    */
   flashingCells: ReadonlySet<string>;
    /** The `plugins` sync prop resolved (see {@link ResolvedPlugins}); always defined — an absent list resolves to empty members, so overlays/bands/mounts/observers never read undefined. */
  plugins: ResolvedPlugins;
  /** Which input wrote the current selection; touch selections show the selection handles. */
  selectionPointer: SelectionPointer;
  lastHighlightedRow: number | null;
  lastHighlightedCol: number | null;
  /** The row range gesture that Shift steps and the marker drag continue; stale once the row channel or the view changes. */
  rowRangeGesture: RowRangeGesture | null;
  columnWidths: Record<string, number>;
  /** `autosizeOnMount` as passed to the provider; the mounted root consumes it once. */
  autosizeOnMount?: boolean | AutosizeOptions;
  /** null = follow the `columns` prop order. */
  columnOrder: string[] | null;
  /** Single source of truth for visibility; seeded with the def-level `hidden` ids of each column when its id first appears. */
  hiddenColumns: readonly string[];
  /**
   * The current column-layout snapshot (`widths`/`order`/`pins`/`hidden`), recomputed at every
   * commit point (resize release, reorder, pin, hide, `setColumnLayout`) and at every `columns`
   * swap — never on live resize frames. Its identity is the echo token of the controlled
   * `columnLayout` prop: a prop that is the same object a commit just fired is an echo and
   * applies nothing.
   */
  columnLayout: ColumnLayout;
  /** The validated `columnGroups` prop; null when no group keeps a column. */
  columnGroupModel: ColumnGroupModel | null;
  sortState: SortSpec[];
  /** Mirrors the `sortMode` sync prop; `"server"` keeps `sortState` out of every view rebuild. */
  sortMode: "client" | "server";
  /** Mirrors the `sortLocale` sync prop; the default is `locale`, then `"en-US"`. */
  sortLocale: string;
  /** Mirrors the `filterMode` sync prop; `"server"` keeps `filterState` out of every view rebuild. */
  filterMode: "client" | "server";
  filterState: FilterNode[];
  filterJoin: FilterJoinOperator;
  /** Quick-search text; never affects `viewIndex` (search highlights + navigates, it doesn't filter). */
  searchText: string;
  /** How `searchText` matches; set through `actions.setSearch` and kept across searches. */
  searchOptions: Required<SearchOptions>;
  /**
   * Whether `sortState`/`filterState`/`searchText` are controlled (their sync prop
   * was defined on the last `_syncProps`), set once per sync and read by `toggleSort`/`setSorts`/
   * `setFilters`/`setSearch` (server override). Controlled mode:
   * the action still fires its `onXChange` callback but does NOT write the corresponding state
   * field itself — `_syncProps` is the only writer once the consumer's prop (and thus the store)
   * actually changes, standard controlled-input semantics (a callback-ignoring consumer's grid
   * stays visually fixed).
   */
  sortControlled: boolean;
  filterControlled: boolean;
  filterJoinControlled: boolean;
  searchControlled: boolean;
  /** Rows per page; `null` shows every row. */
  pageSize: number | null;
  /** The requested page; the view shows `min(page, last page)`. */
  page: number;
  pageControlled: boolean;
  pageSizeControlled: boolean;
  onPageChange: ((page: number) => void) | undefined;
  onPageSizeChange: ((pageSize: number | null) => void) | undefined;
  /** Every cell matching `searchText`, view-index row-major order; computed once per `setSearch`/`_syncProps`/`setSorts`/`setFilters`, capped at 1000 hits with early exit. */
  searchMatches: SearchMatch[];
  /** `searchMatches` as a `"${viewRow}:${columnId}"` Set for O(1) per-cell highlight lookup. */
  searchMatchSet: ReadonlySet<string>;
  /**
   * `searchMatches` grouped by view row -> matched column indices, for {@link computeRowCellState}'s
   * per-row derivation (the previous per-row `for` loop over every visible
   * column, each doing a `searchMatchSet.has(`${row}:${columnId}`)` string-key lookup, cost ~44ms/2000
   * ticks at 100k rows/8 cols with an active search — measured 29x faster building this map once per
   * search-text change and doing an O(1) `Map.get` per row per tick instead).
   */
  searchMatchRows: ReadonlyMap<number, ReadonlySet<number>>;
  /** True when more than 1000 cells match; `searchMatches` then holds the first 1000. */
  searchMatchesCapped: boolean;
  /** Recomputed by _syncProps/toggleSort/setSorts/setFilters only — search no longer affects it. With `groupBy` set, an entry below 0 names a group row (`groupLayout.rows[-entry - 1]`); read a row through `dataIndexAt`. */
  viewIndex: number[];
  /**
   * Bumped at every row-moving or row-replacing write (insert/delete/duplicate/reorder, a
   * consumer `data` replacement) — the rowId↔dataIndex mapping changed; value-only writes never
   * bump. `useDataGridRowIdToViewRow` keys on this instead of `data` so a streaming tick skips the
   * O(n) map rebuild. Relies on `getRowId` returning stable ids across value-only writes (ids are
   * identity, not content) — the same invariant the rowId index cache holds.
   */
  rowIdentityVersion: number;
  /**
   * True when a write changed a value that the active sort or filter reads, so the displayed order
   * no longer matches the data: a deferred `updateCells`/`updateRows` batch, an edit, a paste, a
   * fill, a clear, or (in server mode) a push that marks a row stale. Drives a "re-sort"
   * affordance; `reconcileView()` (or any sort/filter/search change) clears it. With `useDataGridServerRows`, `reconcileView()`
   * keeps it `true` until the answer delivers the stale rows again. See
   * {@link useDataGridViewStale}.
   */
  viewStale: boolean;
  /**
   * Under a server sort or filter, the ids of loaded rows that a push changed in a column the spec reads. The row keeps
   * its place and carries `data-row-stale` until the server delivers it again. Empty in a client grid.
   */
  staleRowIds: ReadonlySet<string>;
  /** Recomputed by _syncProps/setColumnOrder-ish actions that touch order/visibility. */
  visibleColumns: readonly AnyColumnDef[];
  /**
   * Imperative scroll-into-view, registered by the mounted `DataGridRoot` (null before mount/after
   * unmount). Lets add-ons outside the root's subtree (e.g. `data-grid-toolbar`'s search, which sits
   * as a `DataGridRoot` sibling) move the viewport without reaching into
   * root-internal refs. See {@link useDataGridScrollToCell}.
   */
  scrollToCellImpl: ((coord: ViewCoord) => void) | null;
  /** DOM focus for the active cell's element, or the grid when that element is not rendered; registered by the mounted `DataGridRoot`, like `scrollToCellImpl`. */
  focusImpl: (() => void) | null;
  /** Runs a keymap action like its bound key; registered by the mounted `DataGridRoot`. `preventDefault` and `triggerKey` carry a key event's effects. */
  runShortcutImpl: ((action: GridAction, event?: { preventDefault: () => void; triggerKey?: string }) => void) | null;
  /** Focuses the quick-search input; registered by the mounted `DataGridSearch` (null without one), which makes `focusSearch` leave the key to the browser. */
  focusSearchImpl: (() => void) | null;
  /**
   * The autosize measure context the mounted `DataGridRoot` registers (fonts, mounted row
   * window, header-menu flag) — `null` before mount/after unmount, when
   * {@link DataGridActions.autosizeColumns} measures nothing.
   */
  measureFonts: (() => AutosizeMeasureContext | null) | null;
  /** @internal The data-write cluster's mutable context box (see `data-write.ts`); exposed here so the `useDataGridScrollToCell` ref resolution shares its row-index cache and stale-ref warn flag. */
  dataWrite: DataWriteContext;
  /**
   * The `readOnly` sync prop, defaulted to `false`: editing and delete are disabled grid-wide,
   * independent of any per-column `readOnly`. Seeded from the provider's init props (SSR and the
   * first client paint already see it) and kept in sync by the config phase, so a flip to `true`
   * is live before the next event; every reader (root `aria-readonly`, interaction, clipboard,
   * context menu) goes through this field.
   */
  readOnly: boolean;
  /** @internal The server hook holds the rows of the previous spec: user gestures that write are refused, consumer writes pass. Only write paths read it. */
  serverHeld: boolean;
  /**
   * The effective keymap — `DEFAULT_KEYMAP` merged with the `keymap` sync prop — seeded at store
   * creation and kept in sync by the config phase, the single source of truth for bindings
   * (backing the `data-grid-keybindings` add-on). Keeps its reference while the prop's entries
   * are content-equal (see `keymapContentEqual`). `DEFAULT_KEYMAP` when no prop is passed.
   */
  keymap: Keymap;
  /** The merged command map: the plugins' commands in array order, then the consumer's `commands`, which win silently; a built-in action name is dropped. `null` when no plugin or consumer command exists. */
  commands: Record<string, GridCommand<unknown>> | null;
  /** {@link DEFAULT_LABELS} deep-merged with the `labels` sync prop; see {@link useDataGridLabels}. */
  labels: DataGridLabels;
  /** The `locale` sync prop, `"en-US"` when absent. */
  locale: string;
  /** The live-region text of the latest row move (drag, keyboard, or `reorderRows`); empty before the first. */
  rowMoveAnnouncement: string;
  /** What the grid's live region announces next; the region formats it from the current labels. `seq` grows with every record, so a repeated text is announced again. `null` before the first. */
  liveAnnouncement: LiveAnnouncement | null;
  /** The public actions only — the `_`-prefixed internals live in the store-private table ({@link getInternalActions}), never in state. */
  actions: DataGridActions;
};

/** `DataGridStoreState` with `data` typed as `readonly TData[]` — the state view {@link useDataGridSelector} hands its selector. Every row in `data` originated from the grid's own `TData`-typed `data`/`defaultData` prop, so the widening is safe. */
export type DataGridStoreStateOf<TData> = Omit<DataGridStoreState, "data" | DataGridInternalStateKey> & { data: readonly TData[] };

type DataGridInternalStateKey = "dataControlled" | "selectAllStage" | "editingRejectionCount" | "selectionPointer" | "lastHighlightedRow" | "lastHighlightedCol" | "rowRangeGesture" | "sortControlled" | "filterControlled" | "filterJoinControlled" | "searchControlled" | "pageControlled" | "pageSizeControlled" | "searchMatchSet" | "groupByControlled" | "pivotControlled" | "expandedControlled" | "serverGroupLayout" | "rowIdentityVersion" | "scrollToCellImpl" | "focusImpl" | "runShortcutImpl" | "focusSearchImpl" | "measureFonts" | "dataWrite";

/** Mutations for a single grid instance, nested under the stable `actions` key. */
export type DataGridActions = {
   /**
    * Moves ONLY the active cell to the cell named by the stable {@link CellRef}, leaving the selection
    * (range, row and column channels) untouched; `null` clears it. Fires NO `onSelectionChange` (contrast
    * `selectCell`, which sets a single-cell selection and fires it). After Escape/`clearSelection`,
    * `selection.current` is `null` while `activeCell` still exists — read the active cell from
    * `activeCell`, not from `selection.current.cell`.
    */
   setActiveCell(ref: CellRef | null): void;
   /** View-index variant of {@link DataGridActions.setActiveCell} for callers that hold a {@link ViewCoord}. */
   setActiveCellAt(coord: ViewCoord | null): void;
   /** Selects the cell named by the stable {@link CellRef} as a single-cell selection. */
   selectCell(ref: CellRef): void;
   /** View-index variant of {@link DataGridActions.selectCell} for callers that hold a {@link ViewCoord}. */
   selectCellAt(coord: ViewCoord): void;
   /** Extends the selection to the cell named by the stable {@link CellRef}. */
   extendTo(ref: CellRef): void;
   /** View-index variant of {@link DataGridActions.extendTo} for callers that hold a {@link ViewCoord}. */
   extendToAt(coord: ViewCoord): void;
   extendSelection(direction: ExtendDirection, opts?: { toEdge?: boolean }): void;
   /** Pushes a ctrl-click range to the cell named by the stable {@link CellRef}. */
   pushRange(ref: CellRef): void;
   /** View-index variant of {@link DataGridActions.pushRange} for callers that hold a {@link ViewCoord}. */
   pushRangeAt(coord: ViewCoord): void;
  selectRow(index: number, opts?: SelectLineActionOptions): void;
  selectColumn(index: number, opts?: SelectLineActionOptions): void;
  selectAll(): void;
  /** Sets one row's checked state absolutely — never a toggle — independent of the last-highlighted/range mechanics `selectRow` uses for click gestures. Checking adds the row to the rows channel; unchecking removes it from the rows channel and from every cell range that covers it. A `rowId` that is not in the view does nothing. No-op when `enableRowSelection` is false. */
  setRowChecked(rowId: string, checked: boolean): void;
  /** View-index variant of {@link DataGridActions.setRowChecked}; like every `At` action, it takes a view row number or a `ViewIndex`. */
  setRowCheckedAt(index: number, checked: boolean): void;
  /**
   * Checks (or unchecks) the span from the gesture's anchor to `target`, replacing the previous span of the same gesture.
   * Without a live gesture the anchor is the former anchor row, else the active row, else `target`.
   * `commit` keeps the rows checked so far as the base of the new span. No-op when `enableRowSelection` is false.
   */
  checkRowRange(target: number, opts?: { commit?: boolean }): void;
  /** Header marker select-all checkbox: sets every view row's membership in the rows channel at once (on a paged grid, the shown page's rows). On a grid with `totalRowCount` and `checkedRowsLifetime="across-filters"` whose view holds unloaded rows, checking calls `selectAllMatching`. No-op when `enableRowSelection` is false. */
  setAllRowsChecked(checked: boolean): void;
  /**
   * Checks every row of the result: every page of a client-paged grid, or every row of a server result, loaded or not. Rows that load later show as checked; unchecking a row excludes it.
   * Returns `{ ok: false, reason }` and changes nothing when row selection is off (`"disabled"`), when the result outruns the shown rows and `checkedRowsLifetime` is not `"across-filters"` (`"needs-across-filters"`),
   * or when a server-sorted or server-filtered grid lacks `totalRowCount` (`"needs-total-row-count"`). A client grid without paging checks its rows. Read the outcome with `useDataGridSelectedRows`.
   */
  selectAllMatching(): SelectAllMatchingResult;
  /** Shows page `page` (1-based) of the view. Calls `onPageChange`; a controlled `page` changes when the parent passes the next one. */
  setPage(page: number): void;
  /** Shows `pageSize` rows per page and keeps the first row of the page on screen; `null` shows every row. Calls `onPageSizeChange` with the new size, or `null`; a controlled `pageSize` changes when the parent passes it. `null` calls `onPageChange(1)` when the page was not 1. */
  setPageSize(pageSize: number | null): void;
  clearSelection(): void;
  /** Drops the `"failed"` marks of rows whose write was refused; rows still `"saving"` keep their mark. */
  clearSaveStatus(): void;
  /**
   * Swaps a row's id for the one the server assigned. `row` is the server's row; `getRowId(row)` is the new id.
   * One write: the row keeps its data position and view position, `onDataChange` fires once with `source: "id-swap"`
   * (`onSave` does not see it, history does not record it), and every state keyed by the old id follows: the open
   * edit, cell errors, remembered checked rows, flashes, save status, saves still in flight and undo entries.
   * No-op on a `readOnly` grid; a development warning for an unknown `oldId` or a new id another row holds. `validateRow` runs again for the swapped row; flashes of the row end.
   */
  replaceRowId(oldId: string, row: unknown): void;
  /**
   * `replaceRowId` for many rows in one write: one `onDataChange` with one `"id-swap"` change, one pass over `data`. Use it
   * after a batch create. A swap that fails its checks is skipped with a development warning; the others apply.
   */
  replaceRowIds(swaps: readonly { oldId: string; row: unknown }[]): void;
  /** Clears the cell range and the column channel and keeps the checked rows. */
  clearCellSelection(): void;
  /**
   * Applies a whole selection in stable {@link CellRef} terms, emitting like a gesture (`onSelectionChange`
   * fires when the result differs from the grid's current value): corner refs resolve through the
   * row-index cache plus the view inverse, a range with an unresolvable corner is dropped,
   * unresolvable `rowIds`/`columnIds` are dropped, and an unresolvable or outside anchor resets to
   * `range.start` (dev mode warns once per grid). A value with an `anchor` also moves the active
   * cell to the anchor; `null` clears the whole selection. A single cell stays `selectCell(ref)`.
   */
  setSelection(next: SelectionState | null): void;
  /** Live width write during a resize drag, clamped to the column's legal range; fires `onColumnResizing`, not `onColumnLayoutChange`. Unknown id: no-op. */
  previewColumnWidth(id: string, width: number): void;
  /** Ends a drag without a commit: restores the stored width from before the first preview (or none), fires `onColumnResizing` with `renderedWidth`. */
  cancelColumnResize(id: string, renderedWidth: number): void;
  /**
   * Sets the column's width AND fires `onColumnLayoutChange` once — the resize-drag-release/autosize
   * commit point. The width is clamped exactly as {@link previewColumnWidth} clamps, and the fired
   * snapshot carries the clamped value. Fires only when the width differs from the last committed
   * one; an unknown column id is a no-op.
   */
  setColumnWidth(id: string, width: number): void;
  /**
   * Sizes columns to their content over the whole view, not the mounted window: samples
   * `options.sampleRows` view rows (default 1000, clamped to [1, 10000]) evenly strided across
   * the view plus the mounted window's rows, measures each column's cell-type display text with
   * canvas `measureText`, and commits every changed width in ONE write with ONE
   * `onColumnLayoutChange`. Default targets: every visible column while column resizing is
   * enabled and `resizable !== false`; a named hidden, non-resizable, or unknown (dev-warned)
   * column is skipped. Unchanged widths commit nothing and fire no event. Returns the measured
   * widths; `{}` when the grid has no mounted root (nothing measured, nothing written).
   */
  autosizeColumns(options?: AutosizeOptions): Record<string, number>;
  /**
   * Drops a column's width override, restoring its def `width` (and re-joining `flex` distribution
   * — a manually resized flex column leaves it while an override is set). No-op without an
   * override. Fires `onColumnLayoutChange` once, with the override gone from `widths`.
   */
  resetColumnWidth(id: string): void;
  /**
   * Moves column `id` to sit immediately before/after `targetId`, within its own pin zone. `id` can be a column group id:
   * its columns move as one block. Fires `onColumnLayoutChange` once on an actual move. Returns `{ ok: true }` on a move,
   * else the reason: `"disabled"` (`enableColumnReorder` is false), `"unknown-column"`, `"not-reorderable"` (the column,
   * the target, or a group member has `reorderable: false`), `"pin-zone"` (the target is in another pin zone), or `"nothing-to-do"`.
   */
  setColumnOrder(id: string, targetId: string, position: "before" | "after"): ColumnOrderResult;
  /** The result {@link setColumnOrder} returns for the same arguments, without the move: drives a Move button's `disabled` state. */
  canSetColumnOrder(id: string, targetId: string, position: "before" | "after"): ColumnOrderResult;
  /** Pins/unpins a column (`null` = unpinned). No-op when the id is unknown, the column's `pinnable: false`, grid-wide `enableColumnPinning` is false, or the pin already matches. Fires `onColumnLayoutChange` once on a real change. */
  setColumnPin(id: string, pin: ColumnPin | null): void;
  /**
   * Shows/hides a column via the `hiddenColumns` set; works on a def-level `hidden: true` column
   * — `setColumnHidden(id, false)` re-shows it. A new `columns` array seeds the def's flag only for an id
   * the grid has not seen; a known id keeps its runtime visibility.
   * No-op when the id is unknown or the visibility already matches; otherwise fires
   * `onColumnLayoutChange` once.
   */
  setColumnHidden(id: string, hidden: boolean): void;
  /**
   * Applies a partial column layout as ONE commit (the imperative twin of the `columnLayout`
   * prop): each given part (`widths`, `order`, `pins`, `hidden`) replaces that part, omitted
   * parts keep the current value. Normalized like `columnLayout` (unknown ids dropped, missing
   * order ids appended in def order, widths clamped, pins on `pinnable: false` columns ignored), and fires
   * `onColumnLayoutChange` once only when the layout actually changed.
   */
  setColumnLayout(parts: Partial<ColumnLayout>): void;
  /** Restores widths, order, pins, and hidden columns to the `columns` defs: the pre-resize, pre-reorder layout. Fires `onColumnLayoutChange` once, and only when the layout changed. */
  resetColumnLayout(): void;
  /** Steps the column to its next sort direction, or to no sort. `{ additive: true }` keeps the other sorts, as a Shift-click on the header does. */
  toggleSort(columnId: string, options?: { additive?: boolean }): void;
  setSorts(sorts: SortSpec[]): void;
  /** Sets the group columns; unknown, `groupable: false`, and repeated ids drop. */
  setGroupBy(next: readonly string[]): void;
  /** Adds the column as the innermost group level, or removes it. */
  toggleGroupBy(columnId: string): void;
  /** Sets the pivot column, or turns the pivot off with `undefined`. */
  setPivot(next: PivotSpec | undefined): void;
  /** Sets the open groups. */
  setExpanded(next: ExpandedState): void;
  /** Opens a closed group and closes an open one. */
  toggleGroup(groupId: string): void;
  /** Opens every group. */
  expandAll(): GroupActionResult;
  /** Closes every group. */
  collapseAll(): GroupActionResult;
  setFilters(filters: FilterNode[]): void;
  /** Sets how the top-level filters combine and emits `onFilterJoinChange`; a controlled grid only emits. */
  setFilterJoin(join: FilterJoinOperator): void;
  /** Sets quick-search text (and, when given, the search options) and recomputes `searchMatches`/`searchMatchSet`/`searchMatchesCapped` once; never touches `viewIndex`. Omitted options keep the current ones. */
  setSearch(text: string, options?: SearchOptions): void;
  /** Enters edit mode at the cell named by the stable {@link CellRef}, cancelling an open session first; no-op when the grid or column is readOnly, or its type is unregistered or declares `activate`. */
  startEditing(ref: CellRef, initialText?: string): void;
  /** View-index variant of {@link DataGridActions.startEditing} for callers that hold a {@link ViewCoord}. */
  startEditingAt(coord: ViewCoord, initialText?: string): void;
  /** Discards the in-progress edit without emitting a change. */
  cancelEditing(): void;
  /**
   * Validates and commits the in-progress edit; rejects (keeps editing, sets editingError) or emits
   * one DataChange and moves activeCell by `movement`. No-op in a read-only grid.
   */
  commitCellEdit(value: unknown, movement?: { dx: number; dy: number }): void;
  /** Direct-write path for types with no edit mode (checkbox): validates and commits `value` at the cell named by the stable {@link CellRef} without requiring `startEditing` first, and never moves the active cell. No-op in a read-only grid. */
  commitCellValue(ref: CellRef, value: unknown): void;
  /** View-index variant of {@link DataGridActions.commitCellValue} for callers that hold a {@link ViewCoord}. */
  commitCellValueAt(coord: ViewCoord, value: unknown): void;
  /**
   * Merges `errors` into `cellErrors` per-key (an existing entry for a cell not named here
   * survives untouched). NOT a data change: no `DataChange`, no history entry, no `onDataChange`
   * echo — see `cellErrors`' doc comment. The typical caller is an `onDataChange` handler's
   * `.catch()` after a server 422, mapping its field errors to `{ rowId, columnId, message }[]`.
   */
  setCellErrors(errors: readonly CellErrorEntry[]): void;
  /** Clears `cellErrors` for `targets`, or every entry when `targets` is omitted. Same non-data-change contract as `setCellErrors`. */
  clearCellErrors(targets?: readonly CellErrorTarget[]): void;
  /**
